/// Version anchor for the review-pool state machine and its durable routing
/// identity.  Future revisions must use a new symbol instead of changing V1
/// replay semantics in place.
pub const REVIEW_PANEL_RUNTIME_CONTRACT_V1: u32 = 1;

/// Version anchor for the r82 channel-closure bridge.
///
/// Version one binds DSH acceptance to its authenticated late request header,
/// promotes only lease-scoped legacy review artifacts, and derives a
/// SmartClaw terminal only from an action receipt plus an exact session-bound
/// payload record.  Incompatible semantics require a new symbol.
pub const R82_CHANNEL_CLOSURE_CONTRACT_V1: u32 = 1;

/// Version anchor for exact recovery of uncommitted review-accounting
/// suffixes. Version two separates one legacy Quorum delivery from the
/// generation-scoped Panel batches instead of inferring mode from round
/// history.
pub const REVIEW_ACCOUNTING_RECOVERY_CONTRACT_V2: u32 = 2;

/// Structurally exact review-accounting suffix accepted by V2 recovery.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReviewAccountingSuffixKindV1 {
    /// Exactly one legacy `ReviewDelivered`, bound to one preceding request.
    LegacySingleton,
    /// One or more complete Panel accounting batches validated in order.
    PanelBatches,
}

#[cfg(test)]
mod channel_supervisor_contract_tests {
    use super::*;

    fn git(root: &Path, args: &[&str]) {
        let output = Command::new("git")
            .arg("-C")
            .arg(root)
            .args(args)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "git {args:?}: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[test]
    fn post_spawn_publication_failure_is_effect_unknown_not_action_rejected() {
        let error = anyhow::Error::new(ChannelPublicationEffectUnknown {
            wake_id: "019fc320-1111-4222-8333-444455556666".to_string(),
            detail: "injected append failure".to_string(),
        });
        assert!(channel_publication_effect_unknown(&error));
        assert!(!failure::is_action_rejection(&error));
        let classified =
            failure::with_cli_disposition(error, failure::CliDisposition::EffectUnknown);
        assert_eq!(failure::cli_error_exit_code(&classified), 5);
        assert!(!failure::is_action_rejection(&classified));
    }

    #[test]
    fn schema3_channel_review_prompt_includes_the_exact_wake_id() {
        let head = "0123456789012345678901234567890123456789";
        let wake_id = "019fc320-1111-4222-8333-444455556666";
        let expectation = crate::verify::ReviewContractExpectation::exact(
            "B320",
            "r83",
            "B320-A0002",
            "review",
            "smartclaw",
            head,
        )
        .unwrap();
        let prompt = channel_review_prompt(
            "review the fixed candidate",
            &expectation,
            Path::new("/repo/.worktrees/review-B320-A0002-review-smartclaw-g01"),
            Path::new("/repo/coordination/runtime/review-inbox/r83/B320-A0002-review-smartclaw.md"),
            wake_id,
        )
        .unwrap();
        let expected = format!(
            "---\ntaskId: B320\nround: r83\nattemptId: B320-A0002\nrole: review\nreviewer: smartclaw\nverdict: __VERDICT__\nreviewedHead: {head}\nwakeId: {wake_id}\n---"
        );
        assert!(prompt.contains(&expected));
        assert_eq!(prompt.matches("wakeId:").count(), 1);
        for retired in ["seatId:", "generation:", "policyBaseSha:"] {
            assert!(!prompt.contains(retired));
        }
    }

    #[test]
    fn channel_receipt_and_terminal_copy_the_exact_wake_snapshot_binding() {
        let digest = "a".repeat(64);
        let wake = ledger::event(
            "WakeIssued",
            "runtime:orch",
            Some("B320"),
            Some("r83"),
            serde_json::json!({
                "method": "unified-channel-v1",
                "configDigest": digest,
                "requestDigest": digest,
                "attachmentManifestSha256": digest,
                "commandDigest": digest,
                "executableIdentityDigest": digest,
                "requestedTuple": {"provider": "local", "model": "model-a", "effort": "high", "mode": null},
                "effectiveTuple": {"provider": "local", "model": "model-a", "effort": "high", "mode": null},
                "driver": "opencode",
                "harness": "alpha",
                "observationSource": "opencode-db-and-json-stream",
                "invocationCwd": "/repo",
                "cwdSelection": "project-root",
                "fixedHead": "0123456789012345678901234567890123456789",
            }),
        );
        let expected = channel_action_binding_from_wake(&wake).unwrap().unwrap();
        let mut terminal = ledger::event(
            "ManagedWakeTerminated",
            "runtime:orch",
            Some("B320"),
            Some("r83"),
            serde_json::json!({"wakeId": "wake-1"}),
        );
        attach_channel_action_binding(&wake, &mut terminal).unwrap();
        assert_eq!(
            terminal.payload.as_ref().unwrap()["channelBinding"],
            expected
        );
        validate_existing_channel_action_binding(&wake, &terminal).unwrap();
        let mut tampered_terminal = terminal;
        tampered_terminal.payload.as_mut().unwrap()["channelBinding"]["requestDigest"] =
            serde_json::json!("b".repeat(64));
        assert!(validate_existing_channel_action_binding(&wake, &tampered_terminal).is_err());

        let mut malformed = wake.clone();
        malformed.payload.as_mut().unwrap()["commandDigest"] = serde_json::json!("bad");
        assert!(channel_action_binding_from_wake(&malformed).is_err());
        let mut bad_tuple = wake;
        bad_tuple.payload.as_mut().unwrap()["effectiveTuple"] =
            serde_json::json!({"surprise": true});
        assert!(channel_action_binding_from_wake(&bad_tuple).is_err());
    }

    #[test]
    fn receiptless_channel_terminal_releases_custody_without_authorizing_an_answer() {
        let root = std::env::current_dir()
            .unwrap()
            .join(".cowork-temp")
            .join(format!("B320-receiptless-terminal-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        let round = "r83";
        let task = "B320";
        let attempt = "B320-A0001";
        let harness = "alpha";
        let wake_id = "019fc320-1111-4222-8333-444455556666";
        let continuation = format!("review:{round}:{task}:{attempt}:review:{harness}");
        let digest = "a".repeat(64);
        let request_digest = "b".repeat(64);
        let rendered_digest = "c".repeat(64);
        let fixed_head = "0123456789012345678901234567890123456789";
        let log_path = root.join("opencode.jsonl");
        fs::write(
            &log_path,
            b"{\"type\":\"step_start\",\"sessionID\":\"oc-session\"}\n{\"type\":\"text\",\"sessionID\":\"oc-session\",\"part\":{\"text\":\"PASS\"}}\n{\"type\":\"step_finish\",\"sessionID\":\"oc-session\",\"part\":{\"type\":\"step-finish\",\"reason\":\"stop\"}}\n",
        )
        .unwrap();
        let runtime_limit = managed_wake_runtime_limit(Some(1_800));
        let wake = ledger::event(
            "WakeIssued",
            "runtime:orch",
            Some(task),
            Some(round),
            serde_json::json!({
                "wakeId": wake_id,
                "controlWakeId": wake_id,
                "continuationId": continuation,
                "attemptId": attempt,
                "action": "review",
                "agent": harness,
                "harnessId": "opencode",
                "providerKind": "opencode",
                "requestedProvider": null,
                "requestedModel": null,
                "requestedEffort": null,
                "requestMessageSha256": request_digest,
                "renderedMessageSha256": rendered_digest,
                "requestSessionId": null,
                "backendState": "pending",
                "probeOffset": 0,
                "runtimeLimit": runtime_limit,
                "terminalCapability": "native",
                "logPath": log_path,
                "method": "unified-channel-v1",
                "configDigest": digest,
                "requestDigest": digest,
                "attachmentManifestSha256": digest,
                "commandDigest": digest,
                "executableIdentityDigest": digest,
                "requestedTuple": {"provider": "OD-OC", "model": "model-a", "effort": "high", "mode": null},
                "effectiveTuple": {"provider": "OD-OC", "model": "model-a", "effort": "high", "mode": null},
                "driver": "opencode",
                "harness": harness,
                "observationSource": "opencode-db-and-json-stream",
                "invocationCwd": root,
                "cwdSelection": "target-worktree",
                "fixedHead": fixed_head,
            }),
        );
        let lease = ledger::event(
            "WorkspaceLeased",
            "runtime:orch",
            Some(task),
            Some(round),
            serde_json::json!({
                "siteId": "B320-review-alpha-g01",
                "generation": 1,
                "attemptId": attempt,
                "role": "review",
                "agent": harness,
                "reviewedHead": fixed_head,
                "wakeId": wake_id,
                "paths": {"worktree": ".worktrees/review-B320", "target": "orch/target/review-B320"},
            }),
        );
        let containment = production_managed_containment(true);
        let status = WakeSupervisorStatus {
            protocol_revision: WAKE_SUPERVISOR_PROTOCOL_REVISION,
            token: "32032032032032032032032032032032".to_string(),
            wake_id: wake_id.to_string(),
            agent: Some(harness.to_string()),
            runtime_limit,
            completion_reason: ManagedWakeStopReason::ExactTerminal,
            hard_deadline_reached: false,
            cancel_request_id: None,
            cancel_reason: None,
            terminal_seen: true,
            exited_naturally: true,
            signals: Vec::new(),
            containment_capability: containment.capability,
            containment_claim: containment.claim,
            managed_scope_terminated: containment.managed_scope_terminated,
            fork_complete: containment.fork_complete,
            process_tree_terminated: containment.legacy_process_tree_terminated,
            owned_helpers: 0,
            termination_order: Vec::new(),
            ambiguity: Vec::new(),
            exit_status: Some(0),
            error: None,
            observation_diagnostics: ManagedObservationDiagnostics::default(),
            topology_snapshots: 1,
            full_credential_inspections: 1,
            log_bytes_read: fs::metadata(&log_path).unwrap().len(),
            last_frame_age_secs: None,
            last_frame_summary: Some("apparent PASS without acceptance".to_string()),
            elapsed_secs: Some(1),
        };
        let events = vec![lease.clone(), wake.clone()];
        let (receiptless_status, receiptless) = terminal_record_from_status(
            &root,
            &wake,
            &status,
            crate::harness::CapabilitySource::Native,
            &events,
        )
        .unwrap();
        assert!(!receiptless_status.terminal_seen);
        assert_eq!(receiptless.state, crate::harness::TerminalState::Failed);
        assert!(!receiptless.turn_ended);
        assert!(receiptless.final_text_sha256.is_none());
        assert!(receiptless.output_path.is_none());
        assert!(receiptless.output_sha256.is_none());
        assert!(receiptless.usage.is_none());
        let mut terminal = managed_wake_terminated_event_with_record(
            round,
            Some(task),
            &receiptless_status,
            receiptless,
        );
        attach_channel_action_binding(&wake, &mut terminal).unwrap();
        assert_eq!(payload_string(&terminal, "state"), Some("failed"));
        assert_eq!(
            payload_string(&terminal, "outcomeClass"),
            Some("OperationalError")
        );
        validate_existing_channel_action_binding(&wake, &terminal).unwrap();
        let release = crate::sites::workspace_release_for_termination(&events, round, &terminal)
            .unwrap()
            .expect("receiptless custody terminal must release its exact review site");
        let mut released = events.clone();
        released.extend([terminal, release]);
        let terminal = released
            .iter()
            .find(|event| event.kind == "ManagedWakeTerminated")
            .unwrap();
        assert!(
            crate::sites::workspace_release_for_termination(&released, round, terminal)
                .unwrap()
                .is_none()
        );

        let mut accepted = backend_receipt_event(
            round,
            Some(task),
            Some(attempt),
            harness,
            &rendered_digest,
            log_path.to_str().unwrap(),
            &BackendReceipt {
                kind: BackendReceiptKind::OpenCode,
                wake_id: wake_id.to_string(),
                continuation_id: continuation,
                message_sha256: request_digest,
                request_session_id: None,
                observed_session_id: Some("oc-session".to_string()),
                probe_offset: 0,
                probe_end: fs::metadata(&log_path).unwrap().len(),
                signed_pin: None,
            },
            &digest,
        );
        attach_channel_action_binding(&wake, &mut accepted).unwrap();
        let (accepted_status, answered) = terminal_record_from_status(
            &root,
            &wake,
            &status,
            crate::harness::CapabilitySource::Native,
            &[wake.clone(), accepted.clone()],
        )
        .unwrap();
        assert!(accepted_status.terminal_seen);
        assert_eq!(answered.state, crate::harness::TerminalState::Empty);
        assert!(answered.final_text_sha256.is_none());
        assert!(answered.output_path.is_none());
        assert!(answered.output_sha256.is_none());
        let mut accepted_terminal = managed_wake_terminated_event_with_record(
            round,
            Some(task),
            &accepted_status,
            answered,
        );
        attach_channel_action_binding(&wake, &mut accepted_terminal).unwrap();
        assert_eq!(
            payload_string(&accepted_terminal, "outcomeClass"),
            Some("DeliveredTerminal")
        );
        validate_unified_channel_terminal_shape(&wake, &accepted_terminal).unwrap();
        assert!(crate::sites::workspace_release_for_termination(
            &events,
            round,
            &accepted_terminal,
        )
        .unwrap()
        .is_some());

        let mut malformed = accepted.clone();
        malformed.payload.as_mut().unwrap()["channelBinding"]["requestDigest"] =
            serde_json::json!("d".repeat(64));
        assert!(terminal_record_from_status(
            &root,
            &wake,
            &status,
            crate::harness::CapabilitySource::Native,
            &[wake.clone(), malformed],
        )
        .is_err());
        assert!(terminal_record_from_status(
            &root,
            &wake,
            &status,
            crate::harness::CapabilitySource::Native,
            &[wake.clone(), accepted.clone(), accepted],
        )
        .is_err());
        let mut legacy = wake;
        legacy.payload.as_mut().unwrap()["method"] = serde_json::json!("typed-runtime");
        assert!(terminal_record_from_status(
            &root,
            &legacy,
            &status,
            crate::harness::CapabilitySource::Native,
            &[legacy.clone()],
        )
        .is_err());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn smartclaw_channel_answer_promotes_only_after_exact_receipt_session_and_output() {
        let root = std::env::current_dir()
            .unwrap()
            .join(".cowork-temp")
            .join(format!("B320-smartclaw-promotion-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        let round = "r83";
        let task = "B320";
        let attempt = "B320-A0002";
        let harness = "smartclaw";
        let wake_id = "019fc320-1111-4222-8333-444455556666";
        let request_session = format!("orch-wake-{wake_id}");
        let continuation = format!("review:{round}:{task}:{attempt}:review:{harness}");
        let digest = "a".repeat(64);
        let request_digest = "b".repeat(64);
        let rendered_digest = "c".repeat(64);
        let fixed_head = "0123456789012345678901234567890123456789";
        let log_path = root.join("smartclaw.jsonl");
        let exact_payload = format!(
            "{{\"payloads\":[{{\"text\":\"PASS\"}}],\"meta\":{{\"agentMeta\":{{\"sessionId\":\"{request_session}\"}}}}}}\n"
        );
        fs::write(&log_path, &exact_payload).unwrap();
        let output_path = root.join("coordination/runtime/review-inbox/r83/review.md");
        fs::create_dir_all(output_path.parent().unwrap()).unwrap();
        fs::write(&output_path, b"substantive SmartClaw review\n").unwrap();
        let runtime_limit = managed_wake_runtime_limit(Some(1_800));
        let wake = ledger::event(
            "WakeIssued",
            "runtime:orch",
            Some(task),
            Some(round),
            serde_json::json!({
                "wakeId": wake_id,
                "controlWakeId": wake_id,
                "continuationId": continuation,
                "attemptId": attempt,
                "action": "review",
                "agent": harness,
                "harnessId": harness,
                "providerKind": "smartclaw",
                "requestedProvider": null,
                "requestedModel": null,
                "requestedEffort": null,
                "requestMessageSha256": request_digest,
                "renderedMessageSha256": rendered_digest,
                "requestSessionId": request_session,
                "backendState": "pending",
                "probeOffset": 0,
                "runtimeLimit": runtime_limit,
                "terminalCapability": "derived",
                "logPath": log_path,
                "reviewOutputPath": output_path,
                "method": "unified-channel-v1",
                "configDigest": digest,
                "requestDigest": digest,
                "attachmentManifestSha256": digest,
                "commandDigest": digest,
                "executableIdentityDigest": digest,
                "requestedTuple": {"provider": null, "model": null, "effort": null, "mode": null},
                "effectiveTuple": {"provider": null, "model": null, "effort": null, "mode": null},
                "driver": "smartclaw",
                "harness": harness,
                "observationSource": "dewusmartclaw-multica-session",
                "invocationCwd": root,
                "cwdSelection": "project-root",
                "fixedHead": fixed_head,
            }),
        );
        let mut accepted = backend_receipt_event(
            round,
            Some(task),
            Some(attempt),
            harness,
            &rendered_digest,
            log_path.to_str().unwrap(),
            &BackendReceipt {
                kind: BackendReceiptKind::SmartClaw,
                wake_id: wake_id.to_string(),
                continuation_id: continuation,
                message_sha256: request_digest,
                request_session_id: Some(request_session.clone()),
                observed_session_id: Some(request_session.clone()),
                probe_offset: 0,
                probe_end: fs::metadata(&log_path).unwrap().len(),
                signed_pin: None,
            },
            &digest,
        );
        attach_channel_action_binding(&wake, &mut accepted).unwrap();
        let containment = production_managed_containment(true);
        let status = WakeSupervisorStatus {
            protocol_revision: WAKE_SUPERVISOR_PROTOCOL_REVISION,
            token: "32032032032032032032032032032032".to_string(),
            wake_id: wake_id.to_string(),
            agent: Some(harness.to_string()),
            runtime_limit,
            completion_reason: ManagedWakeStopReason::NaturalExit,
            hard_deadline_reached: false,
            cancel_request_id: None,
            cancel_reason: None,
            terminal_seen: false,
            exited_naturally: true,
            signals: Vec::new(),
            containment_capability: containment.capability,
            containment_claim: containment.claim,
            managed_scope_terminated: containment.managed_scope_terminated,
            fork_complete: containment.fork_complete,
            process_tree_terminated: containment.legacy_process_tree_terminated,
            owned_helpers: 0,
            termination_order: Vec::new(),
            ambiguity: Vec::new(),
            exit_status: Some(0),
            error: None,
            observation_diagnostics: ManagedObservationDiagnostics::default(),
            topology_snapshots: 1,
            full_credential_inspections: 1,
            log_bytes_read: fs::metadata(&log_path).unwrap().len(),
            last_frame_age_secs: Some(0),
            last_frame_summary: Some("payloads-terminal".to_string()),
            elapsed_secs: Some(1),
        };
        let (promoted, record) = terminal_record_from_status(
            &root,
            &wake,
            &status,
            crate::harness::CapabilitySource::Derived,
            &[wake.clone(), accepted.clone()],
        )
        .unwrap();
        assert!(promoted.terminal_seen);
        assert_eq!(record.state, crate::harness::TerminalState::Answered);
        assert!(record.turn_ended);
        assert!(record.output_path.is_some() && record.output_sha256.is_some());
        let mut terminal =
            managed_wake_terminated_event_with_record(round, Some(task), &promoted, record);
        attach_channel_action_binding(&wake, &mut terminal).unwrap();
        validate_unified_channel_terminal_shape(&wake, &terminal).unwrap();
        assert_eq!(
            payload_string(&terminal, "outcomeClass"),
            Some("DeliveredTerminal")
        );

        // Exercise the new generation through the real terminal reconciler,
        // including receiptless calls. A native end is not answer authority.
        let native_prompt = "actual rendered request 知🧭";
        let native_sha = hex::encode(Sha256::digest(native_prompt.as_bytes()));
        let database = root.join("native.sqlite");
        let native_body = "NATIVE FINAL: complete separate answer\n";
        let make_database = r#"
import json,sqlite3,sys
db,sid,cwd,prompt,answer=sys.argv[1:]; c=sqlite3.connect(db)
c.executescript('CREATE TABLE cowork_sessions(id TEXT,title TEXT,status TEXT,cwd TEXT); CREATE TABLE cowork_messages(id TEXT,session_id TEXT,type TEXT,content TEXT,metadata TEXT,sequence INTEGER);')
c.execute('INSERT INTO cowork_sessions VALUES(?,?,?,?)',('native-1','multica:'+sid,'completed',cwd))
c.execute('INSERT INTO cowork_messages VALUES(?,?,?,?,?,?)',('user-1','native-1','user',prompt,'{}',0))
c.execute('INSERT INTO cowork_messages VALUES(?,?,?,?,?,?)',('tool-1','native-1','tool_use','',json.dumps({'toolUseId':'native-tool'}),1))
c.execute('INSERT INTO cowork_messages VALUES(?,?,?,?,?,?)',('denied-1','native-1','tool_result','Not executed: denied',json.dumps({'toolUseId':'native-tool','isError':True}),2))
c.execute('INSERT INTO cowork_messages VALUES(?,?,?,?,?,?)',('denied-note','native-1','system','Native policy denied the tool','{}',3))
c.execute('INSERT INTO cowork_messages VALUES(?,?,?,?,?,?)',('denied-2','native-1','tool_result','denied',json.dumps({'toolUseId':'native-tool','isError':True}),4))
c.execute('INSERT INTO cowork_messages VALUES(?,?,?,?,?,?)',('final-1','native-1','assistant',answer,json.dumps({'isFinal':True}),5))
c.commit()
"#;
        assert!(Command::new("/usr/bin/python3")
            .args(["-I", "-c", make_database])
            .arg(&database)
            .arg(&request_session)
            .arg(&root)
            .arg(native_prompt)
            .arg(native_body)
            .status()
            .unwrap()
            .success());
        let mutate_store = |sql: &str| {
            assert!(Command::new("/usr/bin/python3").args(["-I", "-c",
                "import sqlite3,sys; c=sqlite3.connect(sys.argv[1]); c.execute(sys.argv[2]); c.commit()"])
                .arg(&database).arg(sql).status().unwrap().success());
        };
        let mut native_wake = wake.clone();
        let native_payload = native_wake.payload.as_mut().unwrap();
        native_payload["observationSource"] =
            serde_json::json!(crate::channel::smartclaw::OBSERVATION_SOURCE);
        native_payload["nativeDatabasePath"] = serde_json::json!(database);
        native_payload["renderedMessageSha256"] = serde_json::json!(native_sha);
        let mut native_accepted = accepted.clone();
        native_accepted.payload.as_mut().unwrap()["renderedMessageSha256"] =
            serde_json::json!(native_sha);
        attach_channel_action_binding(&native_wake, &mut native_accepted).unwrap();
        let native_events = [native_wake.clone(), native_accepted];
        let project = || {
            terminal_record_from_status(
                &root,
                &native_wake,
                &status,
                crate::harness::CapabilitySource::Derived,
                &native_events,
            )
        };
        let (native_status, native_record) = project().unwrap();
        assert!(native_status.terminal_seen);
        assert_eq!(native_record.state, crate::harness::TerminalState::Answered);
        assert_eq!(
            native_record.final_text_sha256.as_deref(),
            Some(hex::encode(Sha256::digest(native_body.as_bytes())).as_str())
        );
        for code in [70, 71] {
            let mut eof_status = status.clone();
            eof_status.exit_status = Some(code);
            let (closed, answer) = terminal_record_from_status(
                &root,
                &native_wake,
                &eof_status,
                crate::harness::CapabilitySource::Derived,
                &native_events,
            )
            .unwrap();
            assert_eq!(
                closed.exit_status,
                Some(code),
                "transport status is never rewritten"
            );
            assert!(closed.terminal_seen);
            assert_eq!(answer.state, crate::harness::TerminalState::Answered);
            let mut event =
                managed_wake_terminated_event_with_record(round, Some(task), &closed, answer);
            attach_channel_action_binding(&native_wake, &mut event).unwrap();
            validate_unified_channel_terminal_shape(&native_wake, &event).unwrap();
        }
        // A completed native denial graph must not launder a supervisor deadline.
        for claimed_terminal in [false, true] {
            let mut deadline = status.clone();
            deadline.completion_reason = ManagedWakeStopReason::HardDeadline;
            deadline.hard_deadline_reached = true;
            deadline.exited_naturally = false;
            deadline.signals = vec!["TERM".into()];
            deadline.exit_status = Some(-15);
            deadline.terminal_seen = claimed_terminal;
            let (closed, record) = terminal_record_from_status(
                &root, &native_wake, &deadline,
                crate::harness::CapabilitySource::Derived, &native_events,
            ).unwrap();
            assert_eq!(record.state, crate::harness::TerminalState::TimedOut);
            assert!(!closed.terminal_seen);
            assert_eq!(closed.completion_reason, ManagedWakeStopReason::HardDeadline);
            assert_eq!(closed.signals, vec!["TERM"]);
            assert_eq!(closed.exit_status, Some(-15));
            assert_eq!(deadline.terminal_seen, claimed_terminal, "raw status is immutable");
            let mut terminal = managed_wake_terminated_event_with_record(
                round, Some(task), &closed, record,
            );
            attach_channel_action_binding(&native_wake, &mut terminal).unwrap();
            validate_unified_channel_terminal_shape(&native_wake, &terminal).unwrap();
            assert_eq!(payload_string(&terminal, "outcomeClass"), Some("StoppedByHardDeadline"));
        }
        let projection_path = log_path.with_extension("native-projection.json");
        let published = fs::read(&projection_path).unwrap();
        project().unwrap();
        assert_eq!(
            fs::read(&projection_path).unwrap(),
            published,
            "exact replay is idempotent"
        );

        let (no_receipt_status, no_receipt_record) = terminal_record_from_status(
            &root,
            &native_wake,
            &status,
            crate::harness::CapabilitySource::Derived,
            &[native_wake.clone()],
        )
        .unwrap();
        assert!(!no_receipt_status.terminal_seen);
        assert_ne!(
            no_receipt_record.state,
            crate::harness::TerminalState::Answered
        );
        assert!(!no_receipt_record.turn_ended && no_receipt_record.final_text_sha256.is_none());
        mutate_store("UPDATE cowork_sessions SET status='running'");
        assert!(
            terminal_record_from_status(
                &root,
                &native_wake,
                &status,
                crate::harness::CapabilitySource::Derived,
                &[native_wake.clone()]
            )
            .is_err(),
            "receiptless client exit cannot bypass native-running HOLD"
        );
        mutate_store("UPDATE cowork_sessions SET status='completed'");
        let mut unclosed = status.clone();
        unclosed.managed_scope_terminated = false;
        assert!(terminal_record_from_status(
            &root,
            &native_wake,
            &unclosed,
            crate::harness::CapabilitySource::Derived,
            &native_events
        )
        .is_err());
        let mut observed_error = status.clone();
        observed_error.error = Some("scope observation unavailable".into());
        assert!(terminal_record_from_status(
            &root,
            &native_wake,
            &observed_error,
            crate::harness::CapabilitySource::Derived,
            &native_events
        )
        .is_err());

        fs::write(
            &log_path,
            format!("{exact_payload}{{\"type\":\"activity\"}}\n"),
        )
        .unwrap();
        assert!(
            project().is_err(),
            "changed closed raw bytes are not a benign replay"
        );
        fs::write(&log_path, &exact_payload).unwrap();
        mutate_store("UPDATE cowork_messages SET content='changed final' WHERE id='final-1'");
        assert!(
            project().is_err(),
            "published native final cannot silently change"
        );
        // A new observation with a known native end but no valid answer may
        // close with zero vote; it must not freeze an unavailable projection.
        fs::remove_file(&projection_path).unwrap();
        mutate_store("UPDATE cowork_messages SET metadata='{}' WHERE id='final-1'");
        let (empty_status, empty_record) = project().unwrap();
        assert!(!empty_status.terminal_seen);
        assert_ne!(empty_record.state, crate::harness::TerminalState::Answered);
        assert!(empty_record.final_text_sha256.is_none());
        assert!(!projection_path.exists());

        let mut signaled_status = status.clone();
        signaled_status.terminal_seen = true;
        signaled_status.signals = vec!["TERM".to_string()];
        let (signaled_status, signaled_record) = terminal_record_from_status(
            &root,
            &wake,
            &signaled_status,
            crate::harness::CapabilitySource::Derived,
            &[wake.clone(), accepted.clone()],
        )
        .unwrap();
        assert!(!signaled_status.terminal_seen);
        assert_eq!(signaled_record.state, crate::harness::TerminalState::Empty);
        assert!(!signaled_record.turn_ended);
        let mut signaled_terminal = managed_wake_terminated_event_with_record(
            round,
            Some(task),
            &signaled_status,
            signaled_record,
        );
        attach_channel_action_binding(&wake, &mut signaled_terminal).unwrap();
        assert_eq!(
            payload_string(&signaled_terminal, "outcomeClass"),
            Some("TruncatedNoTerminal")
        );
        validate_unified_channel_terminal_shape(&wake, &signaled_terminal).unwrap();

        fs::write(&log_path, b"{\"activity\":true}\n").unwrap();
        let mut forged_native_status = status.clone();
        forged_native_status.terminal_seen = true;
        let (rejected_native_status, rejected_native_record) = terminal_record_from_status(
            &root,
            &wake,
            &forged_native_status,
            crate::harness::CapabilitySource::Derived,
            &[wake.clone(), accepted.clone()],
        )
        .unwrap();
        assert!(!rejected_native_status.terminal_seen);
        assert_ne!(
            rejected_native_record.state,
            crate::harness::TerminalState::Answered
        );
        let mut rejected_native_terminal = managed_wake_terminated_event_with_record(
            round,
            Some(task),
            &rejected_native_status,
            rejected_native_record,
        );
        attach_channel_action_binding(&wake, &mut rejected_native_terminal).unwrap();
        assert_eq!(
            payload_string(&rejected_native_terminal, "outcomeClass"),
            Some("TruncatedNoTerminal")
        );
        validate_unified_channel_terminal_shape(&wake, &rejected_native_terminal).unwrap();
        fs::write(&log_path, &exact_payload).unwrap();

        let mut inconsistent = terminal.clone();
        inconsistent.payload.as_mut().unwrap()["terminalSeen"] = serde_json::json!(false);
        inconsistent.payload.as_mut().unwrap()["outcomeClass"] =
            serde_json::json!("TruncatedNoTerminal");
        assert!(validate_unified_channel_terminal_shape(&wake, &inconsistent).is_err());

        let mut unknown_state = terminal.clone();
        unknown_state.payload.as_mut().unwrap()["state"] = serde_json::json!("unknown");
        assert!(validate_unified_channel_terminal_shape(&wake, &unknown_state).is_err());
        let mut unknown_outcome = terminal.clone();
        unknown_outcome.payload.as_mut().unwrap()["outcomeClass"] =
            serde_json::json!("UnknownOutcome");
        assert!(validate_unified_channel_terminal_shape(&wake, &unknown_outcome).is_err());

        let mut non_smart_wake = wake.clone();
        non_smart_wake.payload.as_mut().unwrap()["driver"] = serde_json::json!("claude");
        non_smart_wake.payload.as_mut().unwrap()["providerKind"] = serde_json::json!("claude");
        let mut non_smart_terminal = terminal.clone();
        attach_channel_action_binding(&non_smart_wake, &mut non_smart_terminal).unwrap();
        validate_unified_channel_terminal_shape(&non_smart_wake, &non_smart_terminal).unwrap();
        let mut exact_review_terminal = non_smart_terminal.clone();
        exact_review_terminal.payload.as_mut().unwrap()["completionReason"] =
            serde_json::json!("exact-terminal");
        validate_unified_channel_terminal_shape(&non_smart_wake, &exact_review_terminal).unwrap();
        for action in ["consult", "execute"] {
            let mut action_wake = non_smart_wake.clone();
            action_wake.payload.as_mut().unwrap()["action"] = serde_json::json!(action);
            let mut action_terminal = exact_review_terminal.clone();
            action_terminal.payload.as_mut().unwrap()["outputPath"] = serde_json::Value::Null;
            action_terminal.payload.as_mut().unwrap()["outputSha256"] = serde_json::Value::Null;
            attach_channel_action_binding(&action_wake, &mut action_terminal).unwrap();
            validate_unified_channel_terminal_shape(&action_wake, &action_terminal).unwrap();
        }
        let mut non_smart_inconsistent = inconsistent.clone();
        attach_channel_action_binding(&non_smart_wake, &mut non_smart_inconsistent).unwrap();
        assert!(
            validate_unified_channel_terminal_shape(&non_smart_wake, &non_smart_inconsistent)
                .is_err()
        );

        fs::remove_file(&output_path).unwrap();
        let (missing_output_status, missing_output_record) = terminal_record_from_status(
            &root,
            &wake,
            &status,
            crate::harness::CapabilitySource::Derived,
            &[wake.clone(), accepted.clone()],
        )
        .unwrap();
        assert!(missing_output_status.terminal_seen);
        assert_eq!(
            missing_output_record.state,
            crate::harness::TerminalState::Empty
        );
        assert!(missing_output_record.turn_ended);
        assert!(missing_output_record.final_text_sha256.is_none());
        assert!(missing_output_record.output_path.is_none());
        assert!(missing_output_record.output_sha256.is_none());
        let mut missing_output_terminal = managed_wake_terminated_event_with_record(
            round,
            Some(task),
            &missing_output_status,
            missing_output_record,
        );
        attach_channel_action_binding(&wake, &mut missing_output_terminal).unwrap();
        assert_eq!(
            payload_string(&missing_output_terminal, "outcomeClass"),
            Some("DeliveredTerminal")
        );
        validate_unified_channel_terminal_shape(&wake, &missing_output_terminal).unwrap();
        let lease = ledger::event(
            "WorkspaceLeased",
            "runtime:orch",
            Some(task),
            Some(round),
            serde_json::json!({
                "siteId": "B320-review-smartclaw-g01",
                "generation": 1,
                "attemptId": attempt,
                "role": "review",
                "agent": harness,
                "reviewedHead": fixed_head,
                "wakeId": wake_id,
                "paths": {
                    "worktree": ".worktrees/review-B320-A0002-review-smartclaw-g01",
                    "target": "orch/target/review-B320-A0002-review-smartclaw-g01"
                },
            }),
        );
        let release = crate::sites::workspace_release_for_termination(
            &[lease, wake.clone(), accepted.clone()],
            round,
            &missing_output_terminal,
        )
        .unwrap()
        .expect("trusted empty SmartClaw review must close and release its exact site");
        assert_eq!(payload_string(&release, "wakeId"), Some(wake_id));
        fs::write(&output_path, b"substantive SmartClaw review\n").unwrap();

        let mut deadline_status = status.clone();
        deadline_status.completion_reason = ManagedWakeStopReason::HardDeadline;
        deadline_status.hard_deadline_reached = true;
        deadline_status.terminal_seen = true;
        deadline_status.exited_naturally = false;
        deadline_status.exit_status = Some(72);
        let (deadline_status, deadline_record) = terminal_record_from_status(
            &root,
            &wake,
            &deadline_status,
            crate::harness::CapabilitySource::Derived,
            &[wake.clone(), accepted.clone()],
        )
        .unwrap();
        assert!(!deadline_status.terminal_seen);
        assert_eq!(
            deadline_record.state,
            crate::harness::TerminalState::TimedOut
        );
        let mut deadline_terminal = managed_wake_terminated_event_with_record(
            round,
            Some(task),
            &deadline_status,
            deadline_record,
        );
        attach_channel_action_binding(&wake, &mut deadline_terminal).unwrap();
        validate_unified_channel_terminal_shape(&wake, &deadline_terminal).unwrap();
        assert_eq!(
            payload_string(&deadline_terminal, "outcomeClass"),
            Some("StoppedByHardDeadline")
        );

        let mut cancel_status = status.clone();
        cancel_status.completion_reason = ManagedWakeStopReason::ManualCancel;
        cancel_status.terminal_seen = true;
        cancel_status.exited_naturally = false;
        cancel_status.cancel_request_id = Some("cancel-B320-A0002".to_string());
        cancel_status.cancel_reason = Some("authenticated test cancel".to_string());
        cancel_status.exit_status = None;
        let (cancel_status, cancel_record) = terminal_record_from_status(
            &root,
            &wake,
            &cancel_status,
            crate::harness::CapabilitySource::Derived,
            &[wake.clone(), accepted.clone()],
        )
        .unwrap();
        assert!(!cancel_status.terminal_seen);
        assert_eq!(cancel_record.state, crate::harness::TerminalState::Canceled);
        let mut cancel_terminal = managed_wake_terminated_event_with_record(
            round,
            Some(task),
            &cancel_status,
            cancel_record,
        );
        attach_channel_action_binding(&wake, &mut cancel_terminal).unwrap();
        validate_unified_channel_terminal_shape(&wake, &cancel_terminal).unwrap();
        assert_eq!(
            payload_string(&cancel_terminal, "outcomeClass"),
            Some("StoppedByAuthenticatedCancel")
        );

        let mut wrong_session = accepted;
        wrong_session.payload.as_mut().unwrap()["observedSessionId"] =
            serde_json::json!("wrong-session");
        assert!(terminal_record_from_status(
            &root,
            &wake,
            &status,
            crate::harness::CapabilitySource::Derived,
            &[wake.clone(), wrong_session],
        )
        .is_err());

        let alias = root.join("review-hardlink-alias.md");
        fs::hard_link(&output_path, &alias).unwrap();
        assert!(terminal_output_artifact(&root, &wake).is_err());
        fs::remove_file(alias).unwrap();
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn channel_terminal_reader_handles_smartclaw_and_claude_frames() {
        let root = std::env::current_dir()
            .unwrap()
            .join(".cowork-temp")
            .join(format!("B320-terminal-reader-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();

        let smart_log = root.join("smartclaw.log");
        fs::write(
            &smart_log,
            b"{\"payloads\":[{\"text\":\"PASS\"}],\"meta\":{\"agentMeta\":{\"sessionId\":\"orch-wake-w1\"}}}\n",
        )
        .unwrap();
        let smart_wake = ledger::event(
            "WakeIssued",
            "runtime:orch",
            Some("B320"),
            Some("r83"),
            serde_json::json!({
                "driver": "smartclaw",
                "requestSessionId": "orch-wake-w1",
            }),
        );
        let smart = read_managed_terminal_frame(&smart_log, &smart_wake)
            .unwrap()
            .unwrap();
        assert!(smart.turn_ended);
        assert!(smart.final_text_sha256.is_some());

        let claude_log = root.join("claude.log");
        fs::write(
            &claude_log,
            b"{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"result\":\"PASS\",\"usage\":{\"input_tokens\":1}}\n",
        )
        .unwrap();
        let claude_wake = ledger::event(
            "WakeIssued",
            "runtime:orch",
            Some("B320"),
            Some("r83"),
            serde_json::json!({"driver": "claude"}),
        );
        let claude = read_managed_terminal_frame(&claude_log, &claude_wake)
            .unwrap()
            .unwrap();
        assert!(claude.turn_ended);
        assert!(claude.final_text_sha256.is_some());
        assert!(claude.usage.is_some());
        fs::write(
            &claude_log,
            b"{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":true,\"result\":\"error\"}\n",
        )
        .unwrap();
        assert!(read_managed_terminal_frame(&claude_log, &claude_wake)
            .unwrap()
            .is_none());

        let drift_log = root.join("opencode-session-drift.log");
        fs::write(
            &drift_log,
            b"{\"type\":\"step_start\",\"sessionID\":\"A\"}\n{\"type\":\"text\",\"sessionID\":\"B\",\"part\":{\"text\":\"forged\"}}\n{\"type\":\"step_finish\",\"sessionID\":\"A\",\"part\":{\"type\":\"step-finish\",\"reason\":\"stop\"}}\n",
        )
        .unwrap();
        let drift_wake = ledger::event(
            "WakeIssued",
            "runtime:orch",
            Some("B320"),
            Some("r83"),
            serde_json::json!({"driver": "opencode"}),
        );
        assert!(read_managed_terminal_frame(&drift_log, &drift_wake).is_err());

        for (driver, body) in [
            (
                "opencode",
                "{\"type\":\"text\",\"part\":{\"text\":\"PASS\"}}\n{\"type\":\"step_finish\",\"part\":{\"type\":\"step-finish\",\"reason\":\"stop\"}}\n",
            ),
            (
                "codex",
                "{\"type\":\"item.completed\",\"item\":{\"type\":\"agent_message\",\"text\":\"PASS\"}}\n{\"type\":\"turn.completed\"}\n",
            ),
            ("cursor", "{\"type\":\"result\",\"result\":\"PASS\"}\n"),
            (
                "codebuddy",
                "{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"result\":\"PASS\"}\n",
            ),
            (
                "mimo",
                "{\"type\":\"step_finish\",\"part\":{\"text\":\"PASS\"}}\n",
            ),
        ] {
            let path = root.join(format!("{driver}.log"));
            fs::write(&path, body).unwrap();
            let wake = ledger::event(
                "WakeIssued",
                "runtime:orch",
                Some("B320"),
                Some("r83"),
                serde_json::json!({"driver": driver}),
            );
            let facts = read_managed_terminal_frame(&path, &wake)
                .unwrap()
                .unwrap();
            assert!(facts.turn_ended, "{driver}");
            assert!(facts.final_text_sha256.is_some(), "{driver}");
        }
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn channel_supervisor_accepts_exact_linked_worktree_without_relaxing_legacy_cwd() {
        let root = std::env::current_dir()
            .unwrap()
            .join(".cowork-temp")
            .join(format!("B320-supervisor-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        git(&root, &["init", "-q", "-b", "main"]);
        fs::write(root.join("tracked.txt"), b"base\n").unwrap();
        git(&root, &["add", "tracked.txt"]);
        git(
            &root,
            &[
                "-c",
                "user.name=orch-test",
                "-c",
                "user.email=orch@test.invalid",
                "commit",
                "-qm",
                "base",
            ],
        );
        let root = fs::canonicalize(root).unwrap();
        let worktree = root.join("review-worktree");
        git(
            &root,
            &[
                "worktree",
                "add",
                "-q",
                "--detach",
                worktree.to_str().unwrap(),
                "HEAD",
            ],
        );
        let logs = root.join("coordination/runtime/logs");
        fs::create_dir_all(&logs).unwrap();
        let log_path = logs.join("wake-alpha.jsonl");
        File::create(&log_path).unwrap();
        let supervisor = authenticated_supervisor_dir(&root, true).unwrap();
        let token = fresh_supervisor_token().unwrap();
        let configured_program = root.join("provider");
        fs::write(&configured_program, b"#!/bin/sh\nexit 0\n").unwrap();
        fs::set_permissions(&configured_program, fs::Permissions::from_mode(0o755)).unwrap();
        let wrapper = root.join("coordination/scripts/wake-multica.sh");
        fs::create_dir_all(wrapper.parent().unwrap()).unwrap();
        fs::write(&wrapper, b"#!/bin/sh\nexit 0\n").unwrap();
        fs::set_permissions(&wrapper, fs::Permissions::from_mode(0o644)).unwrap();
        let program = PathBuf::from("/bin/sh");
        let digest = "a".repeat(64);
        let program_identity = crate::channel::executable_identity_digest_v1(&program).unwrap();
        let executable_identity =
            crate::channel::executable_identity_digest_v1(&configured_program).unwrap();
        let wrapper_identity =
            crate::channel::code_owned_wrapper_identity_digest_v1(&wrapper).unwrap();
        let fixed_head = crate::gitx::rev_parse(&worktree, "HEAD^{commit}").unwrap();
        let binding = ChannelSupervisorBindingV1 {
            standalone: false,
            requested_tuple: None,
            effective_tuple: None,
            alias: "alpha".to_string(),
            driver: crate::harness::HarnessId::SmartClaw,
            action: "review".to_string(),
            config_digest: digest.clone(),
            request_digest: digest.clone(),
            attachment_manifest_digest: digest.clone(),
            command_digest: digest.clone(),
            program_identity_digest: program_identity,
            configured_executable: configured_program.clone(),
            configured_executable_identity_digest: executable_identity,
            wrapper_executable: Some(wrapper.clone()),
            wrapper_identity_digest: Some(wrapper_identity),
            head_root: worktree.clone(),
            fixed_head,
        };
        let spec = WakeSupervisorLaunchSpec {
            version: 1,
            protocol_revision: WAKE_SUPERVISOR_PROTOCOL_REVISION,
            token: token.clone(),
            argv: vec![
                program.display().to_string(),
                wrapper.display().to_string(),
                "review".to_string(),
            ],
            env: BTreeMap::new(),
            channel_binding: Some(binding),
            environment_is_complete: true,
            cwd: worktree.clone(),
            log_path,
            ack_path: supervisor.join(format!("{token}.ack.json")),
            status_path: supervisor.join(format!("{token}.status.json")),
            policy: WakeSupervisorPolicy::production(),
            wake_id: Some(fresh_managed_wake_id()),
            agent: Some("alpha".to_string()),
            attach_action_id: None,
            continued_from_wake_id: None,
            runtime_limit: managed_wake_runtime_limit(Some(60)),
            launch_variant: WakeSupervisorLaunchVariant::ManagedRevision3,
            baseline: Vec::new(),
            baseline_topology: Vec::new(),
        };
        let parsed =
            parse_wake_supervisor_launch_spec(&root, &serde_json::to_vec(&spec).unwrap()).unwrap();
        assert_eq!(parsed.cwd, worktree);
        let mut wrong_driver = spec.clone();
        wrong_driver.channel_binding.as_mut().unwrap().driver = crate::harness::HarnessId::OpenCode;
        let topology_error =
            parse_wake_supervisor_launch_spec(&root, &serde_json::to_vec(&wrong_driver).unwrap())
                .unwrap_err();
        assert!(
            topology_error.contains("driver contract"),
            "{topology_error}"
        );

        fs::write(worktree.join("head-drift.txt"), b"drift\n").unwrap();
        git(&worktree, &["add", "head-drift.txt"]);
        git(
            &worktree,
            &[
                "-c",
                "user.name=orch-test",
                "-c",
                "user.email=orch@test.invalid",
                "commit",
                "-qm",
                "head drift",
            ],
        );
        let head_error =
            parse_wake_supervisor_launch_spec(&root, &serde_json::to_vec(&spec).unwrap())
                .unwrap_err();
        assert!(head_error.contains("fixed HEAD 漂移"), "{head_error}");

        let mut binary_drift = spec.clone();
        binary_drift.channel_binding.as_mut().unwrap().fixed_head =
            crate::gitx::rev_parse(&worktree, "HEAD^{commit}").unwrap();
        fs::write(&configured_program, b"#!/bin/sh\nexit 0\n# replaced\n").unwrap();
        let binary_error =
            parse_wake_supervisor_launch_spec(&root, &serde_json::to_vec(&binary_drift).unwrap())
                .unwrap_err();
        assert!(
            binary_error.contains("configured executable identity 漂移"),
            "{binary_error}"
        );

        let mut wrapper_drift = binary_drift.clone();
        wrapper_drift
            .channel_binding
            .as_mut()
            .unwrap()
            .configured_executable_identity_digest =
            crate::channel::executable_identity_digest_v1(&configured_program).unwrap();
        fs::write(&wrapper, b"#!/bin/sh\nexit 0\n# replaced\n").unwrap();
        let wrapper_error =
            parse_wake_supervisor_launch_spec(&root, &serde_json::to_vec(&wrapper_drift).unwrap())
                .unwrap_err();
        assert!(
            wrapper_error.contains("wrapper identity 漂移"),
            "{wrapper_error}"
        );

        let mut legacy = wrapper_drift;
        let legacy_bin = root.join("legacy-bin");
        fs::create_dir(&legacy_bin).unwrap();
        let legacy_program = legacy_bin.join("opencode");
        fs::write(&legacy_program, b"#!/bin/sh\nexit 0\n").unwrap();
        fs::set_permissions(&legacy_program, fs::Permissions::from_mode(0o755)).unwrap();
        legacy.argv[0] = legacy_program.display().to_string();
        legacy.protocol_revision = LEGACY_WAKE_SUPERVISOR_PROTOCOL_REVISION;
        legacy.wake_id = None;
        legacy.runtime_limit = managed_wake_runtime_limit(None);
        legacy.channel_binding = None;
        let value = serde_json::to_value(legacy).unwrap();
        let mut value = value.as_object().unwrap().clone();
        value.remove("wakeId");
        value.remove("runtimeLimit");
        assert!(
            parse_wake_supervisor_launch_spec(&root, &serde_json::to_vec(&value).unwrap())
                .unwrap_err()
                .contains("legacy wake supervisor cwd")
        );
        fs::remove_dir_all(&root).unwrap();
    }
}

/// Closed policy inputs used by the V1 review-panel evaluator.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReviewPanelPolicyV1 {
    /// Minimum number of unique substantive PASS seats needed for success.
    pub minimum_passes: usize,
    /// Whether one PASS must come from a primary-lineage seat.
    pub require_primary_pass: bool,
    /// Maximum number of business-invalid generations the panel may consume.
    pub maximum_business_retries: usize,
    /// Whether a nongate PASS may close only a failed secondary seat.
    pub nongate_substitutes_secondary_only: bool,
}

/// Terminal or pending state of one immutable V1 seat generation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ReviewPanelSeatStateV1 {
    /// The routed generation has not produced a terminal fact yet.
    Pending,
    /// A substantive PASS artifact was delivered for the exact route.
    Pass,
    /// A substantive FAIL finding was delivered; only formal roles veto V1.
    Fail,
    /// A substantive BLOCKED finding was delivered; only formal roles veto V1.
    Blocked,
    /// The provider answered, but the artifact was absent or contract-invalid.
    BusinessInvalid,
    /// Admission, authentication, pin, managed-runtime setup, or Agy
    /// canary/formal-answer validation failed without consuming a business retry.
    #[serde(rename = "system-terminal-invalid")]
    SystemInvalid,
}

/// Replay identity and state for one V1 review seat generation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct ReviewPanelSeatV1 {
    /// Stable logical seat identity retained across a business retry.
    pub seat_id: String,
    /// Monotonic generation; generation two is the only V1 business retry.
    pub generation: u32,
    /// Routed role (`primary`, `secondary`, or `nongate`).
    pub role: String,
    /// Exact registered agent selected for this generation.
    pub agent: String,
    /// Whether this seat can satisfy the required primary-lineage PASS.
    pub primary_lineage: bool,
    /// Whether a business-invalid generation may be retried.
    pub retry_eligible: bool,
    /// Current state reconstructed exclusively from durable events.
    pub state: ReviewPanelSeatStateV1,
}

/// Deterministic next action for a fully replayed V1 panel snapshot.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum ReviewPanelDecisionV1 {
    /// The supplied snapshot double-counts or contains a malformed identity.
    Invalid,
    /// Quorum and the primary-lineage requirement are both satisfied.
    Pass,
    /// A substantive FAIL or BLOCKED finding monotonically vetoes PASS.
    Veto,
    /// One exact business-invalid seat is eligible for its next generation.
    Retry {
        /// Stable seat identity that the retry command must name.
        seat_id: String,
    },
    /// A routed seat is still pending, so final PASS/veto/exhaustion waits.
    Awaiting,
    /// No allowed retry/backfill can make the signed quorum reachable.
    PoolExhausted,
}

/// Evaluate a V1 panel without consulting clocks, files, mutable registries,
/// or list order.  System-invalid generations never consume the business
/// retry budget; the caller supplies separately counted durable retries and
/// remaining primary-capable backfills.
pub fn evaluate_review_panel_v1(
    policy: &ReviewPanelPolicyV1,
    seats: &[ReviewPanelSeatV1],
    business_retries_used: usize,
    eligible_backfills: usize,
) -> ReviewPanelDecisionV1 {
    let unique_seats = seats
        .iter()
        .map(|seat| (seat.seat_id.as_str(), seat.generation))
        .collect::<BTreeSet<_>>();
    let unique_agents = seats
        .iter()
        .map(|seat| seat.agent.as_str())
        .collect::<BTreeSet<_>>();
    if policy.minimum_passes == 0
        || policy.maximum_business_retries > 1
        || unique_seats.len() != seats.len()
        || unique_agents.len() != seats.len()
        || seats.iter().any(|seat| {
            seat.seat_id.trim().is_empty()
                || seat.generation == 0
                || seat.agent.trim().is_empty()
                || !matches!(seat.role.as_str(), "primary" | "secondary" | "nongate")
        })
    {
        return ReviewPanelDecisionV1::Invalid;
    }

    let pending = seats
        .iter()
        .filter(|seat| seat.state == ReviewPanelSeatStateV1::Pending)
        .count();
    if seats.iter().any(|seat| {
        seat.role != "nongate"
            && matches!(
                seat.state,
                ReviewPanelSeatStateV1::Fail | ReviewPanelSeatStateV1::Blocked
            )
    }) {
        return if pending == 0 {
            ReviewPanelDecisionV1::Veto
        } else {
            ReviewPanelDecisionV1::Awaiting
        };
    }

    let primary_pass = seats
        .iter()
        .any(|seat| seat.state == ReviewPanelSeatStateV1::Pass && seat.primary_lineage);
    let formal_passes = seats
        .iter()
        .filter(|seat| seat.state == ReviewPanelSeatStateV1::Pass && seat.role != "nongate")
        .count();
    let unavailable_secondary = seats.iter().any(|seat| {
        seat.role == "secondary"
            && matches!(
                seat.state,
                ReviewPanelSeatStateV1::BusinessInvalid | ReviewPanelSeatStateV1::SystemInvalid
            )
    });
    let nongate_substitution = seats
        .iter()
        .any(|seat| seat.role == "nongate" && seat.state == ReviewPanelSeatStateV1::Pass)
        && (!policy.nongate_substitutes_secondary_only || unavailable_secondary);
    let pass_count = formal_passes + usize::from(nongate_substitution);
    if pending == 0
        && pass_count >= policy.minimum_passes
        && (!policy.require_primary_pass || primary_pass)
    {
        return ReviewPanelDecisionV1::Pass;
    }

    if business_retries_used < policy.maximum_business_retries {
        let mut retryable = seats
            .iter()
            .filter(|seat| {
                seat.state == ReviewPanelSeatStateV1::BusinessInvalid && seat.retry_eligible
            })
            .map(|seat| seat.seat_id.as_str())
            .collect::<Vec<_>>();
        retryable.sort_unstable();
        retryable.dedup();
        if let Some(seat_id) = retryable.first() {
            return ReviewPanelDecisionV1::Retry {
                seat_id: (*seat_id).to_string(),
            };
        }
    }

    let retry_capacity = seats
        .iter()
        .filter(|seat| {
            seat.retry_eligible
                && seat.state == ReviewPanelSeatStateV1::BusinessInvalid
                && business_retries_used < policy.maximum_business_retries
        })
        .count();
    let primary_reachable = primary_pass
        || seats.iter().any(|seat| {
            seat.primary_lineage
                && matches!(
                    seat.state,
                    ReviewPanelSeatStateV1::Pending | ReviewPanelSeatStateV1::BusinessInvalid
                )
        })
        || eligible_backfills > 0;
    let pass_reachable = pass_count
        .saturating_add(pending)
        .saturating_add(retry_capacity)
        .saturating_add(eligible_backfills)
        >= policy.minimum_passes;
    if pass_reachable && (!policy.require_primary_pass || primary_reachable) && pending > 0 {
        ReviewPanelDecisionV1::Awaiting
    } else {
        ReviewPanelDecisionV1::PoolExhausted
    }
}

/// Durable identity returned for one selected/retried/backfilled route.
