#[derive(Debug, Clone, PartialEq, Eq)]
struct PanelRouteAuthorizationV1 {
    task_id: String,
    selected_event_id: String,
    route_event_id: String,
    route: ledger::ReviewSeatRoutedPayloadV1,
}

fn bind_panel_route_event_identity_v1(
    payload: &mut serde_json::Value,
    authorization: Option<&PanelRouteAuthorizationV1>,
) {
    let Some(authorization) = authorization else {
        return;
    };
    payload["panelId"] = serde_json::json!(authorization.route.panel_id);
    payload["seatId"] = serde_json::json!(authorization.route.seat_id);
    payload["generation"] = serde_json::json!(authorization.route.generation);
    payload["routeEventId"] = serde_json::json!(authorization.route_event_id);
    payload["policyBaseSha"] = serde_json::json!(authorization.route.policy_base_sha);
    payload["reviewedHead"] = serde_json::json!(authorization.route.reviewed_head);
}

/// Termination is topology-typed: a directly managed CLI owns a process
/// group, while the SmartClaw socket bridge can only be judged by its exact
/// wake log.  `LogQuiesceOnly` deliberately does not imply that the SmartClaw
/// daemon was cancelled; the socket cancellation protocol belongs to H16.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TerminationPlan {
    SignalProcessGroup,
    LogQuiesceOnly,
}

/// Resolve the default from the current signed ROUND-IR rather than from a
/// mutable task-card read or a CLI literal.
pub fn default_review_deadline_secs(root: &Path, task_id: &str, role: &str) -> Result<u64> {
    crate::card::validate_task_id(task_id)?;
    let role = crate::sites::SiteRole::parse(role).map_err(anyhow::Error::msg)?;
    if role == crate::sites::SiteRole::Implement {
        bail!("review deadline role must be primary, secondary, or nongate");
    }
    let round = current_round(root)?;
    let events = read_round_ledger_events(root, &round)?;
    let active = crate::plan::require_active_round_ir(root, &round, &events)?;
    let task = active
        .candidate
        .tasks
        .iter()
        .find(|task| task.id == task_id)
        .with_context(|| format!("review task {task_id} 不在 active ROUND-IR"))?;
    Ok(review_deadline_secs(
        role.as_str(),
        task.required_evidence.len(),
    ))
}
/// Signed ROUND-IR role which authorizes a nongate review wake.
///
/// Keep this vocabulary centralized: the request role remains `nongate`, while
/// scheduling capacities use this review-specific capability name.
pub const NONGATE_REVIEW_ROLE: &str = "nongate-review";

fn review_permit_role(role: crate::sites::SiteRole) -> &'static str {
    match role {
        crate::sites::SiteRole::Primary => "primary-review",
        crate::sites::SiteRole::Secondary => "secondary-review",
        crate::sites::SiteRole::Nongate => NONGATE_REVIEW_ROLE,
        crate::sites::SiteRole::Review => "review",
        crate::sites::SiteRole::Implement => "implement",
    }
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AttachRefusal {
    SourceNotProvenTerminal,
    SourceWakeMismatch,
    ManagedScopeNotTerminated,
    TerminalFactsInvalid,
}

impl std::fmt::Display for AttachRefusal {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(match self {
            Self::SourceNotProvenTerminal => {
                "immutable managed-wake terminal status is unavailable"
            }
            Self::SourceWakeMismatch => "terminal status does not belong to the source wake",
            Self::ManagedScopeNotTerminated => {
                "terminal status does not prove managedScopeTerminated=true"
            }
            Self::TerminalFactsInvalid => "terminal status facts are internally inconsistent",
        })
    }
}

impl std::error::Error for AttachRefusal {}

/// Immutable proof used for the narrowly-scoped H64 continuation-fence
/// exemption.  The proof stores only a digest and a wake binding; raw process
/// or provider-session credentials never enter it.
#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SessionDeathEvidence {
    wake_id: String,
    evidence_sha256: String,
    outcome: String,
}

impl SessionDeathEvidence {
    pub fn from_terminal_facts(facts: &ManagedWakeTerminationFacts) -> Option<Self> {
        if !facts.managed_scope_terminated {
            return None;
        }
        let outcome = classify_managed_wake_outcome(facts);
        if matches!(outcome, ManagedWakeOutcomeClass::OperationalError(_)) {
            return None;
        }
        let canonical = serde_json::json!({
            "wakeId": facts.wake_id,
            "agent": facts.agent,
            "completionReason": facts.completion_reason,
            "terminalSeen": facts.terminal_seen,
            "exitedNaturally": facts.exited_naturally,
            "hardDeadlineReached": facts.hard_deadline_reached,
            "cancelRequestId": facts.cancel_request_id,
            "signals": facts.signals,
            "managedScopeTerminated": facts.managed_scope_terminated,
            "logBytesRead": facts.log_bytes_read,
        });
        let encoded = serde_json::to_vec(&canonical).ok()?;
        Some(Self {
            wake_id: facts.wake_id.clone(),
            evidence_sha256: sha256_hex(&encoded),
            outcome: outcome.ledger_name().to_string(),
        })
    }

    pub const fn exempts_request_digest(&self) -> bool {
        true
    }

    pub fn wake_id(&self) -> &str {
        &self.wake_id
    }

    pub fn evidence_sha256(&self) -> &str {
        &self.evidence_sha256
    }

    pub fn outcome(&self) -> &str {
        &self.outcome
    }
}

/// Construct the narrow H64 resume exemption directly from an immutable
/// supervisor terminal-status frame.  This deliberately accepts the compact
/// public status shape as well as the supervisor's richer on-disk object, but
/// every field needed to establish terminality must be present with the right
/// type.  Missing fields and partially-written JSON therefore fail closed.
pub fn session_death_evidence_from_status(status_json: &str) -> Option<SessionDeathEvidence> {
    let value = serde_json::from_str::<serde_json::Value>(status_json).ok()?;
    let object = value.as_object()?;

    for required in [
        "wakeId",
        "completionReason",
        "terminalSeen",
        "exitedNaturally",
        "exitStatus",
        "cancelReason",
        "signals",
        "hardDeadlineReached",
        "managedScopeTerminated",
        "logBytesRead",
    ] {
        if !object.contains_key(required) {
            return None;
        }
    }

    let wake_id = object.get("wakeId")?.as_str()?.trim();
    let completion_reason = object.get("completionReason")?.as_str()?.trim();
    if wake_id.is_empty() || completion_reason.is_empty() {
        return None;
    }
    object.get("terminalSeen")?.as_bool()?;
    object.get("exitedNaturally")?.as_bool()?;
    match object.get("exitStatus")? {
        serde_json::Value::Null => {}
        value if value.as_i64().is_some() => {}
        _ => return None,
    }
    match object.get("cancelReason")? {
        serde_json::Value::Null => {}
        value if value.as_str().is_some() => {}
        _ => return None,
    }
    if !object
        .get("signals")?
        .as_array()?
        .iter()
        .all(|signal| signal.as_str().is_some())
    {
        return None;
    }
    let terminal_seen = object.get("terminalSeen")?.as_bool()?;
    let hard_deadline_reached = object.get("hardDeadlineReached")?.as_bool()?;
    let managed_scope_terminated = object.get("managedScopeTerminated")?.as_bool()?;
    let cancel_request_id = object
        .get("cancelRequestId")
        .and_then(serde_json::Value::as_str)
        .filter(|request_id| !request_id.trim().is_empty());
    object.get("logBytesRead")?.as_u64()?;
    if !managed_scope_terminated {
        return None;
    }

    let outcome = if terminal_seen {
        "DeliveredTerminal"
    } else if hard_deadline_reached {
        "StoppedByHardDeadline"
    } else if completion_reason == "manual-cancel" && cancel_request_id.is_some() {
        "StoppedByAuthenticatedCancel"
    } else if completion_reason == "natural-exit" {
        "TruncatedNoTerminal"
    } else {
        return None;
    };

    Some(SessionDeathEvidence {
        wake_id: wake_id.to_string(),
        evidence_sha256: sha256_hex(status_json.as_bytes()),
        outcome: outcome.to_string(),
    })
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct SessionDeathDeclaration {
    pub wake_id: String,
    pub evidence: SessionDeathEvidence,
}

pub fn declare_managed_session_dead(
    wake_id: &str,
    evidence: Option<&SessionDeathEvidence>,
) -> Result<SessionDeathDeclaration> {
    if wake_id.trim().is_empty() {
        bail!("managed session death declaration requires a nonblank wakeId");
    }
    let evidence =
        evidence.context("managed session death declaration requires terminal evidence")?;
    if evidence.wake_id != wake_id {
        bail!("managed session death evidence wakeId mismatch");
    }
    Ok(SessionDeathDeclaration {
        wake_id: wake_id.to_string(),
        evidence: evidence.clone(),
    })
}

fn stable_uuid_from_material(material: &str) -> String {
    let mut bytes: [u8; 16] = Sha256::digest(material.as_bytes())[..16]
        .try_into()
        .expect("SHA-256 prefix is sixteen bytes");
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    let encoded = hex::encode(bytes);
    format!(
        "{}-{}-{}-{}-{}",
        &encoded[0..8],
        &encoded[8..12],
        &encoded[12..16],
        &encoded[16..20],
        &encoded[20..32]
    )
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ManagedWakeAttachPlan {
    pub source_wake_id: String,
    pub continuation_wake_id: String,
    pub mode: AttachMode,
    pub death_evidence: SessionDeathEvidence,
}

pub fn plan_managed_wake_attach(
    source_wake_id: &str,
    mode: AttachMode,
    evidence: Option<&SessionDeathEvidence>,
) -> std::result::Result<ManagedWakeAttachPlan, AttachRefusal> {
    let evidence = evidence.ok_or(AttachRefusal::SourceNotProvenTerminal)?;
    if evidence.wake_id != source_wake_id {
        return Err(AttachRefusal::SourceWakeMismatch);
    }
    Ok(ManagedWakeAttachPlan {
        source_wake_id: source_wake_id.to_string(),
        continuation_wake_id: stable_uuid_from_material(&format!(
            "managed-wake-continuation\0{source_wake_id}\0{}",
            mode.as_str()
        )),
        mode,
        death_evidence: evidence.clone(),
    })
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ReviewWakePairing {
    Bound { review_key: String, wake_id: String },
    LegacyUnpaired { review_key: String },
}

/// Pair reviews only through an explicit `wakeId`.  Legacy adjacency, agent
/// equality and timestamp equality are never promoted into a binding.
#[doc(hidden)]
pub fn pair_review_requests_with_wakes(
    events: &[orch_core::EventRecord],
) -> Vec<ReviewWakePairing> {
    let wake_ids = events
        .iter()
        .filter(|event| event.kind == "WakeIssued")
        .filter_map(|event| payload_string(event, "wakeId"))
        .collect::<BTreeSet<_>>();

    events
        .iter()
        .filter(|event| event.kind == "ReviewRequested")
        .map(|event| {
            let payload = event.payload.as_ref();
            let component = |key: &str| {
                payload
                    .and_then(|value| value.get(key))
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("<missing>")
            };
            let review_key = format!(
                "{}:{}:{}:{}",
                event.task_id.as_deref().unwrap_or("<missing>"),
                component("attemptId"),
                component("role"),
                component("agent")
            );
            match payload_string(event, "wakeId") {
                Some(wake_id) if wake_ids.contains(wake_id) => ReviewWakePairing::Bound {
                    review_key,
                    wake_id: wake_id.to_string(),
                },
                _ => ReviewWakePairing::LegacyUnpaired { review_key },
            }
        })
        .collect()
}

const PANEL_LATE_CONVERGENCE_PROOF_DARWIN_PASSIVE_V1: &str = "darwin-passive-v1";

#[derive(Debug, Clone, Default)]
struct ManagedTerminalFrameFacts {
    exact_reason: Option<String>,
    turn_ended: bool,
    final_text_sha256: Option<String>,
    session_id: Option<String>,
    provider: Option<String>,
    model: Option<String>,
    effort: Option<String>,
    usage: Option<serde_json::Value>,
    usage_absent_reason: Option<String>,
}

fn read_managed_terminal_frame(
    log_path: &Path,
    wake: &orch_core::EventRecord,
) -> Result<Option<ManagedTerminalFrameFacts>> {
    read_managed_terminal_frame_with_closure(log_path, wake, false)
}

fn read_managed_terminal_frame_with_closure(
    log_path: &Path,
    wake: &orch_core::EventRecord,
    stream_closed: bool,
) -> Result<Option<ManagedTerminalFrameFacts>> {
    if !log_path.exists() {
        return Ok(None);
    }
    let bytes = fs::read(log_path)
        .with_context(|| format!("read managed wake log failed: {}", log_path.display()))?;
    let driver = payload_string(wake, "driver").or_else(|| payload_string(wake, "harnessId"));
    if driver == Some("smartclaw") {
        let expected_session = payload_string(wake, "requestSessionId")
            .context("SmartClaw WakeIssued missing requestSessionId")?;
        if payload_string(wake, "observationSource")
            == Some(crate::channel::smartclaw::OBSERVATION_SOURCE)
        {
            if !stream_closed {
                bail!(
                    "SmartClaw raw writer closure is unproven; native projection unavailable; HOLD"
                );
            }
            let cwd = Path::new(
                payload_string(wake, "invocationCwd")
                    .context("SmartClaw native observation missing cwd")?,
            );
            let prompt_sha = payload_string(wake, "renderedMessageSha256")
                .context("SmartClaw native observation missing rendered prompt digest")?;
            let database = Path::new(
                payload_string(wake, "nativeDatabasePath")
                    .context("SmartClaw native database path was not captured; HOLD")?,
            );
            if !database.is_absolute()
                || database.components().any(|part| {
                    matches!(
                        part,
                        std::path::Component::CurDir | std::path::Component::ParentDir
                    )
                })
            {
                bail!("SmartClaw captured native database path is not canonical; HOLD");
            }
            let native = crate::channel::smartclaw::inspect_native_final(
                cwd,
                database,
                expected_session,
                cwd,
                prompt_sha,
                &bytes,
                stream_closed,
            )?;
            if native["nativeTerminated"] != true {
                bail!(
                    "SmartClaw native termination unproven; final projection unavailable; HOLD: {}",
                    crate::redact::redact_full(&native["reason"].to_string())
                );
            }
            let projection_path = log_path.with_extension("native-projection.json");
            let metadata =
                serde_json::to_vec_pretty(&crate::channel::smartclaw::without_text(&native))?;
            if native["projectionStatus"] == "available" {
                match fs::symlink_metadata(&projection_path) {
                    Ok(_) => {
                        let captured = crate::channel::capture_attachment_manifest_v1(&[
                            projection_path.as_path(),
                        ])?;
                        if captured.entries()[0].bytes() != metadata {
                            bail!("SmartClaw native projection changed after publication");
                        }
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                        crate::consult::write_new_regular(&projection_path, &metadata)?;
                    }
                    Err(error) => return Err(error).context("inspect native projection path"),
                }
            }
            return Ok(Some(ManagedTerminalFrameFacts {
                exact_reason: Some(if native["projectionStatus"] == "available" {
                    "native-final".into()
                } else {
                    "native-ended-without-valid-final".into()
                }),
                turn_ended: true,
                final_text_sha256: native
                    .pointer("/final/sha256")
                    .and_then(serde_json::Value::as_str)
                    .map(str::to_string),
                session_id: Some(expected_session.to_string()),
                usage_absent_reason: Some(
                    "native projection provides no provider usage receipt".into(),
                ),
                ..ManagedTerminalFrameFacts::default()
            }));
        }
        return parse_smartclaw_payload_terminal_v1(&bytes, expected_session).map(|terminal| {
            terminal.map(|terminal| ManagedTerminalFrameFacts {
                exact_reason: Some("payloads-terminal".to_string()),
                turn_ended: true,
                final_text_sha256: Some(terminal.final_text_sha256),
                session_id: Some(terminal.session_id),
                provider: None,
                model: None,
                effort: None,
                usage: None,
                usage_absent_reason: Some(
                    "SmartClaw payload terminal exposes no mechanical usage object".to_string(),
                ),
            })
        });
    }
    let mut observed = None;
    let mut last_answer: Option<(Option<String>, String)> = None;
    let mut last_session_id: Option<String> = None;
    for line in String::from_utf8_lossy(&bytes).split_inclusive('\n') {
        if matches!(driver, Some("claude" | "codebuddy")) && !line.ends_with('\n') {
            continue;
        }
        let Ok(value) = serde_json::from_str::<serde_json::Value>(&line) else {
            continue;
        };
        let event_type = value.get("type").and_then(serde_json::Value::as_str);
        if let Some(session) = value
            .get("sessionID")
            .or_else(|| value.get("sessionId"))
            .or_else(|| value.get("thread_id"))
            .and_then(serde_json::Value::as_str)
            .filter(|session| !session.trim().is_empty())
        {
            last_session_id = Some(session.to_string());
        }
        let answer_candidate = match driver {
            Some("opencode") if event_type == Some("text") => value
                .pointer("/part/text")
                .and_then(serde_json::Value::as_str),
            Some("codex")
                if event_type == Some("item.completed")
                    && value
                        .pointer("/item/type")
                        .and_then(serde_json::Value::as_str)
                        == Some("agent_message") =>
            {
                value
                    .pointer("/item/text")
                    .and_then(serde_json::Value::as_str)
            }
            _ => None,
        };
        if let Some(text) = answer_candidate.filter(|text| !text.trim().is_empty()) {
            last_answer = Some((last_session_id.clone(), text.to_string()));
        }
        let accepted = match driver {
            Some("claude" | "codebuddy") => claude_family_result_is_success(&value),
            Some("opencode") => {
                event_type == Some("step_finish")
                    && value
                        .pointer("/part/type")
                        .and_then(serde_json::Value::as_str)
                        == Some("step-finish")
                    && value
                        .pointer("/part/reason")
                        .and_then(serde_json::Value::as_str)
                        == Some("stop")
            }
            Some("codex") => event_type == Some("turn.completed"),
            Some("pi") => event_type == Some("pi.terminal"),
            Some("zcode") => event_type == Some("zcode.terminal"),
            Some("dsh") => event_type == Some("dsh.terminal"),
            Some("cursor") => event_type == Some("result"),
            Some("mimo") => event_type == Some("step_finish"),
            Some(_) => false,
            None => matches!(
                event_type,
                Some("pi.terminal" | "zcode.terminal" | "dsh.terminal")
            ),
        };
        if !accepted {
            continue;
        }
        if observed.is_some() {
            bail!(
                "managed wake log contains more than one terminal frame: {}",
                log_path.display()
            );
        }
        let usage = value
            .get("usage")
            .filter(|usage| usage.is_object())
            .cloned();
        let terminal_session = value
            .get("sessionId")
            .or_else(|| value.get("sessionID"))
            .or_else(|| value.get("thread_id"))
            .and_then(serde_json::Value::as_str)
            .filter(|session| !session.trim().is_empty())
            .map(str::to_string)
            .or_else(|| last_session_id.clone());
        let terminal_text = match driver {
            Some("claude" | "cursor" | "codebuddy") => {
                value.get("result").and_then(serde_json::Value::as_str)
            }
            Some("mimo") => value
                .pointer("/part/text")
                .and_then(serde_json::Value::as_str),
            Some("opencode" | "codex") => match last_answer.as_ref() {
                Some((answer_session, text)) if answer_session == &terminal_session => {
                    Some(text.as_str())
                }
                Some(_) => bail!("managed terminal answer session drifted"),
                None => None,
            },
            _ => None,
        };
        let final_text_sha256 = value
            .get("finalTextSha256")
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
            .or_else(|| {
                terminal_text
                    .filter(|text| !text.trim().is_empty())
                    .map(|text| sha256_hex(text.as_bytes()))
            });
        observed = Some(ManagedTerminalFrameFacts {
            exact_reason: value
                .get("exactReason")
                .and_then(serde_json::Value::as_str)
                .filter(|reason| !reason.trim().is_empty())
                .map(str::to_string)
                .or_else(|| Some(format!("{} terminal frame", driver.unwrap_or("managed")))),
            turn_ended: true,
            final_text_sha256,
            session_id: terminal_session,
            provider: value
                .get("provider")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string),
            model: value
                .get("model")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string),
            effort: value
                .get("effort")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string),
            usage,
            usage_absent_reason: value
                .get("usageAbsentReason")
                .and_then(serde_json::Value::as_str)
                .filter(|reason| !reason.trim().is_empty())
                .map(str::to_string),
        });
    }
    Ok(observed)
}

fn receiptless_claude_family_result_promotes_status(
    root: &Path,
    wake: &orch_core::EventRecord,
    status: &WakeSupervisorStatus,
    capability: crate::harness::CapabilitySource,
    log_path: &Path,
    frame: &ManagedTerminalFrameFacts,
) -> Result<bool> {
    let action = match payload_string(wake, "action") {
        Some("consult") => Some(crate::harness::DriverAction::Consult),
        Some("review") => Some(crate::harness::DriverAction::Review),
        Some("execute") => Some(crate::harness::DriverAction::Execute),
        _ => None,
    };
    let nonempty = |key| payload_string(wake, key).is_some_and(|value| !value.trim().is_empty());
    let coherent_scope = match (action, wake.task_id.as_deref()) {
        (Some(crate::harness::DriverAction::Consult), None) => true,
        (
            Some(crate::harness::DriverAction::Review | crate::harness::DriverAction::Execute),
            Some(task),
        ) => {
            !task.trim().is_empty()
                && nonempty("attemptId")
                && (action != Some(crate::harness::DriverAction::Review)
                    || nonempty("reviewOutputPath"))
        }
        _ => false,
    };
    let declared_action = payload_string(wake, "driver")
        .and_then(|driver| crate::harness::HarnessId::parse(driver).ok())
        .zip(action)
        .is_some_and(|(driver, action)| driver.driver_contract(action).is_some());
    if payload_string(wake, "method") != Some("unified-channel-v1")
        || !coherent_scope
        || !declared_action
        || !matches!(payload_string(wake, "driver"), Some("claude" | "codebuddy"))
        || wake
            .payload
            .as_ref()
            .and_then(|payload| payload.get("providerKind"))
            != Some(&serde_json::Value::Null)
        || payload_string(wake, "terminalCapability") != Some("derived")
        || capability != crate::harness::CapabilitySource::Derived
        || status.protocol_revision != WAKE_SUPERVISOR_PROTOCOL_REVISION
        || status.terminal_seen
        || status.completion_reason != ManagedWakeStopReason::NaturalExit
        || !status.exited_naturally
        || status.exit_status != Some(0)
        || status.hard_deadline_reached
        || status.cancel_request_id.is_some()
        || status.cancel_reason.is_some()
        || status.error.is_some()
        || !status.signals.is_empty()
        || !status.managed_scope_terminated
        || !frame.turn_ended
        || frame.final_text_sha256.is_none()
        || payload_string(wake, "wakeId") != Some(status.wake_id.as_str())
    {
        return Ok(false);
    }
    let logs = fs::canonicalize(root.join("coordination/runtime/logs"))?;
    if canonical_parent(log_path)? != logs {
        return Ok(false);
    }
    let metadata = fs::symlink_metadata(log_path).with_context(|| {
        format!(
            "stat Claude-family terminal log failed: {}",
            log_path.display()
        )
    })?;
    Ok(metadata.file_type().is_file()
        && !metadata.file_type().is_symlink()
        && metadata.nlink() == 1
        && metadata.len() == status.log_bytes_read)
}

fn terminal_output_artifact(
    root: &Path,
    wake: &orch_core::EventRecord,
) -> Result<(Option<String>, Option<String>)> {
    let Some(path_text) = payload_string(wake, "reviewOutputPath") else {
        return Ok((None, None));
    };
    let path = PathBuf::from(path_text);
    if !path.is_absolute() || !path.starts_with(root) {
        bail!("WakeIssued reviewOutputPath must remain inside the repository root");
    }
    let Some(bytes) = crate::verify::optional_review_artifact_bytes(
        root,
        &path,
        "unified channel terminal output artifact",
    )?
    else {
        return Ok((None, None));
    };
    if bytes.is_empty() {
        return Ok((None, None));
    }
    Ok((Some(path_text.to_string()), Some(sha256_hex(&bytes))))
}

fn capture_agy_plain_text_review_artifact(
    root: &Path,
    wake: &orch_core::EventRecord,
) -> Result<Option<String>> {
    if payload_string(wake, "providerKind") != Some("agy") {
        return Ok(None);
    }
    let (Some(round), Some(task_id), Some(route_event_id), Some(output_path), Some(log_path)) = (
        wake.round.as_deref(),
        wake.task_id.as_deref(),
        payload_string(wake, "routeEventId"),
        payload_string(wake, "reviewOutputPath"),
        payload_string(wake, "logPath"),
    ) else {
        return Ok(None);
    };
    let output = PathBuf::from(output_path);
    if !output.is_absolute() || !output.starts_with(root) {
        bail!("Agy review output path escaped repository root");
    }
    let events = read_round_ledger_events(root, round)?;
    let routes = events
        .iter()
        .filter(|event| event.event_id == route_event_id)
        .filter_map(|event| {
            let Ok(Some(ledger::RuntimeEventPayloadV1::ReviewSeatRouted(route))) =
                ledger::decode_runtime_event_v1(event)
            else {
                return None;
            };
            Some(route)
        })
        .collect::<Vec<_>>();
    let [route] = routes.as_slice() else {
        bail!("Agy final-text capture 缺唯一 panel route");
    };
    if route.agent != "executor-antigravity"
        || route.wake_id != payload_string(wake, "wakeId").unwrap_or_default()
        || route.reviewed_head != payload_string(wake, "reviewedHead").unwrap_or_default()
    {
        bail!("Agy final-text capture route/wake/head 漂移");
    }
    let expectation = panel_expectation_from_route_v1(round, task_id, route)?;
    let text = fs::read_to_string(log_path).context("Agy final-text log 非 UTF-8")?;
    let path_line = format!("REVIEW_OUTPUT_PATH={output_path}");
    let path_position = text
        .lines()
        .position(|line| line.trim_end_matches('\r') == path_line);
    let Some(path_position) = path_position else {
        return Ok(None);
    };
    let lines = text.lines().collect::<Vec<_>>();
    let mut frontmatter = None::<String>;
    let mut index = path_position + 1;
    while index < lines.len() {
        if lines[index].trim_end_matches('\r') != "```yaml" {
            index += 1;
            continue;
        }
        let mut yaml = String::new();
        index += 1;
        while index < lines.len() && lines[index].trim_end_matches('\r') != "```" {
            yaml.push_str(lines[index]);
            yaml.push('\n');
            index += 1;
        }
        if index < lines.len()
            && crate::verify::check_review_artifact_contract(yaml.as_bytes(), &expectation)
                .is_ok_and(|checked| checked.is_some())
        {
            frontmatter = Some(yaml);
        }
        index += 1;
    }
    let Some(mut artifact) = frontmatter else {
        return Ok(None);
    };
    let body = lines[..path_position]
        .iter()
        .filter(|line| !line.trim().is_empty())
        .filter(|line| serde_json::from_str::<serde_json::Value>(line).is_err())
        .copied()
        .collect::<Vec<_>>()
        .join("\n");
    if body.trim().is_empty() {
        return Ok(None);
    }
    artifact.push_str(&body);
    artifact.push('\n');
    let checked = crate::verify::check_review_artifact_contract(artifact.as_bytes(), &expectation)?
        .context("captured Agy review artifact incomplete")?;
    if checked.substantive_body_len() == 0 {
        return Ok(None);
    }
    let rel = output
        .strip_prefix(root)?
        .to_str()
        .context("Agy captured review path 非 UTF-8")?;
    install_review_no_clobber(root, rel, artifact.as_bytes())?;
    Ok(Some(sha256_hex(body.as_bytes())))
}

fn terminal_record_from_status(
    root: &Path,
    wake: &orch_core::EventRecord,
    status: &WakeSupervisorStatus,
    capability: crate::harness::CapabilitySource,
    events: &[orch_core::EventRecord],
) -> Result<(WakeSupervisorStatus, crate::harness::TerminalRecord)> {
    let log_path = payload_string(wake, "logPath")
        .map(PathBuf::from)
        .context("WakeIssued missing logPath for terminal reconciliation")?;
    let smartclaw_channel = payload_string(wake, "method") == Some("unified-channel-v1")
        && payload_string(wake, "driver") == Some("smartclaw")
        && payload_string(wake, "providerKind") == Some("smartclaw");
    let durable_facts = if payload_string(wake, "providerKind").is_some() {
        Some(durable_receipt_facts(wake)?)
    } else {
        None
    };
    let (accepted_receipt, receiptless_channel) = if let Some(facts) = durable_facts.as_ref() {
        let receipt_count = events
            .iter()
            .filter(|event| {
                event.kind == "AgentEventReceived"
                    && payload_string(event, "agentEvent") == Some("wake-backend-receipt")
                    && (payload_string(event, "actionId") == Some(facts.wake_id.as_str())
                        || payload_string(event, "wakeId") == Some(facts.wake_id.as_str()))
            })
            .count();
        if receipt_count == 0 && facts.channel_binding.is_some() {
            let degraded = events
                .iter()
                .map(|event| degraded_backend_receipt_matches(event, &facts))
                .collect::<Result<Vec<_>>>()?
                .into_iter()
                .filter(|matched| *matched)
                .count();
            if degraded > 1 {
                bail!(
                    "channel terminal found duplicate degraded backend receipts for wakeId={}",
                    facts.wake_id
                );
            }
            (None, true)
        } else {
            (
                Some(require_exact_accepted_backend_receipt(events, facts)?.clone()),
                false,
            )
        }
    } else {
        (None, false)
    };
    let mut trusted_status = status.clone();
    if receiptless_channel {
        trusted_status.terminal_seen = false;
    }
    if smartclaw_channel {
        // SmartClaw declares derived, not native, terminal authority. Ignore
        // every generic-supervisor terminal bit; only the exact receipt,
        // session and payload proof below may promote this channel again.
        trusted_status.terminal_seen = false;
    }
    // New SmartClaw generations require native termination even when no backend
    // acceptance receipt arrived. A killed socket client cannot release its site.
    let native_frame = if smartclaw_channel
        && payload_string(wake, "observationSource")
            == Some(crate::channel::smartclaw::OBSERVATION_SOURCE)
    {
        // This authenticated immutable status is published only after local
        // capture/cleanup. It licenses closed-log parsing, not native death.
        Some(
            read_managed_terminal_frame_with_closure(
                &log_path,
                wake,
                trusted_status.managed_scope_terminated && trusted_status.error.is_none(),
            )?
            .context(
                "SmartClaw native projection unavailable because the raw log is missing; HOLD",
            )?,
        )
    } else {
        None
    };
    let mut frame = if receiptless_channel {
        ManagedTerminalFrameFacts::default()
    } else if let Some(native_frame) = native_frame {
        native_frame
    } else {
        read_managed_terminal_frame(&log_path, wake)?.unwrap_or_default()
    };
    if receiptless_claude_family_result_promotes_status(
        root,
        wake,
        &trusted_status,
        capability,
        &log_path,
        &frame,
    )? {
        trusted_status.terminal_seen = true;
    }
    if let Some(receipt) = accepted_receipt.as_ref() {
        if let (Some(terminal_session), Some(receipt_session)) = (
            frame.session_id.as_deref(),
            payload_string(receipt, "observedSessionId"),
        ) {
            if terminal_session != receipt_session {
                bail!("terminal sessionId 与 accepted backend receipt 不一致");
            }
        }
        for (key, terminal_value) in [
            ("requestedProvider", frame.provider.as_deref()),
            ("requestedModel", frame.model.as_deref()),
            ("requestedEffort", frame.effort.as_deref()),
        ] {
            if let Some(terminal_value) = terminal_value {
                if payload_string(receipt, key) != Some(terminal_value) {
                    bail!("terminal {key} 与 accepted backend receipt 不一致");
                }
            }
        }
    }
    if !receiptless_channel {
        if let Some(final_text_sha256) = capture_agy_plain_text_review_artifact(root, wake)? {
            frame.final_text_sha256 = Some(final_text_sha256);
        }
    }
    let (output_path, output_sha256) = if receiptless_channel {
        (None, None)
    } else {
        terminal_output_artifact(root, wake)?
    };
    let driver_action = match payload_string(wake, "action") {
        Some("execute") => Some(crate::harness::DriverAction::Execute),
        Some("review") => Some(crate::harness::DriverAction::Review),
        Some("consult") => Some(crate::harness::DriverAction::Consult),
        _ => None,
    };
    let wrapper_codes = payload_string(wake, "method") != Some("unified-channel-v1")
        || (trusted_status.hard_deadline_reached && !trusted_status.terminal_seen)
        || payload_string(wake, "driver")
            .and_then(|driver| crate::harness::HarnessId::parse(driver).ok())
            .zip(driver_action)
            .and_then(|(driver, action)| driver.driver_contract(action))
            .is_some_and(|contract| contract.wrapper.is_some());
    let reserved_exit = trusted_status
        .exit_status
        .filter(|_| wrapper_codes)
        .and_then(|code| WRAPPER_EXIT_CODES.iter().find(|entry| entry.code == code));
    let exact_reason = if receiptless_channel {
        "backend acceptance receipt absent before terminal reconciliation".to_string()
    } else {
        frame
            .exact_reason
            .clone()
            .or_else(|| trusted_status.error.clone())
            .or_else(|| {
                trusted_status
                    .cancel_reason
                    .clone()
                    .filter(|reason| !reason.trim().is_empty())
            })
            .unwrap_or_else(|| trusted_status.completion_reason.ledger_name().to_string())
    };
    let usage_present = frame.usage.is_some();
    let usage_absent_reason = frame.usage_absent_reason.or_else(|| {
        if usage_present {
            None
        } else {
            Some(format!(
                "provider usage unavailable after {}",
                reserved_exit
                    .map(|entry| entry.reason)
                    .unwrap_or("provider-native-exit")
            ))
        }
    });
    let provider_terminal_wins = trusted_status.terminal_seen;
    let native_answer_authoritative = smartclaw_channel
        && payload_string(wake, "observationSource")
            == Some(crate::channel::smartclaw::OBSERVATION_SOURCE)
        && frame.exact_reason.as_deref() == Some("native-final")
        && frame.final_text_sha256.is_some()
        && trusted_status.completion_reason == ManagedWakeStopReason::NaturalExit
        && trusted_status.exited_naturally
        && trusted_status.error.is_none()
        && trusted_status.signals.is_empty()
        && !trusted_status.hard_deadline_reached
        && trusted_status.cancel_request_id.is_none()
        && trusted_status.cancel_reason.is_none()
        && (trusted_status.exit_status == Some(0)
            || crate::harness::wrapper_exit_is_transport_eof(trusted_status.exit_status));
    let exit_code = if native_answer_authoritative {
        None // native observation, not the separately retained socket-client status
    } else if receiptless_channel
        && matches!(
            managed_wake_outcome_from_status(&trusted_status),
            ManagedWakeOutcomeClass::OperationalError(_)
        )
    {
        Some(3)
    } else if trusted_status.error.is_some() {
        Some(3)
    } else if trusted_status.hard_deadline_reached && !provider_terminal_wins {
        Some(72)
    } else {
        trusted_status.exit_status
    };
    let agy_natural_turn_end = payload_string(wake, "providerKind") == Some("agy")
        && !receiptless_channel
        && trusted_status.exited_naturally
        && trusted_status.exit_status == Some(0);
    let mut record = crate::harness::classify_terminal_observation_with_wrapper_codes(
        crate::harness::TerminalObservation {
            capability,
            exit_code,
            exact_reason,
            turn_ended: trusted_status.terminal_seen || frame.turn_ended || agy_natural_turn_end,
            final_text: None,
            final_text_sha256: frame.final_text_sha256,
            output_path,
            output_sha256,
            usage: frame.usage,
            usage_absent_reason,
            managed_scope_terminated: trusted_status.managed_scope_terminated,
            activity_seen: trusted_status.log_bytes_read > 0,
            authenticated_cancel: !provider_terminal_wins
                && trusted_status
                    .cancel_request_id
                    .as_deref()
                    .is_some_and(|request_id| !request_id.trim().is_empty()),
        },
        wrapper_codes,
    )?;
    let expected_session = durable_facts
        .as_ref()
        .and_then(|facts| facts.request_session_id.as_deref());
    let accepted_session = accepted_receipt
        .as_ref()
        .and_then(|receipt| payload_string(receipt, "observedSessionId"));
    let review_output_complete = payload_string(wake, "action") != Some("review")
        || (record.output_path.is_some() && record.output_sha256.is_some());
    let trusted_smartclaw_channel_answer = durable_facts.as_ref().is_some_and(|facts| {
        smartclaw_channel
            && facts.provider_kind == BackendReceiptKind::SmartClaw
            && facts.channel_binding.is_some()
            && capability == crate::harness::CapabilitySource::Derived
            && !receiptless_channel
            && accepted_receipt.is_some()
            && frame.session_id.as_deref() == expected_session
            && accepted_session == expected_session
            && frame.exact_reason.as_deref()
                == Some(
                    if payload_string(wake, "observationSource")
                        == Some(crate::channel::smartclaw::OBSERVATION_SOURCE)
                    {
                        "native-final"
                    } else {
                        "payloads-terminal"
                    },
                )
            && frame.turn_ended
            && record.state == crate::harness::TerminalState::Answered
            && record.turn_ended
            && record.final_text_sha256.is_some()
            && trusted_status.completion_reason == ManagedWakeStopReason::NaturalExit
            && trusted_status.exited_naturally
            && (native_answer_authoritative || trusted_status.exit_status == Some(0))
            && !trusted_status.hard_deadline_reached
            && trusted_status.cancel_request_id.is_none()
            && trusted_status.cancel_reason.is_none()
            && trusted_status.error.is_none()
            && trusted_status.signals.is_empty()
            && trusted_status.managed_scope_terminated
    });
    if trusted_smartclaw_channel_answer {
        trusted_status.terminal_seen = true;
    } else if smartclaw_channel && record.state == crate::harness::TerminalState::Answered {
        record.state = match managed_wake_outcome_from_status(&trusted_status) {
            ManagedWakeOutcomeClass::TruncatedNoTerminal => crate::harness::TerminalState::Empty,
            ManagedWakeOutcomeClass::OperationalError(_) => crate::harness::TerminalState::Failed,
            ManagedWakeOutcomeClass::DeliveredTerminal
            | ManagedWakeOutcomeClass::StoppedByHardDeadline
            | ManagedWakeOutcomeClass::StoppedByAuthenticatedCancel => {
                bail!("untrusted SmartClaw answer conflicts with managed outcome")
            }
        };
        record.exact_reason =
            "SmartClaw terminal proof did not satisfy exact receipt/session/payload authority"
                .to_string();
        record.turn_ended = false;
        record.final_text_sha256 = None;
        record.output_path = None;
        record.output_sha256 = None;
    }
    if payload_string(wake, "method") == Some("unified-channel-v1")
        && payload_string(wake, "action") == Some("review")
        && record.state == crate::harness::TerminalState::Answered
        && !review_output_complete
    {
        record.state = crate::harness::TerminalState::Empty;
        record.exact_reason =
            "trusted review terminal omitted a stable output artifact".to_string();
        record.final_text_sha256 = None;
        record.output_path = None;
        record.output_sha256 = None;
    }
    Ok((trusted_status, record))
}

fn validate_unified_channel_terminal_shape(
    wake: &orch_core::EventRecord,
    terminal: &orch_core::EventRecord,
) -> Result<()> {
    if payload_string(wake, "method") != Some("unified-channel-v1") {
        return Ok(());
    }
    validate_existing_channel_action_binding(wake, terminal)?;
    let review_action = payload_string(wake, "action") == Some("review");
    if !crate::generic_review::unified_channel_terminal_closed_v1(terminal, review_action) {
        bail!("channel terminal state/outcome matrix is internally inconsistent");
    }
    Ok(())
}

fn terminal_capability_from_wake(
    wake: &orch_core::EventRecord,
) -> Result<Option<crate::harness::CapabilitySource>> {
    let value = wake
        .payload
        .as_ref()
        .and_then(|payload| payload.get("terminalCapability"))
        .cloned();
    match value {
        None | Some(serde_json::Value::Null) => Ok(None),
        Some(value) => serde_json::from_value(value)
            .map(Some)
            .context("WakeIssued terminalCapability is invalid"),
    }
}

fn managed_wake_terminated_event_with_record(
    round: &str,
    task_id: Option<&str>,
    status: &WakeSupervisorStatus,
    record: crate::harness::TerminalRecord,
) -> orch_core::EventRecord {
    let mut event = managed_wake_terminated_event(round, task_id, status);
    if let Some(payload) = event.payload.as_mut() {
        payload["state"] = serde_json::json!(record.state.as_str());
        payload["exactReason"] = serde_json::json!(record.exact_reason);
        payload["turnEnded"] = serde_json::json!(record.turn_ended);
        payload["finalTextSha256"] = serde_json::json!(record.final_text_sha256);
        payload["outputPath"] = serde_json::json!(record.output_path);
        payload["outputSha256"] = serde_json::json!(record.output_sha256);
        payload["usage"] = record.usage.unwrap_or(serde_json::Value::Null);
        payload["usageAbsentReason"] = serde_json::json!(record.usage_absent_reason);
        payload["managedScopeTerminated"] = serde_json::json!(record.managed_scope_terminated);
        payload["mechanicalTerminalAbsent"] = serde_json::json!(record.mechanical_terminal_absent);
    }
    event
}

fn managed_wake_terminal_absent_event(
    round: &str,
    task_id: Option<&str>,
    wake_id: &str,
    agent: &str,
) -> Result<orch_core::EventRecord> {
    let record =
        crate::harness::classify_terminal_observation(crate::harness::TerminalObservation {
            capability: crate::harness::CapabilitySource::Absent,
            exit_code: None,
            exact_reason: "harness descriptor declares terminal capability absent".to_string(),
            turn_ended: false,
            final_text: None,
            final_text_sha256: None,
            output_path: None,
            output_sha256: None,
            usage: None,
            usage_absent_reason: Some(
                "harness descriptor exposes no mechanical usage source".to_string(),
            ),
            managed_scope_terminated: false,
            activity_seen: false,
            authenticated_cancel: false,
        })?;
    Ok(ledger::event(
        "ManagedWakeTerminalAbsent",
        "runtime:orch",
        task_id,
        Some(round),
        serde_json::json!({
            "wakeId": wake_id,
            "agent": agent,
            "state": record.state.as_str(),
            "exactReason": record.exact_reason,
            "turnEnded": record.turn_ended,
            "finalTextSha256": record.final_text_sha256,
            "outputPath": record.output_path,
            "outputSha256": record.output_sha256,
            "usage": record.usage,
            "usageAbsentReason": record.usage_absent_reason,
            "managedScopeTerminated": record.managed_scope_terminated,
            "mechanicalTerminalAbsent": record.mechanical_terminal_absent,
        }),
    ))
}

fn managed_wake_terminated_event(
    round: &str,
    task_id: Option<&str>,
    status: &WakeSupervisorStatus,
) -> orch_core::EventRecord {
    let outcome = managed_wake_outcome_from_status(status);
    ledger::event(
        "ManagedWakeTerminated",
        "runtime:orch",
        task_id,
        Some(round),
        serde_json::json!({
            "wakeId": status.wake_id,
            "agent": status.agent,
            "completionReason": status.completion_reason.ledger_name(),
            "terminalSeen": status.terminal_seen,
            "exitedNaturally": status.exited_naturally,
            "hardDeadlineReached": status.hard_deadline_reached,
            "cancelRequestId": status.cancel_request_id,
            "signals": status.signals,
            "managedScopeTerminated": status.managed_scope_terminated,
            "processTreeTerminated": status.process_tree_terminated,
            "logBytesRead": status.log_bytes_read,
            "lastFrameAgeSecs": status.last_frame_age_secs,
            "lastFrameSummary": status.last_frame_summary,
            "fullCredentialInspections": status.full_credential_inspections,
            "observationDiagnostics": status.observation_diagnostics,
            "upstreamTermination": "unconfirmed",
            "runtimeLimit": {
                "requested": status.runtime_limit.requested_review_deadline_secs,
                "effective": status.runtime_limit.effective_secs,
                "source": status.runtime_limit.source.ledger_name(),
            },
            "elapsedSecs": status.elapsed_secs,
            "outcomeClass": outcome.ledger_name(),
        }),
    )
}

fn managed_wake_outcome_from_status(status: &WakeSupervisorStatus) -> ManagedWakeOutcomeClass {
    let facts = ManagedWakeTerminationFacts {
        wake_id: status.wake_id.clone(),
        agent: status.agent.clone().unwrap_or_default(),
        completion_reason: Some(status.completion_reason.ledger_name().to_string()),
        terminal_seen: status.terminal_seen,
        exited_naturally: status.exited_naturally,
        hard_deadline_reached: status.hard_deadline_reached,
        cancel_request_id: status.cancel_request_id.clone(),
        signals: status.signals.clone(),
        managed_scope_terminated: status.managed_scope_terminated,
        log_bytes_read: status.log_bytes_read,
    };
    if status.error.is_some() || status.agent.is_none() || status.elapsed_secs.is_none() {
        ManagedWakeOutcomeClass::OperationalError(
            "immutable terminal status is incomplete or reports an error".to_string(),
        )
    } else {
        classify_managed_wake_outcome(&facts)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SmartClawPayloadTerminalV1 {
    session_id: String,
    final_text: String,
    final_text_sha256: String,
    duration_ms: Option<u64>,
}

fn parse_smartclaw_payload_terminal_v1(
    log: &[u8],
    expected_session_id: &str,
) -> Result<Option<SmartClawPayloadTerminalV1>> {
    let mut observed = None;
    for framed in log.split_inclusive(|byte| *byte == b'\n') {
        // split_inclusive returns the final unterminated tail as a slice.  It
        // is deliberately ignored: a partial JSON object is never terminal.
        if framed.last() != Some(&b'\n') {
            continue;
        }
        let mut body = &framed[..framed.len() - 1];
        if body.last() == Some(&b'\r') {
            body = &body[..body.len() - 1];
        }
        let Ok(value) = serde_json::from_slice::<serde_json::Value>(body) else {
            continue;
        };
        let Some(object) = value.as_object() else {
            continue;
        };
        let Some(payloads) = object.get("payloads") else {
            // Nested or substring occurrences do not reach this top-level key.
            continue;
        };
        if observed.is_some() {
            bail!("SmartClaw wake log contains duplicate top-level payloads terminals");
        }
        let payloads = payloads
            .as_array()
            .filter(|items| !items.is_empty())
            .context("SmartClaw top-level payloads must be a non-empty array")?;
        let mut final_text = String::new();
        for payload in payloads {
            let text = payload
                .as_object()
                .and_then(|item| item.get("text"))
                .and_then(serde_json::Value::as_str)
                .filter(|text| !text.is_empty())
                .context("SmartClaw terminal payload lacks non-empty text")?;
            final_text.push_str(text);
        }
        let session_id = object
            .get("meta")
            .and_then(|meta| meta.get("agentMeta"))
            .and_then(|meta| meta.get("sessionId"))
            .and_then(serde_json::Value::as_str)
            .filter(|session| !session.is_empty())
            .context("SmartClaw terminal lacks meta.agentMeta.sessionId")?;
        if session_id != expected_session_id {
            bail!("SmartClaw terminal nested sessionId does not match runtime session");
        }
        if object
            .get("sessionId")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|session| session != expected_session_id)
        {
            bail!("SmartClaw terminal top-level sessionId drifted");
        }
        observed = Some(SmartClawPayloadTerminalV1 {
            session_id: session_id.to_string(),
            final_text: final_text.clone(),
            final_text_sha256: sha256_hex(final_text.as_bytes()),
            duration_ms: object
                .get("meta")
                .and_then(|meta| meta.get("durationMs"))
                .and_then(serde_json::Value::as_u64),
        });
    }
    Ok(observed)
}

/// Test seam for the LF framing and exact nested-session portion of the
/// SmartClaw terminal parser.  It performs no ledger or filesystem mutation;
/// production additionally requires the unified channel receipt, session and
/// managed-status envelope before emitting a terminal fact.
#[doc(hidden)]
pub fn validate_smartclaw_payload_terminal_for_test(
    log: &[u8],
    expected_session_id: &str,
) -> Result<Option<(String, String)>> {
    parse_smartclaw_payload_terminal_v1(log, expected_session_id)
        .map(|terminal| terminal.map(|terminal| (terminal.session_id, terminal.final_text_sha256)))
}

/// Admit reconciliation only for an open schema-3 generation. Closed rounds
/// and markerless schema-1/2 history are immutable observations and return a
/// zero-action decision before any identity lock, provider probe, or append.
fn live_schema3_reconciliation_allowed(
    events: &[orch_core::EventRecord],
    round: &str,
) -> Result<bool> {
    let closed = events
        .iter()
        .filter(|event| event.kind == "RoundClosed")
        .collect::<Vec<_>>();
    if !closed.is_empty() {
        let [closed] = closed.as_slice() else {
            bail!("backend reconciliation 拒绝重复 RoundClosed");
        };
        if closed.actor != "runtime:orch"
            || closed.task_id.is_some()
            || closed.round.as_deref() != Some(round)
        {
            bail!("backend reconciliation 拒绝非 canonical RoundClosed");
        }
        return Ok(false);
    }
    Ok(crate::round::contract_schema_from_events(events, round)?
        == Some(crate::plan::ACTORLESS_ROUND_IR_SCHEMA_VERSION))
}

/// Reconcile one immutable managed-wake status into the round ledger.  The
/// status read occurs inside `append_checked`'s ledger critical section, so
/// concurrent daemon ticks and exact retries can append at most one fact.
fn reconcile_managed_wake_termination_locked(
    root: &Path,
    round: &str,
    wake_id: &str,
) -> Result<bool> {
    let appended = ledger::append_checked(root, round, |events| {
        if !live_schema3_reconciliation_allowed(events, round)? {
            return Ok(Vec::new());
        }
        let existing = events
            .iter()
            .filter(|event| {
                event.kind == "ManagedWakeTerminated"
                    && payload_string(event, "wakeId") == Some(wake_id)
            })
            .collect::<Vec<_>>();
        if existing.len() > 1 {
            bail!(
                "managed wake termination ledger already contains {} facts for wakeId={wake_id}",
                existing.len()
            );
        }
        if let [terminal] = existing.as_slice() {
            let wakes = events
                .iter()
                .filter(|event| {
                    event.kind == "WakeIssued" && payload_string(event, "wakeId") == Some(wake_id)
                })
                .collect::<Vec<_>>();
            let [wake] = wakes.as_slice() else {
                bail!(
                    "managed wake terminal replay requires one WakeIssued for wakeId={wake_id}, found {}",
                    wakes.len()
                );
            };
            validate_existing_channel_action_binding(wake, terminal)?;
            return Ok(Vec::new());
        }

        let wakes = events
            .iter()
            .filter(|event| {
                event.kind == "WakeIssued" && payload_string(event, "wakeId") == Some(wake_id)
            })
            .collect::<Vec<_>>();
        if wakes.len() != 1 {
            bail!(
                "managed wake termination requires exactly one WakeIssued for wakeId={wake_id}, found {}",
                wakes.len()
            );
        }
        let wake = wakes[0];
        let terminal_capability = terminal_capability_from_wake(wake)?;
        let Some(control_wake_id) = payload_string(wake, "controlWakeId") else {
            return match terminal_capability {
                None => Ok(Vec::new()),
                Some(crate::harness::CapabilitySource::Absent) => {
                    let absent = events
                        .iter()
                        .filter(|event| {
                            event.kind == "ManagedWakeTerminalAbsent"
                                && payload_string(event, "wakeId") == Some(wake_id)
                        })
                        .count();
                    if absent > 1 {
                        bail!(
                            "managed wake contains {absent} terminal-absence facts for wakeId={wake_id}"
                        );
                    }
                    if absent == 1 {
                        let terminal = events
                            .iter()
                            .find(|event| {
                                event.kind == "ManagedWakeTerminalAbsent"
                                    && payload_string(event, "wakeId") == Some(wake_id)
                            })
                            .expect("absent count proved one terminal");
                        validate_existing_channel_action_binding(wake, terminal)?;
                        Ok(Vec::new())
                    } else {
                        let agent = payload_string(wake, "agent")
                            .context("WakeIssued missing agent")?;
                        let mut terminal = managed_wake_terminal_absent_event(
                            round,
                            wake.task_id.as_deref(),
                            wake_id,
                            agent,
                        )?;
                        attach_channel_action_binding(wake, &mut terminal)?;
                        Ok(vec![terminal])
                    }
                }
                Some(crate::harness::CapabilitySource::Derived)
                    if payload_string(wake, "providerKind") == Some("smartclaw") =>
                {
                    // Unified SmartClaw actions now publish an authenticated
                    // control/status descriptor. Descriptor-less Panel bridges
                    // are historical evidence and never mint a new terminal.
                    Ok(Vec::new())
                }
                Some(
                    crate::harness::CapabilitySource::Native
                    | crate::harness::CapabilitySource::Derived,
                ) => bail!(
                    "terminal-capable harness lacks a managed control descriptor for wakeId={wake_id}"
                ),
            };
        };
        if control_wake_id != wake_id {
            bail!("managed wake termination controlWakeId does not match wakeId");
        }

        let (dir, descriptor) = read_managed_wake_control_descriptor(root, wake_id)?;
        if !descriptor.status_path.exists() {
            return Ok(Vec::new());
        }
        let body = secure_read_lf_frame(
            &descriptor.status_path,
            &dir,
            MAX_MANAGED_WAKE_CONTROL_BYTES,
        )?;
        let status: WakeSupervisorStatus = serde_json::from_slice(&body)
            .context("parse immutable managed wake terminal status failed")?;
        if status.protocol_revision != descriptor.protocol_revision
            || status.token != descriptor.token
            || status.wake_id != descriptor.wake_id
            || status.runtime_limit != descriptor.runtime_limit
        {
            bail!("immutable managed wake terminal status identity/protocol/runtime mismatch");
        }

        let wake_agent = payload_string(wake, "agent").context("WakeIssued missing agent")?;
        if status
            .agent
            .as_deref()
            .is_some_and(|status_agent| status_agent != wake_agent)
        {
            bail!("immutable managed wake terminal status agent mismatch");
        }
        let wake_runtime: ManagedWakeRuntimeLimit = wake
            .payload
            .as_ref()
            .and_then(|payload| payload.get("runtimeLimit"))
            .cloned()
            .map(serde_json::from_value)
            .transpose()
            .context("WakeIssued runtimeLimit is invalid")?
            .context("managed WakeIssued is missing runtimeLimit")?;
        if wake_runtime != status.runtime_limit {
            bail!("immutable managed wake terminal status differs from WakeIssued runtimeLimit");
        }

        let effective_status = status.clone();

        let mut terminated = if let Some(capability) = terminal_capability {
            if capability == crate::harness::CapabilitySource::Absent {
                bail!("terminal-absent harness unexpectedly produced a managed status descriptor");
            }
            let (effective_status, terminal_record) =
                terminal_record_from_status(root, wake, &effective_status, capability, events)?;
            managed_wake_terminated_event_with_record(
                round,
                wake.task_id.as_deref(),
                &effective_status,
                terminal_record,
            )
        } else {
            // Legacy WakeIssued facts predate harness capability binding and
            // retain their byte-compatible terminal event shape.
            managed_wake_terminated_event(round, wake.task_id.as_deref(), &effective_status)
        };
        attach_channel_action_binding(wake, &mut terminated)?;
        validate_unified_channel_terminal_shape(wake, &terminated)?;
        let released = crate::sites::workspace_release_for_termination(events, round, &terminated)?;
        if recorded_generic_review_wake(events, round, wake)?
            && events.iter().any(|event| {
                event.kind == "WorkspaceLeased" && payload_string(event, "wakeId") == Some(wake_id)
            })
            && released.is_none()
        {
            return Ok(Vec::new());
        }
        let mut facts = vec![terminated];
        if let Some(released) = released {
            facts.push(released);
        }
        Ok(facts)
    })?;
    Ok(appended > 0)
}

fn generic_review_wake_v1(wake: &orch_core::EventRecord, round: &str) -> Result<bool> {
    if wake.kind != "WakeIssued" || wake.round.as_deref() != Some(round) {
        return Ok(false);
    }
    let unified = payload_string(wake, "method") == Some("unified-channel-v1")
        && payload_string(wake, "action") == Some("review");
    let historical_b319 = wake.task_id.as_deref() == Some("B319")
        && wake
            .payload
            .as_ref()
            .is_some_and(|payload| payload.get("bootstrapSourceSha256").is_some());
    if !unified && !historical_b319 {
        return Ok(false);
    }
    let task = wake
        .task_id
        .as_deref()
        .context("generic WakeIssued 缺 taskId")?;
    let attempt = payload_string(wake, "attemptId").context("generic WakeIssued 缺 attemptId")?;
    let agent = payload_string(wake, "agent").context("generic WakeIssued 缺 agent")?;
    let wake_id = payload_string(wake, "wakeId").context("generic WakeIssued 缺 wakeId")?;
    let expected = format!("review:{round}:{task}:{attempt}:review:{agent}");
    if payload_string(wake, "continuationId") != Some(expected.as_str())
        || wake_id.trim().is_empty()
        || (unified
            && (payload_string(wake, "harness") != Some(agent)
                || channel_action_binding_from_wake(wake)?.is_none()))
    {
        bail!("generic WakeIssued identity/channel binding 漂移");
    }
    Ok(true)
}

fn recorded_generic_review_wake(
    events: &[orch_core::EventRecord],
    round: &str,
    wake: &orch_core::EventRecord,
) -> Result<bool> {
    if !generic_review_wake_v1(wake, round)? {
        return Ok(false);
    }
    let Some(task_id) = wake.task_id.as_deref() else {
        return Ok(false);
    };
    Ok(events.iter().any(|event| {
        event.kind == "TaskRecorded"
            && event.actor == "runtime:orch"
            && event.round.as_deref() == Some(round)
            && event.task_id.as_deref() == Some(task_id)
            && event
                .payload
                .as_ref()
                .and_then(|payload| payload.get("postMergeGates"))
                .and_then(serde_json::Value::as_str)
                == Some("all-green")
    }))
}

fn rooted_generic_review_wake(
    events: &[orch_core::EventRecord],
    round: &str,
    wake: &orch_core::EventRecord,
) -> Result<bool> {
    if !generic_review_wake_v1(wake, round)? {
        return Ok(false);
    }
    let (Some(task_id), Some(attempt_id)) =
        (wake.task_id.as_deref(), payload_string(wake, "attemptId"))
    else {
        return Ok(false);
    };
    Ok(events.iter().any(|event| {
        event.kind == "VerdictIssued"
            && event.actor == "verifier:root"
            && event.round.as_deref() == Some(round)
            && event.task_id.as_deref() == Some(task_id)
            && payload_string(event, "attemptId") == Some(attempt_id)
    }))
}

/// Reconcile exactly one managed wake into its authenticated terminal and
/// adjacent workspace release without touching unrelated actions. Legacy or
/// closed generations return `false` before inspecting managed sidecars.
pub(crate) fn reconcile_managed_wake_termination(
    root: &Path,
    round: &str,
    wake_id: &str,
) -> Result<bool> {
    reconcile_managed_wake_termination_with_maintenance(root, round, wake_id, true)
}

fn reconcile_managed_wake_termination_with_maintenance(
    root: &Path,
    round: &str,
    wake_id: &str,
    maintain: bool,
) -> Result<bool> {
    let events = read_round_ledger_events(root, round)?;
    if !live_schema3_reconciliation_allowed(&events, round)? {
        return Ok(false);
    }
    let wake = events
        .iter()
        .find(|event| {
            event.kind == "WakeIssued" && payload_string(event, "wakeId") == Some(wake_id)
        })
        .with_context(|| format!("no WakeIssued for wakeId={wake_id}"))?;
    let agent = payload_string(wake, "agent").context("WakeIssued missing agent")?;
    let appended = with_wake_identity_lock_wait(root, agent, || {
        reconcile_managed_wake_termination_locked(root, round, wake_id)
    })?;
    if appended && maintain {
        match crate::reclaim::maintain_storage_for_round(root, Some(round), false) {
            Ok(report) => {
                for line in crate::reclaim::maintenance_summary(&report) {
                    eprintln!(
                        "[orch] storage maintenance after authenticated native release: {line}"
                    );
                }
            }
            Err(error) => {
                eprintln!("[orch] native release retained; storage maintenance failed: {error:#}")
            }
        }
    }
    Ok(appended)
}

