/// Whether the ordinary all-process topology snapshot can observe an exact
/// PID. This does not promote the row to an owned receipt.
#[doc(hidden)]
pub fn managed_process_topology_snapshot_contains(pid: u32) -> Result<bool> {
    Ok(process_topology_snapshot()?.contains_key(&pid))
}

/// Project the ordinary process-table snapshot to init-adopted rows while retaining the fields
/// needed for consumer-side ownership/noise filtering.
#[doc(hidden)]
pub fn managed_ppid1_pids() -> Result<BTreeMap<u32, ManagedProcessTopology>> {
    Ok(process_topology_snapshot()?
        .into_iter()
        .filter(|(_, row)| row.observed_ppid == 1)
        .collect())
}

/// Cheap per-PID process epoch lookup used by the gate fixture registry's PID-reuse fence.
#[doc(hidden)]
pub fn managed_process_birth_identity(pid: u32) -> Result<Option<String>> {
    Ok(inspect_topology(pid)?.map(|topology| topology.birth_identity))
}

#[doc(hidden)]
pub fn provider_identity_worst_case_settle_ms(inspections: u32) -> u64 {
    PROVIDER_IDENTITY_SETTLE_WINDOW_MS * u64::from(inspections)
}

#[doc(hidden)]
pub fn canary_provider_lifetime_secs() -> u64 {
    const CANARY_TOPOLOGY_INSPECTIONS: u32 = 3;
    let required_ms = provider_identity_worst_case_settle_ms(CANARY_TOPOLOGY_INSPECTIONS) * 2;
    required_ms.div_ceil(1_000)
}

fn exact_gate_group_member_epochs(
    census: &ProcessTopologyCensus,
    member_pids: &[u32],
    pgid: u32,
) -> Result<Vec<(u32, String, bool)>> {
    member_pids
        .iter()
        .map(
            |pid| match exact_group_member_observation(census, *pid, pgid)? {
                ExactGroupMemberObservation::Live(topology) => {
                    if topology.birth_identity.is_empty() {
                        bail!("exact live group member pid {pid} lacks birth identity");
                    }
                    Ok((topology.pid, topology.birth_identity, false))
                }
                ExactGroupMemberObservation::Zombie(zombie) => Ok((
                    zombie.pid,
                    zombie
                        .birth_identity
                        .context("exact zombie group member lacks birth identity")?,
                    true,
                )),
            },
        )
        .collect()
}

#[cfg(target_os = "macos")]
fn exact_gate_group_local_census(member_pids: &[u32]) -> Result<ProcessTopologyCensus> {
    let listed_pids = member_pids.iter().copied().collect::<BTreeSet<_>>();
    let mut topology = BTreeMap::new();
    let mut opaque_zombies = BTreeMap::new();
    for pid in member_pids {
        match inspect_darwin_full_topology(*pid)
            .with_context(|| format!("inspect exact gate group member pid {pid}"))?
        {
            DarwinFullTopologyRead::Exact(row) => {
                if let Some(sidless) = sidless_zombie_containment_proof(&row) {
                    opaque_zombies.insert(*pid, sidless);
                }
                topology.insert(*pid, row);
            }
            DarwinFullTopologyRead::Missing | DarwinFullTopologyRead::PermissionDenied => {
                let fallback = inspect_darwin_fallback_process(*pid)
                    .with_context(|| format!("inspect exact gate group fallback pid {pid}"))?;
                record_darwin_fallback_census_row(
                    *pid,
                    fallback,
                    &mut topology,
                    &mut opaque_zombies,
                )?;
            }
        }
    }
    Ok(ProcessTopologyCensus {
        listed_pids,
        topology,
        opaque_zombies,
    })
}

#[cfg(not(target_os = "macos"))]
fn exact_gate_group_local_census(member_pids: &[u32]) -> Result<ProcessTopologyCensus> {
    let listed_pids = member_pids.iter().copied().collect::<BTreeSet<_>>();
    let mut topology = BTreeMap::new();
    for pid in member_pids {
        if let Some(row) = inspect_topology(*pid)? {
            topology.insert(*pid, row);
        }
    }
    Ok(ProcessTopologyCensus {
        listed_pids,
        topology,
        opaque_zombies: BTreeMap::new(),
    })
}

/// Narrow gate-cleanup observation seam.  The two topology/exact-member
/// snapshots must describe the same immutable epochs; a changing or
/// unprovable group is an error, while `None` is exact ESRCH-backed absence.
pub(crate) fn observe_exact_gate_group_members(
    pgid: u32,
) -> Result<Option<Vec<(u32, String, bool)>>> {
    let mut last_ambiguity = String::new();
    for sample in 1..=3 {
        let first_pids = exact_group_member_pids(pgid)?;
        if first_pids.is_empty() {
            if !process_group_alive_exact(pgid)? {
                return Ok(None);
            }
            last_ambiguity = format!("sample {sample}: live group has no exact member");
            continue;
        }

        let first = exact_gate_group_local_census(&first_pids)
            .and_then(|census| exact_gate_group_member_epochs(&census, &first_pids, pgid));
        let first = match first {
            Ok(members) => members,
            Err(_error) if !process_group_alive_exact(pgid)? => return Ok(None),
            Err(error) => {
                last_ambiguity = format!("sample {sample} detail A failed: {error:#}");
                continue;
            }
        };

        let second_pids = exact_group_member_pids(pgid)?;
        if first_pids != second_pids {
            if second_pids.is_empty() && !process_group_alive_exact(pgid)? {
                return Ok(None);
            }
            last_ambiguity =
                format!("sample {sample} membership changed: {first_pids:?} -> {second_pids:?}");
            continue;
        }
        let second = exact_gate_group_local_census(&second_pids)
            .and_then(|census| exact_gate_group_member_epochs(&census, &second_pids, pgid));
        let second = match second {
            Ok(members) => members,
            Err(_error) if !process_group_alive_exact(pgid)? => return Ok(None),
            Err(error) => {
                last_ambiguity = format!("sample {sample} detail B failed: {error:#}");
                continue;
            }
        };
        let third_pids = exact_group_member_pids(pgid)?;
        if second_pids != third_pids || first != second {
            if third_pids.is_empty() && !process_group_alive_exact(pgid)? {
                return Ok(None);
            }
            last_ambiguity =
                format!("sample {sample} identity/membership changed during exact observation");
            continue;
        }
        return Ok(Some(second));
    }
    bail!("pgid {pgid} exact group observation remained ambiguous: {last_ambiguity}")
}

