/// Atomically replace the wait-script heartbeat with the runtime-owned working
/// identity. The temporary file is in the same directory, so rename is atomic.
pub fn write_working_heartbeat(
    root: &Path,
    agent: &str,
    spawn_pid: u32,
    round: &str,
    generation: &str,
) -> Result<()> {
    validate_agent_component(agent)?;
    if spawn_pid == 0 || round.is_empty() || generation.is_empty() {
        bail!("working heartbeat requires non-zero pid, round, and generation");
    }
    let dir = root.join("coordination/runtime/heartbeats");
    fs::create_dir_all(&dir)
        .with_context(|| format!("create heartbeat directory failed: {}", dir.display()))?;
    let path = dir.join(format!("{agent}.json"));
    let tmp = dir.join(crate::util::unique_scratch_name(&format!(
        "{agent}.json.tmp"
    )));
    let bytes = serde_json::to_vec(&working_heartbeat_json(agent, spawn_pid, round, generation))?;
    fs::write(&tmp, bytes)
        .with_context(|| format!("write working heartbeat failed: {}", tmp.display()))?;
    fs::rename(&tmp, &path)
        .with_context(|| format!("install working heartbeat failed: {}", path.display()))?;
    Ok(())
}

fn validate_wake_permit(
    root: &Path,
    round: &str,
    agent: &str,
    required_role: Option<&str>,
) -> Result<()> {
    validate_wake_permit_with_replacement(root, round, agent, required_role, None)
}

fn validate_panel_route_wake_permit(
    root: &Path,
    round: &str,
    agent: &str,
    required_role: &str,
    authorization: &PanelRouteAuthorizationV1,
) -> Result<()> {
    if authorization.route.agent != agent
        || format!("{}-review", authorization.route.role) != required_role
    {
        bail!("panel route wake permit role/agent 漂移");
    }
    let events = read_round_ledger_events(root, round)?;
    ledger::validate_runtime_event_history_v1_at_root(root, &events, round)?;
    let routes = events
        .iter()
        .filter(|event| {
            event.event_id == authorization.route_event_id
                && event.task_id.as_deref() == Some(authorization.task_id.as_str())
                && matches!(
                    ledger::decode_runtime_event_v1(event),
                    Ok(Some(ledger::RuntimeEventPayloadV1::ReviewSeatRouted(ref route)))
                        if route == &authorization.route
                )
        })
        .count();
    if routes != 1 {
        bail!("panel route wake permit 缺唯一 committed reservation");
    }
    if events
        .iter()
        .filter(|event| {
            event.event_id == authorization.selected_event_id
                && matches!(
                    ledger::decode_runtime_event_v1(event),
                    Ok(Some(ledger::RuntimeEventPayloadV1::ReviewPanelSelected(ref selected)))
                        if selected.panel_id == authorization.route.panel_id
                            && event.task_id.as_deref() == Some(authorization.task_id.as_str())
                )
        })
        .count()
        != 1
        || events.iter().any(|event| {
            matches!(
                ledger::decode_runtime_event_v1(event),
                Ok(Some(ledger::RuntimeEventPayloadV1::ReviewSeatTerminated(ref terminal)))
                    if terminal.panel_id == authorization.route.panel_id
                        && terminal.seat_id == authorization.route.seat_id
                        && terminal.generation == authorization.route.generation
            ) || matches!(
                ledger::decode_runtime_event_v1(event),
                Ok(Some(ledger::RuntimeEventPayloadV1::ReviewPanelClosed(ref closed)))
                    if closed.panel_id == authorization.route.panel_id
            )
        })
    {
        bail!("panel route reservation 已终结或 selected binding 漂移");
    }
    let active = crate::plan::require_active_round_ir(root, round, &events)?;
    if !active
        .candidate
        .scheduling
        .allowed_agents
        .iter()
        .any(|allowed| allowed == agent)
    {
        bail!("panel route agent 未获 active ROUND-IR 授权");
    }
    let capacity = active
        .candidate
        .scheduling
        .capacities
        .get(agent)
        .with_context(|| format!("panel route agent {agent} 缺 signed capacity"))?;
    crate::legacy::role_admits(&capacity.roles, required_role).map_err(anyhow::Error::msg)?;
    if capacity.agent == 0 || capacity.quota == 0 {
        bail!("panel route agent capacity 为 0");
    }
    Ok(())
}

fn validate_wake_permit_with_replacement(
    root: &Path,
    round: &str,
    agent: &str,
    required_role: Option<&str>,
    replacement: Option<&FormalReviewBinding>,
) -> Result<()> {
    validate_agent_component(agent)?;
    let current = current_round(root)?;
    if current != round {
        bail!("wake round 已漂移: requested={round} current={current}");
    }
    let ledger_path = root.join(format!("coordination/rounds/{round}/events.jsonl"));
    let ledger = orch_core::read_ledger(&ledger_path)?;
    if !ledger.bad_lines.is_empty() {
        bail!("wake 拒绝坏账本");
    }
    let active = crate::plan::require_active_round_ir(root, round, &ledger.events)?;
    if active.candidate.schema_version == crate::plan::ACTORLESS_ROUND_IR_SCHEMA_VERSION {
        if replacement.is_some() || !matches!(required_role, None | Some("review")) {
            bail!("schema 3 wake permit 只接受 ordinary wake 或 dynamic generic review，无 replacement");
        }
        return Ok(());
    }
    if let Some(role) = required_role {
        if let Some(slot) = replacement {
            // Validate every declared supersession edge before the scheduler's
            // `(task, role)` latest-wins fold can hide a malformed source.
            wake_supersession_projection(&ledger.events, round)?;
            if slot.agent != agent {
                bail!("review reissue replacement agent does not match wake target");
            }
            crate::legacy::scheduling_admits_replacing_review_slot(
                &ledger.events,
                round,
                &active.candidate.scheduling,
                agent,
                role,
                &slot.task_id,
                &slot.attempt_id,
                &slot.role,
            )
            .map_err(anyhow::Error::msg)?;
        } else {
            crate::legacy::scheduling_admits(
                &ledger.events,
                round,
                &active.candidate.scheduling,
                agent,
                role,
            )
            .map_err(anyhow::Error::msg)?;
        }
    } else {
        if replacement.is_some() {
            bail!("review reissue replacement requires a formal review role");
        }
        if !active
            .candidate
            .scheduling
            .allowed_agents
            .iter()
            .any(|allowed| allowed == agent)
        {
            bail!("agent {agent} 未获 active ROUND-IR 授权");
        }
        let capacity = active
            .candidate
            .scheduling
            .capacities
            .get(agent)
            .with_context(|| format!("agent {agent} 缺 active ROUND-IR capacity"))?;
        if capacity.agent == 0 || capacity.quota == 0 {
            bail!("agent {agent} active ROUND-IR capacity 为 0");
        }
    }
    Ok(())
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WakeSpec {
    pub injectable: bool,
    pub session_id: String,
    pub argv: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SessionMode {
    Fresh,
    Resume,
}

impl SessionMode {
    pub fn as_str(self) -> &'static str {
        match self {
            SessionMode::Fresh => "fresh",
            SessionMode::Resume => "resume",
        }
    }
}

impl std::fmt::Display for SessionMode {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

impl std::str::FromStr for SessionMode {
    type Err = String;

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        match value {
            "fresh" => Ok(SessionMode::Fresh),
            "resume" => Ok(SessionMode::Resume),
            _ => Err(format!(
                "未知 session mode {value:?}；只接受 fresh/resume（fail-closed）"
            )),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SessionOverlay {
    fault: String,
    event_id: String,
}

impl SessionOverlay {
    pub fn degraded(fault: &str, event_id: &str) -> Result<Self, String> {
        if !matches!(
            fault,
            "thread-not-found"
                | "context-exhausted"
                | "sandbox-rejected"
                | "session-limit"
                | "timeout"
        ) {
            return Err(format!("未知 session fault {fault:?}（fail-closed）"));
        }
        if event_id.trim().is_empty() {
            return Err("fault eventId 不能为空（fail-closed）".to_string());
        }
        Ok(Self {
            fault: fault.to_string(),
            event_id: event_id.to_string(),
        })
    }

    pub fn fault(&self) -> &str {
        &self.fault
    }

    pub fn event_id(&self) -> &str {
        &self.event_id
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ResolvedSessionMode {
    pub configured: SessionMode,
    pub effective: SessionMode,
    pub overlay_event_id: Option<String>,
}

pub fn resolve_session_mode(
    configured: SessionMode,
    overlay: Option<&SessionOverlay>,
) -> Result<ResolvedSessionMode, String> {
    Ok(ResolvedSessionMode {
        configured,
        effective: if overlay.is_some() {
            SessionMode::Fresh
        } else {
            configured
        },
        overlay_event_id: overlay.map(|value| value.event_id.clone()),
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SessionRegistration {
    pub configured: SessionMode,
    pub legacy: bool,
    pub session_id: String,
}

struct RegisteredWakeLaunch {
    pid: u32,
    log_path: PathBuf,
    action_wake_id: Option<String>,
    /// Managed direct-provider supervisor identity. Socket-backed providers do
    /// not have one even though they still have an action wake id.
    wake_id: Option<String>,
    provider_kind: Option<BackendReceiptKind>,
    harness_id: Option<crate::harness::HarnessId>,
    terminal_capability: Option<crate::harness::CapabilitySource>,
    plain_text_review_channel: bool,
    request_session_id: Option<String>,
    runtime_limit: Option<ManagedWakeRuntimeLimit>,
    /// 本次注入写入前 legacy 探活日志（wake-<agent>.log）的文件长度，
    /// 即 B100 要求的咬合判定 offset（只判 offset 之后的新内容）。
    legacy_offset: u64,
    /// legacy 探活路径本次轮换结果（B100 修复轮 D1/D2：degraded 时
    /// 已 fail-closed 置空/缺席，绝不保留历史咬合标记）。
    legacy_probe: LegacyProbeState,
    tool: Option<String>,
    requested_provider: Option<String>,
    requested_model: Option<String>,
    requested_effort: Option<String>,
    quota_domain: Option<String>,
    harness_registry_digest: String,
    review_output_path: Option<String>,
}

fn bind_registered_wake_harness_identity(
    payload: &mut serde_json::Value,
    harness_id: Option<crate::harness::HarnessId>,
    terminal_capability: Option<crate::harness::CapabilitySource>,
    harness_registry_digest: &str,
) -> Result<()> {
    let object = payload
        .as_object_mut()
        .context("WakeIssued payload must be a JSON object")?;
    object.insert(
        "harnessId".to_string(),
        serde_json::json!(harness_id.map(|harness| harness.as_str())),
    );
    object.insert(
        "terminalCapability".to_string(),
        serde_json::json!(terminal_capability.map(|capability| capability.as_str())),
    );
    object.insert(
        "harnessRegistryDigest".to_string(),
        serde_json::Value::String(harness_registry_digest.to_string()),
    );
    Ok(())
}

#[derive(Debug, Clone)]
struct HarnessInvocationContext {
    action_id: String,
    wake_id: String,
    round: String,
    task_id: String,
    attempt_id: String,
    role: String,
    cwd: PathBuf,
    fixed_head: String,
    review_output_path: String,
    deadline_secs: u64,
}

/// legacy 探活路径（wake-<agent>.log）的轮换结果（B100 修复轮 D1/D2）。
/// 除 Linked 外均为 fail-closed 降级态：legacy 已被置空或保持缺席，
/// 整份判读只会读到空（保守未咬合方向），绝不残留历史咬合标记。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LegacyProbeState {
    /// legacy 名已硬链到本次 per-attempt inode：整份读 ≡ 本次注入内容。
    Linked,
    /// 旧 legacy 无法解除链接：已截断为空（历史标记已清除），但未能指向本次注入。
    DegradedEmpty,
    /// 旧 legacy 已解除链接但硬链失败：名字保持缺席（读到 ENOENT ≡ 空）。
    DegradedAbsent,
    /// 本次未走注入道（POKE 备用 / --no-wake）：legacy 未触碰。
    NotAttempted,
}

impl LegacyProbeState {
    pub fn as_str(&self) -> &'static str {
        match self {
            LegacyProbeState::Linked => "linked",
            LegacyProbeState::DegradedEmpty => "degraded-empty",
            LegacyProbeState::DegradedAbsent => "degraded-absent",
            LegacyProbeState::NotAttempted => "not-attempted",
        }
    }
}

#[derive(serde::Deserialize)]
struct Registry {
    agents: BTreeMap<String, RegistryAgent>,
}

#[derive(serde::Deserialize)]
struct RegistryAgent {
    // Decode-only fields keep the historical type checks after planner launch retirement.
    #[serde(rename = "injectable")]
    _injectable: bool,
    #[serde(default)]
    mode: Option<String>,
    #[serde(rename = "sessionId", default)]
    session_id: String,
    #[serde(rename = "wake", default)]
    _wake: Option<WakeTemplate>,
    #[serde(rename = "pokeHint", default)]
    poke_hint: String,
}

#[derive(serde::Deserialize)]
struct WakeTemplate {
    #[serde(rename = "argv")]
    _argv: Vec<String>,
    #[serde(rename = "freshArgv", default)]
    _fresh_argv: Vec<String>,
}

pub fn wake_engaged(log: &str) -> bool {
    log.contains("thread.started") || log.contains("turn.started")
}

/// B100 必修回归（append 改造）：wake 日志改用 append/独立文件后可能残留历史注入的
/// 咬合标记，整份判读会把本次失败的注入误判成「已咬合」（污染 orch handshake 与
/// dispatch 成败判定）。本函数把判定作用域收窄到「本次注入写入前记录的文件长度
/// offset」之后的新内容；子串判据（thread.started/turn.started）保持原样不动。
/// offset 越界或落在非字符边界 ⇒ 视为无新内容 ⇒ 未咬合（保守方向）。
pub fn wake_engaged_after(log: &str, offset: usize) -> bool {
    match log.get(offset..) {
        Some(scoped) => wake_engaged(scoped),
        None => false,
    }
}

// ── B179 provider-bound backend receipts and continuation fence ────────────

/// The provider is frozen from the resolved argv before a process is spawned.
/// Log records are never allowed to guess or change this value.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum BackendReceiptKind {
    /// Codex direct CLI thread acceptance.
    Codex,
    /// OpenCode direct CLI session acceptance.
    OpenCode,
    /// SmartClaw socket action receipt bound to the runtime-owned session alias.
    SmartClaw,
    /// The managed Pi streaming wrapper and its directly supervised child tree.
    Pi,
    /// The managed ZCode streaming wrapper, which verifies its external pin.
    ZCode,
    /// Agy direct CLI after the runtime-derived canary acceptance frame.
    Agy,
    /// DSH managed wrapper after the selected session's request header proves
    /// the signed provider, model, and effort tuple.
    Dsh,
}

impl BackendReceiptKind {
    /// Return the stable harness identifier stored in durable wake receipts.
    /// The value is derived from the closed harness catalog, never provider text.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Codex => crate::harness::HarnessId::Codex.as_str(),
            Self::OpenCode => crate::harness::HarnessId::OpenCode.as_str(),
            Self::SmartClaw => crate::harness::HarnessId::SmartClaw.as_str(),
            Self::Pi => crate::harness::HarnessId::Pi.as_str(),
            Self::ZCode => crate::harness::HarnessId::ZCode.as_str(),
            Self::Agy => crate::harness::HarnessId::Agy.as_str(),
            Self::Dsh => crate::harness::HarnessId::Dsh.as_str(),
        }
    }

    fn parse(value: &str) -> std::result::Result<Self, String> {
        match crate::harness::HarnessId::parse(value) {
            Ok(crate::harness::HarnessId::Codex) => Ok(Self::Codex),
            Ok(crate::harness::HarnessId::OpenCode) => Ok(Self::OpenCode),
            Ok(crate::harness::HarnessId::SmartClaw) => Ok(Self::SmartClaw),
            Ok(crate::harness::HarnessId::Pi) => Ok(Self::Pi),
            Ok(crate::harness::HarnessId::ZCode) => Ok(Self::ZCode),
            Ok(crate::harness::HarnessId::Agy) => Ok(Self::Agy),
            Ok(crate::harness::HarnessId::Dsh) => Ok(Self::Dsh),
            _ => Err(format!("unknown backend receipt provider {value:?}")),
        }
    }
}

impl std::fmt::Display for BackendReceiptKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BackendReceiptExpectation {
    pub expected_kind: BackendReceiptKind,
    pub wake_id: String,
    pub continuation_id: String,
    pub request_message_sha256: String,
    pub request_session_id: Option<String>,
    signed_pin: Option<SignedBackendPin>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SignedBackendPin {
    provider: String,
    model: String,
    effort: String,
}

fn required_identity(label: &str, value: &str) -> std::result::Result<(), String> {
    if value.trim().is_empty() || value.bytes().any(|byte| byte.is_ascii_control()) {
        return Err(format!(
            "{label} must be non-empty and contain no control bytes"
        ));
    }
    Ok(())
}

impl BackendReceiptExpectation {
    pub fn new(
        expected_kind: BackendReceiptKind,
        wake_id: &str,
        continuation_id: &str,
        request_message_sha256: &str,
        request_session_id: Option<&str>,
    ) -> std::result::Result<Self, String> {
        required_identity("wakeId", wake_id)?;
        required_identity("continuationId", continuation_id)?;
        parse_continuation_identity(continuation_id)?;
        if !valid_sha256(request_message_sha256) {
            return Err("requestMessageSha256 must be 64 lowercase hex characters".to_string());
        }
        let request_session_id = request_session_id.map(str::to_string);
        if request_session_id
            .as_deref()
            .is_some_and(|value| required_identity("requestSessionId", value).is_err())
        {
            return Err(
                "requestSessionId must be non-empty and contain no control bytes".to_string(),
            );
        }
        if expected_kind == BackendReceiptKind::SmartClaw && request_session_id.is_none() {
            return Err(
                "SmartClaw receipt requires the runtime-owned requestSessionId".to_string(),
            );
        }
        if expected_kind == BackendReceiptKind::SmartClaw
            && request_session_id.as_deref() != Some(format!("orch-wake-{wake_id}").as_str())
        {
            return Err("SmartClaw requestSessionId must be derived from wakeId".to_string());
        }
        if expected_kind != BackendReceiptKind::SmartClaw && request_session_id.is_some() {
            return Err("managed CLI receipt must not invent a requestSessionId".to_string());
        }
        Ok(Self {
            expected_kind,
            wake_id: wake_id.to_string(),
            continuation_id: continuation_id.to_string(),
            request_message_sha256: request_message_sha256.to_string(),
            request_session_id,
            signed_pin: None,
        })
    }

    /// Attach the provider/model/effort tuple signed before spawn.
    ///
    /// Receipt grammars that require a pin reject parsing unless all three
    /// values are present and the provider frame repeats them byte-for-byte.
    pub fn with_signed_pin(
        mut self,
        provider: &str,
        model: &str,
        effort: &str,
    ) -> std::result::Result<Self, String> {
        for (label, value) in [("provider", provider), ("model", model), ("effort", effort)] {
            required_identity(label, value)?;
        }
        self.signed_pin = Some(SignedBackendPin {
            provider: provider.to_string(),
            model: model.to_string(),
            effort: effort.to_string(),
        });
        Ok(self)
    }
}

fn requires_signed_pin(kind: BackendReceiptKind) -> bool {
    matches!(
        kind,
        BackendReceiptKind::Pi
            | BackendReceiptKind::ZCode
            | BackendReceiptKind::Agy
            | BackendReceiptKind::Dsh
    )
}

fn verify_signed_pin(
    expectation: &BackendReceiptExpectation,
    value: &serde_json::Value,
) -> std::result::Result<(), String> {
    let expected = expectation.signed_pin.as_ref().ok_or_else(|| {
        format!(
            "{} backend receipt requires a signed provider/model/effort pin",
            expectation.expected_kind
        )
    })?;
    for (key, wanted) in [
        ("provider", expected.provider.as_str()),
        ("model", expected.model.as_str()),
        ("effort", expected.effort.as_str()),
    ] {
        let observed = nonempty_json_string(value, key)?;
        if observed != wanted {
            return Err(format!(
                "{} backend signed {key} drift: expected={wanted:?} observed={observed:?}",
                expectation.expected_kind
            ));
        }
    }
    Ok(())
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BackendReceipt {
    pub kind: BackendReceiptKind,
    pub wake_id: String,
    pub continuation_id: String,
    pub message_sha256: String,
    pub request_session_id: Option<String>,
    pub observed_session_id: Option<String>,
    pub probe_offset: u64,
    pub probe_end: u64,
    signed_pin: Option<SignedBackendPin>,
}

fn nonempty_json_string<'a>(
    value: &'a serde_json::Value,
    key: &str,
) -> std::result::Result<&'a str, String> {
    value
        .get(key)
        .and_then(serde_json::Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| format!("backend receipt frame has empty/missing {key}"))
}

/// Parse only the configured provider's acceptance frame from one immutable
/// per-attempt log window. Non-JSON diagnostics are tolerated. An open stream
/// without a matching frame remains pending; EOF without one is a loud error.
pub fn backend_receipt_from_log(
    expectation: &BackendReceiptExpectation,
    bytes: &[u8],
    stream_closed: bool,
) -> std::result::Result<Option<BackendReceipt>, String> {
    let text = String::from_utf8_lossy(bytes);
    for line in text.lines() {
        let Ok(value) = serde_json::from_str::<serde_json::Value>(line) else {
            continue;
        };
        let frame_type = value
            .get("type")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        if frame_type == "error" || value.get("error").is_some() {
            return Err(format!(
                "{} backend emitted an error frame before acceptance",
                expectation.expected_kind
            ));
        }
        let observed_frame_kind = match frame_type {
            "thread.started" => Some(BackendReceiptKind::Codex),
            "step_start" | "step_finish" | "tool_use" if value.get("sessionID").is_some() => {
                Some(BackendReceiptKind::OpenCode)
            }
            "text" | "tool_use" | "tool_result" if value.get("sessionId").is_some() => {
                Some(BackendReceiptKind::SmartClaw)
            }
            "pi.session" => Some(BackendReceiptKind::Pi),
            "zcode.pin-verified" => Some(BackendReceiptKind::ZCode),
            "agy.preflight" => Some(BackendReceiptKind::Agy),
            "dsh.session" => Some(BackendReceiptKind::Dsh),
            _ => None,
        };
        if observed_frame_kind.is_some_and(|kind| kind != expectation.expected_kind) {
            return Err(format!(
                "{} backend log contained a receipt frame for the wrong provider",
                expectation.expected_kind
            ));
        }
        let (matched, observed_session_id) = match expectation.expected_kind {
            BackendReceiptKind::Codex if frame_type == "thread.started" => (
                true,
                Some(nonempty_json_string(&value, "thread_id")?.to_string()),
            ),
            BackendReceiptKind::OpenCode
                if matches!(frame_type, "step_start" | "step_finish" | "tool_use") =>
            {
                (
                    true,
                    Some(nonempty_json_string(&value, "sessionID")?.to_string()),
                )
            }
            BackendReceiptKind::SmartClaw
                if matches!(frame_type, "text" | "tool_use" | "tool_result") =>
            {
                let observed = nonempty_json_string(&value, "sessionId")?;
                let requested = expectation
                    .request_session_id
                    .as_deref()
                    .expect("SmartClaw expectation constructor requires a session");
                if observed != requested {
                    return Err(format!(
                        "SmartClaw backend session mismatch: expected={requested:?} observed={observed:?}"
                    ));
                }
                (true, Some(observed.to_string()))
            }
            BackendReceiptKind::Pi if frame_type == "pi.session" => {
                verify_signed_pin(expectation, &value)?;
                (
                    true,
                    Some(nonempty_json_string(&value, "sessionId")?.to_string()),
                )
            }
            BackendReceiptKind::ZCode if frame_type == "zcode.pin-verified" => {
                verify_signed_pin(expectation, &value)?;
                (true, None)
            }
            BackendReceiptKind::Agy if frame_type == "agy.preflight" => {
                verify_signed_pin(expectation, &value)?;
                if nonempty_json_string(&value, "wakeId")? != expectation.wake_id {
                    return Err("Agy preflight wakeId mismatch".to_string());
                }
                let digest = nonempty_json_string(&value, "canarySha256")?;
                if !valid_sha256(digest) {
                    return Err("Agy preflight canarySha256 is invalid".to_string());
                }
                (true, None)
            }
            BackendReceiptKind::Dsh if frame_type == "dsh.session" => {
                verify_signed_pin(expectation, &value)?;
                (
                    true,
                    Some(nonempty_json_string(&value, "sessionId")?.to_string()),
                )
            }
            _ => (false, None),
        };
        if matched {
            return Ok(Some(BackendReceipt {
                kind: expectation.expected_kind,
                wake_id: expectation.wake_id.clone(),
                continuation_id: expectation.continuation_id.clone(),
                message_sha256: expectation.request_message_sha256.clone(),
                request_session_id: expectation.request_session_id.clone(),
                observed_session_id,
                probe_offset: 0,
                probe_end: bytes.len() as u64,
                signed_pin: expectation.signed_pin.clone(),
            }));
        }
    }
    if stream_closed {
        Err(format!(
            "{} backend stream closed without an action-scoped receipt ({} bytes)",
            expectation.expected_kind,
            bytes.len()
        ))
    } else {
        Ok(None)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BackendReceiptLedgerState {
    pub wake_id: String,
    pub continuation_id: String,
    pub request_message_sha256: String,
    pub wake_issued_count: usize,
    pub review_requested_count: usize,
    pub receipt_count: usize,
    pub receipt_action_rejected: bool,
}

impl BackendReceiptLedgerState {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        wake_id: &str,
        continuation_id: &str,
        request_message_sha256: &str,
        wake_issued_count: usize,
        review_requested_count: usize,
        receipt_count: usize,
        receipt_action_rejected: bool,
    ) -> std::result::Result<Self, String> {
        required_identity("wakeId", wake_id)?;
        required_identity("continuationId", continuation_id)?;
        let continuation = parse_continuation_identity(continuation_id)?;
        if !valid_sha256(request_message_sha256) {
            return Err("requestMessageSha256 must be 64 lowercase hex characters".to_string());
        }
        if wake_issued_count != 1 {
            return Err(format!(
                "backend receipt reconcile requires exactly one WakeIssued, found {wake_issued_count}"
            ));
        }
        // `ReviewRequested` is the durable lifecycle fact for formal seats
        // only. Nongate panel seats deliberately use their committed
        // ReviewSeatRouted identity instead and must not manufacture a formal
        // request merely to satisfy backend-receipt accounting.
        let expected_reviews = usize::from(matches!(
            continuation.role.as_deref(),
            Some("primary" | "secondary" | "review")
        ));
        if review_requested_count != expected_reviews {
            return Err(format!(
                "backend receipt reconcile requires {expected_reviews} matching ReviewRequested, found {review_requested_count}"
            ));
        }
        if receipt_count > 1 {
            return Err(format!(
                "backend receipt reconcile found duplicate/conflicting receipts: {receipt_count}"
            ));
        }
        Ok(Self {
            wake_id: wake_id.to_string(),
            continuation_id: continuation_id.to_string(),
            request_message_sha256: request_message_sha256.to_string(),
            wake_issued_count,
            review_requested_count,
            receipt_count,
            receipt_action_rejected,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BackendReceiptReconcileDecision {
    AppendReceiptOnly { wake_id: String },
    AlreadyCommitted { wake_id: String },
}

pub fn backend_receipt_reconcile_decision(
    state: &BackendReceiptLedgerState,
    receipt: &BackendReceipt,
) -> std::result::Result<BackendReceiptReconcileDecision, String> {
    if state.wake_id != receipt.wake_id
        || state.continuation_id != receipt.continuation_id
        || state.request_message_sha256 != receipt.message_sha256
    {
        return Err("backend receipt does not match the durable action identity".to_string());
    }
    Ok(if state.receipt_count == 0 {
        BackendReceiptReconcileDecision::AppendReceiptOnly {
            wake_id: state.wake_id.clone(),
        }
    } else {
        BackendReceiptReconcileDecision::AlreadyCommitted {
            wake_id: state.wake_id.clone(),
        }
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ActiveWake {
    pub agent: String,
    pub continuation_id: String,
    pub wake_id: String,
    pub request_message_sha256: String,
    pub backend_accepted: bool,
    pub wrapper_exited: bool,
}

impl ActiveWake {
    pub fn new(
        agent: &str,
        continuation_id: &str,
        wake_id: &str,
        request_message_sha256: &str,
        backend_accepted: bool,
        wrapper_exited: bool,
    ) -> std::result::Result<Self, String> {
        required_identity("agent", agent)?;
        required_identity("continuationId", continuation_id)?;
        let identity = parse_continuation_identity(continuation_id)?;
        if identity.agent != agent {
            return Err("active wake agent does not match continuationId".to_string());
        }
        required_identity("wakeId", wake_id)?;
        if !valid_sha256(request_message_sha256) {
            return Err("requestMessageSha256 must be 64 lowercase hex characters".to_string());
        }
        Ok(Self {
            agent: agent.to_string(),
            continuation_id: continuation_id.to_string(),
            wake_id: wake_id.to_string(),
            request_message_sha256: request_message_sha256.to_string(),
            backend_accepted,
            wrapper_exited,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum WakeIntent {
    Unscoped,
    Continuation(String),
}

impl WakeIntent {
    pub fn unscoped() -> Self {
        Self::Unscoped
    }

    pub fn continuation(id: &str) -> std::result::Result<Self, String> {
        required_identity("continuationId", id)?;
        parse_continuation_identity(id)?;
        Ok(Self::Continuation(id.to_string()))
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum WakeFenceDecision {
    Spawn,
    Idempotent {
        wake_id: String,
        backend_accepted: bool,
    },
}

fn new_wake_fence_decision(
    active: &[ActiveWake],
    agent: &str,
    intent: &WakeIntent,
    request_message_sha256: &str,
    capacity: usize,
    provider_bound: bool,
    committed_panel_route: bool,
) -> std::result::Result<WakeFenceDecision, String> {
    if committed_panel_route || !provider_bound {
        return Ok(WakeFenceDecision::Spawn);
    }
    wake_fence_decision(active, agent, intent, request_message_sha256, capacity)
        .map(WakeFenceDecision::from)
}

#[doc(hidden)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum WakeFenceOutcome {
    Spawn,
    Idempotent {
        wake_id: String,
        backend_accepted: bool,
    },
}

impl From<WakeFenceOutcome> for WakeFenceDecision {
    fn from(value: WakeFenceOutcome) -> Self {
        match value {
            WakeFenceOutcome::Spawn => Self::Spawn,
            WakeFenceOutcome::Idempotent {
                wake_id,
                backend_accepted,
            } => Self::Idempotent {
                wake_id,
                backend_accepted,
            },
        }
    }
}

pub fn wake_fence_decision(
    active: &[ActiveWake],
    agent: &str,
    intent: &WakeIntent,
    request_message_sha256: &str,
    capacity: usize,
) -> std::result::Result<WakeFenceOutcome, String> {
    required_identity("agent", agent)?;
    if !valid_sha256(request_message_sha256) {
        return Err("requestMessageSha256 must be 64 lowercase hex characters".to_string());
    }
    if capacity == 0 {
        return Err(format!("agent {agent} wake capacity is zero"));
    }

    let owned = active
        .iter()
        .filter(|wake| wake.agent == agent)
        .collect::<Vec<_>>();
    let WakeIntent::Continuation(requested) = intent else {
        return if owned.is_empty() {
            Ok(WakeFenceOutcome::Spawn)
        } else {
            Err(format!(
                "agent {agent} has active continuation {}; unscoped wake rejected",
                owned
                    .iter()
                    .map(|wake| wake.continuation_id.as_str())
                    .collect::<BTreeSet<_>>()
                    .into_iter()
                    .collect::<Vec<_>>()
                    .join(",")
            ))
        };
    };

    let requested_identity = parse_continuation_identity(requested)?;
    if requested_identity.agent != agent {
        return Err(format!(
            "requested continuation agent {} does not match wake target {agent}",
            requested_identity.agent
        ));
    }
    let matching = owned
        .iter()
        .copied()
        .filter(|wake| wake.continuation_id == *requested)
        .collect::<Vec<_>>();
    if matching.is_empty() {
        let inflight = owned
            .iter()
            .map(|wake| wake.continuation_id.as_str())
            .collect::<BTreeSet<_>>()
            .len();
        if inflight >= capacity {
            return Err(format!(
                "agent {agent} wake capacity exhausted: inflight={inflight} capacity={capacity}"
            ));
        }
        return Ok(WakeFenceOutcome::Spawn);
    }

    // The load projection represents a lifecycle that has not received its
    // first WakeIssued with an empty digest. Exact addressing may deliver it
    // even when the same agent owns other continuations.
    if matching.len() == 1
        && matching[0].request_message_sha256.is_empty()
        && !matching[0].backend_accepted
        && !matching[0].wrapper_exited
    {
        return Ok(WakeFenceOutcome::Spawn);
    }
    if matching
        .iter()
        .any(|wake| request_message_sha256 != wake.request_message_sha256)
    {
        return Err(format!("continuation {requested} request digest changed"));
    }

    // A retry history may contain several rejected WakeIssued facts followed
    // by one current pending/accepted wake. Only the current live wake owns an
    // external side effect; two live facts are ambiguous and fail closed.
    let live = matching
        .iter()
        .copied()
        .filter(|wake| wake.backend_accepted || !wake.wrapper_exited)
        .collect::<Vec<_>>();
    if live.len() > 1 {
        return Err(format!(
            "continuation {requested} has ambiguous multiple live wakes: {}",
            live.iter()
                .map(|wake| wake.wake_id.as_str())
                .collect::<Vec<_>>()
                .join(",")
        ));
    }
    if let Some(current) = live.first() {
        return Ok(WakeFenceOutcome::Idempotent {
            wake_id: current.wake_id.clone(),
            backend_accepted: current.backend_accepted,
        });
    }

    // Every exact wake was explicitly rejected before backend acceptance, so
    // retrying cannot duplicate an external session.
    Ok(WakeFenceOutcome::Spawn)
}

/// Explicit caller-layer decision for replacing one accepted review wake whose
/// managed provider scope has been proven dead.  The baseline continuation
/// fence deliberately remains unaware of terminal-session evidence: its four
/// historical answers are part of the frozen B200 contract.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ReissueOutcome {
    Reissue { superseded_wake_id: String },
    Refused { reason: String },
}

pub fn reissue_decision(
    active: &[ActiveWake],
    agent: &str,
    intent: &WakeIntent,
    request_message_sha256: &str,
    capacity: usize,
    death_evidence: Option<&SessionDeathEvidence>,
) -> std::result::Result<ReissueOutcome, String> {
    required_identity("agent", agent)?;
    if !valid_sha256(request_message_sha256) {
        return Err("requestMessageSha256 must be 64 lowercase hex characters".to_string());
    }
    if capacity == 0 {
        return Err(format!("agent {agent} wake capacity is zero"));
    }
    let WakeIntent::Continuation(requested) = intent else {
        return Ok(ReissueOutcome::Refused {
            reason: "reissue requires an exact continuation identity".to_string(),
        });
    };
    let requested_identity = parse_continuation_identity(requested)?;
    if requested_identity.agent != agent {
        return Err(format!(
            "requested continuation agent {} does not match wake target {agent}",
            requested_identity.agent
        ));
    }

    let matching = active
        .iter()
        .filter(|wake| wake.agent == agent && wake.continuation_id == *requested)
        .collect::<Vec<_>>();
    if matching.is_empty() {
        return Ok(ReissueOutcome::Refused {
            reason: format!("exact source continuation {requested} is not active"),
        });
    }

    let Some(evidence) = death_evidence else {
        // Preserve the baseline digest and ambiguity checks even on the loud
        // refusal path.  A changed live request therefore remains a hard fence
        // error rather than being mislabeled as an ordinary missing proof.
        return match wake_fence_decision(active, agent, intent, request_message_sha256, capacity)? {
            WakeFenceOutcome::Idempotent {
                wake_id,
                backend_accepted: true,
            } => Ok(ReissueOutcome::Refused {
                reason: format!(
                    "exact source wake {wake_id} lacks authenticated session-death evidence"
                ),
            }),
            WakeFenceOutcome::Idempotent { wake_id, .. } => Ok(ReissueOutcome::Refused {
                reason: format!("exact source wake {wake_id} is still pending backend acceptance"),
            }),
            WakeFenceOutcome::Spawn => Ok(ReissueOutcome::Refused {
                reason: "no accepted source wake exists for explicit reissue".to_string(),
            }),
        };
    };

    let evidence_matches = matching
        .iter()
        .copied()
        .filter(|wake| wake.wake_id == evidence.wake_id())
        .collect::<Vec<_>>();
    if evidence_matches.len() != 1 {
        return Ok(ReissueOutcome::Refused {
            reason: format!(
                "session-death evidence wakeId {} does not uniquely match the exact source",
                evidence.wake_id()
            ),
        });
    }
    let source = evidence_matches[0];
    if !source.backend_accepted {
        return Ok(ReissueOutcome::Refused {
            reason: format!(
                "exact source wake {} is pending; backend side effects remain unknown",
                source.wake_id
            ),
        });
    }

    // Ask the frozen fence to prove that this accepted wake is the unique live
    // owner.  Use its immutable original digest; the only permitted digest
    // exemption is evaluated immediately afterwards from the exact death
    // evidence.
    match wake_fence_decision(
        active,
        agent,
        intent,
        &source.request_message_sha256,
        capacity,
    )? {
        WakeFenceOutcome::Idempotent {
            wake_id,
            backend_accepted: true,
        } if wake_id == source.wake_id => {}
        WakeFenceOutcome::Idempotent { wake_id, .. } => {
            return Ok(ReissueOutcome::Refused {
                reason: format!(
                    "session-death evidence targets {}, but the exact live wake is {wake_id}",
                    source.wake_id
                ),
            });
        }
        WakeFenceOutcome::Spawn => {
            return Ok(ReissueOutcome::Refused {
                reason: "the exact source is not an accepted live wake".to_string(),
            });
        }
    }

    if request_message_sha256 != source.request_message_sha256 && !evidence.exempts_request_digest()
    {
        return Ok(ReissueOutcome::Refused {
            reason: format!("continuation {requested} request digest changed"),
        });
    }
    Ok(ReissueOutcome::Reissue {
        superseded_wake_id: source.wake_id.clone(),
    })
}

pub fn identity_fence_decision(
    active: &[ActiveWake],
    agent: &str,
    intent: &WakeIntent,
    request_message_sha256: &str,
) -> std::result::Result<WakeFenceDecision, String> {
    wake_fence_decision(active, agent, intent, request_message_sha256, 1).map(Into::into)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ContinuationIdentity {
    round: String,
    task_id: Option<String>,
    attempt_id: Option<String>,
    role: Option<String>,
    agent: String,
    manual_wake_id: Option<String>,
}

fn parse_continuation_identity(
    continuation_id: &str,
) -> std::result::Result<ContinuationIdentity, String> {
    let parts = continuation_id.split(':').collect::<Vec<_>>();
    let identity = match parts.as_slice() {
        [
            "review",
            round,
            task,
            attempt,
            role @ ("primary" | "secondary" | "nongate" | "review"),
            agent,
        ] => {
            ContinuationIdentity {
                round: (*round).to_string(),
                task_id: Some((*task).to_string()),
                attempt_id: Some((*attempt).to_string()),
                role: Some((*role).to_string()),
                agent: (*agent).to_string(),
                manual_wake_id: None,
            }
        }
        ["implementation", round, task, attempt, agent] => ContinuationIdentity {
            round: (*round).to_string(),
            task_id: Some((*task).to_string()),
            attempt_id: Some((*attempt).to_string()),
            role: None,
            agent: (*agent).to_string(),
            manual_wake_id: None,
        },
        ["manual", round, wake_id, agent] => {
            required_identity("manual wakeId", wake_id)?;
            ContinuationIdentity {
                round: (*round).to_string(),
                task_id: None,
                attempt_id: None,
                role: None,
                agent: (*agent).to_string(),
                manual_wake_id: Some((*wake_id).to_string()),
            }
        }
        _ => {
            return Err(format!(
                "continuationId is not a canonical review/implementation/manual identity: {continuation_id:?}"
            ))
        }
    };
    required_identity("continuation round", &identity.round)?;
    required_identity("continuation agent", &identity.agent)?;
    if let Some(task) = identity.task_id.as_deref() {
        required_identity("continuation taskId", task)?;
    }
    if let Some(attempt) = identity.attempt_id.as_deref() {
        required_identity("continuation attemptId", attempt)?;
    }
    if let (Some(task), Some(attempt)) =
        (identity.task_id.as_deref(), identity.attempt_id.as_deref())
    {
        let suffix = attempt.strip_prefix(&format!("{task}-A"));
        if suffix.is_none_or(|suffix| {
            suffix.len() != 4 || !suffix.bytes().all(|byte| byte.is_ascii_digit())
        }) {
            return Err("continuation attemptId is not canonical task-A0000 identity".to_string());
        }
    }
    Ok(identity)
}

/// Stable request binding. Runtime-generated sentinel/challenge bytes are not
/// part of `message`; the typed continuation is length-framed into the hash.
pub fn wake_request_message_sha256(
    message: &str,
    continuation_id: &str,
) -> std::result::Result<String, String> {
    parse_continuation_identity(continuation_id)?;
    let mut hasher = Sha256::new();
    hasher.update(b"orch-wake-request-v1\0");
    hasher.update((continuation_id.len() as u64).to_be_bytes());
    hasher.update(continuation_id.as_bytes());
    hasher.update((message.len() as u64).to_be_bytes());
    hasher.update(message.as_bytes());
    Ok(hex::encode(hasher.finalize()))
}

fn with_wake_identity_lock_wait<T>(
    root: &Path,
    agent: &str,
    action: impl FnOnce() -> Result<T>,
) -> Result<T> {
    validate_agent_component(agent)?;
    let lock_dir = root.join("coordination/runtime/locks");
    fs::create_dir_all(&lock_dir).context("create wake identity lock directory failed")?;
    let file = fs::OpenOptions::new()
        .create(true)
        .read(true)
        .write(true)
        .open(lock_dir.join(format!("wake-identity-{agent}.lock")))
        .context("open wake identity lock failed")?;
    let mut lock = fd_lock::RwLock::new(file);
    let _guard = lock.write().context("wait for wake identity lock failed")?;
    action()
}

fn continuation_for_load(round: &str, agent: &str, item: &crate::legacy::LoadItem) -> String {
    match item.kind {
        crate::legacy::LoadKind::Implementation => format!(
            "implementation:{round}:{}:{}:{agent}",
            item.task_id, item.attempt_id
        ),
        crate::legacy::LoadKind::Review => format!(
            "review:{round}:{}:{}:{}:{agent}",
            item.task_id,
            item.attempt_id,
            item.role.as_deref().unwrap_or("unknown")
        ),
    }
}

#[derive(Debug, Default)]
struct WakeSupersessionProjection {
    superseded: BTreeSet<String>,
    successor_by_source: BTreeMap<String, String>,
}

fn exact_review_request_for_wake<'a>(
    events: &'a [orch_core::EventRecord],
    round: &str,
    wake_id: &str,
) -> Result<&'a orch_core::EventRecord> {
    let requests = events
        .iter()
        .filter(|event| {
            event.kind == "ReviewRequested"
                && event.round.as_deref() == Some(round)
                && payload_string(event, "wakeId") == Some(wake_id)
        })
        .collect::<Vec<_>>();
    if requests.len() != 1 {
        bail!(
            "superseded wake chain requires exactly one ReviewRequested for wakeId={wake_id}, found {}",
            requests.len()
        );
    }
    let request = requests[0];
    if request.actor != "runtime:orch" {
        bail!("superseded wake chain ReviewRequested actor is not runtime:orch");
    }
    Ok(request)
}

fn validate_supersession_review_identity(
    wake: &orch_core::EventRecord,
    request: &orch_core::EventRecord,
    facts: &DurableReceiptFacts,
) -> Result<()> {
    let task_id = wake
        .task_id
        .as_deref()
        .filter(|value| !value.trim().is_empty())
        .context("superseded WakeIssued missing taskId")?;
    let attempt_id = facts
        .identity
        .attempt_id
        .as_deref()
        .context("superseded WakeIssued is not attempt-scoped")?;
    let role = facts
        .identity
        .role
        .as_deref()
        .filter(|role| matches!(*role, "primary" | "secondary"))
        .context("superseded WakeIssued is not a formal review continuation")?;
    if request.task_id.as_deref() != Some(task_id)
        || payload_string(request, "attemptId") != Some(attempt_id)
        || payload_string(request, "role") != Some(role)
        || payload_string(request, "agent") != Some(facts.agent.as_str())
        || payload_string(request, "continuationId") != Some(facts.continuation_id.as_str())
        || payload_string(request, "requestMessageSha256")
            != Some(facts.request_message_sha256.as_str())
        || payload_string(request, "renderedMessageSha256")
            != Some(facts.rendered_message_sha256.as_str())
        || payload_string(request, "providerKind") != Some(facts.provider_kind.as_str())
        || payload_string(request, "logPath") != Some(facts.log_path.as_str())
    {
        bail!("superseded WakeIssued/ReviewRequested identity mismatch");
    }
    let request_session = request
        .payload
        .as_ref()
        .and_then(|payload| payload.get("requestSessionId"));
    let session_matches = match (request_session, facts.request_session_id.as_deref()) {
        (Some(serde_json::Value::Null), None) => true,
        (Some(serde_json::Value::String(observed)), Some(expected)) => observed == expected,
        _ => false,
    };
    if !session_matches {
        bail!("superseded WakeIssued/ReviewRequested session identity mismatch");
    }
    let reviewed_head = payload_string(request, "reviewedHead").unwrap_or_default();
    if reviewed_head.len() != 40
        || !reviewed_head
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        bail!("superseded ReviewRequested reviewedHead must be a full lowercase git object id");
    }
    if request
        .payload
        .as_ref()
        .and_then(|payload| payload.get("deadlineSecs"))
        .and_then(serde_json::Value::as_u64)
        .is_none()
    {
        bail!("superseded ReviewRequested deadlineSecs must be an unsigned integer");
    }
    Ok(())
}

fn exact_death_declaration_for_source<'a>(
    events: &'a [orch_core::EventRecord],
    round: &str,
    source: &DurableReceiptFacts,
) -> Result<&'a orch_core::EventRecord> {
    let declarations = events
        .iter()
        .filter(|event| {
            event.kind == "ManagedWakeAttachState"
                && event.round.as_deref() == Some(round)
                && payload_string(event, "phase") == Some("session-death-declared")
                && payload_string(event, "wakeId") == Some(source.wake_id.as_str())
        })
        .collect::<Vec<_>>();
    if declarations.len() != 1 {
        if declarations.is_empty() {
            bail!(
                "exact source wake {} lacks authenticated session-death evidence (declarations=0)",
                source.wake_id
            );
        }
        bail!(
            "superseded wake chain requires exactly one authenticated death declaration for wakeId={}, found {}",
            source.wake_id,
            declarations.len()
        );
    }
    let declaration = declarations[0];
    let task_id = source
        .identity
        .task_id
        .as_deref()
        .context("death declaration source is not task-scoped")?;
    let attempt_id = source
        .identity
        .attempt_id
        .as_deref()
        .context("death declaration source is not attempt-scoped")?;
    let role = source
        .identity
        .role
        .as_deref()
        .context("death declaration source is not review-scoped")?;
    let expected_action_id =
        sha256_hex(format!("managed-session-death\0{round}\0{}", source.wake_id).as_bytes());
    let evidence_sha256 = payload_string(declaration, "evidenceSha256").unwrap_or_default();
    let outcome = payload_string(declaration, "outcome").unwrap_or_default();
    if declaration.actor != "runtime:orch"
        || declaration.task_id.as_deref() != Some(task_id)
        || payload_string(declaration, "actionId") != Some(expected_action_id.as_str())
        || payload_string(declaration, "attemptId") != Some(attempt_id)
        || payload_string(declaration, "role") != Some(role)
        || payload_string(declaration, "agent") != Some(source.agent.as_str())
        || !valid_sha256(evidence_sha256)
        || !matches!(
            outcome,
            "DeliveredTerminal"
                | "TruncatedNoTerminal"
                | "StoppedByHardDeadline"
                | "StoppedByAuthenticatedCancel"
        )
    {
        bail!("superseded wake chain death declaration identity is not exact");
    }
    Ok(declaration)
}

fn require_exact_accepted_backend_receipt<'a>(
    events: &'a [orch_core::EventRecord],
    source: &DurableReceiptFacts,
) -> Result<&'a orch_core::EventRecord> {
    let receipts = events
        .iter()
        .filter(|event| {
            event.kind == "AgentEventReceived"
                && payload_string(event, "agentEvent") == Some("wake-backend-receipt")
                && (payload_string(event, "actionId") == Some(source.wake_id.as_str())
                    || payload_string(event, "wakeId") == Some(source.wake_id.as_str()))
        })
        .collect::<Vec<_>>();
    if receipts.len() != 1
        || !existing_receipt_matches(receipts[0], source)
            .context("source backend receipt identity is malformed")?
    {
        bail!(
            "reissue source requires exactly one authenticated accepted backend receipt for wakeId={}",
            source.wake_id
        );
    }
    Ok(receipts[0])
}

fn exact_accepted_backend_receipt_if_present<'a>(
    events: &'a [orch_core::EventRecord],
    source: &DurableReceiptFacts,
) -> Result<Option<&'a orch_core::EventRecord>> {
    let mut receipts = Vec::new();
    for event in events {
        if existing_receipt_matches(event, source)
            .context("ordinary replacement source backend receipt identity is malformed")?
        {
            receipts.push(event);
        }
    }
    if receipts.len() > 1 {
        bail!(
            "ordinary replacement source has duplicate accepted backend receipts for wakeId={}: found {}",
            source.wake_id,
            receipts.len()
        );
    }
    if let Some(receipt) = receipts.first() {
        // Preserve the accepted-source supersession class exactly, including
        // durable degraded diagnostics that may precede a later accepted
        // receipt.  The strict explicit --reissue path still calls
        // require_exact_accepted_backend_receipt directly.
        return Ok(Some(*receipt));
    }

    for event in events {
        if degraded_backend_receipt_matches(event, source)
            .context("ordinary replacement source degraded backend receipt identity is malformed")?
        {
            bail!(
                "receiptless ordinary replacement source must not carry a degraded backend receipt for wakeId={}",
                source.wake_id
            );
        }
    }
    Ok(None)
}

fn wake_supersession_projection(
    events: &[orch_core::EventRecord],
    round: &str,
) -> Result<WakeSupersessionProjection> {
    let mut projection = WakeSupersessionProjection::default();
    for (successor_index, successor_event) in events.iter().enumerate() {
        if successor_event.kind != "WakeIssued" {
            continue;
        }
        let Some(payload) = successor_event.payload.as_ref() else {
            continue;
        };
        let Some(raw_source) = payload.get("supersededWakeId") else {
            continue;
        };
        let source_wake_id = raw_source
            .as_str()
            .filter(|value| !value.trim().is_empty())
            .context("WakeIssued.supersededWakeId must be a non-empty string")?;
        let successor_facts = durable_receipt_facts(successor_event)?;
        if successor_event.round.as_deref() != Some(round)
            || successor_facts.provider_kind != BackendReceiptKind::OpenCode
        {
            bail!("wake supersession is limited to managed opencode in the active round");
        }
        if successor_facts.wake_id == source_wake_id {
            bail!("WakeIssued.supersededWakeId must not self-reference");
        }
        let successor_count = events
            .iter()
            .filter(|event| {
                event.kind == "WakeIssued"
                    && payload_string(event, "wakeId") == Some(successor_facts.wake_id.as_str())
            })
            .count();
        if successor_count != 1 {
            bail!(
                "wake supersession successor wakeId must be unique: wakeId={} found={successor_count}",
                successor_facts.wake_id
            );
        }

        let sources = events
            .iter()
            .enumerate()
            .filter(|(_, event)| {
                event.kind == "WakeIssued"
                    && payload_string(event, "wakeId") == Some(source_wake_id)
            })
            .collect::<Vec<_>>();
        if sources.len() != 1 {
            bail!(
                "WakeIssued.supersededWakeId must reference exactly one source wake: wakeId={source_wake_id} found={}",
                sources.len()
            );
        }
        let (source_index, source_event) = sources[0];
        if source_index >= successor_index {
            bail!("WakeIssued.supersededWakeId must reference an earlier wake");
        }
        let source_facts = durable_receipt_facts(source_event)?;
        if source_facts.provider_kind != BackendReceiptKind::OpenCode
            || source_facts.continuation_id != successor_facts.continuation_id
            || source_facts.agent != successor_facts.agent
            || source_facts.identity.task_id != successor_facts.identity.task_id
            || source_facts.identity.attempt_id != successor_facts.identity.attempt_id
            || source_facts.identity.role != successor_facts.identity.role
        {
            bail!("WakeIssued supersession source/successor identity mismatch");
        }
        let source_receipt = exact_accepted_backend_receipt_if_present(events, &source_facts)?;
        let source_request = exact_review_request_for_wake(events, round, source_wake_id)?;
        let successor_request =
            exact_review_request_for_wake(events, round, &successor_facts.wake_id)?;
        validate_supersession_review_identity(source_event, source_request, &source_facts)?;
        validate_supersession_review_identity(
            successor_event,
            successor_request,
            &successor_facts,
        )?;
        if payload_string(source_request, "reviewedHead")
            != payload_string(successor_request, "reviewedHead")
            || source_request
                .payload
                .as_ref()
                .and_then(|payload| payload.get("deadlineSecs"))
                != successor_request
                    .payload
                    .as_ref()
                    .and_then(|payload| payload.get("deadlineSecs"))
        {
            bail!("wake supersession changed the immutable review head or deadline");
        }
        let death = exact_death_declaration_for_source(events, round, &source_facts)?;
        let source_request_index = events
            .iter()
            .position(|event| std::ptr::eq(event, source_request))
            .expect("source review request came from this event slice");
        let source_receipt_index = source_receipt.map(|receipt| {
            events
                .iter()
                .position(|event| std::ptr::eq(event, receipt))
                .expect("source receipt came from this event slice")
        });
        let successor_request_index = events
            .iter()
            .position(|event| std::ptr::eq(event, successor_request))
            .expect("successor review request came from this event slice");
        let death_index = events
            .iter()
            .position(|event| std::ptr::eq(event, death))
            .expect("death declaration came from this event slice");
        if source_receipt.is_none()
            && !matches!(
                payload_string(death, "outcome"),
                Some(
                    "TruncatedNoTerminal"
                        | "StoppedByHardDeadline"
                        | "StoppedByAuthenticatedCancel"
                )
            )
        {
            bail!(
                "receiptless ordinary replacement requires a release-eligible authenticated death outcome"
            );
        }
        let receipt_order_is_valid = source_receipt_index
            .is_none_or(|index| index > source_request_index && index < successor_index);
        if source_request_index != source_index + 1
            || !receipt_order_is_valid
            || death_index <= source_request_index
            || death_index >= successor_index
            || successor_request_index != successor_index + 1
        {
            bail!(
                "superseded wake chain event order is incomplete: expected source wake/request, optional accepted receipt and death before successor wake/request"
            );
        }

        if projection
            .successor_by_source
            .insert(source_wake_id.to_string(), successor_facts.wake_id.clone())
            .is_some()
        {
            bail!("one superseded wake has multiple successor WakeIssued facts");
        }
        projection.superseded.insert(source_wake_id.to_string());
    }
    Ok(projection)
}

fn supersession_leaf(
    projection: &WakeSupersessionProjection,
    source_wake_id: &str,
) -> Option<String> {
    let mut current = projection.successor_by_source.get(source_wake_id)?.clone();
    for _ in 0..projection.successor_by_source.len() {
        let Some(successor) = projection.successor_by_source.get(&current) else {
            return Some(current);
        };
        current = successor.clone();
    }
    // Every validated edge points to a later event, so exhausting this bound
    // means an internal cycle/invariant failure rather than a legitimate leaf.
    None
}

fn declared_session_death_after(
    events: &[orch_core::EventRecord],
    round: &str,
    task_id: &str,
    attempt_id: &str,
    role: &str,
    agent: &str,
    wake_id: &str,
    anchor_index: usize,
    event_kind: &str,
) -> bool {
    events
        .iter()
        .skip(anchor_index.saturating_add(1))
        .any(|event| {
            event.kind == event_kind
                && event.actor == "runtime:orch"
                && event.round.as_deref() == Some(round)
                && event.task_id.as_deref() == Some(task_id)
                && payload_string(event, "phase") == Some("session-death-declared")
                && payload_string(event, "wakeId") == Some(wake_id)
                && payload_string(event, "attemptId") == Some(attempt_id)
                && payload_string(event, "role") == Some(role)
                && payload_string(event, "agent") == Some(agent)
                && payload_string(event, "evidenceSha256").is_some_and(valid_sha256)
                && matches!(
                    payload_string(event, "outcome"),
                    Some(
                        "TruncatedNoTerminal"
                            | "StoppedByHardDeadline"
                            | "StoppedByAuthenticatedCancel"
                    )
                )
        })
}

pub fn active_wakes_from_events(
    events: &[orch_core::EventRecord],
    round: &str,
    agent: &str,
) -> Result<Vec<ActiveWake>> {
    active_wakes_from_events_projected(events, round, agent, Some("ManagedWakeAttachState"))
}

fn active_wakes_from_events_raw(
    events: &[orch_core::EventRecord],
    round: &str,
    agent: &str,
) -> Result<Vec<ActiveWake>> {
    active_wakes_from_events_projected(events, round, agent, None)
}

fn active_wakes_from_events_projected(
    events: &[orch_core::EventRecord],
    round: &str,
    agent: &str,
    declared_death_event_kind: Option<&str>,
) -> Result<Vec<ActiveWake>> {
    let declared_dead =
        |wake_id: &str, wake_index: usize, item: &crate::legacy::LoadItem| -> bool {
            let (Some(event_kind), Some(role)) = (declared_death_event_kind, item.role.as_deref())
            else {
                return false;
            };
            declared_session_death_after(
                events,
                round,
                &item.task_id,
                &item.attempt_id,
                role,
                agent,
                wake_id,
                wake_index,
                event_kind,
            )
        };
    let supersession = wake_supersession_projection(events, round)?;
    let resume_replacements = resume_dispatch::project(events, round)?;
    let load = crate::legacy::agent_inflight_load_from_events(events, round)
        .map_err(anyhow::Error::msg)?;
    let mut active = Vec::new();
    for item in load.get(agent).into_iter().flatten() {
        let continuation_id = continuation_for_load(round, agent, item);
        let wakes = events
            .iter()
            .enumerate()
            .filter(|event| {
                event.1.kind == "WakeIssued"
                    && event.1.round.as_deref().is_none_or(|value| value == round)
                    && payload_string(event.1, "agent") == Some(agent)
                    && payload_string(event.1, "continuationId") == Some(&continuation_id)
            })
            .collect::<Vec<_>>();
        if wakes.is_empty() {
            let released_pending = events
                .iter()
                .enumerate()
                .rev()
                .find(|(_, event)| {
                    event.kind == "ReviewRequested"
                        && event.round.as_deref().is_none_or(|value| value == round)
                        && event.task_id.as_deref() == Some(item.task_id.as_str())
                        && payload_string(event, "attemptId") == Some(item.attempt_id.as_str())
                        && payload_string(event, "role") == item.role.as_deref()
                        && payload_string(event, "agent") == Some(agent)
                        && payload_string(event, "continuationId") == Some(&continuation_id)
                })
                .and_then(|(request_index, request)| {
                    payload_string(request, "wakeId").map(|wake_id| (request_index, wake_id))
                })
                .is_some_and(|(request_index, wake_id)| {
                    declared_dead(wake_id, request_index, item)
                });
            if released_pending {
                continue;
            }
            // Legacy or not-yet-woken lifecycle: it still blocks unscoped and
            // conflicting continuations. Exact typed first delivery may spawn.
            active.push(ActiveWake {
                agent: agent.to_string(),
                continuation_id,
                wake_id: "legacy-or-pending-without-wake-receipt".to_string(),
                request_message_sha256: String::new(),
                backend_accepted: false,
                wrapper_exited: false,
            });
            continue;
        }
        for (wake_index, wake) in wakes {
            let wake_id = payload_string(wake, "wakeId").unwrap_or("legacy-unknown-wake");
            if supersession.superseded.contains(wake_id) || resume_replacements.replaces(wake_id) {
                continue;
            }
            if declared_dead(wake_id, wake_index, item) {
                continue;
            }
            let digest = payload_string(wake, "requestMessageSha256").unwrap_or_default();
            let receipt_count = events
                .iter()
                .filter(|event| {
                    event.kind == "AgentEventReceived"
                        && payload_string(event, "agentEvent") == Some("wake-backend-receipt")
                        && payload_string(event, "actionId") == Some(wake_id)
                })
                .count();
            let degraded_candidates = events
                .iter()
                .filter(|event| {
                    event.kind == "AgentEventReceived"
                        && payload_string(event, "agentEvent")
                            == Some(DEGRADED_BACKEND_RECEIPT_EVENT)
                        && (payload_string(event, "actionId") == Some(wake_id)
                            || payload_string(event, "wakeId") == Some(wake_id))
                })
                .collect::<Vec<_>>();
            let degraded_count = if degraded_candidates.is_empty() {
                0
            } else {
                let facts = durable_receipt_facts(wake)?;
                degraded_candidates
                    .into_iter()
                    .map(|event| degraded_backend_receipt_matches(event, &facts))
                    .collect::<Result<Vec<_>>>()?
                    .into_iter()
                    .filter(|matched| *matched)
                    .count()
            };
            if degraded_count > 1 {
                bail!("active wake has multiple degraded backend receipts for wakeId={wake_id}");
            }
            let wrapper_exited = degraded_count == 0
                && events.iter().any(|event| {
                    event.kind == "ActionRejected"
                        && payload_string(event, "actionId") == Some(wake_id)
                });
            active.push(ActiveWake {
                agent: agent.to_string(),
                continuation_id: continuation_id.clone(),
                wake_id: wake_id.to_string(),
                request_message_sha256: digest.to_string(),
                backend_accepted: receipt_count == 1,
                wrapper_exited,
            });
        }
    }
    Ok(active)
}

fn read_round_ledger_events(root: &Path, round: &str) -> Result<Vec<orch_core::EventRecord>> {
    let read =
        orch_core::read_ledger(&root.join(format!("coordination/rounds/{round}/events.jsonl")))?;
    if !read.bad_lines.is_empty() {
        bail!(
            "wake identity/receipt projection 发现 {} 条坏行，拒绝继续",
            read.bad_lines.len()
        );
    }
    Ok(read.events)
}

fn wake_capacity_from_events(
    root: &Path,
    round: &str,
    events: &[orch_core::EventRecord],
    agent: &str,
) -> Result<usize> {
    let active = crate::plan::require_active_round_ir(root, round, events)?;
    let configured = active
        .candidate
        .scheduling
        .capacities
        .get(agent)
        .with_context(|| format!("agent {agent} 缺 active ROUND-IR capacity"))?;
    let capacity = configured.agent.min(configured.quota);
    if capacity == 0 {
        bail!("agent {agent} active ROUND-IR capacity 为 0");
    }
    Ok(capacity)
}

fn read_captured_probe_bytes(mut captured: CapturedProbeWindow) -> Result<Vec<u8>> {
    let len = usize::try_from(captured.probe_end)
        .with_context(|| format!("probeEnd does not fit usize: {}", captured.probe_end))?;
    let mut bytes = vec![0_u8; len];
    captured.file.read_exact(&mut bytes).with_context(|| {
        format!(
            "read immutable backend receipt window [0,{}) failed: {}",
            captured.probe_end,
            captured.log_path.display()
        )
    })?;
    Ok(bytes)
}

fn backend_receipt_event(
    round: &str,
    task_id: Option<&str>,
    attempt_id: Option<&str>,
    agent: &str,
    rendered_message_sha256: &str,
    log_path: &str,
    receipt: &BackendReceipt,
    window_sha256: &str,
) -> orch_core::EventRecord {
    ledger::event(
        "AgentEventReceived",
        "runtime:orch",
        task_id,
        Some(round),
        serde_json::json!({
            "agentEvent": "wake-backend-receipt",
            "actionId": receipt.wake_id,
            "wakeId": receipt.wake_id,
            "continuationId": receipt.continuation_id,
            "attemptId": attempt_id,
            "agent": agent,
            "providerKind": receipt.kind.as_str(),
            "requestedProvider": receipt.signed_pin.as_ref().map(|pin| pin.provider.as_str()),
            "requestedModel": receipt.signed_pin.as_ref().map(|pin| pin.model.as_str()),
            "requestedEffort": receipt.signed_pin.as_ref().map(|pin| pin.effort.as_str()),
            "requestMessageSha256": receipt.message_sha256,
            "renderedMessageSha256": rendered_message_sha256,
            "receiptKind": receipt.kind.as_str(),
            "requestSessionId": receipt.request_session_id,
            "observedSessionId": receipt.observed_session_id,
            "logPath": log_path,
            "probeOffset": receipt.probe_offset,
            "probeEnd": receipt.probe_end,
            "windowSha256": window_sha256,
            "backendState": "accepted",
        }),
    )
}

#[derive(Debug, Clone)]
struct DurableReceiptFacts {
    wake_id: String,
    continuation_id: String,
    identity: ContinuationIdentity,
    agent: String,
    provider_kind: BackendReceiptKind,
    requested_provider: Option<String>,
    requested_model: Option<String>,
    requested_effort: Option<String>,
    request_message_sha256: String,
    rendered_message_sha256: String,
    request_session_id: Option<String>,
    log_path: String,
    channel_binding: Option<serde_json::Value>,
}

fn required_payload_field<'a>(
    event: &'a orch_core::EventRecord,
    key: &str,
) -> Result<&'a serde_json::Value> {
    event
        .payload
        .as_ref()
        .and_then(|payload| payload.get(key))
        .with_context(|| format!("{} missing payload.{key}", event.kind))
}

/// Rebuild the closed provider-neutral channel binding from one issued action.
pub(crate) fn channel_action_binding_from_wake(
    event: &orch_core::EventRecord,
) -> Result<Option<serde_json::Value>> {
    if payload_string(event, "method") != Some("unified-channel-v1") {
        return Ok(None);
    }
    let payload = event
        .payload
        .as_ref()
        .context("unified channel WakeIssued missing payload")?;
    for key in [
        "configDigest",
        "requestDigest",
        "attachmentManifestSha256",
        "commandDigest",
        "executableIdentityDigest",
    ] {
        if !payload
            .get(key)
            .and_then(serde_json::Value::as_str)
            .is_some_and(valid_sha256)
        {
            bail!("unified channel WakeIssued payload.{key} 必须是 lowercase SHA-256");
        }
    }
    for key in [
        "driver",
        "harness",
        "observationSource",
        "invocationCwd",
        "cwdSelection",
        "fixedHead",
    ] {
        if payload
            .get(key)
            .and_then(serde_json::Value::as_str)
            .is_none_or(|value| value.trim().is_empty())
        {
            bail!("unified channel WakeIssued payload.{key} 必须是 non-blank string");
        }
    }
    let closed_tuple = |value: &serde_json::Value| {
        let Some(object) = value.as_object() else {
            return false;
        };
        let expected = ["effort", "mode", "model", "provider"];
        if object.len() != expected.len() || expected.iter().any(|key| !object.contains_key(*key)) {
            return false;
        }
        object.values().all(|value| {
            value.is_null()
                || value
                    .as_str()
                    .is_some_and(|text| !text.trim().is_empty() && text.trim() == text)
        })
    };
    if !payload
        .get("requestedTuple")
        .is_some_and(|value| closed_tuple(value))
        || !payload
            .get("effectiveTuple")
            .is_some_and(|value| closed_tuple(value))
    {
        bail!("unified channel WakeIssued tuple binding 必须是 object");
    }
    if !payload_string(event, "fixedHead").is_some_and(is_full_review_head) {
        bail!("unified channel WakeIssued fixedHead 必须是 full lowercase SHA");
    }
    Ok(Some(serde_json::json!({
        "configDigest": payload["configDigest"],
        "requestDigest": payload["requestDigest"],
        "attachmentManifestSha256": payload["attachmentManifestSha256"],
        "commandDigest": payload["commandDigest"],
        "executableIdentityDigest": payload["executableIdentityDigest"],
        "requestedTuple": payload["requestedTuple"],
        "effectiveTuple": payload["effectiveTuple"],
        "driver": payload["driver"],
        "harness": payload["harness"],
        "observationSource": payload["observationSource"],
        "invocationCwd": payload["invocationCwd"],
        "cwdSelection": payload["cwdSelection"],
        "fixedHead": payload["fixedHead"],
    })))
}

fn attach_channel_action_binding(
    wake: &orch_core::EventRecord,
    event: &mut orch_core::EventRecord,
) -> Result<()> {
    if let Some(binding) = channel_action_binding_from_wake(wake)? {
        event
            .payload
            .as_mut()
            .context("channel terminal/receipt event missing payload")?["channelBinding"] = binding;
    }
    Ok(())
}

/// Require a receipt, terminal, or mirrored request to carry the exact issued binding.
pub(crate) fn validate_existing_channel_action_binding(
    wake: &orch_core::EventRecord,
    event: &orch_core::EventRecord,
) -> Result<()> {
    let expected = channel_action_binding_from_wake(wake)?;
    let actual = event
        .payload
        .as_ref()
        .and_then(|payload| payload.get("channelBinding"));
    match expected.as_ref() {
        Some(expected) if actual == Some(expected) => Ok(()),
        None if actual.is_none() => Ok(()),
        _ => bail!(
            "{} channelBinding 与 immutable WakeIssued 不一致",
            event.kind
        ),
    }
}

fn durable_receipt_facts(event: &orch_core::EventRecord) -> Result<DurableReceiptFacts> {
    if event.kind != "WakeIssued" || event.actor != "runtime:orch" {
        bail!("backend receipt anchor must be runtime:orch WakeIssued");
    }
    let string = |key: &str| -> Result<String> {
        required_payload_field(event, key)?
            .as_str()
            .filter(|value| !value.trim().is_empty())
            .map(str::to_string)
            .with_context(|| format!("WakeIssued payload.{key} must be a non-empty string"))
    };
    let wake_id = string("wakeId")?;
    let continuation_id = string("continuationId")?;
    let identity = parse_continuation_identity(&continuation_id).map_err(anyhow::Error::msg)?;
    if identity
        .manual_wake_id
        .as_deref()
        .is_some_and(|manual_wake_id| manual_wake_id != wake_id)
    {
        bail!("manual continuation wakeId does not match WakeIssued payload.wakeId");
    }
    let agent = string("agent")?;
    if identity.agent != agent {
        bail!("WakeIssued continuation agent does not match payload.agent");
    }
    if event.round.as_deref() != Some(identity.round.as_str()) {
        bail!("WakeIssued continuation round does not match top-level round");
    }
    if event.task_id.as_deref() != identity.task_id.as_deref() {
        bail!("WakeIssued continuation task does not match top-level taskId");
    }
    let attempt = required_payload_field(event, "attemptId")?;
    match (
        identity.attempt_id.as_deref(),
        attempt.as_str(),
        attempt.is_null(),
    ) {
        (Some(expected), Some(observed), _) if expected == observed => {}
        (None, _, true) => {}
        _ => bail!("WakeIssued continuation attempt does not match payload.attemptId"),
    }
    let provider_kind =
        BackendReceiptKind::parse(&string("providerKind")?).map_err(anyhow::Error::msg)?;
    let optional_pin = |key: &str| -> Result<Option<String>> {
        match event.payload.as_ref().and_then(|payload| payload.get(key)) {
            None | Some(serde_json::Value::Null) => Ok(None),
            Some(serde_json::Value::String(value)) if !value.trim().is_empty() => {
                Ok(Some(value.clone()))
            }
            _ => bail!("WakeIssued payload.{key} must be null or a non-empty string"),
        }
    };
    let requested_provider = optional_pin("requestedProvider")?;
    let requested_model = optional_pin("requestedModel")?;
    let requested_effort = optional_pin("requestedEffort")?;
    if requires_signed_pin(provider_kind)
        && (requested_provider.is_none() || requested_model.is_none() || requested_effort.is_none())
    {
        bail!("Pi/ZCode/Agy/DSH WakeIssued requires requested provider/model/effort pins");
    }
    let request_message_sha256 = string("requestMessageSha256")?;
    let rendered_message_sha256 = string("renderedMessageSha256")?;
    if !valid_sha256(&request_message_sha256) || !valid_sha256(&rendered_message_sha256) {
        bail!("WakeIssued message digests must be lowercase SHA-256");
    }
    let request_session_id = match required_payload_field(event, "requestSessionId")? {
        serde_json::Value::Null => None,
        serde_json::Value::String(value) if !value.trim().is_empty() => Some(value.clone()),
        _ => bail!("WakeIssued requestSessionId must be null or a non-empty string"),
    };
    if provider_kind == BackendReceiptKind::SmartClaw && request_session_id.is_none() {
        bail!("SmartClaw WakeIssued requires requestSessionId");
    }
    if required_payload_field(event, "probeOffset")?.as_u64() != Some(0) {
        bail!("WakeIssued per-attempt probeOffset must be 0");
    }
    if string("backendState")? != "pending" {
        bail!("WakeIssued backendState must be pending");
    }
    Ok(DurableReceiptFacts {
        wake_id,
        continuation_id,
        identity,
        agent,
        provider_kind,
        requested_provider,
        requested_model,
        requested_effort,
        request_message_sha256,
        rendered_message_sha256,
        request_session_id,
        log_path: string("logPath")?,
        channel_binding: channel_action_binding_from_wake(event)?,
    })
}

fn backend_receipt_expectation_with_pin(
    kind: BackendReceiptKind,
    wake_id: &str,
    continuation_id: &str,
    request_message_sha256: &str,
    request_session_id: Option<&str>,
    provider: Option<&str>,
    model: Option<&str>,
    effort: Option<&str>,
) -> Result<BackendReceiptExpectation> {
    let expectation = BackendReceiptExpectation::new(
        kind,
        wake_id,
        continuation_id,
        request_message_sha256,
        request_session_id,
    )
    .map_err(anyhow::Error::msg)?;
    if !requires_signed_pin(kind) {
        return Ok(expectation);
    }
    expectation
        .with_signed_pin(
            provider.context("managed pinned wake is missing requestedProvider")?,
            model.context("managed pinned wake is missing requestedModel")?,
            effort.context("managed pinned wake is missing requestedEffort")?,
        )
        .map_err(anyhow::Error::msg)
}

fn backend_receipt_expectation_from_facts(
    facts: &DurableReceiptFacts,
) -> Result<BackendReceiptExpectation> {
    backend_receipt_expectation_with_pin(
        facts.provider_kind,
        &facts.wake_id,
        &facts.continuation_id,
        &facts.request_message_sha256,
        facts.request_session_id.as_deref(),
        facts.requested_provider.as_deref(),
        facts.requested_model.as_deref(),
        facts.requested_effort.as_deref(),
    )
}

/// Rebuild the provider receipt grammar from one exact durable `WakeIssued`.
///
/// Handshake and late reconciliation must consume the same signed provider,
/// model, effort, continuation and session identity that the runtime actually
/// published. Reconstructing a second expectation in the CLI would silently
/// drop Pi/ZCode pins and reject their otherwise valid native receipt.
pub fn backend_receipt_expectation_for_wake(
    root: &Path,
    round: &str,
    wake_id: &str,
) -> Result<BackendReceiptExpectation> {
    let events = read_round_ledger_events(root, round)?;
    let wakes = events
        .iter()
        .filter(|event| {
            event.kind == "WakeIssued" && payload_string(event, "wakeId") == Some(wake_id)
        })
        .collect::<Vec<_>>();
    if wakes.len() != 1 {
        bail!(
            "backend receipt expectation requires one WakeIssued for wakeId={wake_id}, found {}",
            wakes.len()
        );
    }
    backend_receipt_expectation_from_facts(&durable_receipt_facts(wakes[0])?)
}

fn existing_receipt_matches(
    event: &orch_core::EventRecord,
    facts: &DurableReceiptFacts,
) -> Result<bool> {
    if event.kind != "AgentEventReceived"
        || payload_string(event, "agentEvent") != Some("wake-backend-receipt")
    {
        return Ok(false);
    }
    let anchored = payload_string(event, "actionId") == Some(facts.wake_id.as_str())
        || payload_string(event, "wakeId") == Some(facts.wake_id.as_str());
    if !anchored {
        return Ok(false);
    }
    let exact_string =
        |key: &str, expected: &str| -> bool { payload_string(event, key) == Some(expected) };
    let expected_session = facts.request_session_id.as_deref();
    let session_matches = match event
        .payload
        .as_ref()
        .and_then(|payload| payload.get("requestSessionId"))
    {
        Some(serde_json::Value::Null) => expected_session.is_none(),
        Some(serde_json::Value::String(value)) => Some(value.as_str()) == expected_session,
        _ => false,
    };
    let observed_session_matches = if matches!(
        facts.provider_kind,
        BackendReceiptKind::ZCode | BackendReceiptKind::Agy
    ) {
        event
            .payload
            .as_ref()
            .and_then(|payload| payload.get("observedSessionId"))
            .is_some_and(serde_json::Value::is_null)
    } else {
        payload_string(event, "observedSessionId").is_some_and(|value| !value.is_empty())
    };
    let pin_matches = !requires_signed_pin(facts.provider_kind)
        || (facts
            .requested_provider
            .as_deref()
            .is_some_and(|expected| exact_string("requestedProvider", expected))
            && facts
                .requested_model
                .as_deref()
                .is_some_and(|expected| exact_string("requestedModel", expected))
            && facts
                .requested_effort
                .as_deref()
                .is_some_and(|expected| exact_string("requestedEffort", expected)));
    let observed_channel_binding = event
        .payload
        .as_ref()
        .and_then(|payload| payload.get("channelBinding"));
    let channel_binding_matches = match facts.channel_binding.as_ref() {
        Some(expected) => observed_channel_binding == Some(expected),
        None => observed_channel_binding.is_none(),
    };
    let valid = event.actor == "runtime:orch"
        && event.round.as_deref() == Some(facts.identity.round.as_str())
        && event.task_id.as_deref() == facts.identity.task_id.as_deref()
        && exact_string("actionId", &facts.wake_id)
        && exact_string("wakeId", &facts.wake_id)
        && exact_string("continuationId", &facts.continuation_id)
        && match facts.identity.attempt_id.as_deref() {
            Some(expected) => exact_string("attemptId", expected),
            None => event
                .payload
                .as_ref()
                .and_then(|payload| payload.get("attemptId"))
                .is_some_and(serde_json::Value::is_null),
        }
        && exact_string("agent", &facts.agent)
        && exact_string("providerKind", facts.provider_kind.as_str())
        && exact_string("receiptKind", facts.provider_kind.as_str())
        && exact_string("requestMessageSha256", &facts.request_message_sha256)
        && exact_string("renderedMessageSha256", &facts.rendered_message_sha256)
        && exact_string("logPath", &facts.log_path)
        && exact_string("backendState", "accepted")
        && session_matches
        && observed_session_matches
        && pin_matches
        && channel_binding_matches
        && event
            .payload
            .as_ref()
            .and_then(|payload| payload.get("probeOffset"))
            .and_then(serde_json::Value::as_u64)
            == Some(0)
        && event
            .payload
            .as_ref()
            .and_then(|payload| payload.get("probeEnd"))
            .and_then(serde_json::Value::as_u64)
            .is_some_and(|value| value > 0)
        && payload_string(event, "windowSha256").is_some_and(valid_sha256);
    if !valid {
        bail!(
            "conflicting backend receipt exists for wakeId={}",
            facts.wake_id
        );
    }
    Ok(true)
}

/// Validate one accepted backend receipt against the complete immutable
/// `WakeIssued` tuple. Generic schema-3 review reuses this parser rather than
/// maintaining a weaker receipt grammar.
pub(crate) fn accepted_backend_receipt_matches_wake(
    wake: &orch_core::EventRecord,
    receipt: &orch_core::EventRecord,
) -> Result<bool> {
    let facts = durable_receipt_facts(wake)?;
    existing_receipt_matches(receipt, &facts)
}

const DEGRADED_BACKEND_RECEIPT_EVENT: &str = "wake-backend-receipt-degraded";

fn degraded_backend_receipt_event(
    round: &str,
    facts: &DurableReceiptFacts,
    reason: &str,
) -> orch_core::EventRecord {
    let mut event = ledger::event(
        "AgentEventReceived",
        "runtime:orch",
        facts.identity.task_id.as_deref(),
        Some(round),
        serde_json::json!({
            "agentEvent": DEGRADED_BACKEND_RECEIPT_EVENT,
            "actionId": facts.wake_id,
            "wakeId": facts.wake_id,
            "continuationId": facts.continuation_id,
            "attemptId": facts.identity.attempt_id,
            "agent": facts.agent,
            "providerKind": facts.provider_kind.as_str(),
            "requestMessageSha256": facts.request_message_sha256,
            "renderedMessageSha256": facts.rendered_message_sha256,
            "requestSessionId": facts.request_session_id,
            "logPath": facts.log_path,
            "backendState": "degraded",
            "receiptState": "canonical-reconciliation-failed-after-spawn",
            "externalEffect": "unknown",
            "reason": reason,
        }),
    );
    if let Some(binding) = facts.channel_binding.as_ref() {
        event
            .payload
            .as_mut()
            .expect("degraded receipt has payload")["channelBinding"] = binding.clone();
    }
    event
}

fn degraded_backend_receipt_matches(
    event: &orch_core::EventRecord,
    facts: &DurableReceiptFacts,
) -> Result<bool> {
    if event.kind != "AgentEventReceived"
        || payload_string(event, "agentEvent") != Some(DEGRADED_BACKEND_RECEIPT_EVENT)
    {
        return Ok(false);
    }
    let anchored = payload_string(event, "actionId") == Some(facts.wake_id.as_str())
        || payload_string(event, "wakeId") == Some(facts.wake_id.as_str());
    if !anchored {
        return Ok(false);
    }
    let exact = |key: &str, expected: &str| payload_string(event, key) == Some(expected);
    let request_session_matches = match (
        event
            .payload
            .as_ref()
            .and_then(|payload| payload.get("requestSessionId")),
        facts.request_session_id.as_deref(),
    ) {
        (Some(serde_json::Value::Null), None) => true,
        (Some(serde_json::Value::String(observed)), Some(expected)) => observed == expected,
        _ => false,
    };
    let observed_channel_binding = event
        .payload
        .as_ref()
        .and_then(|payload| payload.get("channelBinding"));
    let channel_binding_matches = match facts.channel_binding.as_ref() {
        Some(expected) => observed_channel_binding == Some(expected),
        None => observed_channel_binding.is_none(),
    };
    let valid = event.actor == "runtime:orch"
        && event.round.as_deref() == Some(facts.identity.round.as_str())
        && event.task_id.as_deref() == facts.identity.task_id.as_deref()
        && exact("actionId", &facts.wake_id)
        && exact("wakeId", &facts.wake_id)
        && exact("continuationId", &facts.continuation_id)
        && match facts.identity.attempt_id.as_deref() {
            Some(attempt) => exact("attemptId", attempt),
            None => event
                .payload
                .as_ref()
                .and_then(|payload| payload.get("attemptId"))
                .is_some_and(serde_json::Value::is_null),
        }
        && exact("agent", &facts.agent)
        && exact("providerKind", facts.provider_kind.as_str())
        && exact("requestMessageSha256", &facts.request_message_sha256)
        && exact("renderedMessageSha256", &facts.rendered_message_sha256)
        && exact("logPath", &facts.log_path)
        && exact("backendState", "degraded")
        && exact(
            "receiptState",
            "canonical-reconciliation-failed-after-spawn",
        )
        && exact("externalEffect", "unknown")
        && request_session_matches
        && channel_binding_matches
        && payload_string(event, "reason").is_some_and(|value| !value.trim().is_empty());
    if !valid {
        bail!(
            "conflicting degraded backend receipt exists for wakeId={}",
            facts.wake_id
        );
    }
    Ok(true)
}

fn reject_degraded_backend_receipt<T>(
    root: &Path,
    round: &str,
    wake_id: &str,
    reason: &str,
) -> Result<T> {
    let bounded_reason = reason.chars().take(1_024).collect::<String>();
    let durable_reason = format!(
        "backend receipt reconciliation degraded after provider spawn; external effect remains possible and automatic respawn is fenced: {bounded_reason}"
    );
    let rejection = failure::ActionRejection::from_command_outcome(
        "wake-backend-receipt",
        wake_id,
        &durable_reason,
        failure::CommandOutcome::PendingReceipt,
    )?;
    ledger::append_checked(root, round, |events| {
        let wakes = events
            .iter()
            .filter(|event| {
                event.kind == "WakeIssued" && payload_string(event, "wakeId") == Some(wake_id)
            })
            .collect::<Vec<_>>();
        if wakes.len() != 1 {
            bail!(
                "degraded backend receipt requires one WakeIssued for wakeId={wake_id}, found {}",
                wakes.len()
            );
        }
        let facts = durable_receipt_facts(wakes[0])?;
        let durable_rejection = if facts.identity.role.as_deref() == Some("review") {
            let task = facts
                .identity
                .task_id
                .as_deref()
                .context("generic degraded receipt 缺 taskId")?;
            let attempt = crate::attempt::current_attempt(events, task)?
                .context("generic degraded receipt 缺 current attempt")?;
            if Some(attempt.attempt_id.as_str()) != facts.identity.attempt_id.as_deref() {
                bail!("generic degraded receipt attempt 漂移");
            }
            rejection.clone().with_attempt(&attempt)
        } else {
            rejection.clone()
        };
        let degraded = events
            .iter()
            .map(|event| degraded_backend_receipt_matches(event, &facts))
            .collect::<Result<Vec<_>>>()?
            .into_iter()
            .filter(|matched| *matched)
            .count();
        if degraded > 1 {
            bail!(
                "degraded backend receipt is not unique for wakeId={wake_id}: found {}",
                degraded
            );
        }
        let rejected = events
            .iter()
            .filter(|event| {
                event.kind == "ActionRejected"
                    && event.actor == "runtime:orch"
                    && event.round.as_deref() == Some(round)
                    && event.task_id.as_deref() == facts.identity.task_id.as_deref()
                    && payload_string(event, "operation") == Some("wake-backend-receipt")
                    && payload_string(event, "actionId") == Some(wake_id)
            })
            .count();
        if rejected > 1 {
            bail!(
                "degraded backend receipt rejection is not unique for wakeId={wake_id}: found {rejected}"
            );
        }
        let mut append = Vec::new();
        if degraded == 0 {
            append.push(degraded_backend_receipt_event(
                round,
                &facts,
                &bounded_reason,
            ));
        }
        if rejected == 0 {
            append.push(failure::rejection_event(
                round,
                facts.identity.task_id.as_deref(),
                &durable_rejection,
            ));
        }
        Ok(append)
    })?;
    Err(rejection.into_error())
}

/// Return the current formal request for one `(round, task, role)` slot.
///
/// Ledger append order is authoritative: timestamps and event ids are not a
/// substitute for the durable sequence.  Deliberately do not pre-validate the
/// remaining request identity here; the receipt guard must see a malformed
/// latest request and reject it instead of silently falling back to an older
/// one.
pub fn current_review_request<'a>(
    events: &'a [orch_core::EventRecord],
    round: &str,
    task_id: &str,
    role: &str,
) -> Option<&'a orch_core::EventRecord> {
    events.iter().rev().find(|event| {
        event.kind == "ReviewRequested"
            && event.round.as_deref() == Some(round)
            && event.task_id.as_deref() == Some(task_id)
            && payload_string(event, "role") == Some(role)
    })
}

fn review_request_matches(
    events: &[orch_core::EventRecord],
    event: &orch_core::EventRecord,
    facts: &DurableReceiptFacts,
    allow_historical_request: bool,
) -> Result<bool> {
    if event.kind != "ReviewRequested" {
        return Ok(false);
    }
    let (Some(task_id), Some(role)) = (
        facts.identity.task_id.as_deref(),
        facts.identity.role.as_deref(),
    ) else {
        return Ok(false);
    };
    let selected = if role == "review" {
        payload_string(event, "wakeId") == Some(facts.wake_id.as_str())
            && payload_string(event, "attemptId") == facts.identity.attempt_id.as_deref()
            && payload_string(event, "agent") == Some(facts.agent.as_str())
            && payload_string(event, "harness") == Some(facts.agent.as_str())
    } else {
        let Some(current) = current_review_request(events, &facts.identity.round, task_id, role)
        else {
            return Ok(false);
        };
        if allow_historical_request {
            // An immutable accepted receipt may be replayed after a later request
            // supersedes its slot.  It remains action-scoped to its own wake id.
            payload_string(event, "wakeId") == Some(facts.wake_id.as_str())
        } else {
            std::ptr::eq(event, current)
        }
    };
    if !selected {
        return Ok(false);
    }
    let anchored = payload_string(event, "wakeId") == Some(facts.wake_id.as_str())
        || payload_string(event, "continuationId") == Some(facts.continuation_id.as_str());
    let exact = |key: &str, expected: &str| payload_string(event, key) == Some(expected);
    let request_session_matches = match (
        event
            .payload
            .as_ref()
            .and_then(|payload| payload.get("requestSessionId")),
        facts.request_session_id.as_deref(),
    ) {
        (Some(serde_json::Value::Null), None) => true,
        (Some(serde_json::Value::String(observed)), Some(expected)) => observed == expected,
        _ => false,
    };
    let valid = anchored
        && event.actor == "runtime:orch"
        && event.round.as_deref() == Some(facts.identity.round.as_str())
        && event.task_id.as_deref() == facts.identity.task_id.as_deref()
        && facts.identity.role.is_some()
        && facts
            .identity
            .role
            .as_deref()
            .is_some_and(|role| exact("role", role))
        && facts
            .identity
            .attempt_id
            .as_deref()
            .is_some_and(|attempt| exact("attemptId", attempt))
        && exact("agent", &facts.agent)
        && exact("wakeId", &facts.wake_id)
        && exact("continuationId", &facts.continuation_id)
        && exact("providerKind", facts.provider_kind.as_str())
        && exact("requestMessageSha256", &facts.request_message_sha256)
        && exact("renderedMessageSha256", &facts.rendered_message_sha256)
        && exact("logPath", &facts.log_path)
        && request_session_matches;
    if !valid {
        if role == "review" {
            bail!(
                "generic ReviewRequested tuple 与 wake facts 冲突: {}",
                facts.wake_id
            );
        }
        bail!(
            "conflicting ReviewRequested exists for wakeId={}",
            facts.wake_id
        );
    }
    Ok(true)
}

fn receipt_ledger_state(
    events: &[orch_core::EventRecord],
    facts: &DurableReceiptFacts,
) -> Result<BackendReceiptLedgerState> {
    let supersession = wake_supersession_projection(events, &facts.identity.round)?;
    let wake_issued_count = events
        .iter()
        .filter(|event| {
            event.kind == "WakeIssued"
                && payload_string(event, "wakeId") == Some(facts.wake_id.as_str())
        })
        .count();
    if facts.channel_binding.is_some()
        && facts.identity.task_id.is_some()
        && facts.identity.role.is_none()
        && facts.identity.manual_wake_id.is_none()
    {
        let wake_position = events
            .iter()
            .position(|event| {
                event.kind == "WakeIssued"
                    && payload_string(event, "wakeId") == Some(facts.wake_id.as_str())
            })
            .context("implementation receipt WakeIssued missing from ledger slice")?;
        let task = facts.identity.task_id.as_deref().unwrap();
        let attempt = facts.identity.attempt_id.as_deref().unwrap();
        let dispatch_count = events[..wake_position]
            .iter()
            .filter(|event| {
                event.kind == "DispatchIssued"
                    && event.actor == "runtime:orch"
                    && event.round.as_deref() == Some(facts.identity.round.as_str())
                    && event.task_id.as_deref() == Some(task)
                    && payload_string(event, "attemptId") == Some(attempt)
                    && payload_string(event, "agent") == Some("local")
                    && payload_string(event, "method") == Some("harness-channel")
                    && payload_string(event, "harness") == Some(facts.agent.as_str())
            })
            .count();
        if dispatch_count != 1 {
            bail!(
                "implementation receipt requires one exact prior local harness DispatchIssued, found {dispatch_count}"
            );
        }
    }
    let mut receipt_count = 0usize;
    for event in events {
        if existing_receipt_matches(event, facts)? {
            receipt_count += 1;
        }
    }
    let allow_historical_request = receipt_count == 1;
    let mut review_requested_count = 0usize;
    for event in events {
        let validated_peer = event.kind == "ReviewRequested"
            && payload_string(event, "continuationId") == Some(facts.continuation_id.as_str())
            && payload_string(event, "wakeId").is_some_and(|other_wake_id| {
                let reaches = |start: &str, target: &str| {
                    let mut cursor = start;
                    for _ in 0..=supersession.successor_by_source.len() {
                        let Some(successor) = supersession.successor_by_source.get(cursor) else {
                            return false;
                        };
                        if successor == target {
                            return true;
                        }
                        cursor = successor;
                    }
                    false
                };
                reaches(other_wake_id, &facts.wake_id) || reaches(&facts.wake_id, other_wake_id)
            });
        if validated_peer {
            // A valid supersession deliberately creates a second
            // ReviewRequested for the same continuation. Ignore only an
            // ancestor/descendant in the exact authenticated chain; every
            // unrelated duplicate still reaches review_request_matches and
            // fails closed.
            continue;
        }
        if review_request_matches(events, event, facts, allow_historical_request)? {
            review_requested_count += 1;
        }
    }
    let rejected = events.iter().any(|event| {
        event.kind == "ActionRejected"
            && payload_string(event, "operation") == Some("wake-backend-receipt")
            && payload_string(event, "actionId") == Some(facts.wake_id.as_str())
    });
    BackendReceiptLedgerState::new(
        &facts.wake_id,
        &facts.continuation_id,
        &facts.request_message_sha256,
        wake_issued_count,
        review_requested_count,
        receipt_count,
        rejected,
    )
    .map_err(anyhow::Error::msg)
}

fn reconcile_backend_receipt_locked(root: &Path, round: &str, wake_id: &str) -> Result<bool> {
    let initial = read_round_ledger_events(root, round)?;
    if !live_schema3_reconciliation_allowed(&initial, round)? {
        return Ok(false);
    }
    let wakes = initial
        .iter()
        .filter(|event| {
            event.kind == "WakeIssued" && payload_string(event, "wakeId") == Some(wake_id)
        })
        .collect::<Vec<_>>();
    if wakes.len() != 1 {
        bail!(
            "backend receipt reconcile requires one WakeIssued for wakeId={wake_id}, found {}",
            wakes.len()
        );
    }
    let facts = durable_receipt_facts(wakes[0])?;
    let initial_state = receipt_ledger_state(&initial, &facts)?;
    if initial_state.receipt_count == 1 {
        return Ok(true);
    }
    let captured =
        capture_probe_window(Path::new(&facts.log_path), 0).map_err(anyhow::Error::msg)?;
    let bytes = read_captured_probe_bytes(captured)?;
    let expectation = backend_receipt_expectation_from_facts(&facts)?;
    let Some(receipt) =
        backend_receipt_from_log(&expectation, &bytes, false).map_err(anyhow::Error::msg)?
    else {
        return Ok(false);
    };
    let mut candidate = backend_receipt_event(
        round,
        facts.identity.task_id.as_deref(),
        facts.identity.attempt_id.as_deref(),
        &facts.agent,
        &facts.rendered_message_sha256,
        &facts.log_path,
        &receipt,
        &sha256_hex(&bytes),
    );
    attach_channel_action_binding(wakes[0], &mut candidate)?;
    let appended = ledger::append_checked(root, round, |events| {
        if !live_schema3_reconciliation_allowed(events, round)? {
            return Ok(Vec::new());
        }
        let wakes = events
            .iter()
            .filter(|event| {
                event.kind == "WakeIssued" && payload_string(event, "wakeId") == Some(wake_id)
            })
            .collect::<Vec<_>>();
        if wakes.len() != 1 {
            bail!(
                "backend receipt fresh replay found {} WakeIssued entries for wakeId={wake_id}",
                wakes.len()
            );
        }
        let fresh = durable_receipt_facts(wakes[0])?;
        if fresh.wake_id != facts.wake_id
            || fresh.continuation_id != facts.continuation_id
            || fresh.agent != facts.agent
            || fresh.provider_kind != facts.provider_kind
            || fresh.request_message_sha256 != facts.request_message_sha256
            || fresh.rendered_message_sha256 != facts.rendered_message_sha256
            || fresh.request_session_id != facts.request_session_id
            || fresh.log_path != facts.log_path
            || fresh.channel_binding != facts.channel_binding
        {
            bail!("WakeIssued receipt facts changed during reconcile");
        }
        let state = receipt_ledger_state(events, &facts)?;
        match backend_receipt_reconcile_decision(&state, &receipt).map_err(anyhow::Error::msg)? {
            BackendReceiptReconcileDecision::AppendReceiptOnly { .. } => Ok(vec![candidate]),
            BackendReceiptReconcileDecision::AlreadyCommitted { .. } => Ok(Vec::new()),
        }
    })?;
    Ok(appended <= 1)
}

/// Production late-reconcile entry. The per-agent identity lock prevents an
/// exact retry, daemon tick, and the original waiter from appending twice.
/// Legacy or closed generations return `false` before reading the wake log.
pub fn reconcile_backend_receipt(root: &Path, round: &str, wake_id: &str) -> Result<bool> {
    let events = read_round_ledger_events(root, round)?;
    if !live_schema3_reconciliation_allowed(&events, round)? {
        return Ok(false);
    }
    let wake = events
        .iter()
        .find(|event| {
            event.kind == "WakeIssued" && payload_string(event, "wakeId") == Some(wake_id)
        })
        .with_context(|| format!("no WakeIssued for wakeId={wake_id}"))?;
    let agent = payload_string(wake, "agent").context("WakeIssued missing agent")?;
    with_wake_identity_lock_wait(root, agent, || {
        reconcile_backend_receipt_locked(root, round, wake_id)
    })
}

/// Daemon-tick recovery for crashes after the initial WakeIssued transaction.
/// Only new-schema pending actions are considered; legacy wake facts are left
/// untouched and can neither be upgraded nor misclassified by log shape.
fn reconcile_terminal_wakes_best_effort(
    wake_ids: BTreeSet<String>,
    mut reconcile: impl FnMut(&str) -> Result<bool>,
) -> Vec<(String, String)> {
    let mut failures = Vec::new();
    for wake_id in wake_ids {
        if let Err(error) = reconcile(&wake_id) {
            failures.push((wake_id, format!("{error:#}")));
        }
    }
    failures
}

/// Reconcile all pending receipts and managed terminals in one open schema-3
/// round. Legacy or closed generations are read-only and return zero.
/// This bulk operation leaves physical maintenance to its caller, so one foreground GC
/// measures and reports all deletions once instead of hiding them in nested callbacks.
pub fn reconcile_pending_backend_receipts(root: &Path, round: &str) -> Result<usize> {
    crate::reclaim::checked_storage_path(root, Path::new("coordination/runtime"))?;
    let events = read_round_ledger_events(root, round)?;
    if !live_schema3_reconciliation_allowed(&events, round)? {
        return Ok(0);
    }
    let mut pending = BTreeSet::new();
    let mut terminal_pending = BTreeSet::new();
    for wake in events.iter().filter(|event| {
        event.kind == "WakeIssued"
            && event.round.as_deref() == Some(round)
            && payload_string(event, "controlWakeId").is_some()
    }) {
        if rooted_generic_review_wake(&events, round, wake)?
            && !recorded_generic_review_wake(&events, round, wake)?
        {
            continue;
        }
        let Some(capability) = terminal_capability_from_wake(wake)? else {
            continue;
        };
        if capability == crate::harness::CapabilitySource::Absent {
            continue;
        }
        let wake_id = payload_string(wake, "wakeId").context("WakeIssued missing wakeId")?;
        let already_terminal = events.iter().any(|event| {
            event.kind == "ManagedWakeTerminated"
                && payload_string(event, "wakeId") == Some(wake_id)
        });
        if !already_terminal {
            terminal_pending.insert(wake_id.to_string());
        }
    }
    for wake in events.iter().filter(|event| {
        event.kind == "WakeIssued"
            && event.round.as_deref() == Some(round)
            && payload_string(event, "backendState") == Some("pending")
    }) {
        if rooted_generic_review_wake(&events, round, wake)? {
            continue;
        }
        let facts = durable_receipt_facts(wake)?;
        let degraded = events
            .iter()
            .map(|event| degraded_backend_receipt_matches(event, &facts))
            .collect::<Result<Vec<_>>>()?
            .into_iter()
            .filter(|matched| *matched)
            .count();
        if degraded > 1 {
            bail!(
                "pending wake has multiple degraded backend receipts for wakeId={}",
                facts.wake_id
            );
        }
        // A degraded marker means the provider was already spawned and its
        // external effect remains uncertain. Daemon ticks must not repeatedly
        // reject it or infer permission to start a replacement. An explicit
        // exact late reconcile may still promote a subsequently valid receipt.
        if degraded == 0 {
            pending.insert(facts.wake_id);
        }
    }
    let mut accepted = 0usize;
    for wake_id in pending {
        if reconcile_backend_receipt(root, round, &wake_id)? {
            accepted += 1;
        }
        terminal_pending.insert(wake_id);
    }
    let terminal_failures = reconcile_terminal_wakes_best_effort(terminal_pending, |wake_id| {
        reconcile_managed_wake_termination_with_maintenance(root, round, wake_id, false)
    });
    for (wake_id, error) in terminal_failures {
        eprintln!("[orch] pending terminal reconcile retained unrelated wake {wake_id}: {error}");
    }
    Ok(accepted)
}

// ── B110 action 精确通道事实 ─────────────────────────────────────────────
// design 契约（r47/B110 任务卡）：
// - actionId/attemptId/attemptNo/pid/logPath/probeOffset/probeEnd 固化进
//   dispatch/nudge/resume 的 durable 事件链；同 action 状态事件身份相同。
// - Delivered 只表示外部 spawn 成功（DeliveryState::Delivered），绝不冒充
//   Engaged；Engaged 由精确日志窗口 [probeOffset, probeEnd) 中的 provider
//   活动另判（wake_engaged_in_window / ActionChannelFacts::engaged_in）。
// - POKE/no-wake 无 pid/log → 显式 Pending；facts 缺字段或类型错 fail-closed。

/// spawn 维度的投递状态。**只**表示外部进程是否成功拉起——Delivered 不代表
/// provider 已咬合（咬合须由精确窗口内的 provider 活动另判）；Pending 用于
/// POKE 备用道 / --no-wake / spawn 失败，是显式状态而非缺席。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DeliveryState {
    /// 未成功 spawn（POKE 备用道 / --no-wake / spawn 失败）——显式待投递。
    Pending,
    /// 外部 spawn 已成功（仅表示进程拉起，不代表已咬合）。
    Delivered,
}

impl DeliveryState {
    /// 从 spawn 结果推导投递状态：成功 → Delivered；失败/未注入 → Pending。
    /// 绝不把 spawn 成功提升为 Engaged（M2 变异点）。
    pub fn from_spawn(spawn_ok: bool) -> Self {
        if spawn_ok {
            DeliveryState::Delivered
        } else {
            DeliveryState::Pending
        }
    }

    pub fn as_str(&self) -> &'static str {
        match self {
            DeliveryState::Pending => "pending",
            DeliveryState::Delivered => "delivered",
        }
    }
}

impl std::fmt::Display for DeliveryState {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// 精确探针窗口：只取 `log[start, end)` 字节（M1 变异点：退化整份日志即红）。
/// `start > end` 或越界 ⇒ Err（fail-closed，绝不悄悄放宽窗口读到旧噪声）。
pub fn exact_probe_slice(log: &[u8], start: u64, end: u64) -> Result<&[u8], String> {
    if start > end {
        return Err(format!("probe 窗口非法：start({start}) > end({end})"));
    }
    let start = usize::try_from(start).map_err(|_| format!("probe start 超出 usize: {start}"))?;
    let end = usize::try_from(end).map_err(|_| format!("probe end 超出 usize: {end}"))?;
    if end > log.len() {
        return Err(format!(
            "probe 窗口越界：end({end}) > log.len({})（拒绝读未到位的字节）",
            log.len()
        ));
    }
    Ok(&log[start..end])
}

/// 在精确窗口内判咬合：只有 `[start, end)` 内的 thread.started/turn.started
/// 才算 provider 活动；窗口外（offset 之前）的旧 fault/engaged 标记不参与判定。
pub fn wake_engaged_in_window(log: &[u8], start: u64, end: u64) -> Result<bool, String> {
    let slice = exact_probe_slice(log, start, end)?;
    Ok(wake_engaged(&String::from_utf8_lossy(slice)))
}

/// 一次 handshake 轮询先捕获、后消费的不可变探针观测。
///
/// `probe_end` 在 [capture_probe_window] 返回时即冻结；后续 evaluator 只会
/// 读取 `[probe_offset, probe_end)`，不会用读取所得 bytes 的长度扩大右端。
/// 打开的文件句柄同时钉住本次观测的文件对象，避免路径在 stat/read 之间被替换。
#[derive(Debug)]
pub struct CapturedProbeWindow {
    pub log_path: PathBuf,
    pub probe_offset: u64,
    pub probe_end: u64,
    file: File,
}

/// 捕获一次 immutable `{logPath, probeOffset, probeEnd}` 观测。
///
/// 这是 handshake 每轮严格两段式协议的第一段。缺文件、symlink、非普通文件、
/// stat/open 对象不一致或 offset 越界都 fail-closed；绝不回退到 legacy 日志，
/// 也不把错误折叠成空窗口。
pub fn capture_probe_window(
    log_path: &Path,
    probe_offset: u64,
) -> Result<CapturedProbeWindow, String> {
    let path_meta = fs::symlink_metadata(log_path)
        .map_err(|error| format!("capture probe stat 失败 {}: {error}", log_path.display()))?;
    if !path_meta.file_type().is_file() || path_meta.file_type().is_symlink() {
        return Err(format!(
            "capture probe 只接受 regular non-symlink: {}",
            log_path.display()
        ));
    }

    let file = File::open(log_path)
        .map_err(|error| format!("capture probe open 失败 {}: {error}", log_path.display()))?;
    let opened_meta = file
        .metadata()
        .map_err(|error| format!("capture probe fstat 失败 {}: {error}", log_path.display()))?;
    if !opened_meta.file_type().is_file() {
        return Err(format!(
            "capture probe 打开对象不是普通文件: {}",
            log_path.display()
        ));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if path_meta.dev() != opened_meta.dev() || path_meta.ino() != opened_meta.ino() {
            return Err(format!(
                "capture probe stat/open 对象发生变化（fail-closed）: {}",
                log_path.display()
            ));
        }
    }

    let probe_end = opened_meta.len();
    if probe_offset > probe_end {
        return Err(format!(
            "capture probe offset 越界：offset({probe_offset}) > end({probe_end})"
        ));
    }
    Ok(CapturedProbeWindow {
        log_path: log_path.to_path_buf(),
        probe_offset,
        probe_end,
        file,
    })
}

/// 消费一次已捕获的探针观测。
///
/// 这是两段式协议的第二段：只按捕获的 `probe_end` 读取固定字节数。
/// 文件在 capture 后增长时，新字节留给下一轮；文件被截短时 `read_exact`
/// 返回 Err，越界竞态 fail-closed，绝不放宽窗口。
pub fn evaluate_captured_probe(mut captured: CapturedProbeWindow) -> Result<bool, String> {
    let captured_len = usize::try_from(captured.probe_end)
        .map_err(|_| format!("captured probeEnd 超出 usize: {}", captured.probe_end))?;
    let mut log = vec![0_u8; captured_len];
    captured.file.read_exact(&mut log).map_err(|error| {
        format!(
            "evaluate captured probe 读取 [0, {}) 失败 {}: {error}",
            captured.probe_end,
            captured.log_path.display()
        )
    })?;
    wake_engaged_in_window(&log, captured.probe_offset, captured.probe_end)
}

/// Consume a pinned immutable capture with a provider-bound receipt grammar.
/// The caller owns the stream-closed observation; PID/wrapper exit is never
/// synthesized into acceptance here.
pub fn evaluate_captured_backend_receipt(
    captured: CapturedProbeWindow,
    expectation: &BackendReceiptExpectation,
    stream_closed: bool,
) -> std::result::Result<Option<BackendReceipt>, String> {
    let bytes = read_captured_probe_bytes(captured).map_err(|error| format!("{error:#}"))?;
    backend_receipt_from_log(expectation, &bytes, stream_closed)
}

/// 一次 action 的精确通道事实：spawn 成功后由 wake 返回并固化进 durable
/// 事件链（DispatchWakeDelivered/ResumeWakeDelivered 及同 action 后续状态事件，
/// nudge 落 NudgeIssued payload）。构造与解析都 fail-closed（M3 变异点）：
/// 空 actionId/attemptId、attemptNo=0、pid=0、空 logPath、窗口倒挂一律拒绝。
///
/// 字段语义：
/// - `log_path`：本次注入的 per-attempt 专属日志（绝不用按 mtime 轮换的
///   legacy `wake-<agent>.log`——相邻 action 会把它重链到别的文件造成串台）；
/// - `probe_offset`：本 action 内容在 `log_path` 中的起始字节（专属文件从 0 起，
///   offset 之前不存在任何旧 fault/engaged 噪声）；
/// - `probe_end`：投递时刻的文件长度水位（固化审计事实）；handshake 的后续
///   探活每轮另由 [capture_probe_window] 捕获新水位，并把该不可变右端显式传给
///   evaluator；任何 evaluator 都不得从 bytes 长度动态扩大右端。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ActionChannelFacts {
    pub action_id: String,
    pub attempt_id: String,
    pub attempt_no: u64,
    pub pid: u32,
    pub log_path: String,
    pub probe_offset: u64,
    pub probe_end: u64,
}

impl ActionChannelFacts {
    /// 构造即校验（fail-closed）：任何身份字段非法都拒绝产出事实。
    pub fn new(
        action_id: &str,
        attempt_id: &str,
        attempt_no: u64,
        pid: u32,
        log_path: &str,
        probe_offset: u64,
        probe_end: u64,
    ) -> Result<Self, String> {
        if action_id.is_empty() {
            return Err("action facts fail-closed：actionId 不能为空".to_string());
        }
        if attempt_id.is_empty() {
            return Err("action facts fail-closed：attemptId 不能为空".to_string());
        }
        if attempt_no == 0 {
            return Err("action facts fail-closed：attemptNo 必须 ≥ 1".to_string());
        }
        if pid == 0 {
            return Err("action facts fail-closed：pid 必须 ≥ 1".to_string());
        }
        if log_path.is_empty() {
            return Err("action facts fail-closed：logPath 不能为空".to_string());
        }
        if probe_end < probe_offset {
            return Err(format!(
                "action facts fail-closed：probe 窗口倒挂 [{probe_offset}, {probe_end})"
            ));
        }
        Ok(ActionChannelFacts {
            action_id: action_id.to_string(),
            attempt_id: attempt_id.to_string(),
            attempt_no,
            pid,
            log_path: log_path.to_string(),
            probe_offset,
            probe_end,
        })
    }

    /// 从 durable 事件 payload 解析通道事实：缺字段或类型错一律 fail-closed。
    /// 期望字段：actionId/attemptId（非空 string）、attemptNo（≥1 整数）、
    /// pid（≥1 整数）、logPath（非空 string）、probeOffset/probeEnd（整数）。
    pub fn from_payload(payload: &serde_json::Value) -> Result<Self, String> {
        let str_field = |key: &str| -> Result<String, String> {
            match payload.get(key) {
                Some(serde_json::Value::String(value)) if !value.is_empty() => Ok(value.clone()),
                _ => Err(format!(
                    "action facts fail-closed：payload {key} 缺失 / 类型错误 / 为空"
                )),
            }
        };
        let u64_field = |key: &str| -> Result<u64, String> {
            match payload.get(key).and_then(serde_json::Value::as_u64) {
                Some(value) => Ok(value),
                None => Err(format!(
                    "action facts fail-closed：payload {key} 缺失 / 类型错误"
                )),
            }
        };
        let pid_raw = u64_field("pid")?;
        let pid = u32::try_from(pid_raw)
            .map_err(|_| format!("action facts fail-closed：payload pid 超出 u32: {pid_raw}"))?;
        ActionChannelFacts::new(
            &str_field("actionId")?,
            &str_field("attemptId")?,
            u64_field("attemptNo")?,
            pid,
            &str_field("logPath")?,
            u64_field("probeOffset")?,
            u64_field("probeEnd")?,
        )
    }

    /// 把通道四元组（pid/logPath/probeOffset/probeEnd）并入 durable 事件
    /// payload；actionId/attemptId/attemptNo 由基础身份 payload 携带，此处不重复
    /// 写入以免双写漂移——同 action 状态事件身份相同由构造保证。
    pub fn insert_channel_fields(&self, payload: &mut serde_json::Value) {
        payload["pid"] = serde_json::json!(self.pid);
        payload["logPath"] = serde_json::json!(self.log_path);
        payload["probeOffset"] = serde_json::json!(self.probe_offset);
        payload["probeEnd"] = serde_json::json!(self.probe_end);
    }

    /// 用调用方已捕获的不可变右端判咬合。右端必须由 capture 段显式传入；
    /// 本 evaluator 不读取 bytes 长度来扩大窗口。越界仍由 exact slice fail-closed。
    pub fn engaged_in(&self, log: &[u8], captured_probe_end: u64) -> Result<bool, String> {
        wake_engaged_in_window(log, self.probe_offset, captured_probe_end)
    }
}

pub fn load_registry(root: &Path) -> Result<BTreeMap<String, WakeSpec>> {
    let definitions = crate::registry::load_agent_definitions(root)?;
    Ok(definitions
        .into_iter()
        .map(|(agent, definition)| {
            let argv = definition
                .legacy_wake
                .as_ref()
                .map(|wake| wake.argv.clone())
                .or_else(|| {
                    definition
                        .tool_definition
                        .as_ref()
                        .map(|tool| tool.launch.argv.clone())
                })
                .unwrap_or_default();
            (
                agent,
                WakeSpec {
                    injectable: definition.injectable,
                    session_id: definition.session_id,
                    argv,
                },
            )
        })
        .collect())
}

fn legacy_session_mode(session_id: &str) -> SessionMode {
    match session_id.trim() {
        ""
        | "fresh-thread-per-wake"
        | "fresh-session-per-wake"
        | "multica-sock"
        | "cwd-scoped--continue"
        | "console-chat" => SessionMode::Fresh,
        _ => SessionMode::Resume,
    }
}

/// 读取显式 session mode；缺少 `mode` 的旧 registry 仍兼容，但明确标为 legacy。
/// 显式未知 mode 一律 fail-closed，绝不猜成 Resume。
pub fn load_session_registry(root: &Path) -> Result<BTreeMap<String, SessionRegistration>> {
    let path = root.join("coordination/agents.yaml");
    let text = fs::read_to_string(&path)
        .with_context(|| format!("读取 AgentRegistry 失败: {}", path.display()))?;
    let registry: Registry = serde_yaml::from_str(&text)
        .with_context(|| format!("解析 AgentRegistry 失败: {}", path.display()))?;
    registry
        .agents
        .into_iter()
        .map(|(agent, spec)| {
            let (configured, legacy) = match spec.mode.as_deref() {
                Some(mode) => (
                    mode.parse::<SessionMode>().map_err(anyhow::Error::msg)?,
                    false,
                ),
                None => (legacy_session_mode(&spec.session_id), true),
            };
            Ok((
                agent,
                SessionRegistration {
                    configured,
                    legacy,
                    session_id: spec.session_id,
                },
            ))
        })
        .collect()
}

/// Resolves registry placeholders as process arguments, never through a shell.
pub fn render_wake_argv(spec: &WakeSpec, message: &str) -> Result<Vec<String>, String> {
    if spec.session_id.is_empty() {
        return Err("sessionId 尚未回填，无法注入唤醒".to_string());
    }
    if spec.argv.is_empty() {
        return Err("wake.argv 不能为空".to_string());
    }
    Ok(spec
        .argv
        .iter()
        .map(|arg| {
            arg.replace("{session}", &spec.session_id)
                .replace("{message}", message)
        })
        .collect())
}

#[derive(Debug, Clone)]
struct FormalReviewBinding {
    task_id: String,
    attempt_id: String,
    role: String,
    agent: String,
    continuation_id: String,
}

fn formal_review_binding_for_wake(
    _root: &Path,
    events: &[orch_core::EventRecord],
    round: &str,
    wake_id: &str,
) -> Result<FormalReviewBinding> {
    let wakes = events
        .iter()
        .filter(|event| {
            event.kind == "WakeIssued"
                && event.round.as_deref().is_none_or(|value| value == round)
                && payload_string(event, "wakeId") == Some(wake_id)
        })
        .collect::<Vec<_>>();
    if wakes.len() != 1 {
        bail!(
            "managed wake status requires exactly one WakeIssued for wakeId={wake_id}, found {}",
            wakes.len()
        );
    }
    let wake = wakes[0];
    if payload_string(wake, "providerKind") != Some("opencode") {
        bail!("unsupported: attach is limited to managed opencode review wakes");
    }
    let reviews = events
        .iter()
        .filter(|event| {
            event.kind == "ReviewRequested"
                && event.round.as_deref().is_none_or(|value| value == round)
                && payload_string(event, "wakeId") == Some(wake_id)
        })
        .collect::<Vec<_>>();
    if reviews.len() != 1 {
        bail!(
            "unsupported: source wake must bind exactly one formal ReviewRequested, found {}",
            reviews.len()
        );
    }
    let review = reviews[0];
    let required = |key: &str| {
        payload_string(review, key)
            .filter(|value| !value.trim().is_empty())
            .map(str::to_string)
            .with_context(|| format!("formal ReviewRequested missing {key}"))
    };
    let task_id = review
        .task_id
        .as_ref()
        .filter(|value| !value.trim().is_empty())
        .cloned()
        .context("formal ReviewRequested missing taskId")?;
    let attempt_id = required("attemptId")?;
    let role = required("role")?;
    let agent = required("agent")?;
    let continuation_id = required("continuationId")?;
    if payload_string(wake, "agent") != Some(agent.as_str()) {
        bail!("source WakeIssued/ReviewRequested agent binding mismatch");
    }
    Ok(FormalReviewBinding {
        task_id,
        attempt_id,
        role,
        agent,
        continuation_id,
    })
}

#[derive(Debug, Clone)]
struct DeclaredDeadReviewReplacement {
    source_wake_id: String,
    binding: FormalReviewBinding,
}

fn declared_dead_review_replacement(
    root: &Path,
    events: &[orch_core::EventRecord],
    round: &str,
    request: &ReviewRequest,
) -> Result<Option<DeclaredDeadReviewReplacement>> {
    if !matches!(request.role.as_str(), "primary" | "secondary") {
        return Ok(None);
    }
    let continuation_id = format!(
        "review:{round}:{}:{}:{}:{}",
        request.task_id, request.attempt_id, request.role, request.agent
    );
    let supersession = wake_supersession_projection(events, round)?;
    for (wake_index, wake) in events.iter().enumerate().rev() {
        if wake.kind != "WakeIssued"
            || wake.round.as_deref() != Some(round)
            || wake.task_id.as_deref() != Some(request.task_id.as_str())
            || payload_string(wake, "attemptId") != Some(request.attempt_id.as_str())
            || payload_string(wake, "agent") != Some(request.agent.as_str())
            || payload_string(wake, "continuationId") != Some(continuation_id.as_str())
        {
            continue;
        }
        let wake_id = payload_string(wake, "wakeId").context("WakeIssued missing wakeId")?;
        if supersession.superseded.contains(wake_id)
            || !declared_session_death_after(
                events,
                round,
                &request.task_id,
                &request.attempt_id,
                &request.role,
                &request.agent,
                wake_id,
                wake_index,
                "ManagedWakeAttachState",
            )
        {
            continue;
        }
        let binding = formal_review_binding_for_wake(root, events, round, wake_id)?;
        if binding.task_id != request.task_id
            || binding.attempt_id != request.attempt_id
            || binding.role != request.role
            || binding.agent != request.agent
            || binding.continuation_id != continuation_id
        {
            bail!("declared-dead review replacement identity drifted");
        }
        return Ok(Some(DeclaredDeadReviewReplacement {
            source_wake_id: wake_id.to_string(),
            binding,
        }));
    }
    Ok(None)
}

#[derive(Debug, Clone)]
struct ReissueAuthorization {
    binding: FormalReviewBinding,
    evidence: SessionDeathEvidence,
}

fn reissue_authorization_from_events(
    root: &Path,
    events: &[orch_core::EventRecord],
    round: &str,
    source_wake_id: &str,
) -> Result<ReissueAuthorization> {
    let sources = events
        .iter()
        .enumerate()
        .filter(|(_, event)| {
            event.kind == "WakeIssued"
                && event.round.as_deref() == Some(round)
                && payload_string(event, "wakeId") == Some(source_wake_id)
        })
        .collect::<Vec<_>>();
    if sources.len() != 1 {
        bail!(
            "reissue requires exactly one source WakeIssued for wakeId={source_wake_id}, found {}",
            sources.len()
        );
    }
    let (source_index, source_event) = sources[0];
    let source = durable_receipt_facts(source_event)?;
    if source.provider_kind != BackendReceiptKind::OpenCode {
        bail!(
            "unsupported provider scope: reissue is limited to managed opencode formal review wakes"
        );
    }
    let receipt = require_exact_accepted_backend_receipt(events, &source)?;
    let request = exact_review_request_for_wake(events, round, source_wake_id)?;
    validate_supersession_review_identity(source_event, request, &source)?;
    let binding = formal_review_binding_for_wake(root, events, round, source_wake_id)?;
    let declaration = exact_death_declaration_for_source(events, round, &source)?;
    let declaration_index = events
        .iter()
        .position(|event| std::ptr::eq(event, declaration))
        .expect("death declaration came from this event slice");
    let request_index = events
        .iter()
        .position(|event| std::ptr::eq(event, request))
        .expect("source review request came from this event slice");
    let receipt_index = events
        .iter()
        .position(|event| std::ptr::eq(event, receipt))
        .expect("source receipt came from this event slice");
    if request_index != source_index + 1
        || receipt_index <= request_index
        || declaration_index <= request_index
    {
        bail!(
            "reissue source event order is incomplete: expected source WakeIssued/ReviewRequested before receipt and authenticated death"
        );
    }
    let evidence = SessionDeathEvidence {
        wake_id: source_wake_id.to_string(),
        evidence_sha256: payload_string(declaration, "evidenceSha256")
            .expect("validated declaration has evidenceSha256")
            .to_string(),
        outcome: payload_string(declaration, "outcome")
            .expect("validated declaration has outcome")
            .to_string(),
    };
    Ok(ReissueAuthorization { binding, evidence })
}

pub fn managed_wake_status(root: &Path, wake_id: &str) -> Result<ManagedWakeStatusView> {
    let round = current_round(root)?;
    let events = read_round_ledger_events(root, &round)?;
    let wakes = events
        .iter()
        .filter(|event| {
            event.kind == "WakeIssued"
                && event.round.as_deref().is_none_or(|value| value == round)
                && payload_string(event, "wakeId") == Some(wake_id)
        })
        .collect::<Vec<_>>();
    if wakes.len() != 1 {
        bail!(
            "managed wake status requires exactly one WakeIssued for wakeId={wake_id}, found {}",
            wakes.len()
        );
    }
    let wake = wakes[0];
    let agent = payload_string(wake, "agent")
        .filter(|value| !value.trim().is_empty())
        .context("WakeIssued missing agent")?;
    let provider_kind = payload_string(wake, "providerKind")
        .filter(|value| matches!(*value, "opencode" | "codex" | "pi" | "zcode"))
        .context(
            "unsupported-or-not-managed: status supports managed opencode/codex/Pi/ZCode wakes",
        )?;
    let (dir, descriptor) = read_managed_wake_control_descriptor(root, wake_id)
        .context("untrusted-runtime-artifact: managed wake descriptor rejected")?;
    if let Some(facts) = descriptor.invocation.as_ref() {
        if facts.binding.alias != agent
            || payload_string(wake, "configDigest") != Some(facts.binding.config_digest.as_str())
            || payload_string(wake, "requestDigest") != Some(facts.binding.request_digest.as_str())
            || payload_string(wake, "fixedHead") != Some(facts.binding.fixed_head.as_str())
        {
            bail!("untrusted-runtime-artifact: invocation descriptor/ledger binding mismatch");
        }
    }
    status_from_artifacts(&dir, &descriptor, agent, provider_kind)
}

/// Refuse the retired review-scoped session-death writer without side effects.
pub fn record_managed_session_death(root: &Path, wake_id: &str) -> Result<()> {
    let _ = (root, wake_id);
    bail!("legacy review session-death declaration 已退役；使用 provider-neutral status/cancel")
}

/// Refuse the retired formal-review attach writer until a driver-neutral
/// control contract exists.
#[allow(clippy::too_many_arguments)]
pub fn run_managed_wake_attach(
    root: &Path,
    source_wake_id: &str,
    mode: AttachMode,
    reason: &str,
    deadline_secs: u64,
) -> Result<()> {
    let _ = (root, source_wake_id, mode, reason, deadline_secs);
    bail!("legacy formal-review attach 已退役；当前 driver 未提供 provider-neutral attach")
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ActiveSessionOverlay {
    pub agent: String,
    pub fault: String,
    pub fault_event_id: String,
    pub applied_event_id: String,
    pub generation: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SessionStatus {
    pub configured: SessionMode,
    pub effective: SessionMode,
    pub legacy: bool,
    pub overlay: Option<ActiveSessionOverlay>,
}

fn payload_string<'a>(event: &'a orch_core::EventRecord, key: &str) -> Option<&'a str> {
    event.payload.as_ref()?.get(key)?.as_str()
}

/// 重放 Applied/Cleared 对，返回该 agent 当前仍生效的 durable overlay。
/// Cleared 必须精确引用当前 Applied eventId；陈旧/串 agent 的 clear 不生效。
pub fn active_session_overlay(
    events: &[orch_core::EventRecord],
    agent: &str,
) -> Option<ActiveSessionOverlay> {
    let mut active: Option<ActiveSessionOverlay> = None;
    for event in events {
        match event.kind.as_str() {
            "SessionOverlayApplied" if payload_string(event, "agent") == Some(agent) => {
                let Some(fault) = payload_string(event, "fault") else {
                    continue;
                };
                let fault_event_id = payload_string(event, "faultEventId")
                    .or_else(|| payload_string(event, "eventId"));
                let Some(fault_event_id) = fault_event_id else {
                    continue;
                };
                let Some(generation) = payload_string(event, "generation") else {
                    continue;
                };
                if SessionOverlay::degraded(fault, fault_event_id).is_err() || generation.is_empty()
                {
                    continue;
                }
                active = Some(ActiveSessionOverlay {
                    agent: agent.to_string(),
                    fault: fault.to_string(),
                    fault_event_id: fault_event_id.to_string(),
                    applied_event_id: event.event_id.clone(),
                    generation: generation.to_string(),
                });
            }
            "SessionOverlayCleared" if payload_string(event, "agent") == Some(agent) => {
                if let Some(current) = &active {
                    if payload_string(event, "appliedEventId")
                        == Some(current.applied_event_id.as_str())
                    {
                        active = None;
                    }
                }
            }
            _ => {}
        }
    }
    active
}

fn validate_session_overlay_events(events: &[orch_core::EventRecord], agent: &str) -> Result<()> {
    for event in events {
        if event.kind != "SessionOverlayApplied" || payload_string(event, "agent") != Some(agent) {
            continue;
        }
        let fault = payload_string(event, "fault")
            .with_context(|| format!("{} 缺 fault", event.event_id))?;
        let fault_event_id = payload_string(event, "faultEventId")
            .or_else(|| payload_string(event, "eventId"))
            .with_context(|| format!("{} 缺 faultEventId", event.event_id))?;
        SessionOverlay::degraded(fault, fault_event_id).map_err(anyhow::Error::msg)?;
        let generation = payload_string(event, "generation")
            .with_context(|| format!("{} 缺 generation", event.event_id))?;
        if generation.is_empty() {
            bail!("{} 的 generation 为空", event.event_id);
        }
    }
    Ok(())
}

fn read_round_events(root: &Path, round: &str) -> Result<Vec<orch_core::EventRecord>> {
    let path = root.join(format!("coordination/rounds/{round}/events.jsonl"));
    if !path.is_file() {
        return Ok(Vec::new());
    }
    let ledger_read = orch_core::read_ledger(&path)
        .with_context(|| format!("读取 session overlay 账本失败: {}", path.display()))?;
    if !ledger_read.bad_lines.is_empty() {
        bail!(
            "session overlay 账本含坏行，拒绝猜测状态: {:?}",
            ledger_read.bad_lines
        );
    }
    Ok(ledger_read.events)
}

pub fn session_status(root: &Path, round: &str, agent: &str) -> Result<SessionStatus> {
    let registrations = load_session_registry(root)?;
    let registration = registrations
        .get(agent)
        .with_context(|| format!("AgentRegistry 未注册 agent: {agent}"))?;
    let events = read_round_events(root, round)?;
    validate_session_overlay_events(&events, agent)?;
    let overlay = active_session_overlay(&events, agent);
    let pure_overlay = overlay
        .as_ref()
        .map(|entry| SessionOverlay::degraded(&entry.fault, &entry.fault_event_id))
        .transpose()
        .map_err(anyhow::Error::msg)?;
    let resolved = resolve_session_mode(registration.configured, pure_overlay.as_ref())
        .map_err(anyhow::Error::msg)?;
    Ok(SessionStatus {
        configured: resolved.configured,
        effective: resolved.effective,
        legacy: registration.legacy,
        overlay,
    })
}

fn record_session_overlay_applied(
    root: &Path,
    round: &str,
    agent: &str,
    fault: &str,
    fault_event_id: &str,
    generation: &str,
) -> Result<orch_core::EventRecord> {
    SessionOverlay::degraded(fault, fault_event_id).map_err(anyhow::Error::msg)?;
    if generation.is_empty() {
        bail!("SessionOverlayApplied generation 不能为空");
    }
    let event = ledger::event(
        "SessionOverlayApplied",
        "runtime:orch",
        None,
        Some(round),
        serde_json::json!({
            "agent": agent,
            "fault": fault,
            "faultEventId": fault_event_id,
            "generation": generation,
        }),
    );
    ledger::append(root, round, std::slice::from_ref(&event))?;
    Ok(event)
}

fn record_session_overlay_cleared(
    root: &Path,
    round: &str,
    agent: &str,
    applied_event_id: &str,
    generation: &str,
    engaged_evidence: serde_json::Value,
) -> Result<()> {
    let event = ledger::event(
        "SessionOverlayCleared",
        "runtime:orch",
        None,
        Some(round),
        serde_json::json!({
            "agent": agent,
            "appliedEventId": applied_event_id,
            "generation": generation,
            "engagedEvidence": engaged_evidence,
        }),
    );
    ledger::append(root, round, &[event])
}

struct CapturedChannelEvidence {
    faults: Vec<crate::chanhealth::ChannelFault>,
    engaged: bool,
    evidence: serde_json::Value,
}

/// 对 Delivered 的 action facts 重新 capture 一个不可变 end；Delivered 自带的初始
/// probeEnd 只作字段完整性校验，不被当作终身右端。
fn capture_channel_evidence(
    root: &Path,
    event: &orch_core::EventRecord,
) -> Result<Option<CapturedChannelEvidence>> {
    let Some(payload) = event.payload.as_ref() else {
        return Ok(None);
    };
    let facts = match ActionChannelFacts::from_payload(payload) {
        Ok(facts) => facts,
        Err(_) => return Ok(None),
    };
    let path = {
        let candidate = PathBuf::from(&facts.log_path);
        if candidate.is_absolute() {
            candidate
        } else {
            root.join(candidate)
        }
    };
    let mut captured = match capture_probe_window(&path, facts.probe_offset) {
        Ok(captured) => captured,
        Err(_) => return Ok(None),
    };
    if captured.probe_end == captured.probe_offset {
        return Ok(None);
    }
    let captured_len = usize::try_from(captured.probe_end)
        .map_err(|_| anyhow::anyhow!("captured probeEnd 超出 usize"))?;
    let mut bytes = vec![0_u8; captured_len];
    captured.file.read_exact(&mut bytes).with_context(|| {
        format!(
            "读取 captured session evidence 失败: {}",
            captured.log_path.display()
        )
    })?;
    let slice = exact_probe_slice(&bytes, captured.probe_offset, captured.probe_end)
        .map_err(anyhow::Error::msg)?;
    if slice.is_empty() {
        return Ok(None);
    }
    let text = String::from_utf8_lossy(slice);
    let faults = crate::chanhealth::scan_wake_log(&text);
    let engaged = wake_engaged(&text);
    Ok(Some(CapturedChannelEvidence {
        faults,
        engaged,
        evidence: serde_json::json!({
            "logPath": facts.log_path,
            "probeOffset": captured.probe_offset,
            "probeEnd": captured.probe_end,
            "engaged": engaged,
            "marker": if engaged { "provider-activity" } else { "none" },
        }),
    }))
}

fn delivered_for_agent(event: &orch_core::EventRecord, agent: &str) -> bool {
    matches!(
        event.kind.as_str(),
        "DispatchWakeDelivered" | "ResumeWakeDelivered"
    ) && payload_string(event, "agent") == Some(agent)
}

/// 每次 provider spawn 前执行：先重放 durable overlay，再用上一代 Delivered 的
/// 最新 immutable capture 尝试清除；无 active overlay 时才从 faulted Delivered 应用新 overlay。
pub fn reconcile_session_overlay(
    root: &Path,
    round: &str,
    agent: &str,
    configured: SessionMode,
) -> Result<ResolvedSessionMode> {
    let mut events = read_round_events(root, round)?;
    validate_session_overlay_events(&events, agent)?;
    if let Some(active) = active_session_overlay(&events, agent) {
        let applied_index = events
            .iter()
            .position(|event| event.event_id == active.applied_event_id)
            .unwrap_or(events.len());
        for event in events.iter().skip(applied_index.saturating_add(1)) {
            if !delivered_for_agent(event, agent) {
                continue;
            }
            let Some(generation) = payload_string(event, "leaseGeneration") else {
                continue;
            };
            if generation == active.generation {
                continue;
            }
            let Some(captured) = capture_channel_evidence(root, event)? else {
                continue;
            };
            if captured.engaged && captured.faults.is_empty() {
                record_session_overlay_cleared(
                    root,
                    round,
                    agent,
                    &active.applied_event_id,
                    generation,
                    captured.evidence,
                )?;
                return resolve_session_mode(configured, None).map_err(anyhow::Error::msg);
            }
        }
        let overlay = SessionOverlay::degraded(&active.fault, &active.fault_event_id)
            .map_err(anyhow::Error::msg)?;
        return resolve_session_mode(configured, Some(&overlay)).map_err(anyhow::Error::msg);
    }

    // Cleared 之前的旧 fault 不能重新应用；只扫描最后一个 overlay 控制事件之后的 Delivered。
    let last_overlay_control = events
        .iter()
        .rposition(|event| {
            matches!(
                event.kind.as_str(),
                "SessionOverlayApplied" | "SessionOverlayCleared"
            ) && payload_string(event, "agent") == Some(agent)
        })
        .map(|index| index + 1)
        .unwrap_or(0);
    for event in events.drain(last_overlay_control..).rev() {
        if !delivered_for_agent(&event, agent) {
            continue;
        }
        let Some(generation) = payload_string(&event, "leaseGeneration") else {
            continue;
        };
        let Some(captured) = capture_channel_evidence(root, &event)? else {
            continue;
        };
        let Some(fault) = captured.faults.first() else {
            continue;
        };
        record_session_overlay_applied(
            root,
            round,
            agent,
            fault.as_str(),
            &event.event_id,
            generation,
        )?;
        let overlay = SessionOverlay::degraded(fault.as_str(), &event.event_id)
            .map_err(anyhow::Error::msg)?;
        return resolve_session_mode(configured, Some(&overlay)).map_err(anyhow::Error::msg);
    }
    resolve_session_mode(configured, None).map_err(anyhow::Error::msg)
}

fn render_wake_argv_for_mode(
    spec: &WakeSpec,
    message: &str,
    mode: SessionMode,
) -> Result<Vec<String>, String> {
    if mode == SessionMode::Resume {
        return render_wake_argv(spec, message);
    }
    if spec.argv.is_empty() {
        return Err("wake.argv 不能为空".to_string());
    }
    let mut argv = Vec::with_capacity(spec.argv.len());
    let mut skip_session = false;
    for arg in &spec.argv {
        if skip_session {
            if arg.contains("{session}") {
                skip_session = false;
                continue;
            }
            skip_session = false;
        }
        if matches!(arg.as_str(), "resume" | "--resume" | "-r" | "--session") {
            skip_session = true;
            continue;
        }
        if arg.contains("{session}") {
            return Err(format!(
                "fresh mode 无法安全移除孤立 session 占位参数 {arg:?}（fail-closed）"
            ));
        }
        argv.push(arg.replace("{message}", message));
    }
    if skip_session {
        return Err("fresh mode 的 resume/session 选项缺少值（fail-closed）".to_string());
    }
    Ok(argv)
}

fn render_registered_invocation(
    root: &Path,
    agent: &str,
    message: &str,
    mode: SessionMode,
) -> Result<crate::registry::RenderedInvocation> {
    let definitions = crate::registry::load_agent_definitions(root)?;
    let definition = definitions
        .get(agent)
        .with_context(|| format!("AgentRegistry 未注册 agent: {agent}"))?;
    let declares_pin =
        definition.provider.is_some() || definition.model.is_some() || definition.effort.is_some();
    let descriptor_exists = root
        .join(crate::harness::HARNESS_REGISTRY_RELPATH)
        .try_exists()
        .context("检查 HarnessRegistry 是否存在失败")?;
    // Headerless legacy fixtures predate the descriptor file and carry no
    // signed pin to police. Any declared pin, or any installed descriptor
    // registry, enters the strict path: missing/invalid bytes and key drift
    // all reject before either renderer can construct an invocation.
    if declares_pin || descriptor_exists {
        let harness_registry = crate::harness::load_harness_registry(root)?;
        crate::harness::assert_pin_is_transportable(&harness_registry, agent, definition)?;
    }
    if let Some(wake) = definition.legacy_wake.as_ref() {
        return Ok(crate::registry::render_legacy_invocation(
            definition,
            render_wake_argv_for_mode(wake, message, mode).map_err(anyhow::Error::msg)?,
        ));
    }
    crate::registry::render_invocation(definition, root, &definition.session_id, message)
}

fn invocation_envelope_harness(argv: &[String]) -> Option<crate::harness::HarnessId> {
    managed_stream_harness(argv)
}

fn resolve_bare_provider_from_path(program: &str) -> Result<PathBuf> {
    if Path::new(program).components().count() != 1 {
        bail!("provider PATH lookup accepts only one bare executable name");
    }
    let path = std::env::var_os("PATH").context("PATH is unavailable for provider resolution")?;
    for component in std::env::split_paths(&path) {
        if !component.is_absolute() {
            bail!("provider PATH contains a non-absolute component");
        }
        let candidate = component.join(program);
        if candidate.is_file() && fs::metadata(&candidate)?.permissions().mode() & 0o111 != 0 {
            return fs::canonicalize(&candidate).with_context(|| {
                format!(
                    "canonicalize provider executable failed: {}",
                    candidate.display()
                )
            });
        }
    }
    bail!("provider executable {program:?} was not found in an absolute-component PATH")
}

fn provider_binary_for_envelope(
    definition: &crate::registry::AgentDefinition,
    harness: crate::harness::HarnessId,
) -> Result<PathBuf> {
    if let Some(configured) = definition.provider_bin.as_deref() {
        return Ok(PathBuf::from(configured));
    }
    let (legacy_key, legacy_default) = match harness {
        crate::harness::HarnessId::Pi => ("ORCH_PI_BIN", None),
        crate::harness::HarnessId::ZCode => (
            "ORCH_ZCODE_BIN",
            Some("/Applications/ZCode.app/Contents/Resources/glm/zcode.cjs"),
        ),
        crate::harness::HarnessId::Dsh => ("ORCH_DSH_BIN", None),
        _ => bail!("invocation envelope provider binary requested for unmanaged harness"),
    };
    if let Some(value) = std::env::var_os(legacy_key) {
        return Ok(PathBuf::from(value));
    }
    if let Some(default) = legacy_default {
        return Ok(PathBuf::from(default));
    }
    if harness == crate::harness::HarnessId::Pi {
        return resolve_bare_provider_from_path("pi");
    }
    bail!(
        "managed harness {} has no providerBin and {legacy_key} is absent; refusing PATH fallback",
        harness.as_str()
    )
}

fn orch_binary_for_envelope(root: &Path) -> Result<PathBuf> {
    let current = std::env::current_exe().context("resolve running orch executable failed")?;
    let current_is_orch = current
        .file_name()
        .and_then(|name| name.to_str())
        .is_some_and(|name| name == "orch");
    if current_is_orch {
        return Ok(current);
    }
    let built = root.join("orch/target/debug/orch");
    if built.is_file() && fs::metadata(&built)?.permissions().mode() & 0o111 != 0 {
        return fs::canonicalize(&built)
            .with_context(|| format!("canonicalize built orch failed: {}", built.display()));
    }
    bail!(
        "reviewer orch binary is not built or executable: {}",
        built.display()
    )
}

fn harness_registry_digest_for_wake(root: &Path) -> Result<String> {
    let path = root.join(crate::harness::HARNESS_REGISTRY_RELPATH);
    if path.exists() {
        return crate::harness::registry_digest(root);
    }
    // Headerless synthetic fixtures predate HarnessRegistry. They retain an
    // explicit, stable absence digest instead of gaining a field-less event;
    // every real repository has the descriptor file and takes the branch above.
    Ok(sha256_hex(b"legacy-fixture-without-harness-registry"))
}

fn implementation_fixed_head(
    root: &Path,
    round: &str,
    task_id: &str,
    attempt_id: &str,
) -> Result<String> {
    let events = read_round_ledger_events(root, round)?;
    events
        .iter()
        .rev()
        .find(|event| {
            event.kind == "DispatchIssued"
                && event.task_id.as_deref() == Some(task_id)
                && payload_string(event, "attemptId") == Some(attempt_id)
        })
        .and_then(|event| payload_string(event, "baseSha"))
        .map(str::to_string)
        .with_context(|| {
            format!(
                "implementation invocation lacks DispatchIssued baseSha for {task_id}/{attempt_id}"
            )
        })
}

#[allow(clippy::too_many_arguments)]
fn harness_invocation_context(
    root: &Path,
    round: &str,
    wake_id: &str,
    continuation: Option<&ContinuationIdentity>,
    provisioned: Option<&ProvisionedReviewSite>,
    review_output_path: Option<&str>,
    deadline_secs: u64,
) -> Result<HarnessInvocationContext> {
    let scoped_continuation = continuation
        .is_some_and(|identity| identity.task_id.is_some() && identity.attempt_id.is_some());
    let (task_id, attempt_id, role) = match continuation {
        Some(identity) => match (&identity.task_id, &identity.attempt_id) {
            (Some(task_id), Some(attempt_id)) => (
                task_id.clone(),
                attempt_id.clone(),
                identity
                    .role
                    .clone()
                    .unwrap_or_else(|| "implement".to_string()),
            ),
            (None, None) if identity.manual_wake_id.is_some() && identity.role.is_none() => (
                "MANUAL".to_string(),
                "MANUAL-A0000".to_string(),
                "implement".to_string(),
            ),
            _ => bail!("managed continuation has incomplete task/attempt identity"),
        },
        None => (
            "MANUAL".to_string(),
            "MANUAL-A0000".to_string(),
            "implement".to_string(),
        ),
    };
    let (cwd, fixed_head, review_output_path) = match (provisioned, review_output_path) {
        (Some(site), Some(output)) => (
            fs::canonicalize(&site.site.worktree).with_context(|| {
                format!(
                    "canonicalize invocation review cwd failed: {}",
                    site.site.worktree
                )
            })?,
            site.reviewed_head.clone(),
            output.to_string(),
        ),
        (None, None) => {
            let fixed_head = if scoped_continuation {
                implementation_fixed_head(root, round, &task_id, &attempt_id)?
            } else {
                crate::gitx::rev_parse(root, "HEAD")?
            };
            (
                fs::canonicalize(root).context("canonicalize invocation root cwd failed")?,
                fixed_head,
                crate::harness::NO_REVIEW_OUTPUT.to_string(),
            )
        }
        _ => bail!("review invocation cwd and output path must be supplied together"),
    };
    Ok(HarnessInvocationContext {
        action_id: wake_id.to_string(),
        wake_id: wake_id.to_string(),
        round: round.to_string(),
        task_id,
        attempt_id,
        role,
        cwd,
        fixed_head,
        review_output_path,
        deadline_secs,
    })
}

fn invocation_envelope_map(
    root: &Path,
    agent: &str,
    definition: &crate::registry::AgentDefinition,
    rendered: &crate::registry::RenderedInvocation,
    harness: crate::harness::HarnessId,
    context: &HarnessInvocationContext,
) -> Result<BTreeMap<String, String>> {
    let registry = crate::harness::load_harness_registry(root)?;
    let described = registry
        .get(agent)
        .with_context(|| format!("HarnessRegistry lacks agent {agent}"))?;
    if described.harness != harness {
        bail!(
            "registered wrapper/harness identity mismatch for {agent}: argv={} descriptor={}",
            harness.as_str(),
            described.harness.as_str()
        );
    }
    let legacy_prefix = match harness {
        crate::harness::HarnessId::Pi => "ORCH_PI",
        crate::harness::HarnessId::ZCode => "ORCH_ZCODE",
        crate::harness::HarnessId::Dsh => "ORCH_DSH",
        _ => bail!(
            "unsupported invocation-envelope harness {}",
            harness.as_str()
        ),
    };
    let requested = |field: Option<&String>, suffix: &str| -> Result<String> {
        field
            .cloned()
            .or_else(|| std::env::var(format!("{legacy_prefix}_{suffix}")).ok())
            .with_context(|| {
                format!(
                    "managed harness {} lacks required {suffix} pin",
                    harness.as_str()
                )
            })
    };
    let provider = requested(rendered.requested_provider.as_ref(), "PROVIDER")?;
    let model = requested(rendered.requested_model.as_ref(), "MODEL")?;
    let effort = requested(rendered.requested_effort.as_ref(), "EFFORT")?;
    let provider_bin = provider_binary_for_envelope(definition, harness)?;
    let orch_bin = orch_binary_for_envelope(root)?;
    Ok(BTreeMap::from([
        ("ORCH_HARNESS_ID".to_string(), harness.as_str().to_string()),
        (
            "ORCH_HARNESS_ACTION_ID".to_string(),
            context.action_id.clone(),
        ),
        ("ORCH_HARNESS_WAKE_ID".to_string(), context.wake_id.clone()),
        ("ORCH_HARNESS_ROUND".to_string(), context.round.clone()),
        ("ORCH_HARNESS_TASK_ID".to_string(), context.task_id.clone()),
        (
            "ORCH_HARNESS_ATTEMPT_ID".to_string(),
            context.attempt_id.clone(),
        ),
        ("ORCH_HARNESS_ROLE".to_string(), context.role.clone()),
        (
            "ORCH_HARNESS_CWD".to_string(),
            context.cwd.display().to_string(),
        ),
        (
            "ORCH_HARNESS_FIXED_HEAD".to_string(),
            context.fixed_head.clone(),
        ),
        ("ORCH_HARNESS_PROVIDER".to_string(), provider),
        ("ORCH_HARNESS_MODEL".to_string(), model),
        ("ORCH_HARNESS_EFFORT".to_string(), effort),
        (
            "ORCH_HARNESS_PROVIDER_BIN".to_string(),
            provider_bin.display().to_string(),
        ),
        (
            "ORCH_HARNESS_REVIEW_OUTPUT_PATH".to_string(),
            context.review_output_path.clone(),
        ),
        (
            "ORCH_HARNESS_ORCH_BIN".to_string(),
            orch_bin.display().to_string(),
        ),
        (
            "ORCH_HARNESS_DEADLINE_SECS".to_string(),
            context.deadline_secs.to_string(),
        ),
    ]))
}

/// Serialize cold starts by tool, not by agent instance.  The lock and last
/// launch marker are filesystem-backed so two independent orch processes share
/// the same startup gate.
fn with_tool_startup_gate<T>(
    root: &Path,
    definition: &crate::registry::AgentDefinition,
    action: impl FnOnce() -> Result<T>,
) -> Result<T> {
    let Some(tool) = definition.tool.as_deref() else {
        return action();
    };
    let lock_dir = root.join("coordination/runtime/locks");
    fs::create_dir_all(&lock_dir).context("create tool startup lock directory failed")?;
    let lock_path = lock_dir.join(format!("startup-{tool}.lock"));
    let marker_path = lock_dir.join(format!("startup-{tool}.last"));
    let file = fs::OpenOptions::new()
        .create(true)
        .read(true)
        .write(true)
        .open(&lock_path)
        .with_context(|| format!("open tool startup lock failed: {}", lock_path.display()))?;
    let mut lock = fd_lock::RwLock::new(file);
    let _guard = lock.write().context("wait for tool startup lock failed")?;
    let last_launch = fs::read_to_string(&marker_path)
        .ok()
        .and_then(|value| value.trim().parse::<u128>().ok())
        .and_then(|millis| UNIX_EPOCH.checked_add(Duration::from_millis(millis as u64)));
    let now = SystemTime::now();
    let wait = crate::registry::plan_startup_wait(definition, last_launch, now)
        .map_err(anyhow::Error::msg)?;
    if !wait.is_zero() {
        std::thread::sleep(wait);
    }
    let launch_time = SystemTime::now();
    let millis = launch_time
        .duration_since(UNIX_EPOCH)
        .context("system clock before Unix epoch")?
        .as_millis();
    fs::write(&marker_path, millis.to_string()).with_context(|| {
        format!(
            "write tool startup marker failed: {}",
            marker_path.display()
        )
    })?;
    action()
}

const TEST_COMMAND_SUMMARY_CHARS: usize = 160;

fn test_command_summary(value: &str) -> String {
    let mut chars = value.chars();
    let prefix = chars
        .by_ref()
        .take(TEST_COMMAND_SUMMARY_CHARS)
        .collect::<String>();
    if chars.next().is_some() {
        format!("{prefix:?}…")
    } else {
        format!("{prefix:?}")
    }
}

/// Test-only predicate shared by the integration contract and the CLI's
/// exact-PID `ps` assertion. Production code deliberately has no call site.
#[doc(hidden)]
pub fn validate_hidden_supervisor_command_line_for_test(
    command_line: &str,
    expected_program: &str,
    expected_root: &str,
) -> std::result::Result<(), String> {
    let expected = format!("{expected_program} --root {expected_root} __wake-supervise");
    let observed = command_line.trim_matches(|character: char| character.is_ascii_whitespace());
    let summaries = || {
        format!(
            "expected={} observed={}",
            test_command_summary(&expected),
            test_command_summary(observed)
        )
    };

    if command_line.is_empty() || expected_program.is_empty() || expected_root.is_empty() {
        return Err(format!(
            "hidden supervisor exact command requires three non-empty inputs; {}",
            summaries()
        ));
    }
    for (name, value) in [
        ("expected program", expected_program),
        ("expected root", expected_root),
    ] {
        let has_framing_whitespace = value
            .chars()
            .next()
            .is_some_and(|character| character.is_ascii_whitespace())
            || value
                .chars()
                .last()
                .is_some_and(|character| character.is_ascii_whitespace());
        if has_framing_whitespace
            || value
                .as_bytes()
                .iter()
                .any(|byte| matches!(byte, b'\0' | b'\r' | b'\n'))
        {
            return Err(format!(
                "hidden supervisor {name} has ambiguous framing; {}",
                summaries()
            ));
        }
    }
    if observed.is_empty() {
        return Err(format!(
            "hidden supervisor observed command is empty after ps framing; {}",
            summaries()
        ));
    }
    if observed != expected {
        return Err(format!(
            "hidden supervisor exact __wake-supervise command mismatch; {}",
            summaries()
        ));
    }
    Ok(())
}

/// Preserve a spawn prerequisite as the primary diagnostic when an armed test
/// hook could not have run. A captured receipt wins because the later forged
/// protocol rejection is the expected result of those tests.
#[doc(hidden)]
pub fn require_test_hook_capture_or_explain<T>(
    hook_name: &str,
    capture: Option<T>,
    spawn_error: Option<&str>,
) -> std::result::Result<T, String> {
    if hook_name.trim().is_empty() {
        return Err("test hook name must not be empty".to_string());
    }
    if spawn_error.is_some_and(|error| error.trim().is_empty()) {
        return Err(format!(
            "{hook_name} received an empty spawn error diagnostic"
        ));
    }
    if let Some(capture) = capture {
        return Ok(capture);
    }
    match spawn_error {
        Some(error) => Err(format!(
            "{hook_name} did not capture immutable process receipts because spawn failed: {error}"
        )),
        None => Err(format!(
            "{hook_name} completed spawn without observing the armed hook capture"
        )),
    }
}

