#[allow(clippy::too_many_arguments)]
fn captured_effective_spawn_env(
    overrides: &BTreeMap<String, String>,
) -> Result<BTreeMap<String, String>> {
    let mut effective = BTreeMap::new();
    for (key, value) in std::env::vars_os() {
        let key = key
            .into_string()
            .map_err(|_| anyhow::anyhow!("provider environment contains a non-UTF-8 key"))?;
        let value = value
            .into_string()
            .map_err(|_| anyhow::anyhow!("provider environment contains a non-UTF-8 value"))?;
        let runtime_owned = matches!(key.as_str(), "PWD" | "OLDPWD" | "SHLVL" | "_")
            || key.starts_with("ORCH_HARNESS_")
            || key == "ORCH_MULTICA_SESSION"
            || key == "ORCH_MULTICA_CWD"
            || key.starts_with("ORCH_PI_")
            || key.starts_with("ORCH_DSH_")
            || key.starts_with("ORCH_ZCODE_");
        if !runtime_owned {
            effective.insert(key, value);
        }
    }
    effective.extend(overrides.clone());
    Ok(effective)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ProviderSpawnEffect {
    None,
    Uncertain,
}

fn spawn_registered_wake(
    root: &Path,
    round: &str,
    agent: &str,
    message: &str,
    managed_wake_id: Option<&str>,
    review_deadline_secs: Option<u64>,
    continuation: Option<&ContinuationIdentity>,
    provisioned: Option<&ProvisionedReviewSite>,
    review_output_path: Option<&str>,
    prepared_rendered: Option<crate::registry::RenderedInvocation>,
    invocation_cwd: Option<&Path>,
    spawn_effect: Option<&mut ProviderSpawnEffect>,
) -> Result<RegisteredWakeLaunch> {
    let mut spawn_effect = spawn_effect;
    let definitions = crate::registry::load_agent_definitions(root)?;
    let definition = definitions
        .get(agent)
        .with_context(|| format!("AgentRegistry 未注册 agent: {agent}"))?;
    if !definition.injectable {
        bail!("agent {agent} 不支持注入唤醒；请走 POKE 备用信道");
    }
    let mut rendered = match prepared_rendered {
        Some(rendered) => rendered,
        None => {
            let sessions = load_session_registry(root)?;
            let session = sessions
                .get(agent)
                .with_context(|| format!("AgentRegistry 缺少 session 配置: {agent}"))?;
            let resolved = reconcile_session_overlay(root, round, agent, session.configured)?;
            render_registered_invocation(root, agent, message, resolved.effective)?
        }
    };
    let invocation_cwd = invocation_cwd.unwrap_or(root);
    let canonical_invocation_cwd = fs::canonicalize(invocation_cwd)?;
    if !canonical_invocation_cwd.starts_with(fs::canonicalize(root)?) {
        bail!("registered wake invocation cwd 逃出 repository root");
    }
    let argv = rendered.argv.clone();
    let provider_kind = backend_receipt_kind_from_argv(&argv).ok();
    let envelope_harness = invocation_envelope_harness(&argv);
    let descriptor_exists = root
        .join(crate::harness::HARNESS_REGISTRY_RELPATH)
        .try_exists()
        .context("check HarnessRegistry before terminal capability binding failed")?;
    let harness_descriptor = if descriptor_exists {
        let harness_registry = crate::harness::load_harness_registry(root)?;
        Some(
            harness_registry
                .get(agent)
                .with_context(|| format!("HarnessRegistry missing descriptor for {agent}"))?
                .clone(),
        )
    } else {
        None
    };
    let plain_text_review_channel =
        is_exact_agy_provider_argv(&argv) || (!descriptor_exists && is_agy_program(&argv));
    let action_wake_id =
        (provider_kind.is_some() || envelope_harness.is_some() || harness_descriptor.is_some())
            .then(|| {
                managed_wake_id
                    .map(str::to_string)
                    .unwrap_or_else(fresh_managed_wake_id)
            });
    // Registry test adapters may intentionally use small local commands such as
    // `echo`. The public classifier remains fail-closed, while the generic wake
    // harness preserves its legacy ability to spawn such adapters. Only a
    // positively identified direct CLI receives managed-process-group semantics.
    let identity_kind = durable_identity_kind(&argv).ok();
    let runtime_limit = identity_kind
        .is_some_and(DurableIdentityKind::is_managed_pid_group)
        .then(|| managed_wake_runtime_limit(review_deadline_secs));
    let envelope_deadline_secs = managed_wake_runtime_limit(review_deadline_secs).effective_secs;
    let control_wake_id = if identity_kind.is_some_and(DurableIdentityKind::is_managed_pid_group) {
        let wake_id = action_wake_id
            .clone()
            .context("managed provider action wake identity missing")?;
        if !is_strict_uuid(&wake_id) {
            bail!("managed wake control wakeId must be a strict UUID");
        }
        Some(wake_id)
    } else {
        None
    };
    let request_session_id = (provider_kind == Some(BackendReceiptKind::SmartClaw)).then(|| {
        format!(
            "orch-wake-{}",
            action_wake_id
                .as_deref()
                .expect("SmartClaw provider has an action wake id")
        )
    });
    if let (Some(harness), true) = (envelope_harness, descriptor_exists) {
        if harness_descriptor
            .as_ref()
            .is_some_and(|descriptor| descriptor.harness != harness)
        {
            bail!("resolved wrapper harness differs from its registered descriptor");
        }
        let envelope_wake_id = action_wake_id
            .as_deref()
            .context("managed wrapper invocation lacks an action wake identity")?;
        let mut context = harness_invocation_context(
            root,
            round,
            envelope_wake_id,
            continuation,
            provisioned,
            review_output_path,
            envelope_deadline_secs,
        )?;
        if agent == "executor-dsh" {
            context.cwd = canonical_invocation_cwd.clone();
        }
        let envelope =
            invocation_envelope_map(root, agent, definition, &rendered, harness, &context)?;
        // Validate before either direct Command::spawn or supervisor spawn and
        // use RenderedInvocation.env as the sole runtime-to-wrapper exit.
        crate::harness::InvocationEnvelope::from_map(envelope.clone())?;
        rendered.env.extend(envelope);
    }
    if let Some(session_id) = request_session_id.as_deref() {
        rendered
            .env
            .insert("ORCH_MULTICA_SESSION".to_string(), session_id.to_string());
        let provider_cwd = provisioned
            .map(|site| fs::canonicalize(&site.site.worktree))
            .transpose()?
            .unwrap_or_else(|| canonical_invocation_cwd.clone());
        rendered.env.insert(
            "ORCH_MULTICA_CWD".to_string(),
            provider_cwd.display().to_string(),
        );
    }
    rendered.env = captured_effective_spawn_env(&rendered.env)?;
    let harness_registry_digest = harness_registry_digest_for_wake(root)?;
    let (program, args) = argv.split_first().context("wake.argv 不能为空")?;

    let log_dir = root.join("coordination/runtime/logs");
    fs::create_dir_all(&log_dir)
        .with_context(|| format!("创建 wake 日志目录失败: {}", log_dir.display()))?;
    // B100：每次注入落独立 per-attempt 文件（时刻+pid+进程内计数器，errata O28），
    // 历史不再被 File::create 截断覆盖；WakeIssued.logPath 指向该文件。
    let log_path = crate::activity::wake_log_path(root, agent);
    // B100 必修回归：记录本次注入写入前 legacy 探活日志的文件长度当 offset——
    // 咬合判定只允许看 offset 之后的新内容（wake_engaged_after）。
    let legacy_path = log_dir.join(format!("wake-{agent}.log"));
    let legacy_offset = fs::metadata(&legacy_path).map(|m| m.len()).unwrap_or(0);
    let stdout = File::options()
        .create_new(true)
        .write(true)
        .open(&log_path)
        .with_context(|| format!("创建 per-attempt wake 日志失败: {}", log_path.display()))?;
    let stderr = stdout
        .try_clone()
        .with_context(|| format!("复制 wake 日志句柄失败: {}", log_path.display()))?;
    // legacy 探活路径保持可用（wake_engaged 探活 / orch handshake 依赖）：重链到本次
    // 注入的新文件。旧名字解除链接不影响既有 per-attempt inode（历史保留）；新文件
    // 从 0 字节起只含本次注入内容—— handshake 整份读到的东西恰好等价于
    // 「offset 之后的新内容」这一收窄作用域，历史残留不会把本轮空注入误判成已咬合。
    // B100 修复轮 D1/D2：轮换是 fail-closed 的——任何失败路径都保证 legacy 不含
    // 历史咬合标记（置空/缺席），失败原因写进本次 per-attempt 日志（诊断写盘失败
    // 打 stderr 可见，不影响返回态）；极端情况下（remove 与截断双失败）直接中止
    // 注入，绝不在可能残留旧标记的状态下 spawn。
    let legacy_probe = relink_legacy_wake_log(agent, &legacy_path, &log_path)?;
    if legacy_probe != LegacyProbeState::Linked {
        println!(
            "· legacy 探活降级（{}）：握手判读将保守读到空/缺席，本次注入内容见 per-attempt 日志 {}",
            legacy_probe.as_str(),
            log_path.display()
        );
    }
    // 后台 spawn 不等待（r19 实弹实测:注入 turn=对方完整工作 turn,可达十几分钟——
    // 同步等待会把 dispatch 阻塞成执行者时长;成败凭日志与后续收取链判定）。
    let pid = with_tool_startup_gate(root, definition, || {
        if identity_kind.is_some_and(DurableIdentityKind::is_managed_pid_group) {
            drop(stdout);
            drop(stderr);
            let control_id = control_wake_id
                .as_deref()
                .context("managed wake control identity missing")?;
            let managed_limit = runtime_limit.context("managed wake runtime limit missing")?;
            if is_exact_agy_provider_argv(&argv) {
                let launched = with_agy_managed_preflight(
                    &argv,
                    &rendered.env,
                    &canonical_invocation_cwd,
                    &log_path,
                    control_id,
                    message,
                    rendered
                        .requested_provider
                        .as_deref()
                        .context("Agy signed provider pin missing")?,
                    rendered
                        .requested_model
                        .as_deref()
                        .context("Agy signed model pin missing")?,
                    rendered
                        .requested_effort
                        .as_deref()
                        .context("Agy signed effort pin missing")?,
                    || {
                        spawn_managed_wake_supervisor(
                            root,
                            agent,
                            &argv,
                            &log_path,
                            control_id,
                            managed_limit,
                            &rendered.env,
                            None,
                            &canonical_invocation_cwd,
                        )
                    },
                );
                if launched.is_ok() {
                    if let Some(effect) = spawn_effect.as_deref_mut() {
                        *effect = ProviderSpawnEffect::Uncertain;
                    }
                }
                return launched;
            }
            let launched = spawn_managed_wake_supervisor(
                root,
                agent,
                &argv,
                &log_path,
                control_id,
                managed_limit,
                &rendered.env,
                None,
                &canonical_invocation_cwd,
            );
            if launched.is_ok() {
                if let Some(effect) = spawn_effect.as_deref_mut() {
                    *effect = ProviderSpawnEffect::Uncertain;
                }
            }
            launched
        } else {
            let proxy_lifecycle = (identity_kind == Some(DurableIdentityKind::WakeLogProxy))
                .then(|| wake_owner_lifecycle_plan(WakeOwnerKind::WakeLogProxy));
            if proxy_lifecycle
                .is_some_and(|plan| plan.handoff != WakeOwnerHandoff::ImmediatelyAfterSpawn)
            {
                bail!("wake log proxy lifecycle requires immediate handoff");
            }
            let reaper = if proxy_lifecycle.is_some_and(|plan| plan.prearm_reaper) {
                Some(prepare_wake_owner_reaper(
                    root,
                    action_wake_id
                        .as_deref()
                        .context("wake log proxy action wake identity missing")?,
                    WakeOwnerKind::WakeLogProxy,
                )?)
            } else {
                None
            };
            let mut command = Command::new(program);
            command.args(args);
            command.current_dir(&canonical_invocation_cwd);
            command.env_clear();
            command.envs(&rendered.env);
            if proxy_lifecycle.is_some_and(|plan| plan.isolate_process_group) {
                command.process_group(0);
            }
            let child = command
                // 注入子进程 stdin=null，
                // 否则被唤醒的 headless 客户端（如 codex，adapter.rs:86「stdin 必须关闭」）可能阻塞等 stdin。
                .stdin(Stdio::null())
                .stdout(Stdio::from(stdout))
                .stderr(Stdio::from(stderr))
                .spawn()
                .with_context(|| format!("spawn wake 注入失败: {program}"))?;
            if let Some(effect) = spawn_effect.as_deref_mut() {
                *effect = ProviderSpawnEffect::Uncertain;
            }
            let pid = child.id();
            if let Some(reaper) = reaper {
                reaper
                    .handoff(child)
                    .context("handoff wake log proxy to exact-Child reaper failed")?;
            }
            Ok(pid)
        }
    })?;
    println!(
        "· wake 注入已后台发出（agent={agent}，pid {}）；日志: {}",
        pid,
        log_path.display()
    );
    Ok(RegisteredWakeLaunch {
        pid,
        log_path,
        action_wake_id,
        wake_id: control_wake_id,
        provider_kind,
        harness_id: harness_descriptor
            .as_ref()
            .map(|descriptor| descriptor.harness),
        terminal_capability: harness_descriptor
            .as_ref()
            .map(|descriptor| descriptor.terminal),
        plain_text_review_channel,
        request_session_id,
        runtime_limit,
        legacy_offset,
        legacy_probe,
        tool: rendered.tool,
        requested_provider: rendered.requested_provider,
        requested_model: rendered.requested_model,
        requested_effort: rendered.requested_effort,
        quota_domain: Some(definition.profile.quota_domain.clone()),
        harness_registry_digest,
        review_output_path: review_output_path.map(str::to_string),
    })
}

/// legacy 探活路径轮换（B100，修复轮 D1/D2 重写）：把 `wake-<agent>.log` 重链到
/// 本次注入的 per-attempt 文件。硬链是同目录 inode 级操作，子进程实时输出同时经
/// 两个名字可见；旧名字解除链接只是去掉一个目录项，旧 per-attempt 文件的历史字节
/// 不受影响。
///
/// fail-closed 契约（D1）：任何失败路径都**绝不静默保留旧内容**——
/// - remove 失败 ⇒ 把 legacy 截断为空（DegradedEmpty），历史咬合标记被清除；
/// - hard_link 失败 ⇒ legacy 保持缺席（DegradedAbsent），**不退化 copy**（D2：
///   copy 复制的是 relink 那一刻的空文件且永不更新，是必假阴性的中间态，废弃）；
/// - remove 与截断都失败 ⇒ 无法保证 legacy 不含历史标记，返回 Err 中止本次注入。
/// 所有降级/失败原因都会写进本次 per-attempt 日志；诊断写盘失败不静默丢弃——
/// 打到 stderr（含 agent / 目标路径 / 原始错误，B100 修复轮 2）保持可见，
/// 但**不改变返回态、不中止注入**（核心安全性质与一条日志是否写成功无关）。
fn relink_legacy_wake_log(
    agent: &str,
    legacy_path: &Path,
    attempt_path: &Path,
) -> Result<LegacyProbeState> {
    relink_legacy_wake_log_with(
        agent,
        legacy_path,
        attempt_path,
        |p| fs::remove_file(p),
        |src, dst| fs::hard_link(src, dst),
        |path, line| {
            let mut f = fs::OpenOptions::new().append(true).open(path)?;
            writeln!(f, "{line}")
        },
    )
}

/// relink 的可测 seam（D1 回归要求）：remove / hard_link / 写 per-attempt 日志
/// 三个动作参数化为闭包，测试可注入失败验证 fail-closed 行为；截断故意不经
/// seam——真实清空才能被测试断言「legacy 不再含历史咬合标记」。
/// note（诊断写盘）失败不静默丢弃：打 stderr 可见（含 agent / 目标路径 / 原始
/// 错误），但继续返回原有降级态——为一条日志阻断真实工作是方向错误（裁决书 §三）。
fn relink_legacy_wake_log_with<R, L, N>(
    agent: &str,
    legacy_path: &Path,
    attempt_path: &Path,
    remove: R,
    hard_link: L,
    mut note: N,
) -> Result<LegacyProbeState>
where
    R: Fn(&Path) -> io::Result<()>,
    L: Fn(&Path, &Path) -> io::Result<()>,
    N: FnMut(&Path, &str) -> io::Result<()>,
{
    match remove(legacy_path) {
        Ok(()) => {}
        Err(e) if e.kind() == io::ErrorKind::NotFound => {}
        Err(e) => {
            let msg = format!(
                "orch wake: legacy probe rotate failed (remove: {e}); \
                 truncating legacy to empty (fail-closed, D1)"
            );
            if let Err(ne) = note(attempt_path, &msg) {
                eprintln!(
                    "orch wake: 降级原因写入 per-attempt 日志失败（agent={agent}，目标 {}，写盘错误: {ne}）；原因原文: {msg}",
                    attempt_path.display()
                );
            }
            return match File::create(legacy_path) {
                Ok(_) => Ok(LegacyProbeState::DegradedEmpty),
                Err(e2) => {
                    let msg = format!(
                        "orch wake: fail-closed truncate failed ({e2}); \
                         aborting injection to keep stale engagement marks out of the probe"
                    );
                    if let Err(ne) = note(attempt_path, &msg) {
                        eprintln!(
                            "orch wake: 降级原因写入 per-attempt 日志失败（agent={agent}，目标 {}，写盘错误: {ne}）；原因原文: {msg}",
                            attempt_path.display()
                        );
                    }
                    bail!(
                        "legacy 探活日志 {} 无法 fail-closed 轮换（remove: {e}; truncate: {e2}）；\
                         为杜绝历史咬合标记造成的假阳性，本次注入中止",
                        legacy_path.display()
                    );
                }
            };
        }
    }
    match hard_link(attempt_path, legacy_path) {
        Ok(()) => Ok(LegacyProbeState::Linked),
        Err(e) => {
            let msg = format!(
                "orch wake: legacy probe hard-link failed ({e}); legacy left absent \
                 (fail-closed, D2: no stale copy); judge via the per-attempt log path"
            );
            if let Err(ne) = note(attempt_path, &msg) {
                eprintln!(
                    "orch wake: 降级原因写入 per-attempt 日志失败（agent={agent}，目标 {}，写盘错误: {ne}）；原因原文: {msg}",
                    attempt_path.display()
                );
            }
            Ok(LegacyProbeState::DegradedAbsent)
        }
    }
}

/// 显式 `orch wake` 的预算化入口（向后兼容包装）。
///
/// Dispatch/Nudge 已在各自的意图事件上计数，因此它们从 `dispatch_wake` 直接走
/// `spawn_registered_wake`；只有人工显式 wake 在成功 spawn 后写 `WakeIssued`。
/// 若 spawn 后落账失败，reservation 故意保留，避免实际模型启动漏计。
///
/// 旧入口：等价于 `MessageSource::Default`（来源未富标识）；新 CLI 走
/// [run_wake_with_message] 以落 messageSource/messageBytes。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ReviewSite {
    pub worktree: String,
    pub target_dir: String,
}

fn validate_review_component(label: &str, value: &str) -> std::result::Result<(), String> {
    let valid = !value.is_empty()
        && value
            .bytes()
            .next()
            .is_some_and(|byte| byte.is_ascii_alphanumeric())
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'));
    if valid {
        Ok(())
    } else {
        Err(format!(
            "review site {label} 必须是单一安全 component: {value:?}"
        ))
    }
}

/// Gitignored staging location used by every formal review writer.
pub fn review_inbox_relpath(
    round: &str,
    attempt_id: &str,
    role: &str,
    agent: &str,
) -> Result<String> {
    validate_review_component("round", round).map_err(anyhow::Error::msg)?;
    validate_review_component("attempt", attempt_id).map_err(anyhow::Error::msg)?;
    validate_review_component("agent", agent).map_err(anyhow::Error::msg)?;
    let role = crate::sites::SiteRole::parse(role).map_err(anyhow::Error::msg)?;
    if role == crate::sites::SiteRole::Implement {
        bail!("implement role does not have a review inbox");
    }
    Ok(format!(
        "coordination/runtime/review-inbox/{round}/{attempt_id}-{role}-{agent}.md"
    ))
}

/// Choose the immutable delivery path. Before verdict it is canonical; after
/// verdict it is the next monotonic `late-N` path and can never alias the
/// canonical artifact.
pub fn review_delivery_relpath(
    round: &str,
    attempt_id: &str,
    role: &str,
    agent: &str,
    post_verdict: bool,
    existing_late_numbers: &[u64],
) -> Result<String> {
    // Reuse the staging validator for every path component.
    let _ = review_inbox_relpath(round, attempt_id, role, agent)?;
    let canonical =
        crate::verify::canonical_review_artifact_relpath(round, attempt_id, role, agent);
    if !post_verdict {
        return Ok(canonical);
    }
    if existing_late_numbers.contains(&0) {
        bail!("late review ordinal must be positive");
    }
    let next = existing_late_numbers
        .iter()
        .copied()
        .max()
        .unwrap_or(0)
        .checked_add(1)
        .context("late review ordinal overflow")?;
    let stem = canonical
        .strip_suffix(".md")
        .context("canonical review path lacks .md suffix")?;
    Ok(format!("{stem}-late-{next}.md"))
}

fn ensure_review_inbox_parent(root: &Path, rel: &str) -> Result<()> {
    let path = root.join(rel);
    let parent = path.parent().context("review inbox path lacks parent")?;
    let relative = parent
        .strip_prefix(root)
        .context("review inbox parent escaped repository root")?;
    let mut cursor = root.to_path_buf();
    for component in relative.components() {
        let std::path::Component::Normal(name) = component else {
            bail!("review inbox parent contains an unsafe component");
        };
        cursor.push(name);
        match fs::symlink_metadata(&cursor) {
            Ok(metadata) => {
                if metadata.file_type().is_symlink() || !metadata.is_dir() {
                    bail!(
                        "review inbox parent must be a real directory: {}",
                        cursor.display()
                    );
                }
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                match fs::create_dir(&cursor) {
                    Ok(()) => {}
                    // Two formal reviewers may prepare the same round inbox
                    // concurrently.  Losing the mkdir race is success only
                    // after a fresh no-follow stat proves the winner created
                    // the exact real directory we expected.
                    Err(create_error)
                        if create_error.kind() == std::io::ErrorKind::AlreadyExists =>
                    {
                        let metadata = fs::symlink_metadata(&cursor).with_context(|| {
                            format!(
                                "restat raced review inbox directory failed: {}",
                                cursor.display()
                            )
                        })?;
                        if metadata.file_type().is_symlink() || !metadata.is_dir() {
                            bail!(
                                "raced review inbox parent is not a real directory: {}",
                                cursor.display()
                            );
                        }
                    }
                    Err(create_error) => {
                        return Err(create_error).with_context(|| {
                            format!("create review inbox directory failed: {}", cursor.display())
                        })
                    }
                }
            }
            Err(error) => {
                return Err(error).with_context(|| {
                    format!("stat review inbox directory failed: {}", cursor.display())
                })
            }
        }
    }
    Ok(())
}

/// Deterministically plan an in-repository review worktree and build directory.
///
/// The function is pure so the seed can lock down the path contract.  Actual
/// provisioning separately verifies canonical parents, creates a detached
/// worktree, and checks its fixed HEAD before any provider is spawned.
pub fn review_site_plan_generation(
    root: &str,
    attempt_id: &str,
    role: crate::sites::SiteRole,
    agent: &str,
    generation: u32,
) -> std::result::Result<ReviewSite, String> {
    let root_path = Path::new(root);
    if root.is_empty() || !root_path.is_absolute() {
        return Err(format!(
            "review site repo root 必须是非空绝对路径: {root:?}"
        ));
    }
    if root_path.components().any(|component| {
        matches!(
            component,
            std::path::Component::CurDir | std::path::Component::ParentDir
        )
    }) {
        return Err(format!(
            "review site repo root 不得含 . 或 .. component: {root:?}"
        ));
    }
    validate_review_component("attempt", attempt_id)?;
    validate_review_component("agent", agent)?;
    if generation == 0 {
        return Err("review site generation 必须为正数".to_string());
    }

    let basename = format!(
        "review-{attempt_id}-{}-{agent}-g{generation:02}",
        role.as_str()
    );
    let worktree = root_path.join(".worktrees").join(&basename);
    let target_dir = root_path.join("orch/target").join(&basename);
    if !worktree.starts_with(root_path) || !target_dir.starts_with(root_path) {
        return Err("review site 路径逃出 repo root（fail-closed）".to_string());
    }
    Ok(ReviewSite {
        worktree: worktree.display().to_string(),
        target_dir: target_dir.display().to_string(),
    })
}

/// Legacy path calculator retained exclusively for read-only recovery
/// diagnostics in `verify.rs`.  New provisioning never calls this function:
/// legacy names have no attempt/generation identity and therefore cannot be
/// lease-backed or automatically deleted.
pub fn review_site_plan(
    root: &str,
    task: &str,
    role: &str,
    agent: &str,
) -> std::result::Result<ReviewSite, String> {
    let root_path = Path::new(root);
    if root.is_empty() || !root_path.is_absolute() {
        return Err(format!(
            "review site repo root 必须是非空绝对路径: {root:?}"
        ));
    }
    if root_path.components().any(|component| {
        matches!(
            component,
            std::path::Component::CurDir | std::path::Component::ParentDir
        )
    }) {
        return Err(format!(
            "review site repo root 不得含 . 或 .. component: {root:?}"
        ));
    }
    validate_review_component("task", task)?;
    validate_review_component("agent", agent)?;
    let role = crate::sites::SiteRole::parse(role)?;
    if role == crate::sites::SiteRole::Implement {
        return Err("implement role does not provision a review site".to_string());
    }
    let identity = format!("{task}-{role}-{agent}");
    let worktree = root_path.join(".worktrees").join(&identity);
    let target_dir = root_path
        .join("orch/target")
        .join(format!("review-{identity}"));
    Ok(ReviewSite {
        worktree: worktree.display().to_string(),
        target_dir: target_dir.display().to_string(),
    })
}

#[derive(Debug, Clone)]
struct ProvisionedReviewSite {
    site: ReviewSite,
    lease: crate::sites::Site,
    reviewed_head: String,
}

fn ensure_canonical_path_inside(root: &Path, path: &Path, label: &str) -> Result<()> {
    let canonical_root = fs::canonicalize(root)
        .with_context(|| format!("canonicalize repo root failed: {}", root.display()))?;
    let subject = if path.exists() {
        path
    } else {
        path.parent()
            .with_context(|| format!("{label} 缺 parent: {}", path.display()))?
    };
    let canonical_subject = fs::canonicalize(subject)
        .with_context(|| format!("canonicalize {label} failed: {}", subject.display()))?;
    if !canonical_subject.starts_with(&canonical_root) {
        bail!(
            "{label} 必须位于 repo root 内: path={} root={}",
            path.display(),
            canonical_root.display()
        );
    }
    Ok(())
}

fn review_worktree_is_detached(worktree: &Path) -> Result<bool> {
    let output = Command::new("git")
        .arg("-C")
        .arg(worktree)
        .args(["symbolic-ref", "--quiet", "--short", "HEAD"])
        .output()
        .with_context(|| {
            format!(
                "检查 review worktree detached 状态失败: {}",
                worktree.display()
            )
        })?;
    match output.status.code() {
        Some(0) => Ok(false),
        Some(1) => Ok(true),
        _ => bail!(
            "检查 review worktree detached 状态失败: path={} status={} stderr={}",
            worktree.display(),
            output.status,
            String::from_utf8_lossy(&output.stderr).trim()
        ),
    }
}

fn provision_review_site(
    root: &Path,
    round: &str,
    wake_id: &str,
    request: &ReviewRequest,
    expected: &crate::verify::ReviewContractExpectation,
) -> Result<ProvisionedReviewSite> {
    if expected.task_id() != request.task_id
        || expected.attempt_id() != request.attempt_id
        || expected.role() != request.role
        || expected.reviewer() != request.agent
    {
        bail!("review site request 与 runtime contract identity 不匹配");
    }
    fs::create_dir_all(root.join(".worktrees"))
        .with_context(|| format!("创建 review worktree root 失败: {}", root.display()))?;
    fs::create_dir_all(root.join("orch/target"))
        .with_context(|| format!("创建 review target root 失败: {}", root.display()))?;
    let reviewed_head = expected.reviewed_head().to_string();
    let branch_head = crate::gitx::rev_parse(root, &format!("refs/heads/task/{}", request.task_id))
        .with_context(|| format!("解析被审 task/{} 固定 HEAD 失败", request.task_id))?;
    if branch_head != reviewed_head {
        bail!(
            "被审 task/{} tip 未绑定 immutable collect HEAD: expected={} actual={}",
            request.task_id,
            reviewed_head,
            branch_head
        );
    }
    let role = crate::sites::SiteRole::parse(&request.role).map_err(anyhow::Error::msg)?;
    let root_text = root
        .to_str()
        .context("review site repo root 不是合法 UTF-8")?;
    let leased = crate::sites::lease_review_site_with(
        root,
        round,
        &request.task_id,
        &request.attempt_id,
        role,
        &request.agent,
        &reviewed_head,
        wake_id,
        |leased| {
            let planned = review_site_plan_generation(
                root_text,
                &request.attempt_id,
                role,
                &request.agent,
                leased.generation,
            )
            .map_err(anyhow::Error::msg)?;
            let worktree = PathBuf::from(&planned.worktree);
            let target_dir = PathBuf::from(&planned.target_dir);
            if worktree != root.join(&leased.worktree) || target_dir != root.join(&leased.target) {
                bail!("review site planner 与 durable lease paths 漂移");
            }
            ensure_canonical_path_inside(root, &worktree, "review worktree")?;
            ensure_canonical_path_inside(root, &target_dir, "review target dir")?;

            if worktree.exists() {
                let metadata = fs::symlink_metadata(&worktree).with_context(|| {
                    format!("读取 review worktree 元数据失败: {}", worktree.display())
                })?;
                if metadata.file_type().is_symlink() || !metadata.is_dir() {
                    bail!(
                        "review worktree 已被占用且不可幂等复用: {}",
                        worktree.display()
                    );
                }
                ensure_canonical_path_inside(root, &worktree, "existing review worktree")?;
                let existing_head =
                    crate::gitx::rev_parse(&worktree, "HEAD").with_context(|| {
                        format!(
                            "既有 review worktree 不是可读 git 现场: {}",
                            worktree.display()
                        )
                    })?;
                let detached = review_worktree_is_detached(&worktree)?;
                if existing_head != reviewed_head || !detached {
                    bail!(
                        "review worktree 已存在但不是目标 detached HEAD: path={} expected={} actual={} detached={}",
                        worktree.display(),
                        reviewed_head,
                        existing_head,
                        detached
                    );
                }
            } else {
                crate::gitx::worktree_add_detached(root, &worktree, &reviewed_head).with_context(
                    || {
                        format!(
                            "provision review worktree failed before injection: {} @{}",
                            worktree.display(),
                            reviewed_head
                        )
                    },
                )?;
            }
            validate_review_site_repository(root, &worktree)?;

            if target_dir.exists() {
                let metadata = fs::symlink_metadata(&target_dir).with_context(|| {
                    format!("读取 review target 元数据失败: {}", target_dir.display())
                })?;
                if metadata.file_type().is_symlink() || !metadata.is_dir() {
                    bail!(
                        "review target dir 已被占用且不可幂等复用: {}",
                        target_dir.display()
                    );
                }
            } else {
                fs::create_dir_all(&target_dir).with_context(|| {
                    format!(
                        "provision review target dir failed before injection: {}",
                        target_dir.display()
                    )
                })?;
            }
            ensure_canonical_path_inside(root, &target_dir, "provisioned review target dir")?;
            let actual_head = crate::gitx::rev_parse(&worktree, "HEAD")?;
            if actual_head != reviewed_head || !review_worktree_is_detached(&worktree)? {
                bail!(
                    "review site postcondition failed: {} 未 detached 于固定 HEAD {}",
                    worktree.display(),
                    reviewed_head
                );
            }
            Ok(())
        },
    )?;
    let site = review_site_plan_generation(
        root_text,
        &request.attempt_id,
        role,
        &request.agent,
        leased.generation,
    )
    .map_err(anyhow::Error::msg)?;
    Ok(ProvisionedReviewSite {
        site,
        lease: leased,
        reviewed_head,
    })
}

fn reject_and_retire_pre_spawn_review_site<T>(
    root: &Path,
    round: &str,
    wake_id: &str,
    request: &ReviewRequest,
    provisioned: &ProvisionedReviewSite,
    error: anyhow::Error,
) -> Result<T> {
    let reason = format!("schema 3 review rejected before provider spawn: {error:#}");
    let mut rejection = None;
    ledger::append_checked(root, round, |events| {
        let attempt = crate::attempt::current_attempt(events, &request.task_id)?
            .context("pre-spawn review rejection 缺 current attempt")?;
        if attempt.attempt_id != request.attempt_id {
            bail!("pre-spawn review rejection attempt 漂移");
        }
        let leases = events
            .iter()
            .filter(|event| {
                event.kind == "WorkspaceLeased"
                    && event.round.as_deref() == Some(round)
                    && event.task_id.as_deref() == Some(request.task_id.as_str())
                    && payload_string(event, "wakeId") == Some(wake_id)
            })
            .collect::<Vec<_>>();
        let [lease] = leases.as_slice() else {
            bail!("pre-spawn review rejection 要求唯一 WorkspaceLeased");
        };
        let site = &provisioned.lease;
        if payload_string(lease, "siteId") != Some(site.site_id.as_str())
            || lease
                .payload
                .as_ref()
                .and_then(|payload| payload.get("generation"))
                .and_then(serde_json::Value::as_u64)
                .and_then(|value| u32::try_from(value).ok())
                != Some(site.generation)
            || payload_string(lease, "attemptId") != Some(site.attempt_id.as_str())
            || payload_string(lease, "role") != Some(site.role.as_str())
            || payload_string(lease, "agent") != Some(site.agent.as_str())
            || events.iter().any(|event| {
                matches!(event.kind.as_str(), "WakeIssued" | "ReviewRequested")
                    && payload_string(event, "wakeId") == Some(wake_id)
            })
        {
            bail!("pre-spawn review rejection lease identity/absence proof 失败");
        }
        if events.iter().any(|event| {
            (event.kind == "ActionRejected" && payload_string(event, "actionId") == Some(wake_id))
                || (event.kind == crate::sites::SITE_RETIRED_EVENT_KIND
                    && payload_string(event, "wakeId") == Some(wake_id))
        }) {
            bail!("pre-spawn review rejection 已存在冲突 terminal fact");
        }
        let rejected = failure::ActionRejection::from_disposition(
            "wake",
            wake_id,
            &reason,
            failure::CliDisposition::Rejected,
        )?
        .with_attempt(&attempt);
        let rejected_event = failure::rejection_event(round, Some(&request.task_id), &rejected);
        let retirement = ledger::event(
            crate::sites::SITE_RETIRED_EVENT_KIND,
            "runtime:orch",
            Some(&site.task_id),
            Some(round),
            serde_json::json!({
                "siteId": site.site_id,
                "generation": site.generation,
                "taskId": site.task_id,
                "attemptId": site.attempt_id,
                "role": site.role.as_str(),
                "agent": site.agent,
                "wakeId": site.wake_id,
                "trigger": "pre-spawn-rejected",
                "retireEventId": rejected_event.event_id,
            }),
        );
        rejection = Some(rejected);
        Ok(vec![rejected_event, retirement])
    })?;
    Err(rejection
        .context("pre-spawn review rejection transaction 未返回 rejection")?
        .into_error())
}

#[derive(Debug)]
struct PreparedReviewProbe {
    sentinel_path: PathBuf,
    challenge: String,
    site: ReviewSite,
    output_path: String,
    expectation: crate::verify::ReviewContractExpectation,
}

/// Render the runtime-owned review identity: seven base fields for legacy
/// delivery plus four mandatory seat fields for a panel-routed artifact.
/// Planner prose may precede this block but can never replace a fixed value.
pub fn render_review_frontmatter_template(
    expected: &crate::verify::ReviewContractExpectation,
) -> Result<String> {
    // Reconstructing through `exact` keeps this public renderer fail-closed if
    // a future internal caller ever bypasses the expectation constructor.
    let panel = expected.panel_identity();
    if let Some(panel) = panel {
        crate::verify::ReviewContractExpectation::panel_exact(
            expected.task_id(),
            expected.round(),
            expected.attempt_id(),
            expected.role(),
            expected.reviewer(),
            expected.reviewed_head(),
            &panel.seat_id,
            panel.generation,
            &panel.wake_id,
            &panel.policy_base_sha,
        )?;
    } else {
        crate::verify::ReviewContractExpectation::exact(
            expected.task_id(),
            expected.round(),
            expected.attempt_id(),
            expected.role(),
            expected.reviewer(),
            expected.reviewed_head(),
        )?;
    }
    let panel_lines = panel.map_or_else(String::new, |panel| {
        format!(
            "seatId: {}\ngeneration: {}\nwakeId: {}\npolicyBaseSha: {}\n",
            panel.seat_id, panel.generation, panel.wake_id, panel.policy_base_sha
        )
    });
    Ok(format!(
        "---\n\
         taskId: {}\n\
         round: {}\n\
         attemptId: {}\n\
         role: {}\n\
         reviewer: {}\n\
         verdict: __VERDICT__\n\
         reviewedHead: {}\n\
         {}---\n",
        expected.task_id(),
        expected.round(),
        expected.attempt_id(),
        expected.role(),
        expected.reviewer(),
        expected.reviewed_head(),
        panel_lines,
    ))
}

/// Render the neutral review-site handoff. Reachability is proven by the
/// provider harness transcript, never by asking the reviewer to echo a nonce.
pub const REVIEW_SCRATCH_POLICY: &str = concat!(
    "SCRATCH POLICY: You MUST keep every scratch, backup, and negative-mutation file inside ",
    "the repository. Do not write outside the repository, including /tmp, and do not use ",
    "mktemp when it defaults there. Prefer no backup file: undo each mutation with an exact ",
    "inverse edit, then prove restoration with git diff --exit-code."
);

/// Build the neutral, runtime-owned review-site handoff around planner prose.
/// Callers append the exact frontmatter template separately; this text makes
/// the seven base fields and panel-only four-field extension non-substitutable.
#[allow(clippy::too_many_arguments)]
pub fn review_probe_message_body(
    worktree: &str,
    target_dir: &str,
    reviewed_head: &str,
    sentinel_path: &str,
    scope_note: &str,
    request: &str,
) -> String {
    format!(
        "ORCH REVIEW SITE (provisioned; do not create or relocate it)\n\
         WORKTREE={worktree}\n\
         CARGO_TARGET_DIR={target_dir}\n\
         REVIEWED_HEAD={reviewed_head}\n\
         CLEANUP=runtime-lease-gated; reviewer must not remove this site or its sentinel\n\
         REGISTRY_SANDBOX_SCOPE={scope_note}\n\
         {REVIEW_SCRATCH_POLICY}\n\
         ORCH_REVIEW_SITE_WORKTREE_GIT={worktree}/.git\n\
         ORCH_REVIEW_SITE_SENTINEL={sentinel_path}\n\
         REVIEW OUTPUT CONTRACT: write the review only to the absolute REVIEW_OUTPUT_PATH \
         appended by the runtime below. The runtime chooses either a legacy inbox or a \
         lease-scoped spool inside this review worktree. Do not relocate or commit it.\n\
         REVIEW FRONTMATTER requires every field in the runtime template: taskId / round / \
         attemptId / role / reviewer / verdict / reviewedHead, plus seatId / generation / wakeId / \
         policyBaseSha for a panel route. Extra fields are ignored but reported loudly; fields \
         outside that selected contract never replace a required field. In particular, verifier: cannot \
         replace reviewer:.\n\
         Reachability evidence: before reviewing, read both ORCH_REVIEW_SITE_WORKTREE_GIT and \
         ORCH_REVIEW_SITE_SENTINEL. The provider harness records the tool output; no \
         acknowledgement, nonce echo, or self-attestation is requested. If either read fails, \
         stop without reviewing. After both reads, continue with:\n\
         {request}\n",
    )
}

fn ensure_review_spool_directory(worktree: &Path, label: &str) -> Result<PathBuf> {
    let spool = worktree.join(".cowork-temp/review-spool");
    let mut cursor = worktree.to_path_buf();
    for component in [".cowork-temp", "review-spool"] {
        cursor.push(component);
        match fs::symlink_metadata(&cursor) {
            Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
                bail!("{label} review spool parent 必须是 real directory")
            }
            Ok(_) => {}
            Err(error) if error.kind() == io::ErrorKind::NotFound => {
                fs::create_dir(&cursor).with_context(|| {
                    format!(
                        "create {label} review spool parent failed: {}",
                        cursor.display()
                    )
                })?;
            }
            Err(error) => {
                return Err(error)
                    .with_context(|| format!("stat {label} review spool parent failed"))
            }
        }
    }
    Ok(spool)
}

fn prepare_review_probe_message(
    resolved: ResolvedMessage,
    provisioned: &ProvisionedReviewSite,
    scope: &crate::agent_profile::SandboxScope,
    root: &Path,
    round: &str,
    wake_id: &str,
    expectation: &crate::verify::ReviewContractExpectation,
) -> Result<(ResolvedMessage, PreparedReviewProbe)> {
    let sentinel_id = fresh_uuid();
    let challenge = fresh_uuid();
    let sentinel_path = PathBuf::from(&provisioned.site.target_dir)
        .join(format!(".orch-review-probe-{sentinel_id}"));
    fs::write(&sentinel_path, format!("{challenge}\n")).with_context(|| {
        format!(
            "写 review reachability sentinel 失败: {}",
            sentinel_path.display()
        )
    })?;
    let scope_note = match scope {
        crate::agent_profile::SandboxScope::RepoRootOnly => {
            "repo-root-only (safe default)".to_string()
        }
        crate::agent_profile::SandboxScope::DeclaredUnverified(roots) => {
            format!("declared-unverified({})", roots.join(","))
        }
    };
    let mut text = review_probe_message_body(
        &provisioned.site.worktree,
        &provisioned.site.target_dir,
        &provisioned.reviewed_head,
        &sentinel_path.display().to_string(),
        &scope_note,
        &resolved.text,
    );
    if expectation.round() != round {
        bail!("review prompt expectation round 漂移");
    }
    let (output_path, destination_note) = if let Some(panel) = expectation.panel_identity() {
        let worktree = PathBuf::from(&provisioned.site.worktree);
        if !worktree.starts_with(root) {
            bail!("panel review worktree escaped repository root");
        }
        let spool = ensure_review_spool_directory(&worktree, "panel")?;
        let name = format!(
            "{}-{}-g{}-{}.md",
            expectation.attempt_id(),
            panel.seat_id,
            panel.generation,
            panel.wake_id,
        );
        (
            spool.join(name),
            "This is the lease-scoped panel spool inside the review worktree; do not write the main repository directly.",
        )
    } else if expectation.reviewer() == "executor-dsh" {
        let worktree = PathBuf::from(&provisioned.site.worktree);
        if !worktree.starts_with(root) {
            bail!("DSH legacy review worktree escaped repository root");
        }
        for value in [
            expectation.attempt_id(),
            expectation.role(),
            expectation.reviewer(),
            wake_id,
        ] {
            validate_review_component("DSH legacy spool component", value)
                .map_err(anyhow::Error::msg)?;
        }
        let spool = ensure_review_spool_directory(&worktree, "DSH legacy")?;
        let name = format!(
            "{}-{}-{}-{}.md",
            expectation.attempt_id(),
            expectation.role(),
            expectation.reviewer(),
            wake_id,
        );
        (
            spool.join(name),
            "This is the wake-scoped DSH legacy spool inside the leased review worktree; runtime validates and promotes it without clobber.",
        )
    } else {
        let output_rel = review_inbox_relpath(
            round,
            expectation.attempt_id(),
            expectation.role(),
            expectation.reviewer(),
        )?;
        ensure_review_inbox_parent(root, &output_rel)?;
        (
            root.join(output_rel),
            "This is the legacy main-repository review inbox path.",
        )
    };
    let output_path_text = output_path.display().to_string();
    let mut template = render_review_frontmatter_template(expectation)?;
    if expectation.role() == "review" {
        template = template.replacen("\n---\n", &format!("\nwakeId: {wake_id}\n---\n"), 1);
    }
    let panel_final_check = if expectation.panel_identity().is_some() {
        "PANEL FINAL CHECK: before exiting, read REVIEW_OUTPUT_PATH back and prove the header contains all eleven required fields: taskId, round, attemptId, role, reviewer, verdict, reviewedHead, seatId, generation, wakeId, policyBaseSha. A legacy seven-field header is invalid and cannot be repaired after terminal; never write or copy the legacy main-inbox artifact.\n"
    } else if expectation.role() == "review" {
        "GENERIC REVIEW FINAL CHECK: before exiting, read REVIEW_OUTPUT_PATH back and prove the header contains exactly taskId, round, attemptId, role, reviewer, verdict, reviewedHead, wakeId. role must be review.\n"
    } else {
        ""
    };
    text.push_str(&format!(
        "REVIEW_OUTPUT_PATH={}\n\
         The line above and the runtime block below are authoritative and were appended after all \
         custom planner prose. {destination_note} Write only that exact path and do not commit it in the worktree. \
         Replace only __VERDICT__ with PASS, FAIL, or BLOCKED.\n\
         {panel_final_check}\
         ```yaml\n{template}```\n\
         In the final response, emit the exact REVIEW_OUTPUT_PATH line and a closed yaml fence with \
         every final field shown above so plain-text review channels can prove exact consumption.\n",
        output_path_text
    ));
    let enriched = ResolvedMessage {
        bytes: text.len(),
        text,
        source: resolved.source,
    };
    Ok((
        enriched,
        PreparedReviewProbe {
            sentinel_path,
            challenge,
            site: provisioned.site.clone(),
            output_path: output_path_text,
            expectation: expectation.clone(),
        },
    ))
}

/// Harness-owned transcript field that proved the sentinel challenge was read.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReviewProbeSource {
    ClawToolOutput,
    CodexCommandOutput,
    OpenCodeToolOutput,
    /// Kept as an explicit non-proof source so callers can assert that
    /// assistant prose is never accepted.
    AssistantText,
}

/// Evidence that one exact review-wake log window was consumed by its provider.
///
/// The generic marker is retained for existing Codex-style adapters.  A
/// structured proof is stronger: it means the provider read the fresh,
/// runtime-owned sentinel and returned its unpredictable challenge in a
/// harness-owned tool-output field.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReviewConsumptionProof {
    GenericWakeEngaged,
    StructuredProbe(ReviewProbeSource),
}

fn string_field_contains(value: Option<&serde_json::Value>, challenge: &str) -> bool {
    value
        .and_then(serde_json::Value::as_str)
        .is_some_and(|text| text.contains(challenge))
}

/// Parse provider JSON-lines and inspect only harness-generated tool output.
///
/// Provider logs may contain ordinary text diagnostics between JSON records;
/// those lines are ignored. Assistant text is deliberately never evidence.
pub fn probe_challenge_observed(log: &str, challenge: &str) -> Option<ReviewProbeSource> {
    for line in log.lines() {
        let Ok(value) = serde_json::from_str::<serde_json::Value>(line) else {
            continue;
        };
        match value.get("type").and_then(serde_json::Value::as_str) {
            Some("tool_result") => {
                let output_hit = string_field_contains(value.get("output"), challenge);
                let payload_hit = value
                    .get("payloads")
                    .and_then(serde_json::Value::as_array)
                    .is_some_and(|payloads| {
                        payloads
                            .iter()
                            .any(|payload| string_field_contains(payload.get("text"), challenge))
                    });
                if output_hit || payload_hit {
                    return Some(ReviewProbeSource::ClawToolOutput);
                }
            }
            Some("item.completed")
                if value
                    .pointer("/item/type")
                    .and_then(serde_json::Value::as_str)
                    == Some("command_execution") =>
            {
                if string_field_contains(value.pointer("/item/aggregated_output"), challenge) {
                    return Some(ReviewProbeSource::CodexCommandOutput);
                }
            }
            Some("tool_use") => {
                if string_field_contains(value.pointer("/part/state/output"), challenge) {
                    return Some(ReviewProbeSource::OpenCodeToolOutput);
                }
            }
            _ => {}
        }
    }
    None
}

/// Combine the two independently audited review-consumption proofs for one
/// immutable `[probe_offset, probe_end)` window.  Provider traffic alone is
/// never enough: structured evidence must contain this exact challenge in a
/// harness-owned completed-tool field.
pub fn review_consumption_proof(
    log: &[u8],
    probe_offset: u64,
    probe_end: u64,
    challenge: &str,
) -> Result<Option<ReviewConsumptionProof>, String> {
    if challenge.trim().is_empty() {
        return Err("review consumption challenge must not be empty".to_string());
    }
    let slice = exact_probe_slice(log, probe_offset, probe_end)?;
    let scoped = String::from_utf8_lossy(slice);
    if let Some(source) = probe_challenge_observed(&scoped, challenge) {
        return Ok(Some(ReviewConsumptionProof::StructuredProbe(source)));
    }
    if wake_engaged(&scoped) {
        return Ok(Some(ReviewConsumptionProof::GenericWakeEngaged));
    }
    Ok(None)
}

/// Antigravity's existing `agy` channel has no harness-owned tool-output
/// records. Its sole narrow compatibility proof is an exact path plus a
/// complete runtime identity in one immutable log window.
pub fn plain_text_review_contract_consumed(
    log: &[u8],
    probe_offset: u64,
    probe_end: u64,
    review_output_path: &str,
    expected: &crate::verify::ReviewContractExpectation,
) -> Result<bool> {
    let slice = exact_probe_slice(log, probe_offset, probe_end).map_err(anyhow::Error::msg)?;
    let text = match std::str::from_utf8(slice) {
        Ok(text) => text,
        Err(error) if error.error_len().is_none() => return Ok(false),
        Err(error) => return Err(error).context("agy review log window 必须为 UTF-8"),
    };
    let path_line = format!("REVIEW_OUTPUT_PATH={review_output_path}");
    if !text
        .split_inclusive('\n')
        .map(|line| line.trim_end_matches(['\r', '\n']))
        .any(|line| line == path_line)
    {
        return Ok(false);
    }

    let mut in_yaml = false;
    let mut yaml = String::new();
    for line in text.split_inclusive('\n') {
        let marker = line.trim_end_matches(['\r', '\n']);
        if !in_yaml {
            if marker == "```yaml" {
                in_yaml = true;
                yaml.clear();
            }
            continue;
        }
        if marker == "```" {
            if crate::verify::check_review_artifact_contract(yaml.as_bytes(), expected)
                .is_ok_and(|checked| checked.is_some())
            {
                return Ok(true);
            }
            in_yaml = false;
            yaml.clear();
        } else {
            yaml.push_str(line);
        }
    }
    Ok(false)
}

fn captured_probe_observed(
    mut captured: CapturedProbeWindow,
    challenge: &str,
) -> std::result::Result<Option<ReviewProbeSource>, String> {
    let captured_len = usize::try_from(captured.probe_end)
        .map_err(|_| format!("review probeEnd 超出 usize: {}", captured.probe_end))?;
    let mut log = vec![0_u8; captured_len];
    captured.file.read_exact(&mut log).map_err(|error| {
        format!(
            "review probe 读取 [0, {}) 失败 {}: {error}",
            captured.probe_end,
            captured.log_path.display()
        )
    })?;
    let slice = exact_probe_slice(&log, captured.probe_offset, captured.probe_end)?;
    Ok(probe_challenge_observed(
        &String::from_utf8_lossy(slice),
        challenge,
    ))
}

#[cfg(test)]
fn captured_review_consumption_proof(
    mut captured: CapturedProbeWindow,
    challenge: &str,
) -> std::result::Result<Option<ReviewConsumptionProof>, String> {
    let captured_len = usize::try_from(captured.probe_end).map_err(|_| {
        format!(
            "review consumption probeEnd 超出 usize: {}",
            captured.probe_end
        )
    })?;
    let mut log = vec![0_u8; captured_len];
    captured.file.read_exact(&mut log).map_err(|error| {
        format!(
            "review consumption 读取 [0, {}) 失败 {}: {error}",
            captured.probe_end,
            captured.log_path.display()
        )
    })?;
    review_consumption_proof(&log, captured.probe_offset, captured.probe_end, challenge)
}

fn captured_plain_text_review_consumption(
    mut captured: CapturedProbeWindow,
    output_path: &str,
    expected: &crate::verify::ReviewContractExpectation,
) -> Result<bool> {
    let captured_len = usize::try_from(captured.probe_end)
        .with_context(|| format!("agy review probeEnd 超出 usize: {}", captured.probe_end))?;
    let mut log = vec![0_u8; captured_len];
    captured.file.read_exact(&mut log).with_context(|| {
        format!(
            "agy review consumption 读取 [0, {}) 失败 {}",
            captured.probe_end,
            captured.log_path.display()
        )
    })?;
    plain_text_review_contract_consumed(
        &log,
        captured.probe_offset,
        captured.probe_end,
        output_path,
        expected,
    )
}

fn await_review_probe(
    log_path: &Path,
    probe: &PreparedReviewProbe,
    timeout: Duration,
) -> Result<Option<ReviewProbeSource>> {
    let started = std::time::Instant::now();
    loop {
        let captured = capture_probe_window(log_path, 0).map_err(anyhow::Error::msg)?;
        if let Some(source) =
            captured_probe_observed(captured, &probe.challenge).map_err(anyhow::Error::msg)?
        {
            return Ok(Some(source));
        }
        if started.elapsed() >= timeout {
            return Ok(None);
        }
        std::thread::sleep(Duration::from_millis(25));
    }
}

fn await_plain_text_review_consumption(
    log_path: &Path,
    output_path: &str,
    expected: &crate::verify::ReviewContractExpectation,
    timeout: Duration,
) -> Result<bool> {
    let started = std::time::Instant::now();
    loop {
        let captured = capture_probe_window(log_path, 0).map_err(anyhow::Error::msg)?;
        if captured_plain_text_review_consumption(captured, output_path, expected)? {
            return Ok(true);
        }
        if started.elapsed() >= timeout {
            return Ok(false);
        }
        std::thread::sleep(Duration::from_millis(25));
    }
}

pub fn review_probe_timeout() -> Duration {
    #[cfg(test)]
    {
        Duration::from_secs(5)
    }
    #[cfg(not(test))]
    {
        Duration::from_secs(300)
    }
}

fn plain_text_review_consumption_timeout(request: &ReviewRequest) -> Duration {
    #[cfg(test)]
    {
        let _ = request;
        review_probe_timeout()
    }
    #[cfg(not(test))]
    {
        Duration::from_secs(managed_wake_runtime_limit(Some(request.deadline_secs)).effective_secs)
    }
}

/// Contract probe used by the immutable seeded test. Production-path tests in
/// this module additionally prove the ordering through observable ledger state.
pub const fn review_append_precedes_probe() -> bool {
    true
}

/// A timed-out review probe retains the sentinel for durable diagnosis.
pub const fn review_probe_timeout_deletes_sentinel() -> bool {
    false
}

#[derive(Debug, Clone, PartialEq, Eq)]
/// One schema-3 generic review request bound to a task attempt and harness.
pub struct ReviewRequest {
    /// Reviewed task identity.
    pub task_id: String,
    /// Exact current attempt identity.
    pub attempt_id: String,
    /// Fixed generic role; production accepts only `review`.
    pub role: String,
    /// Harness alias selected for this action.
    pub agent: String,
    /// Explicit deadline or caller-derived workload fallback in seconds;
    /// `deadline_is_explicit` controls action-config precedence before spawn.
    pub deadline_secs: u64,
    /// Whether the caller explicitly chose this deadline. Otherwise it is the
    /// workload fallback and action-local configuration takes precedence.
    pub deadline_is_explicit: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ReviewFallbackContext {
    from_agent: String,
    source_wake_id: String,
    terminal_event_id: String,
    reviewed_head: String,
}

#[derive(Debug, Clone)]
/// Validated durable `ReviewRequested` event ready for atomic publication.
pub struct ReviewRequestEvent(orch_core::EventRecord);

impl std::ops::Deref for ReviewRequestEvent {
    type Target = orch_core::EventRecord;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl ReviewRequestEvent {
    /// Serialize the exact event as one JSONL record without the trailing LF.
    pub fn to_jsonl(&self) -> String {
        serde_json::to_string(&self.0).expect("review request event serializes")
    }

    fn into_record(self) -> orch_core::EventRecord {
        self.0
    }
}

fn validate_review_request(request: &ReviewRequest) -> Result<()> {
    validate_agent_component(&request.agent)?;
    if request.task_id.trim().is_empty()
        || request.attempt_id.trim().is_empty()
        || request
            .task_id
            .bytes()
            .chain(request.attempt_id.bytes())
            .any(|byte| byte.is_ascii_control())
    {
        bail!("review request 的 taskId/attemptId 必须非空且不含控制字符");
    }
    if request.role != "review" {
        bail!("schema 3 review request role 必须精确为 review");
    }
    Ok(())
}

/// Build the durable fact appended by the real wake entry after provider spawn.
///
/// The event timestamp and payload `requestedAt` are identical, so replay never
/// needs to guess the request's start time from a later monitor tick.
pub fn review_request_event(request: &ReviewRequest) -> Result<ReviewRequestEvent> {
    validate_review_request(request)?;
    let mut event = ledger::event(
        "ReviewRequested",
        "runtime:orch",
        Some(&request.task_id),
        None,
        serde_json::json!({
            "attemptId": request.attempt_id,
            "role": request.role,
            "agent": request.agent,
            "deadlineSecs": request.deadline_secs,
        }),
    );
    event
        .payload
        .as_mut()
        .expect("review request payload is always present")["requestedAt"] =
        serde_json::json!(event.ts);
    Ok(ReviewRequestEvent(event))
}

/// Recover the one immutable collect head for an exact attempt before `end`.
/// Conflicting or missing `ReportCollectCompleted.branchSha` facts are rejected
/// so live selection and historical replay bind the same candidate.
pub(crate) fn immutable_collect_head_before(
    events: &[orch_core::EventRecord],
    end: usize,
    round: &str,
    task_id: &str,
    attempt_id: &str,
) -> Result<String> {
    let mut recovered: Option<String> = None;
    for event in &events[..end] {
        if event.kind != "ReportCollectCompleted"
            || event.actor != "runtime:orch"
            || event.round.as_deref() != Some(round)
            || event.task_id.as_deref() != Some(task_id)
            || payload_string(event, "attemptId") != Some(attempt_id)
        {
            continue;
        }
        let head = payload_string(event, "branchSha")
            .filter(|value| is_full_review_head(value))
            .context("matching ReportCollectCompleted 缺完整 40 位 branchSha")?;
        if recovered.as_deref().is_some_and(|current| current != head) {
            bail!("matching ReportCollectCompleted 含冲突 branchSha");
        }
        recovered = Some(head.to_string());
    }
    recovered.with_context(|| {
        format!(
            "review authority 缺可恢复的 immutable collect fact: task={task_id} attempt={attempt_id}"
        )
    })
}

pub(crate) fn review_expectation_from_request_event(
    events: &[orch_core::EventRecord],
    round: &str,
    request: &orch_core::EventRecord,
) -> Result<crate::verify::ReviewContractExpectation> {
    if request.kind != "ReviewRequested"
        || request.actor != "runtime:orch"
        || request.round.as_deref() != Some(round)
    {
        bail!("review artifact 必须绑定 formal runtime ReviewRequested");
    }
    let positions = events
        .iter()
        .enumerate()
        .filter(|(_, candidate)| candidate.event_id == request.event_id)
        .map(|(position, _)| position)
        .collect::<Vec<_>>();
    if positions.len() != 1 {
        bail!("formal ReviewRequested eventId 在账本中不唯一");
    }
    let task_id = request
        .task_id
        .as_deref()
        .filter(|value| !value.is_empty())
        .context("formal ReviewRequested 缺 taskId")?;
    let required = |field: &str| {
        payload_string(request, field)
            .filter(|value| !value.is_empty())
            .with_context(|| format!("formal ReviewRequested 缺 payload.{field}"))
    };
    let attempt_id = required("attemptId")?;
    let role = required("role")?;
    let reviewer = required("agent")?;
    let collect_head =
        immutable_collect_head_before(events, positions[0], round, task_id, attempt_id)?;
    if let Some(value) = request
        .payload
        .as_ref()
        .and_then(|payload| payload.get("reviewedHead"))
    {
        let requested_head = value
            .as_str()
            .filter(|head| is_full_review_head(head))
            .context("ReviewRequested.reviewedHead 必须是完整 40 位小写 hex")?;
        if requested_head != collect_head {
            bail!("ReviewRequested.reviewedHead 与 immutable collect head 不匹配");
        }
    }
    crate::verify::ReviewContractExpectation::exact(
        task_id,
        round,
        attempt_id,
        role,
        reviewer,
        collect_head,
    )
}

fn new_review_expectation(
    root: &Path,
    round: &str,
    events: &[orch_core::EventRecord],
    request: &ReviewRequest,
    fallback: Option<&ReviewFallbackContext>,
    panel_authorization: Option<&PanelRouteAuthorizationV1>,
) -> Result<crate::verify::ReviewContractExpectation> {
    let active = crate::plan::require_active_round_ir(root, round, events)?;
    let task = active
        .candidate
        .tasks
        .iter()
        .find(|task| task.id == request.task_id)
        .with_context(|| format!("review task {} 不在 signed ROUND-IR", request.task_id))?;
    let role = crate::sites::SiteRole::parse(&request.role).map_err(anyhow::Error::msg)?;
    if active.candidate.schema_version == crate::plan::ACTORLESS_ROUND_IR_SCHEMA_VERSION {
        bail!("schema 3 review 必须走 unified channel，不得进入 legacy review renderer");
    }
    let signed_formal = task.required_reviews.iter().any(|required| {
        required.role == request.role
            && (required.agent == request.agent
                || fallback.is_some_and(|context| {
                    required.agent == context.from_agent
                        && signed_review_fallback(task, &request.role)
                            == Some(request.agent.as_str())
                }))
    });
    let signed_nongate = task.review_quorum.is_none()
        || task
            .nongate_seats
            .iter()
            .any(|seat| seat.agent == request.agent);
    let signed_panel = panel_authorization.is_some_and(|authorization| {
        authorization.task_id == request.task_id
            && authorization.route.attempt_id == request.attempt_id
            && authorization.route.role == request.role
            && authorization.route.agent == request.agent
    });
    if panel_authorization.is_some() && !signed_panel {
        bail!("panel route lexical authorization 与 ReviewRequest tuple 漂移");
    }
    if !signed_panel
        && ((role.satisfies_formal_review_slot() && !signed_formal)
            || (role == crate::sites::SiteRole::Nongate && !signed_nongate))
    {
        bail!(
            "review identity 未获 signed ROUND-IR 授权: task={} role={} reviewer={}",
            request.task_id,
            request.role,
            request.agent
        );
    }
    let current = crate::attempt::current_attempt(events, &request.task_id)?
        .with_context(|| format!("review task {} 缺 canonical attempt", request.task_id))?;
    if current.attempt_id != request.attempt_id {
        bail!(
            "review attempt 不是 current canonical attempt: expected={} requested={}",
            current.attempt_id,
            request.attempt_id
        );
    }
    let head = immutable_collect_head_before(
        events,
        events.len(),
        round,
        &request.task_id,
        &request.attempt_id,
    )?;
    if fallback.is_some_and(|context| context.reviewed_head != head) {
        bail!("fallback reviewedHead 与 immutable collect head 不匹配");
    }
    if let Some(authorization) = panel_authorization {
        if authorization.route.reviewed_head != head {
            bail!("panel route reviewedHead 与 immutable collect head 不匹配");
        }
        let resolved = crate::plan::resolve_attempt_runtime_policy(
            root,
            round,
            events,
            &request.task_id,
            &request.attempt_id,
            "review-pool-v1",
        )?;
        if resolved.state != crate::plan::RuntimePolicyStateV1::Active
            || resolved.policy_base_sha != authorization.route.policy_base_sha
        {
            bail!("panel route policy-as-of 未激活或 base 漂移");
        }
    }
    if let Some(authorization) = panel_authorization {
        crate::verify::ReviewContractExpectation::panel_exact(
            &request.task_id,
            round,
            &request.attempt_id,
            &request.role,
            &request.agent,
            head,
            authorization.route.seat_id.clone(),
            authorization.route.generation,
            authorization.route.wake_id.clone(),
            authorization.route.policy_base_sha.clone(),
        )
    } else {
        crate::verify::ReviewContractExpectation::exact(
            &request.task_id,
            round,
            &request.attempt_id,
            &request.role,
            &request.agent,
            head,
        )
    }
}

fn signed_review_fallback<'a>(task: &'a crate::plan::IrTask, role: &str) -> Option<&'a str> {
    task.review_fallbacks
        .iter()
        .find(|fallback| fallback.role == role)
        .map(|fallback| fallback.fallback_agent.as_str())
}

fn fallback_artifact_absent(
    root: &Path,
    round: &str,
    expectation: &crate::verify::ReviewContractExpectation,
) -> Result<()> {
    let canonical_rel = expectation.artifact_relpath();
    let inbox_rel = review_inbox_relpath(
        round,
        expectation.attempt_id(),
        expectation.role(),
        expectation.reviewer(),
    )?;
    for (rel, label) in [
        (canonical_rel, "verdict-bound canonical review"),
        (inbox_rel, "staged review inbox artifact"),
    ] {
        let Some(bytes) =
            crate::verify::optional_review_artifact_bytes(root, &root.join(&rel), label)?
        else {
            continue;
        };
        let checked = crate::verify::check_review_artifact_contract(&bytes, expectation)
            .with_context(|| format!("fallback artifact-first check failed: {rel}"))?;
        let Some(checked) = checked else {
            bail!("fallback source artifact is partial and must be reconciled manually: {rel}");
        };
        if checked.substantive_body_len() == 0 {
            bail!("fallback source artifact has no substantive body: {rel}");
        }
        bail!("fallback forbidden while a valid source artifact awaits reconciliation: {rel}");
    }
    Ok(())
}

fn validate_review_fallback_transition(
    root: &Path,
    events: &[orch_core::EventRecord],
    round: &str,
    request: &ReviewRequest,
    fallback: &ReviewFallbackContext,
) -> Result<Option<String>> {
    let active = crate::plan::require_active_round_ir(root, round, events)?;
    let task = active
        .candidate
        .tasks
        .iter()
        .find(|task| task.id == request.task_id)
        .with_context(|| format!("fallback task {} 不在 signed ROUND-IR", request.task_id))?;
    let signed = task
        .required_reviews
        .iter()
        .filter(|required| {
            required.role == request.role
                && required.agent == fallback.from_agent
                && signed_review_fallback(task, &request.role) == Some(request.agent.as_str())
        })
        .collect::<Vec<_>>();
    if signed.len() != 1 || request.agent == fallback.from_agent {
        bail!("fallback from/to/role 未精确匹配唯一 signed fallbackAgent");
    }
    let current = crate::attempt::current_attempt(events, &request.task_id)?
        .context("fallback task 缺 current attempt")?;
    if current.attempt_id != request.attempt_id {
        bail!("fallback attempt 不是 current canonical attempt");
    }

    let source_requests = events
        .iter()
        .enumerate()
        .filter(|(_, event)| {
            event.kind == "ReviewRequested"
                && event.actor == "runtime:orch"
                && event.round.as_deref() == Some(round)
                && event.task_id.as_deref() == Some(request.task_id.as_str())
                && payload_string(event, "attemptId") == Some(request.attempt_id.as_str())
                && payload_string(event, "role") == Some(request.role.as_str())
                && payload_string(event, "agent") == Some(fallback.from_agent.as_str())
                && payload_string(event, "wakeId") == Some(fallback.source_wake_id.as_str())
        })
        .collect::<Vec<_>>();
    let [(source_position, source_request)] = source_requests.as_slice() else {
        bail!("fallback source 必须有唯一 runtime ReviewRequested 与 wake binding");
    };
    let source_expectation = review_expectation_from_request_event(events, round, source_request)?;
    if source_expectation.reviewed_head() != fallback.reviewed_head {
        bail!("fallback source reviewedHead 与 signed transition 不一致");
    }
    fallback_artifact_absent(root, round, &source_expectation)?;
    if events.iter().any(|event| {
        event.kind == "ReviewDelivered"
            && event.round.as_deref() == Some(round)
            && event.task_id.as_deref() == Some(request.task_id.as_str())
            && payload_string(event, "attemptId") == Some(request.attempt_id.as_str())
            && payload_string(event, "role") == Some(request.role.as_str())
            && payload_string(event, "agent") == Some(fallback.from_agent.as_str())
            && event
                .payload
                .as_ref()
                .and_then(|payload| payload.get("bodyLen"))
                .and_then(serde_json::Value::as_u64)
                .is_some_and(|len| len > 0)
    }) {
        bail!("fallback source 已有 substantive ReviewDelivered");
    }

    let terminals = events
        .iter()
        .enumerate()
        .filter(|(_, event)| event.event_id == fallback.terminal_event_id)
        .collect::<Vec<_>>();
    let [(terminal_position, terminal)] = terminals.as_slice() else {
        bail!("fallback terminalEventId 必须唯一存在");
    };
    let terminal_payload = terminal
        .payload
        .as_ref()
        .and_then(serde_json::Value::as_object)
        .context("fallback ManagedWakeTerminated payload 缺失")?;
    let outcome = terminal_payload
        .get("outcomeClass")
        .and_then(serde_json::Value::as_str)
        .context("fallback terminal outcomeClass 缺失")?;
    if terminal.kind != "ManagedWakeTerminated"
        || terminal.actor != "runtime:orch"
        || terminal.round.as_deref() != Some(round)
        || terminal.task_id.as_deref() != Some(request.task_id.as_str())
        || *terminal_position <= *source_position
        || payload_string(terminal, "wakeId") != Some(fallback.source_wake_id.as_str())
        || payload_string(terminal, "agent") != Some(fallback.from_agent.as_str())
        || terminal_payload
            .get("managedScopeTerminated")
            .and_then(serde_json::Value::as_bool)
            != Some(true)
        || matches!(outcome, "OperationalError" | "StoppedByAuthenticatedCancel")
    {
        bail!("fallback source terminal fact 未证明可替换的 managed scope");
    }
    if events[*source_position + 1..].iter().any(|event| {
        (event.kind == "VerdictIssued"
            && event.task_id.as_deref() == Some(request.task_id.as_str()))
            || crate::attempt::event_terminates_attempt(event, &request.attempt_id)
    }) {
        bail!("fallback source 之后已有 root verdict 或 attempt terminal");
    }

    let selections = events
        .iter()
        .enumerate()
        .filter(|(_, event)| {
            event.kind == "ReviewFallbackSelected"
                && event.round.as_deref() == Some(round)
                && event.task_id.as_deref() == Some(request.task_id.as_str())
                && payload_string(event, "attemptId") == Some(request.attempt_id.as_str())
                && payload_string(event, "role") == Some(request.role.as_str())
        })
        .collect::<Vec<_>>();
    if selections.len() > 1 {
        bail!("fallback selection 重复，拒绝第三个 reviewer wake");
    }
    let Some((selection_position, selection)) = selections.first().copied() else {
        return Ok(None);
    };
    let target_wake_id = payload_string(selection, "targetWakeId")
        .filter(|value| !value.is_empty())
        .context("ReviewFallbackSelected 缺 targetWakeId")?;
    if selection.actor != "runtime:orch"
        || payload_string(selection, "fromAgent") != Some(fallback.from_agent.as_str())
        || payload_string(selection, "toAgent") != Some(request.agent.as_str())
        || payload_string(selection, "reviewedHead") != Some(fallback.reviewed_head.as_str())
        || payload_string(selection, "sourceWakeId") != Some(fallback.source_wake_id.as_str())
        || payload_string(selection, "terminalEventId") != Some(fallback.terminal_event_id.as_str())
    {
        bail!("existing ReviewFallbackSelected 与 signed exact tuple 漂移");
    }
    let target_wakes = events
        .iter()
        .enumerate()
        .filter(|(_, event)| {
            event.kind == "WakeIssued"
                && payload_string(event, "wakeId") == Some(target_wake_id)
                && payload_string(event, "agent") == Some(request.agent.as_str())
        })
        .collect::<Vec<_>>();
    let target_requests = events
        .iter()
        .enumerate()
        .filter(|(_, event)| {
            event.kind == "ReviewRequested"
                && event.task_id.as_deref() == Some(request.task_id.as_str())
                && payload_string(event, "attemptId") == Some(request.attempt_id.as_str())
                && payload_string(event, "role") == Some(request.role.as_str())
                && payload_string(event, "agent") == Some(request.agent.as_str())
                && payload_string(event, "wakeId") == Some(target_wake_id)
        })
        .collect::<Vec<_>>();
    let ([(wake_position, _)], [(request_position, _)]) =
        (target_wakes.as_slice(), target_requests.as_slice())
    else {
        bail!("ReviewFallbackSelected 缺唯一 target WakeIssued/ReviewRequested");
    };
    if selection_position >= *wake_position || *wake_position >= *request_position {
        bail!("fallback durable facts 顺序不是 selected → wake → requested");
    }
    Ok(Some(target_wake_id.to_string()))
}

fn review_key_from_event(
    event: &orch_core::EventRecord,
) -> Result<crate::generic_review::DeliveredReviewKey> {
    let task_id = event
        .task_id
        .as_ref()
        .filter(|value| !value.trim().is_empty())
        .cloned()
        .with_context(|| format!("{} 缺 taskId", event.kind))?;
    let required = |key: &str| {
        payload_string(event, key)
            .filter(|value| !value.trim().is_empty())
            .map(str::to_string)
            .with_context(|| format!("{} 缺 payload.{key}", event.kind))
    };
    Ok(crate::generic_review::DeliveredReviewKey {
        task_id,
        attempt_id: required("attemptId")?,
        role: required("role")?,
        agent: required("agent")?,
    })
}

/// Validate the exact attempt identity accepted by committed-review reconcile.
/// The textual round-trip rejects aliases such as `A1`, `A00001`, zero, a task
/// prefix mismatch, and every path-like component.
pub fn validate_review_reconcile_attempt(task_id: &str, attempt_id: &str) -> Result<()> {
    crate::card::validate_task_id(task_id)?;
    let prefix = format!("{task_id}-A");
    let digits = attempt_id
        .strip_prefix(&prefix)
        .filter(|digits| !digits.is_empty())
        .with_context(|| {
            format!("attemptId {attempt_id:?} 必须匹配 exact task {task_id:?} 的 canonical attempt")
        })?;
    if !digits.bytes().all(|byte| byte.is_ascii_digit()) {
        bail!("attemptId {attempt_id:?} 必须以 canonical 正整数 ordinal 结尾");
    }
    let ordinal = digits
        .parse::<usize>()
        .with_context(|| format!("attemptId {attempt_id:?} ordinal 超出范围"))?;
    if ordinal == 0 || attempt_id != format!("{task_id}-A{ordinal:04}") {
        bail!("attemptId {attempt_id:?} 不是 {task_id:?} 的 canonical 正整数 attempt");
    }
    Ok(())
}

fn validate_committed_review_key(key: &crate::generic_review::DeliveredReviewKey) -> Result<()> {
    crate::card::validate_task_id(&key.task_id)?;
    validate_review_reconcile_attempt(&key.task_id, &key.attempt_id)?;
    if !matches!(key.role.as_str(), "primary" | "secondary") {
        bail!("ReviewRequested/ReviewDelivered role 非法: {:?}", key.role);
    }
    validate_agent_component(&key.agent)?;
    Ok(())
}

/// Refuse the retired committed formal-review reconciler before any read or write.
pub fn reconcile_committed_review_delivery_slots(
    root: &Path,
    task_id: &str,
    attempt_id: &str,
) -> Result<usize> {
    let _ = (root, task_id, attempt_id);
    bail!("legacy committed review reconciliation 已退役；schema 3 仅允许 generic review deliver")
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ReviewDeliveryOutcome {
    pub path: String,
    pub post_verdict: bool,
    pub appended_events: usize,
}

fn latest_formal_review_request<'a>(
    events: &'a [orch_core::EventRecord],
    round: &str,
    task_id: &str,
    attempt_id: &str,
    role: &str,
    agent: &str,
    allow_superseded: bool,
) -> Result<(
    &'a orch_core::EventRecord,
    crate::verify::ReviewContractExpectation,
)> {
    // Before verdict, promotion is allowed only for the request which still
    // occupies the live (task, role) slot.  After verdict, the command is an
    // audit delivery for one immutable historical attempt, so a successor's
    // request must not make the late reviewer impossible to account.
    let request = if allow_superseded {
        events.iter().rev().find(|event| {
            event.kind == "ReviewRequested"
                && event.round.as_deref() == Some(round)
                && event.task_id.as_deref() == Some(task_id)
                && payload_string(event, "attemptId") == Some(attempt_id)
                && payload_string(event, "role") == Some(role)
                && payload_string(event, "agent") == Some(agent)
        })
    } else {
        events.iter().rev().find(|event| {
            event.kind == "ReviewRequested"
                && event.round.as_deref() == Some(round)
                && event.task_id.as_deref() == Some(task_id)
                && payload_string(event, "role") == Some(role)
        })
    }
    .with_context(|| {
        format!(
            "formal review slot missing: task={task_id} attempt={attempt_id} role={role} agent={agent}"
        )
    })?;
    if request.actor != "runtime:orch"
        || payload_string(request, "attemptId") != Some(attempt_id)
        || payload_string(request, "agent") != Some(agent)
    {
        bail!(
            "latest formal review slot identity mismatch: task={task_id} attempt={attempt_id} role={role} agent={agent}"
        );
    }
    let expectation = review_expectation_from_request_event(events, round, request)?;
    Ok((request, expectation))
}

fn exact_root_verdict_for_review<'a>(
    events: &'a [orch_core::EventRecord],
    round: &str,
    task_id: &str,
    attempt_id: &str,
) -> Result<
    Option<(
        usize,
        &'a orch_core::EventRecord,
        crate::verify::RootVerdictPayload,
    )>,
> {
    let mut matching = Vec::new();
    for (position, event) in events.iter().enumerate().filter(|(_, event)| {
        event.kind == "VerdictIssued"
            && event.actor == "verifier:root"
            && event.round.as_deref() == Some(round)
            && event.task_id.as_deref() == Some(task_id)
    }) {
        let payload: crate::verify::RootVerdictPayload = serde_json::from_value(
            event
                .payload
                .clone()
                .context("root VerdictIssued missing payload")?,
        )
        .context("root VerdictIssued payload malformed during review delivery")?;
        if payload.attempt_id == attempt_id {
            matching.push((position, event, payload));
        }
    }
    match matching.len() {
        0 => Ok(None),
        1 => Ok(matching.pop()),
        count => bail!(
            "review delivery found {count} root verdicts for task={task_id} attempt={attempt_id}"
        ),
    }
}

fn review_bytes_binding(bytes: &[u8]) -> (String, u64) {
    (hex::encode(Sha256::digest(bytes)), bytes.len() as u64)
}

struct ReviewPublishTempGuard(Option<PathBuf>);

impl ReviewPublishTempGuard {
    fn remove_now(&mut self) -> Result<()> {
        let Some(path) = self.0.take() else {
            return Ok(());
        };
        match fs::remove_file(&path) {
            Ok(()) => Ok(()),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(error)
                .with_context(|| format!("remove review publish temp failed: {}", path.display())),
        }
    }
}

impl Drop for ReviewPublishTempGuard {
    fn drop(&mut self) {
        if let Some(path) = self.0.take() {
            let _ = fs::remove_file(path);
        }
    }
}

fn cleanup_review_publish_temps(parent: &Path, final_name: &str) -> Result<()> {
    let prefix = format!(".{final_name}.orch-review-publish-");
    for entry in fs::read_dir(parent)
        .with_context(|| format!("scan review publish temps failed: {}", parent.display()))?
    {
        let entry = entry.context("read review publish temp entry failed")?;
        let name = entry
            .file_name()
            .into_string()
            .map_err(|_| anyhow::anyhow!("review publish temp filename is not UTF-8"))?;
        if !name.starts_with(&prefix) || !name.ends_with(".tmp") {
            continue;
        }
        let metadata =
            fs::symlink_metadata(entry.path()).context("stat review publish temp failed")?;
        if metadata.file_type().is_symlink() || !metadata.file_type().is_file() {
            bail!("reserved review publish temp is not a regular file: {name}");
        }
        fs::remove_file(entry.path())
            .with_context(|| format!("remove stale review publish temp failed: {name}"))?;
    }
    Ok(())
}

fn install_review_no_clobber(root: &Path, rel: &str, bytes: &[u8]) -> Result<()> {
    ensure_review_inbox_parent(root, rel)?;
    let path = root.join(rel);
    let parent = path.parent().context("delivered review lacks parent")?;
    let final_name = path
        .file_name()
        .and_then(|value| value.to_str())
        .context("delivered review filename is not UTF-8")?;
    cleanup_review_publish_temps(parent, final_name)?;

    if let Some(actual) = crate::verify::optional_review_artifact_bytes(
        root,
        &path,
        "existing delivered review artifact",
    )? {
        if actual != bytes {
            bail!("review no-clobber conflict at {rel}");
        }
        return Ok(());
    }

    // Write and sync an invisible-to-consumers temporary inode first.  The
    // hard link is the atomic create-if-absent publication step; unlike a
    // direct write to the final name, a process crash can leave only a
    // runtime-owned temp, never a partially written canonical/late artifact.
    let temp_path = parent.join(format!(
        ".{final_name}.orch-review-publish-{}.tmp",
        fresh_uuid()
    ));
    let mut temp_guard = ReviewPublishTempGuard(Some(temp_path.clone()));
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o644)
        .custom_flags(OPEN_NOFOLLOW)
        .open(&temp_path)
        .with_context(|| format!("create review publish temp failed: {}", temp_path.display()))?;
    file.write_all(bytes)
        .with_context(|| format!("write review publish temp failed: {}", temp_path.display()))?;
    file.sync_all()
        .with_context(|| format!("sync review publish temp failed: {}", temp_path.display()))?;
    let handle_metadata = file
        .metadata()
        .context("stat open review publish temp failed")?;
    let path_metadata =
        fs::symlink_metadata(&temp_path).context("stat review publish temp path failed")?;
    if handle_metadata.dev() != path_metadata.dev()
        || handle_metadata.ino() != path_metadata.ino()
        || path_metadata.file_type().is_symlink()
        || !path_metadata.file_type().is_file()
    {
        bail!("review publish temp changed between create and publication");
    }

    match fs::hard_link(&temp_path, &path) {
        Ok(()) => {
            let published = fs::symlink_metadata(&path)
                .with_context(|| format!("stat published review failed: {}", path.display()))?;
            if published.file_type().is_symlink()
                || !published.file_type().is_file()
                || published.dev() != handle_metadata.dev()
                || published.ino() != handle_metadata.ino()
            {
                bail!("published review does not bind the synced temp inode");
            }
        }
        Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
        Err(error) => {
            return Err(error)
                .with_context(|| format!("publish delivered review failed: {}", path.display()))
        }
    }
    drop(file);
    temp_guard.remove_now()?;
    File::open(parent)?.sync_all()?;

    let actual =
        crate::verify::optional_review_artifact_bytes(root, &path, "delivered review artifact")?
            .context("delivered review disappeared after no-clobber install")?;
    if actual != bytes {
        bail!("review no-clobber conflict at {rel}");
    }
    Ok(())
}

/// Integration-test seam for the production no-clobber publisher.  It is
/// restricted to an `orch/target/test-tmp` child and a canonical round review
/// path, so it cannot mutate a production review or arbitrary repository file.
#[doc(hidden)]
pub fn install_review_no_clobber_for_test(root: &Path, rel: &str, bytes: &[u8]) -> Result<()> {
    let scratch = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .context("orch-host manifest layout missing workspace root")?
        .join("target/test-tmp");
    let canonical_root = fs::canonicalize(root)?;
    let canonical_scratch = fs::canonicalize(&scratch)?;
    if canonical_root == canonical_scratch || !canonical_root.starts_with(&canonical_scratch) {
        bail!("review no-clobber test seam only accepts a test-tmp child root");
    }
    if !rel.starts_with("coordination/rounds/")
        || !rel.contains("/reviews/")
        || !rel.ends_with(".md")
    {
        bail!("review no-clobber test seam path is not canonical");
    }
    install_review_no_clobber(&canonical_root, rel, bytes)
}

fn dsh_legacy_staging_rel_for_lease_v1(
    worktree_rel: &str,
    attempt_id: &str,
    role: &str,
    agent: &str,
    wake_id: &str,
) -> Result<String> {
    let worktree = Path::new(worktree_rel);
    if worktree.is_absolute()
        || !worktree_rel.starts_with(".worktrees/")
        || worktree
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        bail!("DSH legacy lease worktree path 非 canonical");
    }
    for value in [attempt_id, role, agent, wake_id] {
        validate_review_component("DSH legacy spool component", value)
            .map_err(anyhow::Error::msg)?;
    }
    Ok(format!(
        "{worktree_rel}/.cowork-temp/review-spool/{attempt_id}-{role}-{agent}-{wake_id}.md"
    ))
}

/// Test seam for the exact lease-to-wake DSH legacy spool relation.  It is
/// pure and performs no filesystem mutation; production rederives the same
/// path before validating and promoting artifact bytes.
#[doc(hidden)]
pub fn validate_dsh_legacy_spool_path_for_test(
    worktree_rel: &str,
    attempt_id: &str,
    role: &str,
    agent: &str,
    wake_id: &str,
    actual_rel: &str,
) -> Result<()> {
    let expected =
        dsh_legacy_staging_rel_for_lease_v1(worktree_rel, attempt_id, role, agent, wake_id)?;
    if expected != actual_rel {
        bail!("DSH legacy spool path is not bound to the exact lease/wake tuple");
    }
    Ok(())
}

/// Promote one completed DSH legacy/Quorum spool artifact under the ledger
/// lock.  The source path is derived from the exact lease and wake, the review
/// contract is revalidated before a no-clobber canonical install, and a valid
/// artifact remains independent of a failed provider terminal.
#[derive(Debug, Clone)]
struct LateReviewFile {
    ordinal: u64,
    rel: String,
    sha256: String,
    byte_len: u64,
    body_len: u64,
}

fn late_review_files(
    root: &Path,
    canonical_rel: &str,
    expectation: &crate::verify::ReviewContractExpectation,
) -> Result<Vec<LateReviewFile>> {
    let canonical = root.join(canonical_rel);
    let parent = canonical
        .parent()
        .context("canonical review lacks parent")?;
    let stem = canonical
        .file_stem()
        .and_then(|value| value.to_str())
        .context("canonical review stem is not UTF-8")?;
    let prefix = format!("{stem}-late-");
    let mut found = Vec::new();
    match fs::symlink_metadata(parent) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
            bail!("review destination parent must be a real directory")
        }
        Ok(_) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(found),
        Err(error) => return Err(error).context("stat review destination parent failed"),
    }
    for entry in fs::read_dir(parent).context("scan late review directory failed")? {
        let entry = entry.context("read late review directory entry failed")?;
        let name = entry
            .file_name()
            .into_string()
            .map_err(|_| anyhow::anyhow!("late review filename is not UTF-8"))?;
        if !name.starts_with(&prefix) {
            continue;
        }
        let suffix = name
            .strip_prefix(&prefix)
            .and_then(|value| value.strip_suffix(".md"))
            .context("late review filename has malformed suffix")?;
        let ordinal = suffix
            .parse::<u64>()
            .context("late review ordinal is not a positive integer")?;
        if ordinal == 0 || suffix != ordinal.to_string() {
            bail!("late review ordinal is not canonical: {name}");
        }
        let rel = Path::new(canonical_rel)
            .parent()
            .context("canonical review relpath lacks parent")?
            .join(&name)
            .to_str()
            .context("late review relpath is not UTF-8")?
            .to_string();
        let bytes = crate::verify::optional_review_artifact_bytes(
            root,
            &entry.path(),
            "late review artifact",
        )?
        .context("late review disappeared during scan")?;
        let checked = crate::verify::check_review_artifact_contract(&bytes, expectation)
            .with_context(|| format!("late review contract failed: {rel}"))?
            .with_context(|| format!("late review is incomplete: {rel}"))?;
        let body_len = checked.substantive_body_len() as u64;
        if body_len == 0 {
            bail!("late review lacks substantive body: {rel}");
        }
        let (sha256, byte_len) = review_bytes_binding(&bytes);
        found.push(LateReviewFile {
            ordinal,
            rel,
            sha256,
            byte_len,
            body_len,
        });
    }
    found.sort_by_key(|file| file.ordinal);
    if found
        .windows(2)
        .any(|pair| pair[0].ordinal == pair[1].ordinal)
    {
        bail!("duplicate late review ordinal detected");
    }
    Ok(found)
}

fn late_review_event_matches(
    event: &orch_core::EventRecord,
    kind: &str,
    round: &str,
    task_id: &str,
    attempt_id: &str,
    role: &str,
    agent: &str,
    path: &str,
    sha256: &str,
    bytes: u64,
    body_len: u64,
    verdict_event_id: &str,
) -> bool {
    let expected_keys: &[&str] = if kind == "EscalationRaised" {
        &[
            "attemptId",
            "role",
            "agent",
            "path",
            "sha256",
            "bytes",
            "bodyLen",
            "verdictEventId",
            "stage",
        ]
    } else {
        &[
            "attemptId",
            "role",
            "agent",
            "path",
            "sha256",
            "bytes",
            "bodyLen",
            "verdictEventId",
        ]
    };
    let payload_exact = event.payload.as_ref().is_some_and(|payload| {
        payload.as_object().is_some_and(|object| {
            object.len() == expected_keys.len()
                && expected_keys.iter().all(|key| object.contains_key(*key))
        })
    });
    event.kind == kind
        && event.actor == "runtime:orch"
        && event.round.as_deref() == Some(round)
        && event.task_id.as_deref() == Some(task_id)
        && payload_string(event, "attemptId") == Some(attempt_id)
        && payload_string(event, "role") == Some(role)
        && payload_string(event, "agent") == Some(agent)
        && payload_string(event, "path") == Some(path)
        && payload_string(event, "sha256") == Some(sha256)
        && event
            .payload
            .as_ref()
            .and_then(|payload| payload.get("bytes"))
            .and_then(serde_json::Value::as_u64)
            == Some(bytes)
        && event
            .payload
            .as_ref()
            .and_then(|payload| payload.get("bodyLen"))
            .and_then(serde_json::Value::as_u64)
            == Some(body_len)
        && payload_string(event, "verdictEventId") == Some(verdict_event_id)
        && (kind != "EscalationRaised"
            || payload_string(event, "stage") == Some("late-review-delivery"))
        && payload_exact
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub(crate) struct ValidatedLateReviewDeliveries {
    pub(crate) paths: BTreeSet<String>,
    pub(crate) event_ids: BTreeSet<String>,
}

/// Recompute every post-verdict review delivery from its immutable root
/// verdict, canonical binding, exact adjacent event pair, and current late
/// artifact bytes.  Merge/seal use the returned identities as a narrow
/// allow-list; event kind or pathname alone never authorizes a dirty file or
/// an expected-main ledger suffix.
pub(crate) fn validate_late_review_deliveries(
    root: &Path,
    round: &str,
    events: &[orch_core::EventRecord],
) -> Result<ValidatedLateReviewDeliveries> {
    let mut validated = ValidatedLateReviewDeliveries::default();
    let mut next_ordinal = BTreeMap::<(String, String, String, String), u64>::new();
    let mut position = 0usize;

    while position < events.len() {
        let delivered = &events[position];
        let is_late_delivery = delivered.kind == "ReviewDelivered"
            && delivered
                .payload
                .as_ref()
                .and_then(|payload| payload.get("verdictEventId"))
                .is_some();
        let is_late_escalation = delivered.kind == "EscalationRaised"
            && payload_string(delivered, "stage") == Some("late-review-delivery");
        if !is_late_delivery && !is_late_escalation {
            position += 1;
            continue;
        }
        if !is_late_delivery {
            bail!("late review escalation is not immediately preceded by its ReviewDelivered pair");
        }
        let escalation = events
            .get(position + 1)
            .context("late ReviewDelivered lacks adjacent EscalationRaised")?;
        let task_id = delivered
            .task_id
            .as_deref()
            .filter(|value| !value.is_empty())
            .context("late ReviewDelivered lacks taskId")?;
        let required = |field: &str| {
            payload_string(delivered, field)
                .filter(|value| !value.is_empty())
                .with_context(|| format!("late ReviewDelivered lacks payload.{field}"))
        };
        let attempt_id = required("attemptId")?;
        let role = required("role")?;
        let agent = required("agent")?;
        let path = required("path")?;
        let sha256 = required("sha256")?;
        let verdict_event_id = required("verdictEventId")?;
        let bytes = delivered
            .payload
            .as_ref()
            .and_then(|payload| payload.get("bytes"))
            .and_then(serde_json::Value::as_u64)
            .filter(|value| *value > 0)
            .context("late ReviewDelivered lacks positive payload.bytes")?;
        let body_len = delivered
            .payload
            .as_ref()
            .and_then(|payload| payload.get("bodyLen"))
            .and_then(serde_json::Value::as_u64)
            .filter(|value| *value > 0)
            .context("late ReviewDelivered lacks positive payload.bodyLen")?;
        if delivered.actor != "runtime:orch" || delivered.round.as_deref() != Some(round) {
            bail!("late ReviewDelivered actor/round mismatch");
        }

        let (verdict_position, verdict, verdict_payload) =
            exact_root_verdict_for_review(events, round, task_id, attempt_id)?
                .context("late ReviewDelivered lacks its unique root verdict")?;
        if verdict_position >= position || verdict.event_id != verdict_event_id {
            bail!("late ReviewDelivered does not follow and bind its root verdict");
        }
        let (_, expectation) = latest_formal_review_request(
            &events[..verdict_position],
            round,
            task_id,
            attempt_id,
            role,
            agent,
            true,
        )?;
        if expectation.reviewed_head() != verdict_payload.head_sha {
            bail!("late review request head does not bind its root verdict");
        }
        let canonical_rel = expectation.artifact_relpath();
        let bindings = verdict_payload
            .reviews
            .iter()
            .filter(|binding| binding.role == role && binding.reviewer == agent)
            .collect::<Vec<_>>();
        let [binding] = bindings.as_slice() else {
            bail!(
                "late review root verdict must bind exactly one canonical review for role={role} reviewer={agent}"
            );
        };
        if binding.path != canonical_rel {
            bail!("late review canonical root-verdict path drifted");
        }
        let canonical_bytes = crate::verify::optional_review_artifact_bytes(
            root,
            &root.join(&canonical_rel),
            "late review canonical binding",
        )?
        .context("late review canonical binding is missing")?;
        let canonical_checked =
            crate::verify::check_review_artifact_contract(&canonical_bytes, &expectation)?
                .context("late review canonical binding is incomplete")?;
        let (canonical_sha, canonical_len) = review_bytes_binding(&canonical_bytes);
        if canonical_sha != binding.sha256
            || canonical_len != binding.bytes
            || canonical_checked.verdict() != binding.verdict
        {
            bail!("late review canonical binding bytes/verdict drifted");
        }

        let late_prefix = format!(
            "{}-late-",
            canonical_rel
                .strip_suffix(".md")
                .context("late review canonical path lacks .md suffix")?
        );
        let ordinal_text = path
            .strip_prefix(&late_prefix)
            .and_then(|suffix| suffix.strip_suffix(".md"))
            .context("late review path escaped its canonical delivery family")?;
        let ordinal = ordinal_text
            .parse::<u64>()
            .context("late review path ordinal is not an integer")?;
        if ordinal == 0 || ordinal_text != ordinal.to_string() {
            bail!("late review path ordinal is not canonical");
        }
        let family = (
            task_id.to_string(),
            attempt_id.to_string(),
            role.to_string(),
            agent.to_string(),
        );
        let expected = next_ordinal.entry(family).or_insert(1);
        if ordinal != *expected {
            bail!(
                "late review durable ordinal is not monotonic: expected={} actual={ordinal}",
                *expected
            );
        }
        *expected = expected
            .checked_add(1)
            .context("late review durable ordinal overflow")?;

        let files = late_review_files(root, &canonical_rel, &expectation)?;
        let file = files
            .iter()
            .find(|candidate| candidate.ordinal == ordinal && candidate.rel == path)
            .context("late review durable pair names a missing or malformed artifact")?;
        if file.sha256 != sha256 || file.byte_len != bytes || file.body_len != body_len {
            bail!("late review durable pair does not bind current artifact bytes");
        }
        if !late_review_event_matches(
            delivered,
            "ReviewDelivered",
            round,
            task_id,
            attempt_id,
            role,
            agent,
            path,
            sha256,
            bytes,
            body_len,
            verdict_event_id,
        ) || !late_review_event_matches(
            escalation,
            "EscalationRaised",
            round,
            task_id,
            attempt_id,
            role,
            agent,
            path,
            sha256,
            bytes,
            body_len,
            verdict_event_id,
        ) {
            bail!("late review durable pair is non-adjacent or payload-drifted");
        }
        if !validated.event_ids.insert(delivered.event_id.clone())
            || !validated.event_ids.insert(escalation.event_id.clone())
        {
            bail!("late review durable pair reuses an eventId");
        }
        if !validated.paths.insert(path.to_string()) {
            bail!("late review durable pair duplicates a path");
        }
        position += 2;
    }
    Ok(validated)
}

