fn channel_review_expectation(
    root: &Path,
    round: &str,
    events: &[orch_core::EventRecord],
    request: &ReviewRequest,
) -> Result<crate::verify::ReviewContractExpectation> {
    validate_review_request(request)?;
    if request.role != "review" || request.agent == "local" {
        bail!("schema 3 channel review 要求 role=review 且 harness != local");
    }
    let active = crate::plan::require_active_round_ir(root, round, events)?;
    if active.candidate.schema_version != crate::plan::ACTORLESS_ROUND_IR_SCHEMA_VERSION
        || !active
            .candidate
            .tasks
            .iter()
            .any(|task| task.id == request.task_id)
    {
        bail!("schema 3 channel review task 不在 actorless active IR");
    }
    let current = crate::attempt::current_attempt(events, &request.task_id)?
        .with_context(|| format!("review task {} 缺 canonical attempt", request.task_id))?;
    if current.attempt_id != request.attempt_id {
        bail!(
            "review attempt 不是 current canonical attempt: expected={} requested={}",
            current.attempt_id,
            request.attempt_id
        );
    }
    if events.iter().any(|event| {
        event.kind == "VerdictIssued"
            && event.task_id.as_deref() == Some(request.task_id.as_str())
            && payload_string(event, "attemptId") == Some(request.attempt_id.as_str())
    }) {
        bail!("root verdict 后不得发起新的 schema 3 review");
    }
    if events.iter().any(|event| {
        event.kind == "ReviewRequested"
            && event.task_id.as_deref() == Some(request.task_id.as_str())
            && payload_string(event, "attemptId") == Some(request.attempt_id.as_str())
            && payload_string(event, "role") == Some("review")
            && payload_string(event, "agent") == Some(request.agent.as_str())
    }) {
        bail!("同 attempt 的 schema 3 harness review 已存在");
    }
    let head = immutable_collect_head_before(
        events,
        events.len(),
        round,
        &request.task_id,
        &request.attempt_id,
    )?;
    crate::verify::ReviewContractExpectation::exact(
        &request.task_id,
        round,
        &request.attempt_id,
        "review",
        &request.agent,
        head,
    )
}

fn channel_review_prompt(
    operator_message: &str,
    expectation: &crate::verify::ReviewContractExpectation,
    worktree: &Path,
    output: &Path,
    wake_id: &str,
) -> Result<String> {
    let frontmatter = render_review_frontmatter_template(expectation)?.replacen(
        "\n---\n",
        &format!("\nwakeId: {wake_id}\n---\n"),
        1,
    );
    Ok(format!(
        "{operator_message}\n\n\
         ORCH_SCHEMA3_GENERIC_REVIEW_V1\n\
         REVIEW_WORKTREE={}\n\
         FULL_HEAD={}\n\
         REVIEW_OUTPUT={}\n\n\
         Review only the fixed HEAD in REVIEW_WORKTREE. Verify the task card, REPORT, diff, tests, and required evidence. \
         Do not edit the reviewed worktree. Write one substantive UTF-8 Markdown answer to REVIEW_OUTPUT using exactly this frontmatter, followed by findings and evidence:\n\n{}\n",
        worktree.display(),
        expectation.reviewed_head(),
        output.display(),
        frontmatter,
    ))
}

/// Start one schema-3 implementation through a harness alias while retaining
/// `local` as the actorless task lifecycle owner.
pub fn run_channel_execute_v3(root: &Path, task: &str, alias: &str) -> Result<WakeRunOutcome> {
    let round = current_round(root)?;
    let events = read_round_ledger_events(root, &round)?;
    let active = crate::plan::require_active_round_ir(root, &round, &events)?;
    if active.candidate.schema_version != crate::plan::ACTORLESS_ROUND_IR_SCHEMA_VERSION {
        bail!("harness execute 只允许 schema 3 active round");
    }
    let dispatch = crate::attempt::resolve_current_dispatch(&events, task, &round)?;
    let attempt_id = dispatch
        .attempt_id
        .as_deref()
        .context("harness execute 缺 attemptId")?;
    let existing = events
        .iter()
        .filter(|event| {
            event.kind == "WakeIssued"
                && event.task_id.as_deref() == Some(task)
                && payload_string(event, "attemptId") == Some(attempt_id)
                && payload_string(event, "harness") == Some(alias)
                && payload_string(event, "action") == Some("execute")
        })
        .collect::<Vec<_>>();
    match existing.as_slice() {
        [event] => {
            let wake_id = payload_string(event, "wakeId")
                .filter(|value| !value.is_empty())
                .context("existing harness execute WakeIssued 缺 wakeId")?;
            return Ok(WakeRunOutcome::Idempotent {
                wake_id: wake_id.to_string(),
            });
        }
        [] => {}
        _ => bail!("harness execute 存在重复 WakeIssued"),
    }
    let go_rel = dispatch.go_path.context("harness execute 缺 GO path")?;
    let relative = Path::new(&go_rel);
    if relative.is_absolute()
        || relative
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
        || !go_rel.starts_with(&format!("coordination/rounds/{round}/dispatch/local/"))
    {
        bail!("harness execute GO path 非 canonical local dispatch artifact");
    }
    let text = fs::read_to_string(root.join(relative))
        .with_context(|| format!("读取 harness execute GO 失败: {go_rel}"))?;
    let resolved = ResolvedMessage {
        bytes: text.len(),
        text,
        source: MessageSource::File,
    };
    crate::close::with_protocol_effect(root, "schema 3 harness execute", || {
        run_channel_wake_v3(root, alias, resolved, None, true, Some(task))
    })
}

// Schema 3 has no task-authored wallMinutes. Both direct one-shot forms use
// the same bounded channel default until an action-local override is supplied.

fn run_channel_wake_v3(
    root: &Path,
    alias: &str,
    resolved: ResolvedMessage,
    mut review: Option<ReviewRequest>,
    _require_active: bool,
    execute_task: Option<&str>,
) -> Result<WakeRunOutcome> {
    with_wake_identity_lock(root, alias, || {
        let round = current_round(root)?;
        let wake_id = fresh_managed_wake_id();
        let events = read_round_ledger_events(root, &round)?;
        let active = crate::plan::require_active_round_ir(root, &round, &events)?;
        if active.candidate.schema_version != crate::plan::ACTORLESS_ROUND_IR_SCHEMA_VERSION {
            bail!("unified channel wake 只允许 schema 3 active round");
        }
        if review.is_some() && execute_task.is_some() {
            bail!("unified channel action 不能同时是 execute 与 review");
        }
        let canonical_root = fs::canonicalize(root)?;

        // Capture once before provisioning a review site. Resolve from the
        // same snapshot again during prepare; no action rereads the file.
        let config = crate::harness_config::load_harness_config_snapshot(root)?;
        let limit_action = if execute_task.is_some() {
            crate::harness_config::HarnessAction::Execute
        } else if review.is_some() {
            crate::harness_config::HarnessAction::Review
        } else {
            crate::harness_config::HarnessAction::Consult
        };
        let selected = config.resolve(alias, limit_action)?;
        if let Some(request) = review.as_ref() {
            validate_review_request(request)?;
        }
        let explicit = review
            .as_ref()
            .filter(|request| request.deadline_is_explicit)
            .map(|request| request.deadline_secs);
        let workload = review
            .as_ref()
            .map(|request| request.deadline_secs)
            .unwrap_or(CHANNEL_ONE_SHOT_DEFAULT_SECS);
        let deadline_secs = selected.limits().deadline_seconds(
            explicit,
            workload,
            MANAGED_WAKE_MAX_RUNTIME_SECS,
        )?;
        if let Some(request) = review.as_mut() {
            request.deadline_secs = deadline_secs;
        }

        let mut provisioned = None;
        macro_rules! channel_pre_spawn_try {
            ($result:expr) => {
                match $result {
                    Ok(value) => value,
                    Err(error) => {
                        let error: anyhow::Error = error.into();
                        if let (Some(site), Some(request)) = (provisioned.as_ref(), review.as_ref())
                        {
                            return reject_and_retire_pre_spawn_review_site(
                                root, &round, &wake_id, request, site, error,
                            );
                        }
                        return Err(error);
                    }
                }
            };
        }
        let (
            action,
            task_id,
            attempt_id,
            target_worktree,
            target_head,
            review_output,
            prompt,
            attachments,
        ) = if let Some(task) = execute_task {
            let _task_contract = active
                .candidate
                .tasks
                .iter()
                .find(|candidate| candidate.id == task)
                .with_context(|| format!("execute task {task} 不在 active IR"))?;
            let dispatch = crate::attempt::resolve_current_dispatch(&events, task, &round)?;
            if dispatch.agent.as_deref() != Some("local") {
                bail!("schema 3 harness execute 的 lifecycle owner 必须保持 local");
            }
            let attempt = dispatch
                .attempt_id
                .clone()
                .context("harness execute DispatchIssued 缺 attemptId")?;
            let base = dispatch
                .base_sha
                .clone()
                .context("harness execute DispatchIssued 缺 baseSha")?;
            let worktree = fs::canonicalize(root.join(format!(".worktrees/{task}")))?;
            validate_review_site_repository(root, &worktree)?;
            let actual_head = crate::gitx::rev_parse(&worktree, "HEAD^{commit}")?;
            if actual_head != base {
                bail!("harness execute worktree HEAD 未固定到 DispatchIssued.baseSha");
            }
            let go_rel = dispatch
                .go_path
                .clone()
                .context("harness execute DispatchIssued 缺 goPath")?;
            let go_path = root.join(&go_rel);
            let card_path = root.join(format!("coordination/rounds/{round}/tasks/{task}.md"));
            let attachment_paths = [card_path.as_path(), go_path.as_path()];
            let attachments = crate::channel::capture_attachment_manifest_v1(&attachment_paths)?;
            (
                crate::channel::InvocationAction::Execute,
                task.to_string(),
                attempt,
                worktree,
                base,
                None,
                resolved.text.clone(),
                attachments,
            )
        } else if let Some(request) = review.as_ref() {
            if request.agent != alias {
                bail!("review request harness 与 wake alias 不一致");
            }
            crate::generic_review::validate_generic_review_admission_v1(
                &events,
                &round,
                &request.task_id,
                &request.attempt_id,
                alias,
                &wake_id,
            )
            .map_err(anyhow::Error::msg)?;
            let expectation = channel_review_expectation(root, &round, &events, request)?;
            let site = provision_review_site(root, &round, &wake_id, request, &expectation)?;
            provisioned = Some(site);
            let worktree = channel_pre_spawn_try!(fs::canonicalize(
                &provisioned
                    .as_ref()
                    .expect("review site saved immediately after lease")
                    .site
                    .worktree
            ));
            let output_rel = channel_pre_spawn_try!(review_inbox_relpath(
                &round,
                &request.attempt_id,
                "review",
                alias,
            ));
            channel_pre_spawn_try!(ensure_review_inbox_parent(root, &output_rel));
            let output = root.join(&output_rel);
            let prompt = channel_pre_spawn_try!(channel_review_prompt(
                &resolved.text,
                &expectation,
                &worktree,
                &output,
                &wake_id,
            ));
            let card_path = worktree.join(format!(
                "coordination/rounds/{round}/tasks/{}.md",
                request.task_id
            ));
            let report_path = worktree.join(format!(
                "coordination/rounds/{round}/reports/{}-REPORT.md",
                request.task_id
            ));
            let attachment_paths = [card_path.as_path(), report_path.as_path()];
            let attachments = channel_pre_spawn_try!(
                crate::channel::capture_attachment_manifest_v1(&attachment_paths)
            );
            (
                crate::channel::InvocationAction::Review,
                request.task_id.clone(),
                request.attempt_id.clone(),
                worktree,
                expectation.reviewed_head().to_string(),
                Some(output),
                prompt,
                attachments,
            )
        } else {
            let head = crate::gitx::rev_parse(&canonical_root, "HEAD^{commit}")?;
            (
                crate::channel::InvocationAction::Consult,
                "MANUAL".to_string(),
                "MANUAL-A0000".to_string(),
                canonical_root.clone(),
                head,
                None,
                resolved.text.clone(),
                crate::channel::capture_attachment_manifest_v1(&[])?,
            )
        };

        let prepared = channel_pre_spawn_try!(crate::channel::prepare_invocation(
            &config,
            crate::channel::InvocationRequest {
                alias: alias.to_string(),
                action,
                prompt,
                project_root: canonical_root.clone(),
                target_worktree,
                target_head,
                attachments,
            },
        ));
        let context = crate::channel::InvocationContextV1 {
            action_id: wake_id.clone(),
            wake_id: wake_id.clone(),
            round: round.clone(),
            task_id: task_id.clone(),
            attempt_id: attempt_id.clone(),
            review_output: review_output.clone(),
            orch_executable: channel_pre_spawn_try!(orch_binary_for_envelope(root)),
            deadline_secs,
        };
        let rendered =
            channel_pre_spawn_try!(crate::channel::render_invocation_v1(prepared, context)
                .and_then(crate::channel::preflight_invocation_v1))
            .into_rendered();
        let log_dir = root.join("coordination/runtime/logs");
        channel_pre_spawn_try!(
            fs::create_dir_all(&log_dir).context("创建 schema 3 channel wake log directory 失败")
        );
        let log_path = crate::activity::wake_log_path(root, alias);
        channel_pre_spawn_try!(File::options()
            .create_new(true)
            .write(true)
            .open(&log_path)
            .with_context(|| format!("创建 channel wake log 失败: {}", log_path.display())));
        let binding = ChannelSupervisorBindingV1 {
            standalone: false,
            requested_tuple: Some(rendered.prepared().requested().tuple.clone()),
            effective_tuple: Some(rendered.prepared().effective().clone()),
            alias: alias.to_string(),
            driver: rendered.prepared().driver(),
            action: rendered.prepared().requested().action.as_str().to_string(),
            config_digest: rendered.prepared().config_digest().to_string(),
            request_digest: rendered.prepared().request_digest().to_string(),
            attachment_manifest_digest: rendered
                .prepared()
                .attachment_manifest_digest()
                .to_string(),
            command_digest: rendered.command_digest().to_string(),
            program_identity_digest: rendered.program_identity_digest().to_string(),
            configured_executable: rendered.prepared().executable().to_path_buf(),
            configured_executable_identity_digest: rendered
                .prepared()
                .executable_identity()
                .sha256()
                .to_string(),
            wrapper_executable: rendered
                .wrapper_identity()
                .map(|identity| identity.configured_path().to_path_buf()),
            wrapper_identity_digest: rendered
                .wrapper_identity()
                .map(|identity| identity.sha256().to_string()),
            head_root: if rendered.prepared().target_worktree().as_os_str().is_empty() {
                rendered.prepared().project_root().to_path_buf()
            } else {
                rendered.prepared().target_worktree().to_path_buf()
            },
            fixed_head: rendered.prepared().target_head().to_string(),
        };
        let runtime_limit = managed_wake_runtime_limit(Some(deadline_secs));
        let pid = match spawn_channel_wake_supervisor(
            root,
            alias,
            rendered.argv(),
            &log_path,
            &wake_id,
            runtime_limit,
            rendered.env(),
            rendered.cwd(),
            binding,
        ) {
            Ok(pid) => pid,
            Err(error) => {
                if let (Some(site), Some(request)) = (provisioned.as_ref(), review.as_ref()) {
                    return reject_and_retire_pre_spawn_review_site(
                        root, &round, &wake_id, request, site, error,
                    );
                }
                return Err(error);
            }
        };

        let provider_kind = (rendered.prepared().driver_contract().receipt
            != crate::harness::CapabilitySource::Absent)
            .then(|| BackendReceiptKind::parse(rendered.prepared().driver().as_str()).ok())
            .flatten();
        let tuple_json = |tuple: &crate::channel::InvocationTuple| {
            serde_json::json!({
                "provider": tuple.provider,
                "model": tuple.model,
                "effort": tuple.effort,
                "mode": tuple.mode,
            })
        };
        let request_session_id = (rendered.prepared().driver()
            == crate::harness::HarnessId::SmartClaw)
            .then(|| format!("orch-wake-{wake_id}"));
        let continuation_id = match rendered.prepared().requested().action {
            crate::channel::InvocationAction::Review => {
                format!("review:{round}:{task_id}:{attempt_id}:review:{alias}")
            }
            crate::channel::InvocationAction::Execute => {
                format!("implementation:{round}:{task_id}:{attempt_id}:{alias}")
            }
            crate::channel::InvocationAction::Consult => {
                format!("manual:{round}:{wake_id}:{alias}")
            }
        };
        let durable_attempt_id = (rendered.prepared().requested().action
            != crate::channel::InvocationAction::Consult)
            .then_some(attempt_id.as_str());
        let mut wake_payload = serde_json::json!({
            "wakeId": wake_id,
            "controlWakeId": wake_id,
            "runtimeLimit": runtime_limit,
            "continuationId": continuation_id,
            "attemptId": durable_attempt_id,
            "agent": alias,
            "harness": alias,
            "harnessId": rendered.prepared().driver().as_str(),
            "driver": rendered.prepared().driver().as_str(),
        });
        wake_payload["providerKind"] =
            serde_json::json!(provider_kind.map(BackendReceiptKind::as_str));
        wake_payload["action"] = serde_json::json!(rendered.prepared().requested().action.as_str());
        wake_payload["terminalCapability"] =
            serde_json::json!(rendered.prepared().driver_contract().terminal.as_str());
        wake_payload["configDigest"] = serde_json::json!(rendered.prepared().config_digest());
        wake_payload["requestDigest"] = serde_json::json!(rendered.prepared().request_digest());
        wake_payload["attachmentManifestSha256"] =
            serde_json::json!(rendered.prepared().attachment_manifest_digest());
        wake_payload["commandDigest"] = serde_json::json!(rendered.command_digest());
        wake_payload["requestedTuple"] = tuple_json(&rendered.prepared().requested().tuple);
        wake_payload["effectiveTuple"] = tuple_json(rendered.prepared().effective());
        wake_payload["requestedProvider"] =
            serde_json::json!(rendered.prepared().requested().provider());
        wake_payload["requestedModel"] = serde_json::json!(rendered.prepared().requested().model());
        wake_payload["requestedEffort"] =
            serde_json::json!(rendered.prepared().requested().effort());
        wake_payload["requestedMode"] = serde_json::json!(rendered.prepared().requested().mode());
        wake_payload["observationSource"] =
            serde_json::json!(rendered.prepared().observation_source());
        if rendered.prepared().driver() == crate::harness::HarnessId::SmartClaw {
            wake_payload["nativeDatabasePath"] = serde_json::json!(
                crate::channel::smartclaw::database_from_environment(rendered.env())
            );
        }
        wake_payload["executable"] =
            serde_json::json!(rendered.prepared().executable().display().to_string());
        wake_payload["executableIdentityDigest"] =
            serde_json::json!(rendered.prepared().executable_identity().sha256());
        wake_payload["invocationCwd"] = serde_json::json!(rendered.cwd().display().to_string());
        wake_payload["cwdSelection"] =
            serde_json::json!(rendered.prepared().cwd_selection().as_str());
        wake_payload["fixedHead"] = serde_json::json!(rendered.prepared().target_head());
        wake_payload["requestMessageSha256"] =
            serde_json::json!(rendered.prepared().request_digest());
        wake_payload["renderedMessageSha256"] =
            serde_json::json!(sha256_hex(rendered.prepared().prompt().as_bytes()));
        wake_payload["requestSessionId"] = serde_json::json!(request_session_id);
        wake_payload["backendState"] = serde_json::json!(if provider_kind.is_some() {
            "pending"
        } else {
            "managed"
        });
        wake_payload["pid"] = serde_json::json!(pid);
        wake_payload["logPath"] = serde_json::json!(log_path.display().to_string());
        wake_payload["probeOffset"] = serde_json::json!(0);
        wake_payload["probeEnd"] = serde_json::json!(0);
        wake_payload["legacyProbeOffset"] = serde_json::json!(0);
        wake_payload["legacyProbe"] = serde_json::json!(LegacyProbeState::NotAttempted.as_str());
        wake_payload["method"] = serde_json::json!("unified-channel-v1");
        wake_payload["messageSource"] = serde_json::json!(resolved.source.as_str());
        wake_payload["messageBytes"] = serde_json::json!(resolved.bytes);
        wake_payload["reviewOutputPath"] = serde_json::json!(review_output
            .as_ref()
            .map(|path| path.display().to_string()));
        let event_task = review
            .as_ref()
            .map(|request| request.task_id.as_str())
            .or(execute_task);
        let wake_event = ledger::event(
            "WakeIssued",
            "runtime:orch",
            event_task,
            Some(&round),
            wake_payload.clone(),
        );
        let mut emitted = vec![wake_event];
        if let Some(request) = review.as_ref() {
            let mut review_payload = wake_payload;
            let mut review_event = review_request_event(request)?.into_record();
            review_event.round = Some(round.clone());
            review_payload["requestedAt"] = serde_json::json!(review_event.ts);
            review_payload["deadlineSecs"] = serde_json::json!(request.deadline_secs);
            review_payload["role"] = serde_json::json!("review");
            review_payload["reviewedHead"] = serde_json::json!(rendered.prepared().target_head());
            review_payload["harness"] = serde_json::json!(alias);
            review_event.payload = Some(review_payload);
            emitted.push(review_event);
        }
        if let Err(error) = ledger::append(root, &round, &emitted) {
            return Err(anyhow::Error::new(ChannelPublicationEffectUnknown {
                wake_id: wake_id.clone(),
                detail: format!("{error:#}"),
            }));
        }
        Ok(WakeRunOutcome::Spawned { wake_id })
    })
}

#[derive(Debug)]
struct ChannelPublicationEffectUnknown {
    wake_id: String,
    detail: String,
}

impl std::fmt::Display for ChannelPublicationEffectUnknown {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            formatter,
            "unified channel provider 已 spawn，但 WakeIssued/ReviewRequested publication 未证实；external effect unknown，禁止自动重试；wakeId={}；先运行 doctor/ledger recover 并核 control sidecar：{}",
            self.wake_id, self.detail
        )
    }
}

impl std::error::Error for ChannelPublicationEffectUnknown {}

fn channel_publication_effect_unknown(error: &anyhow::Error) -> bool {
    error.chain().any(|cause| {
        cause
            .downcast_ref::<ChannelPublicationEffectUnknown>()
            .is_some()
    })
}

fn run_wake_with_message_mode(
    root: &Path,
    agent: &str,
    resolved: ResolvedMessage,
    review: Option<ReviewRequest>,
    require_active: bool,
    reissue_source_wake_id: Option<&str>,
    fallback: Option<ReviewFallbackContext>,
) -> Result<WakeRunOutcome> {
    if review
        .as_ref()
        .is_some_and(|request| request.role != "review")
    {
        bail!("legacy formal/nongate review wake 已退役；schema 3 role 必须为 review");
    }
    let round = current_round(root)?;
    let preflight_wake_id = fresh_uuid();
    let schema3 = crate::gitx::rev_parse(root, "--show-toplevel")
        .ok()
        .map(PathBuf::from)
        .and_then(|path| fs::canonicalize(path).ok())
        .zip(fs::canonicalize(root).ok())
        .is_some_and(|(toplevel, canonical_root)| toplevel == canonical_root)
        && crate::round::contract_schema_at_root(root, &round)?
            == Some(crate::plan::ACTORLESS_ROUND_IR_SCHEMA_VERSION);
    if review.is_some() && !schema3 {
        bail!("schema 1/2 review wake 为只读历史面，拒绝新写入");
    }
    let result = if schema3 {
        if reissue_source_wake_id.is_some() || fallback.is_some() {
            Err(anyhow::anyhow!(
                "schema 3 unified channel 不接受 legacy reissue/fallback"
            ))
        } else {
            crate::close::with_protocol_effect(root, "schema 3 unified wake", || {
                run_channel_wake_v3(root, agent, resolved, review, require_active, None)
            })
        }
    } else {
        if let Err(error) = load_registry(root).and_then(|registry| {
            registry
                .get(agent)
                .with_context(|| format!("AgentRegistry 未注册 agent: {agent}"))
                .map(|_| ())
        }) {
            return failure::reject_action_disposition(
                root,
                &round,
                None,
                "wake",
                &preflight_wake_id,
                &format!("{error:#}"),
                failure::CliDisposition::Rejected,
                None,
            );
        }
        crate::close::with_protocol_effect(root, "explicit wake", || {
            run_wake_with_message_mode_effect(
                root,
                agent,
                resolved,
                review,
                require_active,
                reissue_source_wake_id,
                fallback,
            )
        })
    };
    match result {
        Ok(outcome) => Ok(outcome),
        Err(error) if failure::is_action_rejection(&error) => Err(error),
        Err(error) if channel_publication_effect_unknown(&error) => Err(
            failure::with_cli_disposition(error, failure::CliDisposition::EffectUnknown),
        ),
        Err(error) => failure::reject_action_disposition(
            root,
            &round,
            None,
            "wake",
            &preflight_wake_id,
            &format!("{error:#}"),
            failure::CliDisposition::Rejected,
            None,
        ),
    }
}

fn run_wake_with_message_mode_effect(
    root: &Path,
    agent: &str,
    resolved: ResolvedMessage,
    review: Option<ReviewRequest>,
    require_active: bool,
    reissue_source_wake_id: Option<&str>,
    fallback: Option<ReviewFallbackContext>,
) -> Result<WakeRunOutcome> {
    // The action identity must exist before any rejectable registry/session/budget/provider step.
    // This exact wakeId is used by both WakeIssued and every ActionRejected fallback.
    let wake_id = fresh_managed_wake_id();
    let round = current_round(root)?;
    match run_wake_with_message_inner(
        root,
        agent,
        resolved,
        review,
        &round,
        &wake_id,
        require_active,
        reissue_source_wake_id,
        fallback,
        None,
    ) {
        Ok(outcome) => Ok(outcome),
        Err(error) if failure::is_action_rejection(&error) => Err(error),
        Err(error) => failure::reject_action_disposition(
            root,
            &round,
            None,
            "wake",
            &wake_id,
            &format!("{error:#}"),
            failure::CliDisposition::Rejected,
            None,
        ),
    }
}

fn run_wake_with_message_inner(
    root: &Path,
    agent: &str,
    resolved: ResolvedMessage,
    review: Option<ReviewRequest>,
    round: &str,
    wake_id: &str,
    require_active: bool,
    reissue_source_wake_id: Option<&str>,
    fallback: Option<ReviewFallbackContext>,
    panel_route_authorization: Option<PanelRouteAuthorizationV1>,
) -> Result<WakeRunOutcome> {
    run_wake_with_message_inner_and_append(
        root,
        agent,
        resolved,
        review,
        round,
        wake_id,
        require_active,
        reissue_source_wake_id,
        fallback,
        panel_route_authorization,
        ledger::append,
    )
}

#[allow(clippy::too_many_arguments)]
fn run_wake_with_message_inner_and_append<F>(
    root: &Path,
    agent: &str,
    resolved: ResolvedMessage,
    review: Option<ReviewRequest>,
    round: &str,
    wake_id: &str,
    require_active: bool,
    reissue_source_wake_id: Option<&str>,
    fallback: Option<ReviewFallbackContext>,
    panel_route_authorization: Option<PanelRouteAuthorizationV1>,
    append: F,
) -> Result<WakeRunOutcome>
where
    F: FnOnce(&Path, &str, &[orch_core::EventRecord]) -> Result<()>,
{
    if review.is_some() {
        crate::channel::with_capacity_lock(root, || {
            run_wake_with_message_inner_and_append_locked(
                root,
                agent,
                resolved,
                review,
                round,
                wake_id,
                require_active,
                reissue_source_wake_id,
                fallback,
                panel_route_authorization,
                append,
            )
        })
    } else {
        run_wake_with_message_inner_and_append_locked(
            root,
            agent,
            resolved,
            review,
            round,
            wake_id,
            require_active,
            reissue_source_wake_id,
            fallback,
            panel_route_authorization,
            append,
        )
    }
}

#[allow(clippy::too_many_arguments)]
fn run_wake_with_message_inner_and_append_locked<F>(
    root: &Path,
    agent: &str,
    resolved: ResolvedMessage,
    review: Option<ReviewRequest>,
    round: &str,
    wake_id: &str,
    require_active: bool,
    reissue_source_wake_id: Option<&str>,
    fallback: Option<ReviewFallbackContext>,
    panel_route_authorization: Option<PanelRouteAuthorizationV1>,
    append: F,
) -> Result<WakeRunOutcome>
where
    F: FnOnce(&Path, &str, &[orch_core::EventRecord]) -> Result<()>,
{
    with_wake_identity_lock(root, agent, || {
        run_wake_with_message_inner_and_append_identity_locked(
            root,
            agent,
            resolved,
            review,
            round,
            wake_id,
            require_active,
            reissue_source_wake_id,
            fallback,
            panel_route_authorization,
            append,
        )
    })
}

#[allow(clippy::too_many_arguments)]
fn run_wake_with_message_inner_and_append_identity_locked<F>(
    root: &Path,
    agent: &str,
    resolved: ResolvedMessage,
    review: Option<ReviewRequest>,
    round: &str,
    wake_id: &str,
    require_active: bool,
    reissue_source_wake_id: Option<&str>,
    fallback: Option<ReviewFallbackContext>,
    panel_route_authorization: Option<PanelRouteAuthorizationV1>,
    append: F,
) -> Result<WakeRunOutcome>
where
    F: FnOnce(&Path, &str, &[orch_core::EventRecord]) -> Result<()>,
{
    if review.is_some()
        || reissue_source_wake_id.is_some()
        || fallback.is_some()
        || panel_route_authorization.is_some()
    {
        bail!("legacy formal/panel/fallback wake path 已退役");
    }
    let continuation_id = if let Some(request) = review.as_ref() {
        format!(
            "review:{round}:{}:{}:{}:{agent}",
            request.task_id, request.attempt_id, request.role
        )
    } else {
        format!("manual:{round}:{wake_id}:{agent}")
    };
    let continuation = parse_continuation_identity(&continuation_id).map_err(anyhow::Error::msg)?;
    if continuation.round != round || continuation.agent != agent {
        bail!("wake continuation does not match current round/agent");
    }
    let request_message_sha256 = wake_request_message_sha256(&resolved.text, &continuation_id)
        .map_err(anyhow::Error::msg)?;

    // Registry/session validation is not a provider side effect and must retain
    // the historical POKE diagnostic for non-injectable agents.  It is safe to
    // do before the identity projection; budget, review-site provisioning, log
    // creation and spawn all remain behind the fence.
    let registry = load_registry(root)?;
    let spec = registry
        .get(agent)
        .cloned()
        .with_context(|| format!("AgentRegistry 未注册 agent: {agent}"))?;
    if !spec.injectable {
        bail!("agent {agent} 不支持注入唤醒；请走 POKE 备用信道");
    }
    let sessions = load_session_registry(root)?;
    let session = sessions
        .get(agent)
        .with_context(|| format!("AgentRegistry 缺少 session 配置: {agent}"))?;
    let rendered_argv =
        render_registered_invocation(root, agent, &resolved.text, session.configured)?.argv;
    let provider_kind = backend_receipt_kind_from_argv(&rendered_argv).ok();
    let provider_bound = provider_kind.is_some();
    if reissue_source_wake_id.is_some() {
        if review.is_none() {
            bail!("wake reissue is limited to formal review continuations");
        }
        if provider_kind != Some(BackendReceiptKind::OpenCode) {
            bail!(
                "unsupported provider scope: reissue is limited to managed opencode formal review wakes"
            );
        }
    }

    let fresh_events = read_round_ledger_events(root, round)?;
    let reissue_authorization = reissue_source_wake_id
        .map(|source| reissue_authorization_from_events(root, &fresh_events, round, source))
        .transpose()?;
    if let (Some(request), Some(authorization)) = (review.as_ref(), reissue_authorization.as_ref())
    {
        let binding = &authorization.binding;
        if request.task_id != binding.task_id
            || request.attempt_id != binding.attempt_id
            || request.role != binding.role
            || request.agent != binding.agent
            || binding.agent != agent
            || binding.continuation_id != continuation_id
        {
            bail!("wake reissue request does not match the authenticated source review tuple");
        }
    }
    let review_expectation = review
        .as_ref()
        .map(|request| {
            new_review_expectation(
                root,
                round,
                &fresh_events,
                request,
                fallback.as_ref(),
                panel_route_authorization.as_ref(),
            )
        })
        .transpose()?;
    if crate::round::contract_schema_from_events(&fresh_events, round)?
        == Some(crate::plan::ACTORLESS_ROUND_IR_SCHEMA_VERSION)
    {
        bail!("schema 3 wake 必须走 unified channel，不得进入 legacy wake effect");
    }
    if let (Some(request), Some(context)) = (review.as_ref(), fallback.as_ref()) {
        if reissue_source_wake_id.is_some() {
            bail!("fallback 与 review reissue 是互斥 transition");
        }
        if let Some(existing_wake_id) =
            validate_review_fallback_transition(root, &fresh_events, round, request, context)?
        {
            return Ok(WakeRunOutcome::Idempotent {
                wake_id: existing_wake_id,
            });
        }
    }
    let active = if provider_bound {
        if reissue_source_wake_id.is_some() {
            active_wakes_from_events_raw(&fresh_events, round, agent)?
        } else {
            active_wakes_from_events(&fresh_events, round, agent)?
        }
    } else {
        Vec::new()
    };
    if let Some(source_wake_id) = reissue_source_wake_id {
        let supersession = wake_supersession_projection(&fresh_events, round)?;
        if let Some(successor_wake_id) = supersession_leaf(&supersession, source_wake_id) {
            let matching_successor = active
                .iter()
                .filter(|wake| {
                    wake.agent == agent
                        && wake.continuation_id == continuation_id
                        && wake.wake_id == successor_wake_id
                        && (wake.backend_accepted || !wake.wrapper_exited)
                })
                .collect::<Vec<_>>();
            if matching_successor.len() != 1 {
                bail!(
                    "existing reissue successor is not the unique active wake: source={source_wake_id} successor={successor_wake_id} found={}",
                    matching_successor.len()
                );
            }
            let capacity = wake_capacity_from_events(root, round, &fresh_events, agent)?;
            match wake_fence_decision(
                &active,
                agent,
                &WakeIntent::Continuation(continuation_id.clone()),
                &request_message_sha256,
                capacity,
            )
            .map_err(anyhow::Error::msg)?
            {
                WakeFenceOutcome::Idempotent { wake_id, .. } if wake_id == successor_wake_id => {}
                other => {
                    bail!("existing reissue successor failed the continuation fence: {other:?}")
                }
            }
            if reconcile_backend_receipt_locked(root, round, &successor_wake_id)? {
                return Ok(WakeRunOutcome::Idempotent {
                    wake_id: successor_wake_id,
                });
            }
            return failure::reject_action_command_outcome(
                root,
                round,
                continuation.task_id.as_deref(),
                "wake-backend-receipt",
                &successor_wake_id,
                "existing reissue successor backend receipt is still pending",
                failure::CommandOutcome::PendingReceipt,
                None,
            );
        }
    }

    let declared_dead_replacement = if reissue_authorization.is_none()
        && panel_route_authorization.is_none()
    {
        review
            .as_ref()
            .map(|request| declared_dead_review_replacement(root, &fresh_events, round, request))
            .transpose()?
            .flatten()
    } else {
        None
    };
    let superseded_wake_id = if let Some(context) = fallback.as_ref() {
        Some(context.source_wake_id.clone())
    } else if let Some(authorization) = reissue_authorization.as_ref() {
        let capacity = wake_capacity_from_events(root, round, &fresh_events, agent)?;
        match reissue_decision(
            &active,
            agent,
            &WakeIntent::Continuation(continuation_id.clone()),
            &request_message_sha256,
            capacity,
            Some(&authorization.evidence),
        )
        .map_err(anyhow::Error::msg)?
        {
            ReissueOutcome::Reissue { superseded_wake_id }
                if Some(superseded_wake_id.as_str()) == reissue_source_wake_id =>
            {
                Some(superseded_wake_id)
            }
            ReissueOutcome::Reissue { superseded_wake_id } => bail!(
                "reissue decision source drifted: requested={:?} decided={superseded_wake_id}",
                reissue_source_wake_id
            ),
            ReissueOutcome::Refused { reason } => bail!("wake reissue refused: {reason}"),
        }
    } else {
        // A committed panel route already carries generation, wakeId, policy
        // base and (for retry/backfill) the exact source terminal. The legacy
        // continuation digest is intentionally stable across a role, while a
        // route message changes by generation; comparing those digests would
        // reject every lawful gen2 before spawn. Route-level idempotence stays
        // fenced by the preallocated wakeId under the wake-identity lock.
        let capacity = if provider_bound && panel_route_authorization.is_none() {
            wake_capacity_from_events(root, round, &fresh_events, agent)?
        } else {
            1
        };
        let fence = new_wake_fence_decision(
            &active,
            agent,
            &WakeIntent::Continuation(continuation_id.clone()),
            &request_message_sha256,
            capacity,
            provider_bound,
            panel_route_authorization.is_some(),
        )
        .map_err(anyhow::Error::msg)?;
        if let WakeFenceDecision::Idempotent {
            wake_id: existing_wake_id,
            ..
        } = fence
        {
            if reconcile_backend_receipt_locked(root, round, &existing_wake_id)? {
                return Ok(WakeRunOutcome::Idempotent {
                    wake_id: existing_wake_id,
                });
            }
            return failure::reject_action_command_outcome(
                root,
                round,
                continuation.task_id.as_deref(),
                "wake-backend-receipt",
                &existing_wake_id,
                "exact retry found the original backend receipt still pending",
                failure::CommandOutcome::PendingReceipt,
                None,
            );
        }
        declared_dead_replacement
            .as_ref()
            .map(|replacement| replacement.source_wake_id.clone())
    };
    let replacement = reissue_authorization
        .as_ref()
        .map(|authorization| &authorization.binding)
        .or(declared_dead_replacement
            .as_ref()
            .map(|replacement| &replacement.binding));
    let required_role = review.as_ref().map(|request| {
        let role = crate::sites::SiteRole::parse(&request.role)
            .expect("validated review request has a known site role");
        review_permit_role(role)
    });
    if require_active || required_role.is_some() {
        if let (Some(authorization), Some(role)) =
            (panel_route_authorization.as_ref(), required_role.as_deref())
        {
            validate_panel_route_wake_permit(root, round, agent, role, authorization)?;
        } else {
            validate_wake_permit_with_replacement(
                root,
                round,
                agent,
                required_role.as_deref(),
                replacement,
            )?;
        }
    }

    // Review-site creation is a precondition of the review request, not an
    // instruction delegated to the reviewer.  All filesystem/git failures
    // therefore happen before budget reservation and provider spawn.
    let provisioned = review
        .as_ref()
        .map(|request| {
            provision_review_site(
                root,
                round,
                wake_id,
                request,
                review_expectation
                    .as_ref()
                    .expect("review expectation exists with request"),
            )
        })
        .transpose()?;
    macro_rules! pre_spawn_try {
        ($result:expr) => {
            match $result {
                Ok(value) => value,
                Err(error) => return Err(error),
            }
        };
    }
    let sandbox_scope = if provisioned.is_some() {
        Some(pre_spawn_try!(crate::agent_profile::load_sandbox_scope(
            root, agent
        )
        .map_err(anyhow::Error::msg)))
    } else {
        None
    };
    let permit = budget::check_before_model_wake(root, round)?;
    budget::bind_model_wake_reservation(root, &permit, wake_id)?;
    let mut permit = Some(permit);

    if require_active || required_role.is_some() {
        if let (Some(authorization), Some(role)) =
            (panel_route_authorization.as_ref(), required_role.as_deref())
        {
            pre_spawn_try!(validate_panel_route_wake_permit(
                root,
                round,
                agent,
                role,
                authorization,
            ));
        } else {
            pre_spawn_try!(validate_wake_permit_with_replacement(
                root,
                round,
                agent,
                required_role.as_deref(),
                replacement,
            ));
        }
    }

    let (resolved, prepared_probe) = match (provisioned.as_ref(), sandbox_scope.as_ref()) {
        (Some(site), Some(scope)) => {
            let (resolved, probe) = pre_spawn_try!(prepare_review_probe_message(
                resolved,
                site,
                scope,
                root,
                round,
                wake_id,
                review_expectation
                    .as_ref()
                    .expect("review expectation exists with request"),
            ));
            (resolved, Some(probe))
        }
        (None, None) => (resolved, None),
        _ => pre_spawn_try!(Err(anyhow::anyhow!(
            "review site/sandbox preparation invariant broken"
        ))),
    };
    let invocation_cwd = root;
    let mut spawn_effect = ProviderSpawnEffect::None;
    let launch = match spawn_registered_wake(
        root,
        round,
        agent,
        &resolved.text,
        Some(wake_id),
        review.as_ref().map(|request| request.deadline_secs),
        Some(&continuation),
        provisioned.as_ref(),
        prepared_probe
            .as_ref()
            .map(|probe| probe.output_path.as_str()),
        None,
        Some(invocation_cwd),
        Some(&mut spawn_effect),
    ) {
        Ok(launch) => launch,
        Err(error) => {
            if let Some(probe) = prepared_probe.as_ref() {
                let _ = fs::remove_file(&probe.sentinel_path);
            }
            return Err(error);
        }
    };
    if launch
        .action_wake_id
        .as_deref()
        .is_some_and(|launched| launched != wake_id)
    {
        bail!("spawned provider action wake identity drifted");
    }
    let rendered_message_sha256 = sha256_hex(resolved.text.as_bytes());
    let initial_probe_end = fs::metadata(&launch.log_path)
        .with_context(|| {
            format!(
                "stat spawned wake log failed: {}",
                launch.log_path.display()
            )
        })?
        .len();
    let reservation_id = permit
        .as_ref()
        .and_then(|permit| permit.reservation_id())
        .map(str::to_string);
    let mut wake_payload = serde_json::json!({
        "wakeId": wake_id,
        "controlWakeId": launch.wake_id,
        "runtimeLimit": launch.runtime_limit,
        "continuationId": continuation_id,
        "attemptId": continuation.attempt_id,
        "agent": agent,
        "providerKind": launch.provider_kind.map(BackendReceiptKind::as_str),
        "tool": launch.tool,
        "requestedProvider": launch.requested_provider,
        "requestedModel": launch.requested_model,
        "requestedEffort": launch.requested_effort,
        "quotaDomain": launch.quota_domain,
        "requestMessageSha256": request_message_sha256,
        "renderedMessageSha256": rendered_message_sha256,
        "requestSessionId": launch.request_session_id,
        "backendState": if launch.provider_kind.is_some() { "pending" } else { "legacy-untracked" },
        "pid": launch.pid,
        // B100：指向 per-attempt 独立文件（历史不再被截断覆盖）
        "logPath": launch.log_path.display().to_string(),
        // Per-attempt files are create_new and always start at zero. The
        // old shared-log size remains diagnostics only.
        "probeOffset": 0,
        "probeEnd": initial_probe_end,
        "legacyProbeOffset": launch.legacy_offset,
        // B100 修复轮 D1/D2：legacy 探活轮换状态落账
        // （linked / degraded-empty / degraded-absent；degraded 时已 fail-closed）
        "legacyProbe": launch.legacy_probe.as_str(),
        "method": "manual-cli",
        // B109：富输入来源 + UTF-8 字节数（落账；消费方按需读）
        "messageSource": resolved.source.as_str(),
        "messageBytes": resolved.bytes,
        "reviewOutputPath": launch.review_output_path,
    });
    bind_registered_wake_harness_identity(
        &mut wake_payload,
        launch.harness_id,
        launch.terminal_capability,
        &launch.harness_registry_digest,
    )?;
    bind_panel_route_event_identity_v1(&mut wake_payload, panel_route_authorization.as_ref());
    if let Some(source_wake_id) = superseded_wake_id.as_deref() {
        wake_payload["supersededWakeId"] = serde_json::json!(source_wake_id);
    }
    let fallback_event = fallback.as_ref().map(|context| {
        ledger::event(
            "ReviewFallbackSelected",
            "runtime:orch",
            continuation.task_id.as_deref(),
            Some(round),
            serde_json::json!({
                "attemptId": review.as_ref().expect("fallback has review request").attempt_id,
                "role": review.as_ref().expect("fallback has review request").role,
                "fromAgent": context.from_agent,
                "toAgent": agent,
                "reviewedHead": context.reviewed_head,
                "sourceWakeId": context.source_wake_id,
                "terminalEventId": context.terminal_event_id,
                "targetWakeId": wake_id,
            }),
        )
    });
    if let Some(selection) = fallback_event.as_ref() {
        wake_payload["reviewFallbackEventId"] = serde_json::json!(selection.event_id);
    }
    let wake_event = ledger::event(
        "WakeIssued",
        "runtime:orch",
        continuation.task_id.as_deref(),
        Some(round),
        wake_payload,
    );
    // event 已取得 thread-local reservationId；先 commit 使 append 失败时 reservation
    // 仍然留存并占名额，append 成功后由下一次预算快照识别 fulfilled 并清理。
    if let Some(permit) = permit.as_mut() {
        permit.commit();
    }

    debug_assert_eq!(
        wake_event
            .extra
            .get("modelWakeReservationId")
            .and_then(|value| value.as_str()),
        reservation_id.as_deref()
    );
    let mut events = Vec::with_capacity(if fallback_event.is_some() { 4 } else { 3 });
    if let Some(selection) = fallback_event {
        events.push(selection);
    }
    events.push(wake_event);
    if launch.terminal_capability == Some(crate::harness::CapabilitySource::Absent) {
        events.push(managed_wake_terminal_absent_event(
            round,
            continuation.task_id.as_deref(),
            wake_id,
            agent,
        )?);
    }
    if let Some(request) = review.as_ref().filter(|request| {
        crate::sites::SiteRole::parse(&request.role).is_ok_and(|role| {
            role.satisfies_formal_review_slot() || role == crate::sites::SiteRole::Review
        })
    }) {
        let mut event = review_request_event(request)?.into_record();
        event.round = Some(round.to_string());
        let payload = event
            .payload
            .as_mut()
            .expect("ReviewRequested always has a payload");
        payload["wakeId"] = serde_json::json!(wake_id);
        payload["continuationId"] = serde_json::json!(continuation_id);
        payload["requestMessageSha256"] = serde_json::json!(request_message_sha256);
        payload["renderedMessageSha256"] = serde_json::json!(rendered_message_sha256);
        payload["providerKind"] =
            serde_json::json!(launch.provider_kind.map(BackendReceiptKind::as_str));
        payload["requestedProvider"] = serde_json::json!(launch.requested_provider);
        payload["requestSessionId"] = serde_json::json!(launch.request_session_id);
        payload["logPath"] = serde_json::json!(launch.log_path.display().to_string());
        payload["reviewedHead"] = serde_json::json!(review_expectation
            .as_ref()
            .expect("review expectation exists with request")
            .reviewed_head());
        if request.role == "review" {
            payload["harness"] = serde_json::json!(request.agent);
        }
        bind_panel_route_event_identity_v1(payload, panel_route_authorization.as_ref());
        if let Some(selection) = events
            .iter()
            .find(|event| event.kind == "ReviewFallbackSelected")
        {
            payload["reviewFallbackEventId"] = serde_json::json!(selection.event_id);
        }
        events.push(event);
    }
    // A provider was really spawned. From this point an append failure must be
    // loud: the command returns Err and never claims an unrecorded review wake
    // succeeded. `ledger::append` provides the WAL-backed atomic write.
    append(root, round, &events)?;

    if launch.provider_kind.is_some() {
        let started = Instant::now();
        loop {
            match reconcile_backend_receipt_locked(root, round, wake_id) {
                Ok(true) => break,
                Ok(false) => {}
                Err(error) => {
                    return reject_degraded_backend_receipt(
                        root,
                        round,
                        wake_id,
                        &format!("canonical receipt validation failed: {error:#}"),
                    );
                }
            }
            if started.elapsed() >= review_probe_timeout() {
                let reason = (|| -> Result<String> {
                    let captured =
                        capture_probe_window(&launch.log_path, 0).map_err(anyhow::Error::msg)?;
                    let bytes = read_captured_probe_bytes(captured)?;
                    let expectation = backend_receipt_expectation_with_pin(
                        launch.provider_kind.expect("checked provider kind"),
                        wake_id,
                        &continuation_id,
                        &request_message_sha256,
                        launch.request_session_id.as_deref(),
                        launch.requested_provider.as_deref(),
                        launch.requested_model.as_deref(),
                        launch.requested_effort.as_deref(),
                    )?;
                    Ok(backend_receipt_from_log(&expectation, &bytes, true)
                        .err()
                        .unwrap_or_else(|| "backend receipt timed out".to_string()))
                })()
                .unwrap_or_else(|error| {
                    format!("backend receipt timeout diagnosis failed: {error:#}")
                });
                return reject_degraded_backend_receipt(root, round, wake_id, &reason);
            }
            std::thread::sleep(Duration::from_millis(25));
        }
    }

    // Injection is already irreversible, and its WakeIssued + ReviewRequested
    // facts are now durable in one transaction. A review wake is successful
    // only when this exact per-attempt log proves that the session consumed it.
    if let Some(probe) = prepared_probe.as_ref() {
        let mut plain_text_consumed = false;
        // Unknown test adapters retain the legacy consumption shim. Every
        // production provider above is gated by its action-scoped receipt.
        let consumption_failure = if launch.plain_text_review_channel {
            let request = review
                .as_ref()
                .context("plain-text review consumption 缺 review request")?;
            let consumption_timeout = plain_text_review_consumption_timeout(request);
            match await_plain_text_review_consumption(
                &launch.log_path,
                &probe.output_path,
                &probe.expectation,
                consumption_timeout,
            ) {
                Ok(true) => {
                    plain_text_consumed = true;
                    None
                }
                Ok(false) => Some(format!(
                    "agy exact review contract was not consumed after {}s",
                    consumption_timeout.as_secs()
                )),
                Err(error) => Some(format!(
                    "agy exact review consumption probe failed: {error:#}"
                )),
            }
        } else if launch.provider_kind.is_none() {
            match await_review_probe(&launch.log_path, probe, review_probe_timeout()) {
                Ok(Some(_)) => None,
                Ok(None) => Some(format!(
                    "review structured consumption was not proven after {}s",
                    review_probe_timeout().as_secs()
                )),
                Err(error) => Some(format!("review consumption probe failed: {error:#}")),
            }
        } else {
            None
        };
        if let Some(reason) = consumption_failure {
            let request = review
                .as_ref()
                .expect("a prepared review probe always has a review request");
            ledger::append(
                root,
                round,
                &[ledger::event(
                    "EscalationRaised",
                    "runtime:orch",
                    Some(&request.task_id),
                    Some(round),
                    serde_json::json!({
                        "stage": "review-consumption",
                        "taskId": request.task_id,
                        "role": request.role,
                        "agent": request.agent,
                        "wakeId": wake_id,
                        "logPath": launch.log_path.display().to_string(),
                        "worktree": probe.site.worktree,
                        "targetDir": probe.site.target_dir,
                        "reason": reason,
                    }),
                )],
            )?;
            bail!("审查注入未消费：注入可能被忙碌会话吞掉，请稍后重试；{reason}");
        }

        // The sentinel remains the stronger review-site reachability
        // diagnostic from B164. Engagement gates success; sentinel failure is
        // still durably escalated without erasing the already-sent request.
        let failure_reason = if plain_text_consumed {
            None
        } else {
            match await_review_probe(&launch.log_path, probe, review_probe_timeout()) {
                Ok(Some(_source)) => None,
                Ok(None) => Some(format!(
                    "review probe timed out without structured tool evidence after {}s",
                    review_probe_timeout().as_secs()
                )),
                Err(error) => Some(format!("review probe capture failed: {error:#}")),
            }
        };
        if let Some(reason) = failure_reason {
            let request = review
                .as_ref()
                .expect("a prepared review probe always has a review request");
            ledger::append(
                root,
                round,
                &[ledger::event(
                    "EscalationRaised",
                    "runtime:orch",
                    Some(&request.task_id),
                    Some(round),
                    serde_json::json!({
                        "stage": "review-probe",
                        "taskId": request.task_id,
                        "role": request.role,
                        "agent": request.agent,
                        "wakeId": wake_id,
                        "logPath": launch.log_path.display().to_string(),
                        "worktree": probe.site.worktree,
                        "targetDir": probe.site.target_dir,
                        "reason": reason,
                    }),
                )],
            )?;
        }
    }
    Ok(WakeRunOutcome::Spawned {
        wake_id: wake_id.to_string(),
    })
}

/// 加载某 agent 的 pokeHint（POKE 粘贴词模板）；未注册或无 pokeHint → None。
pub fn poke_hint_for(root: &Path, agent: &str) -> Result<Option<String>> {
    let path = root.join("coordination/agents.yaml");
    let text = fs::read_to_string(&path)
        .with_context(|| format!("读取 AgentRegistry 失败: {}", path.display()))?;
    let registry: Registry = serde_yaml::from_str(&text)
        .with_context(|| format!("解析 AgentRegistry 失败: {}", path.display()))?;
    Ok(registry
        .agents
        .get(agent)
        .map(|s| s.poke_hint.clone())
        .filter(|s| !s.is_empty()))
}

/// dispatch_wake 的对外结果（B100 修复轮 D3）：注入道返回本次注入的
/// per-attempt 日志路径、legacy offset、pid 与探活轮换状态——与 WakeIssued
/// payload 的 logPath/probeOffset/legacyProbe 同值同义，供未来 handshake
/// 接线读取（cmd_handshake 在 orch-cli frozenPaths 内，接线属 planner 侧）；
/// POKE 备用道（未注册/不可注入/--no-wake）injected=false，其余字段为 None。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DispatchWakeOutcome {
    pub injected: bool,
    pub pid: Option<u32>,
    pub log_path: Option<PathBuf>,
    pub wake_id: Option<String>,
    pub provider_kind: Option<BackendReceiptKind>,
    pub request_session_id: Option<String>,
    pub runtime_limit: Option<ManagedWakeRuntimeLimit>,
    pub legacy_offset: Option<u64>,
    pub legacy_probe: LegacyProbeState,
}

/// 派发/催醒后的唤醒分发：injectable 且 sessionId 非空 → run_wake；
/// 否则 → notify_macos + 写 POKE-<agent>.txt（render_poke 渲染 pokeHint，O6 mkdir 自愈）。
/// no_wake=true 时跳过注入（逃生舱），仅走 POKE。
pub fn dispatch_wake(
    root: &Path,
    agent: &str,
    round: &str,
    message: &str,
    no_wake: bool,
) -> Result<DispatchWakeOutcome> {
    crate::close::with_protocol_effect(root, "dispatch wake", || {
        dispatch_wake_effect(root, agent, round, message, no_wake)
    })
}

fn dispatch_wake_effect(
    root: &Path,
    agent: &str,
    round: &str,
    message: &str,
    no_wake: bool,
) -> Result<DispatchWakeOutcome> {
    validate_agent_component(agent)?;
    let registry = load_registry(root)?;
    let spec = registry
        .get(agent)
        .cloned()
        .with_context(|| format!("AgentRegistry 未注册 agent: {agent}"))?;
    match spec {
        s if s.injectable && !s.session_id.is_empty() && !no_wake => {
            let launch = spawn_registered_wake(
                root, round, agent, message, None, None, None, None, None, None, None, None,
            )?;
            println!("✅ 已注入唤醒 {agent}（injectable）");
            Ok(DispatchWakeOutcome {
                injected: true,
                pid: Some(launch.pid),
                log_path: Some(launch.log_path),
                wake_id: launch.action_wake_id,
                provider_kind: launch.provider_kind,
                request_session_id: launch.request_session_id,
                runtime_limit: launch.runtime_limit,
                legacy_offset: Some(launch.legacy_offset),
                legacy_probe: launch.legacy_probe,
            })
        }
        _ => {
            // POKE 备用道
            liveness::notify_macos("orch", &format!("{agent}: {message}"));
            let poke_dir = root.join("coordination/runtime");
            fs::create_dir_all(&poke_dir)?; // O6
            let hint = poke_hint_for(root, agent)?
                .unwrap_or_else(|| format!("r{{round}} 已派发,继续协作:重跑 sh coordination/scripts/wait-dispatch.sh {agent}"));
            let poke_text = render_poke(&hint, round);
            let poke_path = poke_dir.join(format!("POKE-{agent}.txt"));
            fs::write(&poke_path, &poke_text)?;
            println!(
                "📋 POKE 已写: {}（{agent} 不可注入或 --no-wake）",
                poke_path.display()
            );
            Ok(DispatchWakeOutcome {
                injected: false,
                pid: None,
                log_path: None,
                wake_id: None,
                provider_kind: None,
                request_session_id: None,
                runtime_limit: None,
                legacy_offset: None,
                legacy_probe: LegacyProbeState::NotAttempted,
            })
        }
    }
}

fn legacy_probe_state_from_str(value: &str) -> Result<LegacyProbeState> {
    match value {
        "linked" => Ok(LegacyProbeState::Linked),
        "degraded-empty" => Ok(LegacyProbeState::DegradedEmpty),
        "degraded-absent" => Ok(LegacyProbeState::DegradedAbsent),
        "not-attempted" => Ok(LegacyProbeState::NotAttempted),
        _ => bail!("unknown legacy probe state {value:?}"),
    }
}

fn prior_dispatch_outcome(event: &orch_core::EventRecord) -> Result<DispatchWakeOutcome> {
    let payload = event
        .payload
        .as_ref()
        .context("WakeIssued missing payload")?;
    let pid = payload
        .get("pid")
        .and_then(serde_json::Value::as_u64)
        .and_then(|value| u32::try_from(value).ok())
        .filter(|value| *value > 0)
        .context("WakeIssued missing valid pid")?;
    let log_path = payload_string(event, "logPath")
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .context("WakeIssued missing logPath")?;
    let wake_id = payload_string(event, "wakeId")
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .context("WakeIssued missing wakeId")?;
    let provider_kind = BackendReceiptKind::parse(
        payload_string(event, "providerKind").context("WakeIssued missing providerKind")?,
    )
    .map_err(anyhow::Error::msg)?;
    let request_session_id = match payload.get("requestSessionId") {
        Some(serde_json::Value::Null) => None,
        Some(serde_json::Value::String(value)) if !value.is_empty() => Some(value.clone()),
        _ => bail!("WakeIssued requestSessionId invalid"),
    };
    let runtime_limit = payload
        .get("runtimeLimit")
        .filter(|value| !value.is_null())
        .map(|value| serde_json::from_value(value.clone()))
        .transpose()
        .context("WakeIssued runtimeLimit invalid")?;
    Ok(DispatchWakeOutcome {
        injected: true,
        pid: Some(pid),
        log_path: Some(log_path),
        wake_id: Some(wake_id),
        provider_kind: Some(provider_kind),
        request_session_id,
        runtime_limit,
        legacy_offset: payload
            .get("legacyProbeOffset")
            .and_then(serde_json::Value::as_u64),
        legacy_probe: legacy_probe_state_from_str(
            payload_string(event, "legacyProbe").context("WakeIssued missing legacyProbe")?,
        )?,
    })
}

/// Typed implementation/review continuation delivery used by compatibility
/// runtime paths. Only implementation and generic `review` identities remain
/// live; formal/nongate identities are rejected before POKE or provider spawn.
pub fn dispatch_wake_for_continuation(
    root: &Path,
    agent: &str,
    round: &str,
    continuation_id: &str,
    message: &str,
    no_wake: bool,
) -> Result<DispatchWakeOutcome> {
    dispatch_wake_for_continuation_messages(
        root,
        agent,
        round,
        continuation_id,
        message,
        message,
        no_wake,
    )
}

/// Variant for runtime callers that add an action nonce to the rendered
/// provider message. The stable request digest binds `request_message`; the
/// independently audited rendered digest binds the exact injected bytes.
pub(crate) fn dispatch_wake_for_continuation_messages(
    root: &Path,
    agent: &str,
    round: &str,
    continuation_id: &str,
    request_message: &str,
    rendered_message: &str,
    no_wake: bool,
) -> Result<DispatchWakeOutcome> {
    let identity = parse_continuation_identity(continuation_id).map_err(anyhow::Error::msg)?;
    if matches!(
        identity.role.as_deref(),
        Some("primary" | "secondary" | "nongate")
    ) {
        bail!("legacy formal/nongate continuation wake 已退役；仅接受 generic review 或 implementation identity");
    }
    if identity.round != round || identity.agent != agent {
        bail!("typed dispatch continuation does not match round/agent");
    }
    if no_wake {
        return dispatch_wake(root, agent, round, rendered_message, true);
    }
    let request_message_sha256 = wake_request_message_sha256(request_message, continuation_id)
        .map_err(anyhow::Error::msg)?;
    crate::close::with_protocol_effect(root, "typed continuation wake", || {
        with_wake_identity_lock(root, agent, || {
            let events = read_round_ledger_events(root, round)?;
            let active = active_wakes_from_events(&events, round, agent)?;
            let capacity = wake_capacity_from_events(root, round, &events, agent)?;
            let baseline = wake_fence_decision(
                &active,
                agent,
                &WakeIntent::Continuation(continuation_id.to_string()),
                &request_message_sha256,
                capacity,
            );
            let fence = baseline
                .map(WakeFenceDecision::from)
                .map_err(anyhow::Error::msg)?;
            if let WakeFenceDecision::Idempotent {
                wake_id,
                backend_accepted: _,
            } = fence
            {
                if !reconcile_backend_receipt_locked(root, round, &wake_id)? {
                    bail!("typed continuation wake remains pending for wakeId={wake_id}");
                }
                let fresh = read_round_ledger_events(root, round)?;
                let wake = fresh
                    .iter()
                    .find(|event| {
                        event.kind == "WakeIssued"
                            && payload_string(event, "wakeId") == Some(wake_id.as_str())
                    })
                    .context("idempotent typed wake lost WakeIssued")?;
                return prior_dispatch_outcome(wake);
            }

            // A typed Tier-F delivery still has to preserve the historical
            // non-injectable/empty-session POKE fallback.  POKE is selected
            // only after the fresh continuation fence above, so capacity and
            // exact continuation identity are checked before a fallback can
            // signal the requested lifecycle without fabricating a spawn.
            let registry = load_registry(root)?;
            let spec = registry
                .get(agent)
                .with_context(|| format!("AgentRegistry 未注册 agent: {agent}"))?;
            if !spec.injectable || spec.session_id.is_empty() {
                return dispatch_wake(root, agent, round, rendered_message, false);
            }

            let wake_id = identity
                .manual_wake_id
                .clone()
                .unwrap_or_else(fresh_managed_wake_id);
            let launch = spawn_registered_wake(
                root,
                round,
                agent,
                rendered_message,
                Some(&wake_id),
                None,
                Some(&identity),
                None,
                None,
                None,
                None,
                None,
            )?;
            let Some(provider_kind) = launch.provider_kind else {
                // Custom/legacy adapters have no provider-bound grammar. They
                // retain their former behavior instead of fabricating a receipt.
                return Ok(DispatchWakeOutcome {
                    injected: true,
                    pid: Some(launch.pid),
                    log_path: Some(launch.log_path),
                    wake_id: launch.action_wake_id,
                    provider_kind: None,
                    request_session_id: None,
                    runtime_limit: launch.runtime_limit,
                    legacy_offset: Some(launch.legacy_offset),
                    legacy_probe: launch.legacy_probe,
                });
            };
            let rendered_message_sha256 = sha256_hex(rendered_message.as_bytes());
            let probe_end = fs::metadata(&launch.log_path)?.len();
            let mut wake_payload = serde_json::json!({
                "wakeId": wake_id,
                "controlWakeId": launch.wake_id,
                "runtimeLimit": launch.runtime_limit,
                "continuationId": continuation_id,
                "attemptId": identity.attempt_id,
                "agent": agent,
                "providerKind": provider_kind.as_str(),
                "tool": launch.tool,
                "requestedProvider": launch.requested_provider,
                "requestedModel": launch.requested_model,
                "requestedEffort": launch.requested_effort,
                "quotaDomain": launch.quota_domain,
                "requestMessageSha256": request_message_sha256,
                "renderedMessageSha256": rendered_message_sha256,
                "requestSessionId": launch.request_session_id,
                "backendState": "pending",
                "pid": launch.pid,
                "logPath": launch.log_path.display().to_string(),
                "probeOffset": 0,
                "probeEnd": probe_end,
                "legacyProbeOffset": launch.legacy_offset,
                "legacyProbe": launch.legacy_probe.as_str(),
                "method": "typed-runtime",
            });
            bind_registered_wake_harness_identity(
                &mut wake_payload,
                launch.harness_id,
                launch.terminal_capability,
                &launch.harness_registry_digest,
            )?;
            debug_assert!(wake_payload.get("harnessId").is_some());
            debug_assert!(wake_payload.get("terminalCapability").is_some());
            debug_assert_eq!(
                wake_payload
                    .get("harnessRegistryDigest")
                    .and_then(serde_json::Value::as_str),
                Some(launch.harness_registry_digest.as_str())
            );
            ledger::append(
                root,
                round,
                &[ledger::event(
                    "WakeIssued",
                    "runtime:orch",
                    identity.task_id.as_deref(),
                    Some(round),
                    wake_payload,
                )],
            )?;
            let started = Instant::now();
            while !reconcile_backend_receipt_locked(root, round, &wake_id)? {
                if started.elapsed() >= review_probe_timeout() {
                    return failure::reject_action_command_outcome(
                        root,
                        round,
                        identity.task_id.as_deref(),
                        "wake-backend-receipt",
                        &wake_id,
                        "typed continuation backend receipt timed out",
                        failure::CommandOutcome::PendingReceipt,
                        None,
                    );
                }
                std::thread::sleep(Duration::from_millis(25));
            }
            Ok(DispatchWakeOutcome {
                injected: true,
                pid: Some(launch.pid),
                log_path: Some(launch.log_path),
                wake_id: Some(wake_id),
                provider_kind: Some(provider_kind),
                request_session_id: launch.request_session_id,
                runtime_limit: launch.runtime_limit,
                legacy_offset: Some(launch.legacy_offset),
                legacy_probe: launch.legacy_probe,
            })
        })
    })
}

/// Signed-active wrapper for explicit CLI handshake.  Generic Tier-F wake
/// remains a lower-level mechanism until the central single-use permit epic;
/// callers at a user-visible spawn boundary must choose this entry point.
pub fn dispatch_wake_authorized(
    root: &Path,
    agent: &str,
    round: &str,
    message: &str,
    no_wake: bool,
) -> Result<DispatchWakeOutcome> {
    validate_wake_permit(root, round, agent, None)?;
    if no_wake {
        return dispatch_wake(root, agent, round, message, true);
    }
    let registry = load_registry(root)?;
    let spec = registry
        .get(agent)
        .with_context(|| format!("AgentRegistry 未注册 agent: {agent}"))?;
    if !spec.injectable || spec.session_id.is_empty() {
        return dispatch_wake(root, agent, round, message, false);
    }
    let wake_id = fresh_managed_wake_id();
    let continuation_id = format!("manual:{round}:{wake_id}:{agent}");
    dispatch_wake_for_continuation(root, agent, round, &continuation_id, message, false)
}

/// POKE 粘贴词渲染（design/10 §4 之③）：{round} 占位替换；无占位原样直通。
pub fn render_poke(hint_template: &str, round: &str) -> String {
    hint_template.replace("{round}", round)
}

/// 会话切换决策：in-flight 时携带警告文案（不禁止，用户有最终权）。
pub struct SetSessionDecision {
    pub warning: Option<String>,
}

pub fn set_session_decision(task_inflight: bool) -> SetSessionDecision {
    let warning = if task_inflight {
        Some(
            "该 agent 有 in-flight 任务未闭合；切换会话可能中断进行中的棒（用户有最终权）"
                .to_string(),
        )
    } else {
        None
    };
    SetSessionDecision { warning }
}

/// 注册表查找语义：未知 agent → Err（文案含其名）。
pub fn validate_agent(known: &[String], agent: &str) -> Result<(), String> {
    if known.iter().any(|k| k == agent) {
        Ok(())
    } else {
        Err(format!(
            "未知 agent: {agent}（不在 AgentRegistry 注册表内）"
        ))
    }
}

