    #[test]
    fn b312_canceled_panel_terminal_distinguishes_archive_from_late_convergence() {
        let residual_reason = serde_json::json!(concat!(
            "helper cleanup refused; ",
            "residual-convergence-budget-exhausted: pgid=40328; unresolvedPids=[3096]; ",
            "residual-convergence-budget-exhausted: pgid=59147; unresolvedPids=[59147]"
        ));
        let exact_proof = serde_json::json!(PANEL_LATE_CONVERGENCE_PROOF_DARWIN_PASSIVE_V1);
        assert_eq!(
            classify_review_panel_invalid_v1(
                "executor-pi",
                "canceled",
                residual_reason.as_str().unwrap(),
                Some("manual-cancel"),
                Some("01a04b9a-1abd-4b5a-b76d-a6bff9547264"),
                None,
            )
            .unwrap(),
            ReviewPanelSeatStateV1::BusinessInvalid
        );
        assert_eq!(
            classify_review_panel_invalid_v1(
                "executor-pi",
                "canceled",
                "provider/cancelReason is not an authority surface",
                Some("manual-cancel"),
                Some("01a04b9a-1abd-4b5a-b76d-a6bff9547264"),
                Some(&exact_proof),
            )
            .unwrap(),
            ReviewPanelSeatStateV1::SystemInvalid
        );
        assert_eq!(
            classify_review_panel_invalid_v1(
                "executor-pi",
                "answered",
                "artifact invalid",
                None,
                None,
                None,
            )
            .unwrap(),
            ReviewPanelSeatStateV1::BusinessInvalid
        );
        for unknown in [
            serde_json::json!("darwin-passive-v2"),
            serde_json::json!(true),
        ] {
            assert!(classify_review_panel_invalid_v1(
                "executor-pi",
                "canceled",
                residual_reason.as_str().unwrap(),
                Some("manual-cancel"),
                Some("01a04b9a-1abd-4b5a-b76d-a6bff9547264"),
                Some(&unknown),
            )
            .is_err());
        }
        for (completion, request_id) in [
            (
                Some("natural-exit"),
                Some("01a04b9a-1abd-4b5a-b76d-a6bff9547264"),
            ),
            (Some("manual-cancel"), None),
            (Some("manual-cancel"), Some("not-a-strict-uuid")),
        ] {
            assert!(classify_review_panel_invalid_v1(
                "executor-pi",
                "canceled",
                "forged canceled terminal",
                completion,
                request_id,
                Some(&exact_proof),
            )
            .is_err());
        }
    }

