    #[test]
    fn b189_canonical_containment_bundle_keeps_all_claim_fields_consistent() {
        let observed =
            normalize_managed_containment(ManagedContainmentCapability::ObservedReceipted, true);
        assert_eq!(
            observed.claim,
            ManagedContainmentClaim::ManagedScopeTerminated
        );
        assert!(observed.managed_scope_terminated);
        assert!(!observed.fork_complete);
        assert!(!observed.legacy_process_tree_terminated);

        let incomplete =
            normalize_managed_containment(ManagedContainmentCapability::ForkComplete, false);
        assert_eq!(
            incomplete.claim,
            ManagedContainmentClaim::ContainmentUnproven
        );
        assert!(!incomplete.managed_scope_terminated);
        assert!(!incomplete.fork_complete);
        assert!(!incomplete.legacy_process_tree_terminated);

        let complete =
            normalize_managed_containment(ManagedContainmentCapability::ForkComplete, true);
        assert_eq!(
            complete.claim,
            ManagedContainmentClaim::ForkCompleteTerminated
        );
        assert!(complete.managed_scope_terminated);
        assert!(complete.fork_complete);
        assert!(complete.legacy_process_tree_terminated);
    }

