    fn wait_for_managed_supervisor_reaped(
        supervisor_dir: &Path,
        descriptor: &ManagedWakeControlDescriptor,
        deadline: Instant,
    ) {
        let sidecar = supervisor_dir.join(format!("{}.reap.json", descriptor.token));
        loop {
            let value: serde_json::Value =
                serde_json::from_slice(&fs::read(&sidecar).unwrap()).unwrap();
            assert_eq!(value["ownerKind"], "managedSupervisor");
            assert_eq!(value["pid"], descriptor.supervisor_pid);
            assert_eq!(value["pgid"], descriptor.supervisor_pid);
            if value["state"] == "reaped" {
                assert_eq!(value["exitCode"], 0);
                assert!(value.get("waitError").is_none());
                assert!(value.get("reapedAt").is_some());
                assert!(!process_group_alive_exact(descriptor.supervisor_pid).unwrap());
                return;
            }
            assert_eq!(value["state"], "waiting");
            assert!(
                Instant::now() < deadline,
                "managed supervisor exact-Child reaper did not finish: {value}"
            );
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    #[test]
    fn b181_exact_child_reaper_publishes_waiting_then_reaped() {
        let root = temp_root("b181-exact-child-reaper");
        fs::create_dir_all(root.join("coordination/runtime")).unwrap();
        let token = "18118118118118118118118118118118";
        let release = root.join("release");
        let plan = wake_owner_lifecycle_plan(WakeOwnerKind::WakeLogProxy);
        assert!(plan.prearm_reaper);
        let reaper = prepare_wake_owner_reaper(&root, token, WakeOwnerKind::WakeLogProxy)
            .expect("reaper must be armed before spawn");

        let mut command = Command::new("/bin/sh");
        command.args([
            "-c",
            "while [ ! -f \"$1\" ]; do sleep 0.01; done",
            "b181-reaper",
            release.to_str().unwrap(),
        ]);
        if plan.isolate_process_group {
            command.process_group(0);
        }
        let child = command.spawn().unwrap();
        let pid = child.id();
        reaper
            .handoff(child)
            .expect("handoff waits until waiting sidecar is durable");

        let sidecar = authenticated_supervisor_dir(&root, false)
            .unwrap()
            .join(format!("{token}.reap.json"));
        let waiting: serde_json::Value =
            serde_json::from_slice(&fs::read(&sidecar).unwrap()).unwrap();
        assert_eq!(waiting["state"], "waiting");
        assert_eq!(waiting["ownerKind"], "wakeLogProxy");
        assert_eq!(waiting["pid"], pid);
        assert_eq!(waiting["pgid"], pid);
        assert!(process_group_alive_exact(pid).unwrap());

        fs::write(&release, b"release\n").unwrap();
        let deadline = Instant::now() + Duration::from_secs(3);
        let reaped = loop {
            let value: serde_json::Value =
                serde_json::from_slice(&fs::read(&sidecar).unwrap()).unwrap();
            if value["state"] == "reaped" {
                break value;
            }
            assert!(
                Instant::now() < deadline,
                "exact Child reaper did not publish reaped state: {value}"
            );
            std::thread::sleep(Duration::from_millis(5));
        };
        assert_eq!(reaped["pid"], pid);
        assert_eq!(reaped["exitCode"], 0);
        assert!(reaped.get("reapedAt").is_some());
        assert!(!process_group_alive_exact(pid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

    fn remaining_test_deadline(deadline: Instant, label: &str) -> Result<Duration> {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            bail!("{label} exceeded the single fixture deadline");
        }
        Ok(remaining)
    }

    fn wait_for_fixture_file(path: &Path, deadline: Instant, label: &str) -> Result<()> {
        while Instant::now() < deadline {
            if path.is_file() {
                return Ok(());
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        bail!("{label} did not appear before the single fixture deadline")
    }

