    #[test]
    fn b177_zombie_epoch_sentinel_never_anchors_a_live_process() {
        let mut epoch = synthetic_credential(10, std::process::id(), 10);
        epoch.sid = 10;
        epoch.executable_summary = ZOMBIE_PROVIDER_EPOCH_EXECUTABLE.to_string();
        let mut provider = synthetic_topology(10, std::process::id(), 10);
        provider.sid = 10;
        let mut unrelated = synthetic_topology(31, 1, 31);
        unrelated.sid = 10;
        let owned = BTreeMap::from([(epoch.pid, epoch.clone())]);
        let live_snapshot = BTreeMap::from([
            (provider.pid, provider.clone()),
            (unrelated.pid, unrelated.clone()),
        ]);
        assert!(!owned_lineage_root_matches(&epoch, &provider, Some(10)));
        assert!(!lineage_pids(10, Some(10), &owned, &live_snapshot)
            .unwrap()
            .contains(&unrelated.pid));
        assert!(!credential_identity_matches(
            &epoch,
            &synthetic_credential(10, std::process::id(), 10)
        ));

        provider.zombie = true;
        let zombie_snapshot =
            BTreeMap::from([(provider.pid, provider), (unrelated.pid, unrelated.clone())]);
        assert!(lineage_pids(10, Some(10), &owned, &zombie_snapshot)
            .unwrap()
            .contains(&unrelated.pid));
    }

