    /// Test-only last-resort owner. Every fixture test still exercises the
    /// production convergence path first; this guard exists so a failed
    /// assertion cannot leave the regression harness itself as PPID 1 or
    /// strand helper PGIDs, which was the field symptom that triggered A0002.
    struct FixtureProcessGuard {
        provider_pgid: u32,
        owned: BTreeMap<u32, ManagedProcessCredential>,
        helper_pid_files: Vec<PathBuf>,
        child: Option<Child>,
    }

    #[derive(Debug)]
    struct ExactGroupWatchdogEvidence {
        pgid: u32,
        proof_before_term: Option<GroupCredentialProof>,
        term_sent: bool,
        proof_before_kill: Option<GroupCredentialProof>,
        kill_sent: bool,
        proof_after_kill: Option<GroupCredentialProof>,
        esrch: bool,
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum B177LatestDisposition {
        Gone,
        ZombiePendingProviderReap,
        LiveOrAmbiguous,
    }

    impl ExactGroupWatchdogEvidence {
        fn latest_disposition(&self) -> B177LatestDisposition {
            if self.esrch {
                return B177LatestDisposition::Gone;
            }
            let latest = self
                .proof_after_kill
                .or(self.proof_before_kill)
                .or(self.proof_before_term);
            match latest {
                Some(GroupCredentialProof::AlreadyGone) => B177LatestDisposition::Gone,
                Some(GroupCredentialProof::OwnedZombieOnly) => {
                    B177LatestDisposition::ZombiePendingProviderReap
                }
                Some(GroupCredentialProof::OwnedLive) | None => {
                    B177LatestDisposition::LiveOrAmbiguous
                }
            }
        }

        fn summary(&self) -> String {
            format!(
                "pgid={} beforeTERM={:?} termSent={} beforeKILL={:?} killSent={} afterKILL={:?} esrch={} latest={:?}",
                self.pgid,
                self.proof_before_term,
                self.term_sent,
                self.proof_before_kill,
                self.kill_sent,
                self.proof_after_kill,
                self.esrch,
                self.latest_disposition()
            )
        }
    }

    fn watchdog_group_proof(
        pgid: u32,
        owned: &BTreeMap<u32, ManagedProcessCredential>,
    ) -> Result<GroupCredentialProof> {
        revalidate_group_credentials(&mut ProcessObserver::default(), pgid, owned)
            .map_err(|errors| anyhow::anyhow!(errors.join("; ")))
    }

    fn watchdog_signal_before_deadline<P, S>(
        deadline: Instant,
        prove: P,
        send: S,
    ) -> Result<(Option<GroupCredentialProof>, bool)>
    where
        P: FnOnce() -> Result<GroupCredentialProof>,
        S: FnOnce() -> Result<()>,
    {
        if Instant::now() >= deadline {
            return Ok((None, false));
        }
        let proof = prove()?;
        if proof != GroupCredentialProof::OwnedLive || Instant::now() >= deadline {
            return Ok((Some(proof), false));
        }
        // Keep the authorization-to-signal edge inside this helper so every
        // caller uses the same absolute deadline immediately before the
        // syscall (or injected test send).
        if Instant::now() >= deadline {
            return Ok((Some(proof), false));
        }
        send()?;
        Ok((Some(proof), true))
    }

    /// Last-resort test cleanup. Signals remain birth-bound through the same
    /// production exact-group proof; the short raw waits are evidence only.
    /// This helper never turns an ambiguous or zombie-only group into a signal
    /// target.
    fn run_exact_group_watchdog(
        pgid: u32,
        owned: &BTreeMap<u32, ManagedProcessCredential>,
        deadline: Instant,
    ) -> Result<ExactGroupWatchdogEvidence> {
        fn send_exact(pgid: u32, signal: i32) -> Result<()> {
            let pgid = i32::try_from(pgid).context("watchdog pgid exceeds pid_t")?;
            // SAFETY: the caller obtained a fresh production ownership proof
            // for this exact disposable fixture group immediately beforehand.
            if unsafe { libc_kill(-pgid, signal) } == 0 {
                Ok(())
            } else {
                let error = io::Error::last_os_error();
                if error.raw_os_error() == Some(3) {
                    Ok(())
                } else {
                    Err(error).context("watchdog exact-group signal failed")
                }
            }
        }

        let (proof_before_term, term_sent) = watchdog_signal_before_deadline(
            deadline,
            || watchdog_group_proof(pgid, owned),
            || send_exact(pgid, 15),
        )?;
        let term_probe_deadline = deadline.min(Instant::now() + Duration::from_millis(25));
        while process_group_alive_exact(pgid)? && Instant::now() < term_probe_deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let (proof_before_kill, kill_sent) = watchdog_signal_before_deadline(
            deadline,
            || watchdog_group_proof(pgid, owned),
            || send_exact(pgid, 9),
        )?;
        if proof_before_kill == Some(GroupCredentialProof::OwnedZombieOnly) {
            return Ok(ExactGroupWatchdogEvidence {
                pgid,
                proof_before_term,
                term_sent,
                proof_before_kill,
                kill_sent,
                proof_after_kill: None,
                esrch: !process_group_alive_exact(pgid)?,
            });
        }
        let post_kill_probe_deadline = deadline.min(Instant::now() + Duration::from_millis(25));
        while process_group_alive_exact(pgid)? && Instant::now() < post_kill_probe_deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let proof_after_kill = if kill_sent && Instant::now() < deadline {
            Some(watchdog_group_proof(pgid, owned)?)
        } else {
            None
        };
        if matches!(
            proof_after_kill,
            Some(GroupCredentialProof::AlreadyGone | GroupCredentialProof::OwnedZombieOnly)
        ) {
            return Ok(ExactGroupWatchdogEvidence {
                pgid,
                proof_before_term,
                term_sent,
                proof_before_kill,
                kill_sent,
                proof_after_kill,
                esrch: !process_group_alive_exact(pgid)?,
            });
        }
        while process_group_alive_exact(pgid)? && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        Ok(ExactGroupWatchdogEvidence {
            pgid,
            proof_before_term,
            term_sent,
            proof_before_kill,
            kill_sent,
            proof_after_kill,
            esrch: !process_group_alive_exact(pgid)?,
        })
    }

    #[test]
    fn b177_watchdog_slow_proof_sends_no_signal_after_absolute_deadline() {
        let signals = std::cell::RefCell::new(Vec::new());
        let deadline = Instant::now() + Duration::from_millis(2);
        let (term_proof, term_sent) = watchdog_signal_before_deadline(
            deadline,
            || {
                std::thread::sleep(Duration::from_millis(5));
                Ok(GroupCredentialProof::OwnedLive)
            },
            || {
                signals
                    .borrow_mut()
                    .push(crate::tierf::TerminationSignal::Term);
                Ok(())
            },
        )
        .unwrap();
        let (kill_proof, kill_sent) = watchdog_signal_before_deadline(
            deadline,
            || Ok(GroupCredentialProof::OwnedLive),
            || {
                signals
                    .borrow_mut()
                    .push(crate::tierf::TerminationSignal::Kill);
                Ok(())
            },
        )
        .unwrap();

        assert_eq!(term_proof, Some(GroupCredentialProof::OwnedLive));
        assert_eq!(kill_proof, None);
        assert!(!term_sent);
        assert!(!kill_sent);
        assert!(signals.into_inner().is_empty());
    }

    #[test]
    fn b177_watchdog_disposition_uses_only_latest_typed_evidence() {
        let historical_zombie_then_live = ExactGroupWatchdogEvidence {
            pgid: 41,
            proof_before_term: Some(GroupCredentialProof::OwnedZombieOnly),
            term_sent: false,
            proof_before_kill: Some(GroupCredentialProof::OwnedLive),
            kill_sent: false,
            proof_after_kill: None,
            esrch: false,
        };
        assert_eq!(
            historical_zombie_then_live.latest_disposition(),
            B177LatestDisposition::LiveOrAmbiguous
        );

        let latest_zombie = ExactGroupWatchdogEvidence {
            proof_after_kill: Some(GroupCredentialProof::OwnedZombieOnly),
            ..historical_zombie_then_live
        };
        assert_eq!(
            latest_zombie.latest_disposition(),
            B177LatestDisposition::ZombiePendingProviderReap
        );
    }

    struct B177FailureCleanup {
        completed: Option<Result<SupervisionDetails>>,
        diagnostics: Vec<String>,
        joined: bool,
        helper_before_join: B177LatestDisposition,
        provider_before_join: B177LatestDisposition,
        helper_after_join: B177LatestDisposition,
        provider_after_join: B177LatestDisposition,
    }

    fn b177_supervisor_completion_budget(policy: WakeSupervisorPolicy) -> Duration {
        // Main cleanup has at most 64 poll-backed discovery passes, one
        // TERM/KILL window, the two 2s provider/zombie reap windows, and a
        // 500ms scheduling margin. This is derived from the policy used by
        // the test rather than an unrelated fixed recv timeout.
        let millis = policy
            .natural_exit_grace_ms
            .saturating_add(policy.term_grace_ms.saturating_mul(6))
            .saturating_add(policy.poll_interval_ms.saturating_mul(70))
            .saturating_add(4_500);
        Duration::from_millis(millis)
    }

    fn b177_capture_related_marker_receipt(
        provider: &ManagedProcessCredential,
        marker: &Path,
        deadline: Instant,
    ) -> Option<ManagedProcessCredential> {
        while Instant::now() < deadline {
            let candidate = fs::read_to_string(marker)
                .ok()
                .and_then(|text| text.lines().next()?.trim().parse::<u32>().ok())
                .and_then(|pid| inspect_stable_process(pid).ok().flatten());
            if let Some(receipt) = candidate {
                let direct_child = receipt.observed_ppid == provider.pid;
                let same_isolated_session = provider.sid == provider.pid
                    && receipt.sid == provider.sid
                    && receipt.uid == provider.uid;
                if receipt.pid != provider.pid && (direct_child || same_isolated_session) {
                    return Some(receipt);
                }
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        None
    }

    fn b177_receipt_epoch_disposition_from_pair(
        receipts: &[ManagedProcessCredential],
        before: &ProcessTopologyCensus,
        after: &ProcessTopologyCensus,
    ) -> Result<B177LatestDisposition> {
        if receipts.is_empty() {
            return Ok(B177LatestDisposition::Gone);
        }
        let mut zombie_pending = false;
        for receipt in receipts {
            if owned_epoch_retired_by_stable_pair(receipt, before, after)? {
                continue;
            }
            let first = normalized_zombie_epoch(before, receipt.pid)?;
            let second = normalized_zombie_epoch(after, receipt.pid)?;
            let stable_owned_zombie =
                first
                    .as_ref()
                    .zip(second.as_ref())
                    .is_some_and(|(first, second)| {
                        first.same_epoch_and_structure(second)
                            && first.pid == receipt.pid
                            && first.uid == receipt.uid
                            && first.birth_identity == receipt.birth_identity
                    });
            if stable_owned_zombie {
                zombie_pending = true;
            } else {
                return Ok(B177LatestDisposition::LiveOrAmbiguous);
            }
        }
        Ok(if zombie_pending {
            B177LatestDisposition::ZombiePendingProviderReap
        } else {
            B177LatestDisposition::Gone
        })
    }

    fn b177_fresh_receipt_epoch_disposition(
        receipts: &[ManagedProcessCredential],
    ) -> Result<B177LatestDisposition> {
        let before = process_topology_census().context("fresh receipt epoch census A failed")?;
        let after = process_topology_census().context("fresh receipt epoch census B failed")?;
        b177_receipt_epoch_disposition_from_pair(receipts, &before, &after)
    }

    fn b177_stricter_disposition(
        group: B177LatestDisposition,
        epoch: B177LatestDisposition,
    ) -> B177LatestDisposition {
        match (group, epoch) {
            (B177LatestDisposition::LiveOrAmbiguous, _)
            | (_, B177LatestDisposition::LiveOrAmbiguous) => B177LatestDisposition::LiveOrAmbiguous,
            (B177LatestDisposition::ZombiePendingProviderReap, _)
            | (_, B177LatestDisposition::ZombiePendingProviderReap) => {
                B177LatestDisposition::ZombiePendingProviderReap
            }
            (B177LatestDisposition::Gone, B177LatestDisposition::Gone) => {
                B177LatestDisposition::Gone
            }
        }
    }

    fn b177_harden_group_with_fresh_epoch(
        label: &str,
        group: B177LatestDisposition,
        receipts: &[ManagedProcessCredential],
        diagnostics: &mut Vec<String>,
    ) -> B177LatestDisposition {
        match b177_fresh_receipt_epoch_disposition(receipts) {
            Ok(epoch) => {
                let disposition = b177_stricter_disposition(group, epoch);
                diagnostics.push(format!(
                    "{label} disposition group={group:?} epoch={epoch:?} effective={disposition:?}"
                ));
                disposition
            }
            Err(error) => {
                diagnostics.push(format!("{label} fresh epoch proof failed: {error:#}"));
                B177LatestDisposition::LiveOrAmbiguous
            }
        }
    }

    fn b177_fresh_epoch_retirement_disposition(
        receipts: &[ManagedProcessCredential],
    ) -> Result<B177LatestDisposition> {
        Ok(match b177_fresh_receipt_epoch_disposition(receipts)? {
            B177LatestDisposition::Gone => B177LatestDisposition::Gone,
            B177LatestDisposition::ZombiePendingProviderReap
            | B177LatestDisposition::LiveOrAmbiguous => B177LatestDisposition::LiveOrAmbiguous,
        })
    }

    fn b177_fresh_epoch_retirement_until(
        receipts: &[ManagedProcessCredential],
        deadline: Instant,
    ) -> B177LatestDisposition {
        loop {
            match b177_fresh_epoch_retirement_disposition(receipts) {
                Ok(B177LatestDisposition::Gone) => return B177LatestDisposition::Gone,
                Ok(_) | Err(_) if Instant::now() < deadline => {
                    std::thread::sleep(Duration::from_millis(5));
                }
                Ok(disposition) => return disposition,
                Err(_) => return B177LatestDisposition::LiveOrAmbiguous,
            }
        }
    }

    fn b177_bounded_fixture_failure_cleanup(
        label: &str,
        release_paths: &[PathBuf],
        helper_marker: Option<&Path>,
        helper_receipt: &mut Option<ManagedProcessCredential>,
        provider: &ManagedProcessCredential,
        policy: WakeSupervisorPolicy,
        done_rx: &std::sync::mpsc::Receiver<Result<SupervisionDetails>>,
        supervisor: &mut Option<std::thread::JoinHandle<()>>,
    ) -> B177FailureCleanup {
        let total_deadline = Instant::now() + b177_supervisor_completion_budget(policy);
        let provider_reserve =
            Duration::from_millis(policy.term_grace_ms.saturating_mul(3).saturating_add(750));
        let helper_deadline = total_deadline
            .checked_sub(provider_reserve)
            .unwrap_or(total_deadline);
        let mut diagnostics = Vec::new();

        // Prefer capturing the helper while the provider relationship is
        // still live. Release is idempotent; a second short rediscovery covers
        // a marker installed concurrently with the failure edge.
        if helper_receipt.is_none() {
            if let Some(marker) = helper_marker {
                *helper_receipt = b177_capture_related_marker_receipt(
                    provider,
                    marker,
                    helper_deadline.min(Instant::now() + Duration::from_millis(100)),
                );
            }
        }
        for path in release_paths {
            let _ = fs::write(path, b"release\n");
        }
        if helper_receipt.is_none() {
            if let Some(marker) = helper_marker {
                *helper_receipt = b177_capture_related_marker_receipt(
                    provider,
                    marker,
                    helper_deadline.min(Instant::now() + Duration::from_millis(150)),
                );
            }
        }

        let mut provider_owned = BTreeMap::from([(provider.pid, provider.clone())]);
        if let Some(helper) = helper_receipt.as_ref() {
            if helper.pgid == provider.pgid {
                provider_owned.insert(helper.pid, helper.clone());
            }
        }
        // A same-PGID helper has no independent helper group: it is covered
        // by the provider group's fresh proof below. A declared cross-PGID
        // helper, in contrast, must reach a latest Gone/Zombie disposition
        // before any provider signal is considered.
        let helper_before_join = match helper_receipt.as_ref() {
            Some(helper) if helper.pgid == provider.pgid => B177LatestDisposition::Gone,
            Some(helper) if Instant::now() < helper_deadline => {
                let owned = BTreeMap::from([(helper.pid, helper.clone())]);
                match run_exact_group_watchdog(helper.pgid, &owned, helper_deadline) {
                    Ok(evidence) => {
                        let group = evidence.latest_disposition();
                        diagnostics.push(format!("helper {}", evidence.summary()));
                        b177_harden_group_with_fresh_epoch(
                            "helper",
                            group,
                            std::slice::from_ref(helper),
                            &mut diagnostics,
                        )
                    }
                    Err(error) => {
                        diagnostics.push(format!("helper watchdog error: {error:#}"));
                        B177LatestDisposition::LiveOrAmbiguous
                    }
                }
            }
            Some(_) => {
                diagnostics.push("cross-PGID helper cleanup budget expired before proof".into());
                B177LatestDisposition::LiveOrAmbiguous
            }
            None if helper_marker.is_none() => B177LatestDisposition::Gone,
            None => {
                diagnostics.push("declared helper marker lacked a current bound receipt".into());
                B177LatestDisposition::LiveOrAmbiguous
            }
        };
        let helper_allows_provider = matches!(
            helper_before_join,
            B177LatestDisposition::Gone | B177LatestDisposition::ZombiePendingProviderReap
        );
        let retry_reserve = Duration::from_millis(100);
        let first_provider_deadline = total_deadline
            .checked_sub(retry_reserve)
            .unwrap_or(total_deadline);
        let provider_receipts = provider_owned.values().cloned().collect::<Vec<_>>();
        let mut provider_before_join = B177LatestDisposition::LiveOrAmbiguous;
        if helper_allows_provider && Instant::now() < first_provider_deadline {
            match run_exact_group_watchdog(provider.pgid, &provider_owned, first_provider_deadline)
            {
                Ok(evidence) => {
                    let group = evidence.latest_disposition();
                    diagnostics.push(format!("provider {}", evidence.summary()));
                    provider_before_join = b177_harden_group_with_fresh_epoch(
                        "provider",
                        group,
                        &provider_receipts,
                        &mut diagnostics,
                    );
                }
                Err(error) => diagnostics.push(format!("provider watchdog error: {error:#}")),
            }
        }
        if helper_allows_provider
            && provider_before_join == B177LatestDisposition::LiveOrAmbiguous
            && Instant::now() < total_deadline
        {
            match run_exact_group_watchdog(provider.pgid, &provider_owned, total_deadline) {
                Ok(evidence) => {
                    let group = evidence.latest_disposition();
                    diagnostics.push(format!("provider retry {}", evidence.summary()));
                    provider_before_join = b177_harden_group_with_fresh_epoch(
                        "provider retry",
                        group,
                        &provider_receipts,
                        &mut diagnostics,
                    );
                }
                Err(error) => diagnostics.push(format!("provider retry watchdog error: {error:#}")),
            }
        } else if !helper_allows_provider {
            diagnostics.push(format!(
                "provider watchdog blocked by latest helper disposition {helper_before_join:?}"
            ));
        }

        let mut completed = if Instant::now() < total_deadline {
            done_rx
                .recv_timeout(total_deadline.saturating_duration_since(Instant::now()))
                .ok()
        } else {
            done_rx.try_recv().ok()
        };
        if completed.is_none() {
            diagnostics.push(format!(
                "{label} completion deadline exhausted: helperLatest={helper_before_join:?} providerLatest={provider_before_join:?}"
            ));
        }

        // Never detach a cleanup thread. Even when external evidence is not
        // yet settled, synchronous join keeps the thread's ManagedTreeOwner
        // and unique Child handle alive as cleanup authority.
        let joined = supervisor
            .take()
            .expect("fixture supervisor JoinHandle missing")
            .join()
            .is_ok();
        if completed.is_none() {
            completed = done_rx.try_recv().ok();
        }
        if let Some(Ok(details)) = completed.as_mut() {
            converge_supervision_residual(details);
        }
        let helper_after_join = if helper_marker.is_some() && helper_receipt.is_none() {
            diagnostics.push(
                "post-join helper retirement remains ambiguous: declared marker has no receipt"
                    .into(),
            );
            B177LatestDisposition::LiveOrAmbiguous
        } else {
            let helper_receipts = helper_receipt.iter().cloned().collect::<Vec<_>>();
            match b177_fresh_epoch_retirement_disposition(&helper_receipts) {
                Ok(disposition) => disposition,
                Err(error) => {
                    diagnostics.push(format!("fresh helper retirement proof failed: {error:#}"));
                    B177LatestDisposition::LiveOrAmbiguous
                }
            }
        };
        let provider_after_join =
            match b177_fresh_epoch_retirement_disposition(std::slice::from_ref(provider)) {
                Ok(disposition) => disposition,
                Err(error) => {
                    diagnostics.push(format!("fresh provider retirement proof failed: {error:#}"));
                    B177LatestDisposition::LiveOrAmbiguous
                }
            };
        diagnostics.push(format!(
            "post-join fresh retirement: helper={helper_after_join:?} provider={provider_after_join:?}"
        ));
        B177FailureCleanup {
            completed,
            diagnostics,
            joined,
            helper_before_join,
            provider_before_join,
            helper_after_join,
            provider_after_join,
        }
    }

    struct FakeGroupControl {
        proofs: VecDeque<std::result::Result<GroupCredentialProof, Vec<String>>>,
        waits: VecDeque<Result<bool>>,
        signals: Vec<crate::tierf::TerminationSignal>,
    }

    struct ProofCadenceGroupControl {
        proofs: VecDeque<std::result::Result<GroupCredentialProof, Vec<String>>>,
        waits: VecDeque<Result<bool>>,
        signals: Vec<crate::tierf::TerminationSignal>,
        proof_calls: usize,
        proof_delays: VecDeque<Duration>,
        wait_budgets: Vec<Duration>,
    }

    struct LateForkGroupControl<'a> {
        observer: ProcessObserver,
        child: &'a mut Child,
        release_path: PathBuf,
        helper_ready: PathBuf,
        kill_attempts: usize,
        signals: Vec<crate::tierf::TerminationSignal>,
    }

    struct SetpgidForkWindowGroupControl<'a> {
        observer: ProcessObserver,
        child: &'a mut Child,
        release_path: PathBuf,
        helper_ready: PathBuf,
        kill_attempts: usize,
        signals: Vec<crate::tierf::TerminationSignal>,
        observed_late_member: Option<(MemberContainment, ManagedProcessCredential)>,
    }

    impl ManagedGroupControl for FakeGroupControl {
        fn prove(
            &mut self,
            _pgid: u32,
            _owned: &BTreeMap<u32, ManagedProcessCredential>,
        ) -> std::result::Result<GroupCredentialProof, Vec<String>> {
            self.proofs.pop_front().expect("missing fake proof")
        }

        fn send(&mut self, _pgid: u32, signal: crate::tierf::TerminationSignal) -> Result<()> {
            self.signals.push(signal);
            Ok(())
        }

        fn wait_until_gone(&mut self, _pgid: u32, _grace: Duration) -> Result<bool> {
            self.waits.pop_front().expect("missing fake wait")
        }
    }

    impl ManagedGroupControl for ProofCadenceGroupControl {
        fn prove(
            &mut self,
            _pgid: u32,
            _owned: &BTreeMap<u32, ManagedProcessCredential>,
        ) -> std::result::Result<GroupCredentialProof, Vec<String>> {
            self.proof_calls += 1;
            if let Some(delay) = self.proof_delays.pop_front() {
                std::thread::sleep(delay);
            }
            self.proofs.pop_front().expect("missing cadence proof")
        }

        fn send(&mut self, _pgid: u32, signal: crate::tierf::TerminationSignal) -> Result<()> {
            self.signals.push(signal);
            Ok(())
        }

        fn wait_until_gone(&mut self, _pgid: u32, grace: Duration) -> Result<bool> {
            self.wait_budgets.push(grace);
            self.waits.pop_front().expect("missing cadence wait")
        }
    }

    impl ManagedGroupControl for LateForkGroupControl<'_> {
        fn prove(
            &mut self,
            pgid: u32,
            owned: &BTreeMap<u32, ManagedProcessCredential>,
        ) -> std::result::Result<GroupCredentialProof, Vec<String>> {
            revalidate_group_credentials(&mut self.observer, pgid, owned)
        }

        fn send(&mut self, pgid: u32, signal: crate::tierf::TerminationSignal) -> Result<()> {
            self.signals.push(signal);
            if signal == crate::tierf::TerminationSignal::Term {
                return Ok(());
            }
            self.kill_attempts += 1;
            if self.kill_attempts == 1 {
                // Deterministically model the kernel boundary where the owned
                // leader exits while a just-forked same-session member survives
                // the first group KILL delivery. The next production proof
                // sees a leader-gone, non-empty original PGID.
                fs::write(&self.release_path, b"fork\n")?;
                let deadline = Instant::now() + Duration::from_secs(5);
                while !self.helper_ready.is_file() && Instant::now() < deadline {
                    std::thread::sleep(Duration::from_millis(5));
                }
                if !self.helper_ready.is_file() {
                    bail!("late-fork fixture did not publish helper readiness");
                }
                loop {
                    match inspect_opaque_zombie(self.child.id()) {
                        Ok(Some(_)) => break,
                        Ok(None) => {}
                        Err(error) if error.to_string().contains("proved a live process") => {}
                        Err(error) => return Err(error),
                    }
                    if Instant::now() >= deadline {
                        bail!("late-fork fixture leader did not become an unreaped zombie");
                    }
                    std::thread::sleep(Duration::from_millis(5));
                }
                return Ok(());
            }
            let pid = i32::try_from(pgid).context("late-fork pgid exceeds pid_t")?;
            // SAFETY: the preceding production prove call revalidated the
            // original non-empty isolated group and every live member.
            if unsafe { libc_kill(-pid, 9) } != 0 {
                return Err(io::Error::last_os_error()).context("late-fork repeated KILL failed");
            }
            Ok(())
        }

        fn wait_until_gone(&mut self, pgid: u32, grace: Duration) -> Result<bool> {
            if self.kill_attempts < 2 {
                return Ok(false);
            }
            let deadline = Instant::now() + grace;
            loop {
                if !process_group_alive_exact(pgid)? {
                    return Ok(true);
                }
                if Instant::now() >= deadline {
                    return Ok(false);
                }
                std::thread::sleep(Duration::from_millis(5));
            }
        }
    }

    impl ManagedGroupControl for SetpgidForkWindowGroupControl<'_> {
        fn prove(
            &mut self,
            pgid: u32,
            owned: &BTreeMap<u32, ManagedProcessCredential>,
        ) -> std::result::Result<GroupCredentialProof, Vec<String>> {
            if self.observed_late_member.is_none() && self.helper_ready.is_file() {
                let helper_pid = fs::read_to_string(&self.helper_ready)
                    .map_err(|error| vec![format!("read late member pid failed: {error}")])?
                    .trim()
                    .parse::<u32>()
                    .map_err(|error| vec![format!("parse late member pid failed: {error}")])?;
                let helper = inspect_stable_process(helper_pid)
                    .map_err(|error| vec![format!("inspect late member failed: {error:#}")])?
                    .ok_or_else(|| vec!["late member disappeared before proof".to_string()])?;
                let leader = owned
                    .get(&pgid)
                    .ok_or_else(|| vec!["late member proof lacks owned leader".to_string()])?;
                let owned_pids = owned.keys().copied().collect::<BTreeSet<_>>();
                let containment = classify_group_member(
                    helper.pid,
                    helper.observed_ppid,
                    helper.pgid,
                    helper.sid,
                    helper.uid,
                    leader.pid,
                    leader.sid,
                    leader.uid,
                    &owned_pids,
                );
                self.observed_late_member = Some((containment, helper));
            }
            revalidate_group_credentials(&mut self.observer, pgid, owned)
        }

        fn send(&mut self, pgid: u32, signal: crate::tierf::TerminationSignal) -> Result<()> {
            self.signals.push(signal);
            if signal == crate::tierf::TerminationSignal::Term {
                return Ok(());
            }
            self.kill_attempts += 1;
            if self.kill_attempts == 1 {
                // Create the real child inside the first KILL delivery window,
                // but keep the setpgid-only leader alive so kernel PPID is a
                // deterministic owned-lineage edge for the next exact proof.
                fs::write(&self.release_path, b"fork\n")?;
                let deadline = Instant::now() + Duration::from_secs(5);
                while !self.helper_ready.is_file() && Instant::now() < deadline {
                    std::thread::sleep(Duration::from_millis(5));
                }
                if !self.helper_ready.is_file() {
                    bail!("setpgid late-fork fixture did not publish helper readiness");
                }
                return Ok(());
            }
            let pid = i32::try_from(pgid).context("setpgid late-fork pgid exceeds pid_t")?;
            // SAFETY: the immediately preceding production A/full/B proof
            // accepted the real child only through its owned PPID lineage.
            if unsafe { libc_kill(-pid, 9) } != 0 {
                return Err(io::Error::last_os_error())
                    .context("setpgid late-fork repeated KILL failed");
            }
            Ok(())
        }

        fn wait_until_gone(&mut self, pgid: u32, grace: Duration) -> Result<bool> {
            if self.kill_attempts < 2 {
                return Ok(false);
            }
            let deadline = Instant::now() + grace;
            loop {
                let _ = self
                    .child
                    .try_wait()
                    .context("reap setpgid late-fork provider")?;
                if !process_group_alive_exact(pgid)? {
                    return Ok(true);
                }
                if Instant::now() >= deadline {
                    return Ok(false);
                }
                std::thread::sleep(Duration::from_millis(5));
            }
        }
    }

    impl FixtureProcessGuard {
        fn new(child: Child, helper_pid_files: Vec<PathBuf>) -> Self {
            let provider_pgid = child.id();
            let mut guard = Self {
                provider_pgid,
                owned: BTreeMap::new(),
                helper_pid_files,
                child: Some(child),
            };
            if let Ok(Some(receipt)) = inspect_stable_process(provider_pgid) {
                let _ = guard.register_provider_receipt(receipt);
            }
            guard
        }

        fn provider_anchor_is_current(&self, receipt: &ManagedProcessCredential) -> Result<bool> {
            if inspect_stable_process(self.provider_pgid)?.as_ref() == Some(receipt) {
                return Ok(true);
            }
            Ok(capture_isolated_zombie_provider_epoch(self.provider_pgid)?
                .as_ref()
                .is_some_and(|epoch| {
                    epoch == receipt || launch_guard_cleanup_refresh_matches(receipt, epoch)
                }))
        }

        fn register_provider_receipt(&mut self, receipt: ManagedProcessCredential) -> Result<()> {
            if self.child.is_none() {
                bail!("fixture guard is disarmed");
            }
            if receipt.pid != self.provider_pgid || receipt.pgid != self.provider_pgid {
                bail!("fixture provider receipt does not bind the direct Child group");
            }
            if receipt.pid == 0 || receipt.sid == 0 {
                bail!("fixture provider receipt has a zero process identity");
            }
            if !self.provider_anchor_is_current(&receipt)? {
                bail!("fixture provider receipt is no longer current");
            }
            match self.owned.get(&receipt.pid) {
                Some(existing) if existing != &receipt => {
                    if !launch_guard_cleanup_refresh_matches(existing, &receipt) {
                        bail!("conflicting fixture provider receipt");
                    }
                }
                Some(_) => {}
                None => {
                    self.owned.insert(receipt.pid, receipt);
                }
            }
            Ok(())
        }

        fn register_helper_receipt(&mut self, receipt: ManagedProcessCredential) -> Result<()> {
            if self.child.is_none() {
                bail!("fixture guard is disarmed");
            }
            if receipt.pid == self.provider_pgid {
                return self.register_provider_receipt(receipt);
            }
            if receipt.pid == 0 || receipt.pgid == 0 || receipt.sid == 0 {
                bail!("fixture helper receipt has a zero process identity");
            }
            let provider = self
                .owned
                .get(&self.provider_pgid)
                .cloned()
                .context("fixture helper registration lacks a provider receipt")?;
            if !self.provider_anchor_is_current(&provider)? {
                bail!("fixture helper registration lacks a current provider anchor");
            }
            let current = inspect_stable_process(receipt.pid)?
                .context("fixture helper receipt is not a stable live process")?;
            if current != receipt {
                bail!("fixture helper receipt is no longer current");
            }
            let direct_child = receipt.observed_ppid == provider.pid;
            let same_isolated_session = provider.sid == provider.pid
                && receipt.sid == provider.sid
                && receipt.uid == provider.uid;
            if !direct_child && !same_isolated_session {
                bail!("fixture helper receipt has no exact provider relationship");
            }
            match self.owned.get(&receipt.pid) {
                Some(existing) if existing != &receipt => {
                    bail!("conflicting fixture helper receipt")
                }
                Some(_) => {}
                None => {
                    self.owned.insert(receipt.pid, receipt);
                }
            }
            Ok(())
        }

        fn discover_declared_helper_receipts(&mut self, deadline: Instant) {
            let Some(provider) = self.owned.get(&self.provider_pgid).cloned() else {
                return;
            };
            if !self.provider_anchor_is_current(&provider).unwrap_or(false) {
                return;
            }
            for path in self.helper_pid_files.clone() {
                if Instant::now() >= deadline {
                    return;
                }
                let Some(pid) = fs::read_to_string(path)
                    .ok()
                    .and_then(|text| text.lines().next()?.trim().parse::<u32>().ok())
                else {
                    continue;
                };
                if pid == self.provider_pgid {
                    continue;
                }
                // The marker is discovery only. A current kernel credential
                // plus a current exact provider relationship is the sole
                // authority admitted into `owned`.
                let Some(receipt) = inspect_stable_process(pid).ok().flatten() else {
                    continue;
                };
                let _ = self.register_helper_receipt(receipt);
            }
        }

        fn take_child(&mut self) -> Child {
            self.child.take().expect("fixture guard lost direct Child")
        }

        fn take_child_after_exact_admission(
            &mut self,
            admission_path: &Path,
            transfer_path: &Path,
        ) -> Child {
            let ack = fs::read(admission_path)
                .expect("provider-custody transfer requires outer admission ACK");
            assert_eq!(
                ack, b"admitted\n",
                "provider-custody transfer requires the exact admission ACK"
            );
            let child = self.take_child();
            if let Err(error) = atomic_publish_fixture_bytes(transfer_path, b"transferred\n") {
                self.child = Some(child);
                panic!("publish failure-meta transfer marker failed: {error:#}");
            }
            child
        }

        fn wait_until_exited(&mut self, timeout: Duration) -> bool {
            let deadline = Instant::now() + timeout;
            loop {
                if self
                    .child
                    .as_mut()
                    .and_then(|child| child.try_wait().ok())
                    .flatten()
                    .is_some()
                {
                    return true;
                }
                if Instant::now() >= deadline {
                    return false;
                }
                std::thread::sleep(Duration::from_millis(5));
            }
        }
    }

    impl Drop for FixtureProcessGuard {
        fn drop(&mut self) {
            if self.child.is_none() {
                // Ownership was handed to production supervision. The test
                // guard must become completely inert, including on panic.
                return;
            }
            let deadline = Instant::now() + Duration::from_secs(3);
            if !self.owned.contains_key(&self.provider_pgid) {
                if let Ok(Some(receipt)) = inspect_stable_process(self.provider_pgid) {
                    let _ = self.register_provider_receipt(receipt);
                } else if let Ok(Some(receipt)) =
                    capture_isolated_zombie_provider_epoch(self.provider_pgid)
                {
                    let _ = self.register_provider_receipt(receipt);
                }
            }
            let discovery_deadline = deadline
                .checked_sub(Duration::from_secs(1))
                .unwrap_or(deadline)
                .min(Instant::now() + Duration::from_millis(100));
            loop {
                self.discover_declared_helper_receipts(discovery_deadline);
                let all_declared = self.helper_pid_files.iter().all(|path| {
                    fs::read_to_string(path)
                        .ok()
                        .and_then(|text| text.lines().next()?.trim().parse::<u32>().ok())
                        .is_some_and(|pid| self.owned.contains_key(&pid))
                });
                if all_declared || Instant::now() >= discovery_deadline {
                    break;
                }
                std::thread::sleep(Duration::from_millis(5));
            }
            let Some(mut child) = self.child.take() else {
                return;
            };

            let mut groups = BTreeMap::<u32, BTreeMap<u32, ManagedProcessCredential>>::new();
            for receipt in self.owned.values().cloned() {
                groups
                    .entry(receipt.pgid)
                    .or_default()
                    .insert(receipt.pid, receipt);
            }
            let provider_group = groups.remove(&self.provider_pgid);
            let helper_deadline = deadline
                .checked_sub(Duration::from_millis(750))
                .unwrap_or(deadline);
            for (pgid, owned) in groups {
                if Instant::now() >= helper_deadline {
                    break;
                }
                let _ = run_exact_group_watchdog(pgid, &owned, helper_deadline);
            }
            if let Some(owned) = provider_group {
                if Instant::now() < deadline {
                    let _ = run_exact_group_watchdog(self.provider_pgid, &owned, deadline);
                }
            }

            if Instant::now() < deadline
                && child.try_wait().ok().flatten().is_none()
                && Instant::now() < deadline
            {
                // Child::kill targets the uniquely owned Child handle, never
                // a numeric marker or an unproved process group.
                let _ = child.kill();
            }
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                // Reaping is read-only process custody. Never detach or drop
                // the unique Child handle merely because the signal deadline
                // expired; a pathological fixture blocks this test instead
                // of becoming an orphan.
                let _ = child.wait();
            } else {
                match child.wait_timeout(remaining) {
                    Ok(Some(_)) => {}
                    Ok(None) | Err(_) => {
                        let _ = child.wait();
                    }
                }
            }
        }
    }

    #[test]
    fn b177_fixture_guard_take_child_fully_disarms_drop() {
        let child = Command::new("/bin/sleep")
            .arg("60")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0)
            .spawn()
            .unwrap();
        let mut guard = FixtureProcessGuard::new(child, Vec::new());
        let pgid = guard.provider_pgid;
        let receipt = guard.owned.get(&pgid).cloned().unwrap();
        let child = guard.take_child();
        assert!(guard.register_provider_receipt(receipt).is_err());
        let owner = B177FixtureChildOwner::new(child).unwrap();
        drop(guard);

        assert!(process_group_alive_exact(pgid).unwrap());
        drop(owner);
    }

    #[test]
    fn b177_fixture_guard_marker_is_discovery_not_signal_authority() {
        let root = temp_root("guard-unrelated-marker");
        fs::create_dir_all(&root).unwrap();
        let victim = Command::new("/bin/sleep")
            .arg("60")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0)
            .spawn()
            .unwrap();
        let mut victim_guard = FixtureProcessGuard::new(victim, Vec::new());
        let victim_pgid = victim_guard.provider_pgid;
        let marker = root.join("helper-pid");
        fs::write(&marker, format!("{victim_pgid}\n")).unwrap();

        let child = Command::new("/bin/sleep")
            .arg("60")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0)
            .spawn()
            .unwrap();
        let mut unrelated_guard = FixtureProcessGuard::new(child, vec![marker]);
        let mut expired = victim_guard.owned.get(&victim_pgid).cloned().unwrap();
        expired.birth_identity.push_str("-expired");
        assert!(unrelated_guard.register_helper_receipt(expired).is_err());
        unrelated_guard.discover_declared_helper_receipts(Instant::now() + Duration::from_secs(1));
        assert!(!unrelated_guard.owned.contains_key(&victim_pgid));
        drop(unrelated_guard);

        assert!(process_group_alive_exact(victim_pgid).unwrap());
        assert!(victim_guard
            .child
            .as_mut()
            .unwrap()
            .try_wait()
            .unwrap()
            .is_none());
        drop(victim_guard);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_fixture_guard_promotes_related_marker_and_cleans_both_groups() {
        let root = temp_root("guard-related-marker");
        fs::create_dir_all(&root).unwrap();
        let ready = root.join("ready");
        let helper_ready = ready.join("helper-ready");
        let mut command =
            b177_fixture_command(&root, "provider-cross-pgid-sticky-zombie", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let provider_pgid = child.id();
        let delayed_marker = ready.join("delayed-helper-marker");
        let guard = FixtureProcessGuard::new(child, vec![delayed_marker.clone()]);
        let deadline = Instant::now() + Duration::from_secs(5);
        while !helper_ready.is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let helper_pgid = fs::read_to_string(&helper_ready)
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        let helper = inspect_stable_process(helper_pgid).unwrap().unwrap();
        assert_eq!(helper.observed_ppid, provider_pgid);
        assert_ne!(helper_pgid, provider_pgid);

        let marker_writer = std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(30));
            fs::write(delayed_marker, format!("{helper_pgid}\n")).unwrap();
        });
        drop(guard);
        marker_writer.join().unwrap();
        let reap_deadline = Instant::now() + Duration::from_secs(2);
        while (process_group_alive_exact(helper_pgid).unwrap()
            || process_group_alive_exact(provider_pgid).unwrap())
            && Instant::now() < reap_deadline
        {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(!process_group_alive_exact(helper_pgid).unwrap());
        assert!(!process_group_alive_exact(provider_pgid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

    struct ZombieFixtureGuard {
        release_path: PathBuf,
        supervisor: Option<std::thread::JoinHandle<Result<SupervisionDetails>>>,
    }

    impl ZombieFixtureGuard {
        fn finish(mut self) -> SupervisionDetails {
            fs::write(&self.release_path, b"reap\n").unwrap();
            self.supervisor
                .take()
                .unwrap()
                .join()
                .expect("supervision thread panicked")
                .unwrap()
        }
    }

    impl Drop for ZombieFixtureGuard {
        fn drop(&mut self) {
            let _ = fs::write(&self.release_path, b"reap\n");
            if let Some(supervisor) = self.supervisor.take() {
                let _ = supervisor.join();
            }
        }
    }

    #[test]
    fn b177_baseline_precedence_excludes_a_preexisting_provider_descendant() {
        let provider = synthetic_topology(10, 1, 10);
        let sentinel_before_spawn = synthetic_topology(20, 1, 20);
        let mut sentinel = sentinel_before_spawn.clone();
        sentinel.observed_ppid = 10;
        sentinel.pgid = 10;
        let new_helper = synthetic_topology(21, 10, 10);
        let baseline = BTreeMap::from([(sentinel.pid, sentinel_before_spawn)]);
        let current = BTreeMap::from([
            (provider.pid, provider),
            (sentinel.pid, sentinel.clone()),
            (new_helper.pid, new_helper.clone()),
        ]);
        let owned = BTreeMap::from([(10, synthetic_credential(10, 1, 10))]);
        let lineage = lineage_pids(10, None, &owned, &current).unwrap();
        let candidates = candidate_topologies(10, &baseline, &owned, &current, &lineage);
        assert!(!candidates.iter().any(|item| item.pid == sentinel.pid));
        assert!(candidates.iter().any(|item| item.pid == new_helper.pid));

        let mut exec_changed = baseline.get(&20).unwrap().clone();
        exec_changed.executable_hint = "different-after-exec".to_string();
        assert!(baseline_identity_matches(
            baseline.get(&20).unwrap(),
            &exec_changed
        ));
        let mut uid_changed = baseline.get(&20).unwrap().clone();
        uid_changed.uid += 1;
        assert!(baseline_identity_matches(
            baseline.get(&20).unwrap(),
            &uid_changed
        ));
    }

    #[test]
    fn b177_reused_bare_sid_without_current_owned_epoch_never_expands_lineage() {
        let mut stale_provider = synthetic_credential(10, 1, 10);
        stale_provider.sid = 10;
        let mut reused_numeric_leader = synthetic_topology(10, 1, 10);
        reused_numeric_leader.sid = 10;
        reused_numeric_leader.birth_identity = "birth-10-reused".to_string();
        let mut unrelated = synthetic_topology(31, 1, 31);
        unrelated.sid = 10;
        let snapshot = BTreeMap::from([
            (reused_numeric_leader.pid, reused_numeric_leader),
            (unrelated.pid, unrelated.clone()),
        ]);
        let owned = BTreeMap::from([(stale_provider.pid, stale_provider)]);

        let lineage = lineage_pids(10, Some(10), &owned, &snapshot).unwrap();
        assert!(!lineage.contains(&unrelated.pid));
        assert!(candidate_topologies(10, &BTreeMap::new(), &owned, &snapshot, &lineage).is_empty());
    }

    #[test]
