    #[test]
    fn b177_candidate_sandwich_rejects_pid_reuse_and_ancestry_change() {
        let provider = synthetic_topology(10, 1, 10);
        let candidate = synthetic_topology(20, 10, 20);
        let full = synthetic_credential(20, 10, 20);
        let before = BTreeMap::from([
            (provider.pid, provider.clone()),
            (candidate.pid, candidate.clone()),
        ]);
        let owned = BTreeMap::from([(provider.pid, synthetic_credential(10, 1, 10))]);
        assert!(candidate_promotion_is_stable(
            &BTreeMap::new(),
            &candidate,
            &full,
            &before,
            &lineage_pids(provider.pid, None, &owned, &before).unwrap(),
        ));

        let mut reused = candidate.clone();
        reused.birth_identity.push_str("-reused");
        let reused_snapshot =
            BTreeMap::from([(provider.pid, provider.clone()), (reused.pid, reused)]);
        assert!(!candidate_promotion_is_stable(
            &BTreeMap::new(),
            &candidate,
            &full,
            &reused_snapshot,
            &lineage_pids(provider.pid, None, &owned, &reused_snapshot,).unwrap(),
        ));

        let mut detached = candidate.clone();
        detached.observed_ppid = 1;
        let detached_snapshot =
            BTreeMap::from([(provider.pid, provider), (detached.pid, detached)]);
        assert!(!candidate_promotion_is_stable(
            &BTreeMap::new(),
            &candidate,
            &full,
            &detached_snapshot,
            &lineage_pids(10, None, &owned, &detached_snapshot).unwrap(),
        ));
    }

    #[test]
    fn b177_owned_exec_refresh_and_stale_root_reuse_are_fenced() {
        let provider = synthetic_topology(10, 1, 10);
        let provider_receipt = synthetic_credential(10, 1, 10);
        let helper_receipt = synthetic_credential(20, 10, 20);
        let mut refreshed_topology = synthetic_topology(20, 1, 30);
        refreshed_topology.sid = 20;
        refreshed_topology.executable_hint = "replacement".to_string();
        let mut refreshed = helper_receipt.clone();
        refreshed.observed_ppid = 1;
        refreshed.pgid = 30;
        refreshed.sid = 20;
        refreshed.executable_summary = "replacement-full".to_string();
        let refreshed_snapshot = BTreeMap::from([
            (provider.pid, provider.clone()),
            (refreshed_topology.pid, refreshed_topology.clone()),
        ]);
        assert!(owned_helper_refresh_is_stable(
            &helper_receipt,
            &refreshed_topology,
            &refreshed,
            &refreshed_snapshot,
            &BTreeSet::from([20]),
            Some(10),
        ));
        let mut reused_refresh = refreshed.clone();
        reused_refresh.birth_identity.push_str("-reused");
        assert!(!owned_helper_refresh_is_stable(
            &helper_receipt,
            &refreshed_topology,
            &reused_refresh,
            &refreshed_snapshot,
            &BTreeSet::from([20]),
            Some(10),
        ));

        let mut reused_root = synthetic_topology(20, 1, 40);
        reused_root.birth_identity.push_str("-reused");
        let sentinel_child = synthetic_topology(21, 20, 41);
        let snapshot = BTreeMap::from([
            (provider.pid, provider),
            (reused_root.pid, reused_root),
            (sentinel_child.pid, sentinel_child),
        ]);
        let owned = BTreeMap::from([(10, provider_receipt), (20, helper_receipt)]);
        let lineage = lineage_pids(10, Some(10), &owned, &snapshot).unwrap();
        assert!(!lineage.contains(&20));
        assert!(!lineage.contains(&21));
    }

    #[test]
    fn b177_owned_same_birth_authority_drift_is_durable_and_never_signal_authority() {
        let receipt = synthetic_credential(20, 10, 20);
        let mut changed = synthetic_topology(receipt.pid, 1, 77);
        changed.sid = 77;
        changed.uid = receipt.uid + 1;
        let changed_census = ProcessTopologyCensus {
            listed_pids: BTreeSet::from([receipt.pid]),
            topology: BTreeMap::from([(receipt.pid, changed)]),
            opaque_zombies: BTreeMap::new(),
        };
        assert_eq!(
            classify_owned_epoch(&receipt, &changed_census).unwrap(),
            OwnedEpochState::Present
        );
        assert!(
            !owned_epoch_retired_by_stable_pair(&receipt, &changed_census, &changed_census,)
                .unwrap()
        );
        assert_eq!(
            current_owned_epoch_group(&receipt, &changed_census, 10).unwrap(),
            Some(77)
        );

        let missing = ProcessTopologyCensus {
            listed_pids: BTreeSet::from([receipt.pid]),
            topology: BTreeMap::new(),
            opaque_zombies: BTreeMap::new(),
        };
        assert_eq!(
            classify_owned_epoch(&receipt, &missing).unwrap(),
            OwnedEpochState::MissingDetail
        );
        assert!(!owned_epoch_retired_by_stable_pair(&receipt, &missing, &missing).unwrap());
        assert!(current_owned_epoch_group(&receipt, &missing, 10).is_err());

        let absent = ProcessTopologyCensus {
            listed_pids: BTreeSet::new(),
            topology: BTreeMap::new(),
            opaque_zombies: BTreeMap::new(),
        };
        assert!(!owned_epoch_retired_by_stable_pair(&receipt, &changed_census, &absent).unwrap());
        assert!(owned_epoch_retired_by_stable_pair(&receipt, &absent, &absent).unwrap());

        let mut replacement = synthetic_topology(receipt.pid, 1, 88);
        replacement.birth_identity.push_str("-replacement");
        let replacement = ProcessTopologyCensus {
            listed_pids: BTreeSet::from([receipt.pid]),
            topology: BTreeMap::from([(receipt.pid, replacement)]),
            opaque_zombies: BTreeMap::new(),
        };
        assert!(owned_epoch_retired_by_stable_pair(&receipt, &replacement, &replacement).unwrap());
        assert!(!owned_epoch_retired_by_stable_pair(&receipt, &replacement, &absent).unwrap());

        let mut owned = BTreeMap::from([(receipt.pid, receipt.clone())]);
        let mut control = FakeGroupControl {
            proofs: VecDeque::from([Err(vec![
                "same-birth UID/SID/PGID authority changed".to_string()
            ])]),
            waits: VecDeque::new(),
            signals: Vec::new(),
        };
        let outcome = terminate_revalidated_group(&mut control, 77, &owned, Duration::ZERO);
        assert!(!outcome.terminated);
        assert!(outcome.signals.is_empty());
        assert!(control.signals.is_empty());
        assert_eq!(owned.len(), 1, "non-signal custody obligation was dropped");
        assert!(owned.remove(&receipt.pid).is_some());
    }

    #[test]
    fn b177_owned_zombie_epoch_may_move_group_but_remains_no_signal() {
        let receipt = synthetic_credential(20, 10, 20);
        let escaped_pgid = 77;
        let opaque = OpaqueZombieProof {
            pid: receipt.pid,
            observed_ppid: 1,
            pgid: escaped_pgid,
            uid: receipt.uid,
            birth_identity: Some(receipt.birth_identity.clone()),
        };
        assert!(owned_zombie_epoch_matches_receipt(&receipt, &opaque));
        assert!(!opaque_zombie_matches_receipt(&opaque, &receipt));
        let census = ProcessTopologyCensus {
            listed_pids: BTreeSet::from([receipt.pid]),
            topology: BTreeMap::new(),
            opaque_zombies: BTreeMap::from([(receipt.pid, opaque)]),
        };
        assert_eq!(
            current_owned_epoch_group(&receipt, &census, 10).unwrap(),
            Some(escaped_pgid)
        );
        assert!(!owned_epoch_retired_by_stable_pair(&receipt, &census, &census).unwrap());

        let mut control = FakeGroupControl {
            proofs: VecDeque::from([Ok(GroupCredentialProof::OwnedZombieOnly)]),
            waits: VecDeque::new(),
            signals: Vec::new(),
        };
        let outcome = terminate_revalidated_group(
            &mut control,
            escaped_pgid,
            &BTreeMap::from([(receipt.pid, receipt)]),
            Duration::ZERO,
        );
        assert!(outcome.zombie_awaiting_provider_reap);
        assert!(!outcome.terminated);
        assert!(outcome.signals.is_empty());
        assert!(control.signals.is_empty());
    }

    #[test]
    fn b177_structural_zombie_without_birth_never_matches_an_owned_receipt() {
        let receipt = synthetic_credential(20, 10, 20);
        let structural_only = OpaqueZombieProof {
            pid: receipt.pid,
            observed_ppid: receipt.observed_ppid,
            pgid: receipt.pgid,
            uid: receipt.uid,
            birth_identity: None,
        };
        assert!(!opaque_zombie_matches_receipt(&structural_only, &receipt));
        let exact = OpaqueZombieProof {
            birth_identity: Some(receipt.birth_identity.clone()),
            ..structural_only.clone()
        };
        assert!(opaque_zombie_matches_receipt(&exact, &receipt));
        let reused = OpaqueZombieProof {
            birth_identity: Some(format!("{}-reused", receipt.birth_identity)),
            ..structural_only
        };
        assert!(!opaque_zombie_matches_receipt(&reused, &receipt));
    }

    #[test]
    fn b177_term_to_kill_requires_a_fresh_group_identity_proof() {
        let mut reused = FakeGroupControl {
            proofs: VecDeque::from([
                Ok(GroupCredentialProof::OwnedLive),
                Err(vec!["pgid 77 contains unowned pid 88".to_string()]),
            ]),
            waits: VecDeque::from([Ok(false)]),
            signals: Vec::new(),
        };
        let outcome =
            terminate_revalidated_group(&mut reused, 77, &BTreeMap::new(), Duration::ZERO);
        assert_eq!(reused.signals, [crate::tierf::TerminationSignal::Term]);
        assert!(!outcome.terminated);
        assert!(outcome
            .errors
            .iter()
            .any(|error| error.contains("KILL refused")));

        let mut stubborn_owned = FakeGroupControl {
            proofs: VecDeque::from([
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
            ]),
            waits: VecDeque::from([Ok(false), Ok(true)]),
            signals: Vec::new(),
        };
        let outcome =
            terminate_revalidated_group(&mut stubborn_owned, 77, &BTreeMap::new(), Duration::ZERO);
        assert!(outcome.terminated);
        assert!(outcome.errors.is_empty());
        assert_eq!(
            stubborn_owned.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill
            ]
        );

        let mut late_fork = FakeGroupControl {
            proofs: VecDeque::from([
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::AlreadyGone),
            ]),
            waits: VecDeque::from([Ok(false), Ok(false), Ok(true)]),
            signals: Vec::new(),
        };
        let outcome = terminate_revalidated_group(
            &mut late_fork,
            77,
            &BTreeMap::new(),
            Duration::from_millis(20),
        );
        assert!(outcome.terminated);
        assert_eq!(outcome.kill_attempts, 2);
        assert_eq!(
            outcome.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill
            ]
        );
        assert_eq!(
            late_fork.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill,
                crate::tierf::TerminationSignal::Kill
            ]
        );

        let mut reused_after_first_kill = FakeGroupControl {
            proofs: VecDeque::from([
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
                Err(vec!["original group gone; numeric PGID reused".to_string()]),
            ]),
            waits: VecDeque::from([Ok(false), Ok(false)]),
            signals: Vec::new(),
        };
        let outcome = terminate_revalidated_group(
            &mut reused_after_first_kill,
            77,
            &BTreeMap::new(),
            Duration::from_millis(20),
        );
        assert!(!outcome.terminated);
        assert_eq!(outcome.kill_attempts, 1);
        assert!(outcome
            .errors
            .iter()
            .any(|error| error.contains("repeated KILL refused")));
        assert_eq!(
            reused_after_first_kill.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill
            ]
        );
    }

    #[test]
    fn b177_post_kill_raw_probe_is_short_and_two_typed_proofs_are_mandatory() {
        let grace = Duration::from_millis(20);
        let mut late_live_then_zombie = ProofCadenceGroupControl {
            proofs: VecDeque::from([
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedZombieOnly),
            ]),
            waits: VecDeque::from([Ok(false), Ok(false), Ok(false)]),
            signals: Vec::new(),
            proof_calls: 0,
            proof_delays: VecDeque::new(),
            wait_budgets: Vec::new(),
        };
        let outcome =
            terminate_revalidated_group(&mut late_live_then_zombie, 77, &BTreeMap::new(), grace);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(!outcome.terminated);
        assert!(outcome.zombie_awaiting_provider_reap);
        assert_eq!(outcome.kill_attempts, 2);
        assert_eq!(late_live_then_zombie.proof_calls, 4);
        assert_eq!(late_live_then_zombie.wait_budgets[0], grace);
        assert!(late_live_then_zombie.wait_budgets[1..]
            .iter()
            .all(|budget| *budget <= Duration::from_millis(5)));
        assert_eq!(
            late_live_then_zombie.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill,
                crate::tierf::TerminationSignal::Kill,
            ]
        );

        let mut raw_esrch = ProofCadenceGroupControl {
            proofs: VecDeque::from([
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::AlreadyGone),
                Ok(GroupCredentialProof::AlreadyGone),
            ]),
            waits: VecDeque::from([Ok(false), Ok(true), Ok(true)]),
            signals: Vec::new(),
            proof_calls: 0,
            proof_delays: VecDeque::new(),
            wait_budgets: Vec::new(),
        };
        let outcome = terminate_revalidated_group(&mut raw_esrch, 77, &BTreeMap::new(), grace);
        assert!(outcome.terminated);
        assert!(outcome.errors.is_empty());
        assert_eq!(raw_esrch.proof_calls, 4);
        assert_eq!(raw_esrch.wait_budgets[0], grace);
        assert!(raw_esrch.wait_budgets[1..]
            .iter()
            .all(|budget| *budget <= Duration::from_millis(5)));
        assert_eq!(
            raw_esrch.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill,
            ]
        );

        let deadline_grace = Duration::from_millis(1);
        let mut slow_post_kill_proof = ProofCadenceGroupControl {
            proofs: VecDeque::from([
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
            ]),
            waits: VecDeque::from([Ok(false), Ok(false), Ok(false)]),
            signals: Vec::new(),
            proof_calls: 0,
            proof_delays: VecDeque::from([
                Duration::ZERO,
                Duration::ZERO,
                Duration::from_millis(5),
                Duration::ZERO,
            ]),
            wait_budgets: Vec::new(),
        };
        let outcome = terminate_revalidated_group(
            &mut slow_post_kill_proof,
            77,
            &BTreeMap::new(),
            deadline_grace,
        );
        assert!(!outcome.terminated);
        assert_eq!(slow_post_kill_proof.proof_calls, 4);
        assert_eq!(outcome.kill_attempts, 1);
        assert_eq!(
            slow_post_kill_proof.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill,
            ],
            "a proof completing after the fixed deadline must stay read-only"
        );
        assert!(outcome
            .errors
            .iter()
            .any(|error| error.contains("remained live after revalidated KILL")));
    }

    #[test]
    fn b177_real_group_revalidation_wrong_pgid_refuses_every_signal() {
        let child = Command::new("/bin/sleep")
            .arg("60")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0)
            .spawn()
            .unwrap();
        let mut fixture = FixtureProcessGuard::new(child, Vec::new());
        let pgid = fixture.provider_pgid;
        let receipt = capture_provider_credential(&mut ProcessObserver::default(), pgid)
            .expect("capture real isolated group leader credential");
        fixture.register_provider_receipt(receipt.clone()).unwrap();
        let mut wrong_group = receipt;
        wrong_group.pgid = pgid + 1;
        let owned = BTreeMap::from([(wrong_group.pid, wrong_group)]);
        let mut observer = ProcessObserver::default();
        let mut control = SystemGroupControl {
            observer: &mut observer,
            direct_child: None,
        };
        let outcome =
            terminate_revalidated_group(&mut control, pgid, &owned, Duration::from_millis(10));
        assert!(!outcome.terminated);
        assert!(outcome.signals.is_empty());
        assert!(outcome
            .errors
            .iter()
            .any(|error| error.contains("credential changed before signal")));
        assert!(process_group_alive_exact(pgid).unwrap());

        // Keep ownership in the guard until all assertions have passed; its
        // Drop path tears down only this disposable test group.
        assert!(fixture
            .child
            .as_mut()
            .unwrap()
            .try_wait()
            .unwrap()
            .is_none());
    }

    #[test]
    fn b177_provider_zombie_anchor_authorizes_late_fork_repeat_kill() {
        let root = temp_root("provider-zombie-late-fork");
        fs::create_dir_all(&root).unwrap();
        let ready = root.join("ready");
        let mut command =
            b177_fixture_command(&root, "provider-fork-after-release-then-exit", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, Vec::new());
        let pgid = fixture.provider_pgid;
        let deadline = Instant::now() + Duration::from_secs(5);
        while !ready.join("provider-ready").is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let provider = inspect_stable_process(pgid).unwrap().unwrap();
        assert_eq!(
            (provider.pid, provider.pgid, provider.sid),
            (pgid, pgid, pgid)
        );
        fixture.register_provider_receipt(provider.clone()).unwrap();
        let owned = BTreeMap::from([(pgid, provider)]);
        let mut control = LateForkGroupControl {
            observer: ProcessObserver::default(),
            child: fixture.child.as_mut().unwrap(),
            release_path: ready.join("fork-now"),
            helper_ready: ready.join("helper-ready"),
            kill_attempts: 0,
            signals: Vec::new(),
        };
        let outcome = terminate_revalidated_group(
            &mut control,
            pgid,
            &owned,
            Duration::from_millis(WakeSupervisorPolicy::production().term_grace_ms),
        );
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(!outcome.terminated);
        assert!(outcome.zombie_awaiting_provider_reap);
        assert_eq!(outcome.kill_attempts, 2);
        assert_eq!(
            outcome.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill
            ]
        );
        assert_eq!(
            control.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill,
                crate::tierf::TerminationSignal::Kill
            ]
        );
        drop(control);
        fixture.child.as_mut().unwrap().wait().unwrap();
        let deadline = Instant::now() + Duration::from_secs(2);
        while process_group_alive_exact(pgid).unwrap() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(!process_group_alive_exact(pgid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b241_setpgid_only_fork_window_child_is_contained_by_lineage() {
        let root = temp_root("setpgid-lineage-late-fork");
        fs::create_dir_all(&root).unwrap();
        let ready = root.join("ready");
        let helper_ready = ready.join("helper-ready");
        let mut command =
            b177_fixture_command(&root, "provider-fork-after-release-and-stay", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, vec![helper_ready.clone()]);
        let pgid = fixture.provider_pgid;
        let deadline = Instant::now() + Duration::from_secs(5);
        while !ready.join("provider-ready").is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let provider = inspect_stable_process(pgid).unwrap().unwrap();
        assert_eq!((provider.pid, provider.pgid), (pgid, pgid));
        assert_ne!(
            provider.sid, pgid,
            "process_group(0) must isolate only the PGID, not create a session"
        );
        fixture.register_provider_receipt(provider.clone()).unwrap();
        let owned = BTreeMap::from([(pgid, provider.clone())]);
        let mut control = SetpgidForkWindowGroupControl {
            observer: ProcessObserver::default(),
            child: fixture.child.as_mut().unwrap(),
            release_path: ready.join("fork-now"),
            helper_ready,
            kill_attempts: 0,
            signals: Vec::new(),
            observed_late_member: None,
        };
        let outcome = terminate_revalidated_group(
            &mut control,
            pgid,
            &owned,
            Duration::from_millis(WakeSupervisorPolicy::production().term_grace_ms),
        );
        let (containment, helper) = control
            .observed_late_member
            .clone()
            .expect("production proof did not inspect the real fork-window child");
        let physical_signals = control.signals.clone();
        drop(control);

        assert_eq!(containment, MemberContainment::ContainedByLineage);
        assert_eq!(helper.observed_ppid, provider.pid);
        assert_eq!(helper.pgid, provider.pgid);
        assert_eq!(helper.sid, provider.sid);
        assert_eq!(helper.uid, provider.uid);
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(outcome.terminated);
        assert_eq!(outcome.kill_attempts, 2);
        assert_eq!(
            outcome.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill
            ]
        );
        assert_eq!(
            physical_signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill,
                crate::tierf::TerminationSignal::Kill
            ]
        );
        fixture.child.as_mut().unwrap().wait().unwrap();
        assert!(!process_group_alive_exact(pgid).unwrap());
        drop(fixture);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_current_owned_member_anchors_session_after_leader_reap() {
        let root = temp_root("owned-member-session-anchor");
        fs::create_dir_all(&root).unwrap();
        let ready = root.join("ready");
        let mut command =
            b177_fixture_command(&root, "provider-two-same-group-then-exit", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, Vec::new());
        let pgid = fixture.provider_pgid;
        let deadline = Instant::now() + Duration::from_secs(5);
        while !(ready.join("owned-ready").is_file() && ready.join("late-ready").is_file())
            && Instant::now() < deadline
        {
            std::thread::sleep(Duration::from_millis(5));
        }
        let owned_pid = fs::read_to_string(ready.join("owned-ready"))
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        let late_pid = fs::read_to_string(ready.join("late-ready"))
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        let leader = inspect_stable_process(pgid).unwrap().unwrap();
        let owned_member = inspect_stable_process(owned_pid).unwrap().unwrap();
        assert_eq!(owned_member.sid, leader.sid);
        fixture.register_provider_receipt(leader.clone()).unwrap();
        fixture
            .register_helper_receipt(owned_member.clone())
            .unwrap();
        fs::write(ready.join("exit-now"), b"exit\n").unwrap();
        fixture.child.as_mut().unwrap().wait().unwrap();
        assert!(!exact_group_member_pids(pgid).unwrap().contains(&pgid));
        assert!(exact_group_member_pids(pgid).unwrap().contains(&late_pid));
        let owned = BTreeMap::from([(pgid, leader), (owned_pid, owned_member)]);
        assert_eq!(
            revalidate_group_credentials(&mut ProcessObserver::default(), pgid, &owned),
            Ok(GroupCredentialProof::OwnedLive)
        );
        let watchdog =
            run_exact_group_watchdog(pgid, &owned, Instant::now() + Duration::from_secs(3))
                .unwrap();
        assert!(watchdog.term_sent || watchdog.kill_sent || watchdog.esrch);
        let deadline = Instant::now() + Duration::from_secs(2);
        while process_group_alive_exact(pgid).unwrap() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(!process_group_alive_exact(pgid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_log_tail_is_incremental_and_rejects_replace_or_shrink() {
        let root = temp_root("incremental-tail");
        fs::create_dir_all(&root).unwrap();
        let path = root.join("wake.jsonl");
        fs::write(&path, b"one\npartial").unwrap();
        let mut tail = ManagedLogTail::open(&path).unwrap();
        assert_eq!(tail.read_complete_lines().unwrap(), ["one"]);
        assert_eq!(tail.bytes_read, 11);

        let mut append = fs::OpenOptions::new().append(true).open(&path).unwrap();
        append.write_all(b"-two\nthree\n").unwrap();
        append.flush().unwrap();
        assert_eq!(
            tail.read_complete_lines().unwrap(),
            ["partial-two", "three"]
        );
        let final_len = fs::metadata(&path).unwrap().len();
        assert_eq!(tail.bytes_read, final_len);
        assert!(tail.read_complete_lines().unwrap().is_empty());
        assert_eq!(tail.bytes_read, final_len, "old bytes must not be reparsed");

        let replacement = root.join("replacement");
        fs::write(&replacement, b"replacement\n").unwrap();
        fs::rename(&replacement, &path).unwrap();
        assert!(tail
            .read_complete_lines()
            .unwrap_err()
            .to_string()
            .contains("replaced"));

        let shrink_path = root.join("shrink.jsonl");
        fs::write(&shrink_path, b"before-shrink\n").unwrap();
        let mut shrink_tail = ManagedLogTail::open(&shrink_path).unwrap();
        shrink_tail.read_complete_lines().unwrap();
        File::create(&shrink_path).unwrap();
        assert!(shrink_tail
            .read_complete_lines()
            .unwrap_err()
            .to_string()
            .contains("shrank"));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_oversized_log_record_is_discarded_across_chunks_until_lf() {
        let root = temp_root("oversized-log-record");
        fs::create_dir_all(&root).unwrap();
        let path = root.join("wake.jsonl");
        let oversized = vec![b'x'; MAX_MANAGED_LOG_RECORD_BYTES + 512 * 1024];
        fs::write(&path, &oversized).unwrap();
        let mut tail = ManagedLogTail::open(&path).unwrap();
        while tail.offset < oversized.len() as u64 {
            assert!(tail.read_complete_lines().unwrap().is_empty());
            assert!(tail.partial.len() <= MAX_MANAGED_LOG_RECORD_BYTES);
        }
        assert!(tail.discarding_oversized_record);
        assert!(tail.partial.is_empty());

        let exact = r#"{"type":"step_finish","part":{"type":"step-finish","reason":"stop"}}"#;
        let mut append = fs::OpenOptions::new().append(true).open(&path).unwrap();
        append.write_all(format!("\n{exact}\n").as_bytes()).unwrap();
        append.flush().unwrap();
        assert_eq!(tail.read_complete_lines().unwrap(), [exact]);
        assert!(!tail.discarding_oversized_record);
        assert_eq!(
            classify_managed_terminal("opencode", exact),
            ManagedTerminal::OpenCodeStop
        );
        fs::remove_dir_all(root).unwrap();
    }

