    #[test]
    fn b177_birth_identity_change_refuses_signal_and_already_gone_is_idempotent() {
        let mut child = Command::new("/bin/sh")
            .args(["-c", "trap '' TERM; while :; do sleep 10; done"])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0)
            .spawn()
            .unwrap();
        let pgid = child.id();
        let exact = inspect_stable_process(pgid).unwrap().unwrap();
        let mut changed = exact.clone();
        changed.birth_identity.push_str("-reused");
        let owned = BTreeMap::from([(pgid, changed)]);
        let mut observer = ProcessObserver::default();
        let ambiguity = revalidate_group_credentials(&mut observer, pgid, &owned).unwrap_err();
        assert!(ambiguity
            .iter()
            .any(|line| line.contains("credential changed")));
        assert!(ambiguity.iter().all(|line| !line.contains("while :")));
        crate::tierf::terminate_managed_process_group(pgid, Duration::from_millis(30)).unwrap();
        child.wait().unwrap();

        let mut short = Command::new("/bin/sh")
            .args(["-c", "sleep 0.05"])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0)
            .spawn()
            .unwrap();
        let short_pgid = short.id();
        let short_identity = inspect_stable_process(short_pgid).unwrap().unwrap();
        short.wait().unwrap();
        let deadline = std::time::Instant::now() + Duration::from_secs(1);
        while process_group_alive_exact(short_pgid).unwrap() && std::time::Instant::now() < deadline
        {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(!process_group_alive_exact(short_pgid).unwrap());
        let gone = BTreeMap::from([(short_pgid, short_identity)]);
        assert_eq!(
            revalidate_group_credentials(&mut ProcessObserver::default(), short_pgid, &gone,),
            Ok(GroupCredentialProof::AlreadyGone)
        );
    }

