    #[test]
    fn b177_owned_zombie_only_direct_child_reaps_before_group_esrch() {
        let child = Command::new("/bin/sleep")
            .arg("0.2")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0)
            .spawn()
            .unwrap();
        let mut fixture = FixtureProcessGuard::new(child, Vec::new());
        let pgid = fixture.provider_pgid;
        let receipt = inspect_stable_process(pgid)
            .unwrap()
            .expect("direct-child fixture lacks a stable credential");
        fixture.register_provider_receipt(receipt.clone()).unwrap();
        let owned = BTreeMap::from([(receipt.pid, receipt)]);
        let proof_deadline = Instant::now() + Duration::from_secs(2);
        loop {
            if revalidate_group_credentials(&mut ProcessObserver::default(), pgid, &owned)
                == Ok(GroupCredentialProof::OwnedZombieOnly)
            {
                break;
            }
            assert!(
                Instant::now() < proof_deadline,
                "direct child never reached an exact zombie-only group"
            );
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(process_group_alive_exact(pgid).unwrap());

        let started = Instant::now();
        let mut child_status = None;
        let outcome = {
            let mut observer = ProcessObserver::default();
            let mut control = SystemGroupControl {
                observer: &mut observer,
                direct_child: Some((fixture.child.as_mut().unwrap(), &mut child_status)),
            };
            terminate_revalidated_group(&mut control, pgid, &owned, Duration::from_millis(30))
        };
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(outcome.signals.is_empty());
        assert!(outcome.terminated);
        assert!(!outcome.zombie_awaiting_provider_reap);
        assert!(child_status.is_some());
        assert!(!process_group_alive_exact(pgid).unwrap());
        assert!(
            started.elapsed() < Duration::from_secs(1),
            "exact zombie-only Child reap waited for a circular PGID-ESRCH condition"
        );
    }

    #[test]
    fn b177_live_unowned_same_group_member_refuses_signal() {
        let root = temp_root("unowned-same-group");
        fs::create_dir_all(&root).unwrap();
        let provider_ready = root.join("provider-ready");
        let helper_ready = root.join("helper-ready");
        let mut provider_command =
            b177_fixture_command(&root, "provider-stubborn", Some(&provider_ready));
        provider_command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0);
        let mut provider = provider_command.spawn().unwrap();
        let pgid = provider.id();
        let mut helper_command =
            b177_fixture_command(&root, "stubborn-helper", Some(&helper_ready));
        helper_command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(pgid as i32);
        let mut helper = helper_command.spawn().unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        while !(provider_ready.is_file() && helper_ready.is_file()) && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let provider_credential = inspect_stable_process(pgid).unwrap().unwrap();
        let helper_credential = inspect_stable_process(helper.id()).unwrap().unwrap();
        let owned = BTreeMap::from([(pgid, provider_credential)]);
        assert_ne!(owned[&pgid].sid, pgid, "fixture must be setpgid-only");
        assert!(
            !owned.contains_key(&helper_credential.observed_ppid),
            "migrated helper must have no owned PPID lineage"
        );
        let owned_pids = owned.keys().copied().collect::<BTreeSet<_>>();
        let leader = owned.get(&pgid).unwrap();
        let classification = classify_group_member(
            helper_credential.pid,
            helper_credential.observed_ppid,
            helper_credential.pgid,
            helper_credential.sid,
            helper_credential.uid,
            leader.pid,
            leader.sid,
            leader.uid,
            &owned_pids,
        );
        let mut observer = ProcessObserver::default();
        let mut control = SystemGroupControl {
            observer: &mut observer,
            direct_child: None,
        };
        let outcome =
            terminate_revalidated_group(&mut control, pgid, &owned, Duration::from_millis(30));
        let provider_survived_refusal = provider.try_wait().unwrap().is_none();
        let helper_survived_refusal = helper.try_wait().unwrap().is_none();
        let _ = provider.kill();
        let _ = helper.kill();
        provider.wait().unwrap();
        helper.wait().unwrap();
        let group_gone = !process_group_alive_exact(pgid).unwrap();
        fs::remove_dir_all(root).unwrap();

        assert_eq!(classification, MemberContainment::Unowned);
        assert!(outcome.signals.is_empty());
        assert!(outcome
            .errors
            .iter()
            .any(|line| line.contains("contains unowned pid")));
        assert!(provider_survived_refusal);
        assert!(helper_survived_refusal);
        assert!(group_gone);
    }

