    #[test]
    fn b177_same_pgid_child_prevents_false_natural_success_after_leader_exit() {
        const B203_TRIAL_GATE_SAMPLES: usize = 10;
        let mut completed = 0;
        for sample in 0..B203_TRIAL_GATE_SAMPLES {
            b203_h75_one_sample(sample);
            completed += 1;
        }
        assert_eq!(completed, 10, "H75 trial-gate samples completed");
    }

    fn b203_h75_one_sample(sample: usize) {
        let root = temp_root(&format!("same-pgid-child-sample-{sample}"));
        fs::create_dir_all(&root).unwrap();
        // H75 (planner test-only stabilization, r62/B204): this single fixture
        // deadline covers helper readiness + exact promotion + full supervision.
        // 12s was sized for a 557-test binary; B204 raises it to 595 tests, many
        // of which spawn real processes, so under in-binary parallel load the
        // sequence can exceed 12s and the fixture gives up before the terminal
        // record lands — surfacing as a false `terminal_seen` red. This is a
        // fixture wall-clock budget only: no production timeout changes and no
        // assertion is relaxed, so a terminal that never arrives still reddens
        // the test (just later). Same class as H80's test-only 1s -> 5s receipt
        // budget, where production stayed at 300s.
        let fixture_deadline = Instant::now() + Duration::from_secs(60);
        let log_path = root.join("wake.jsonl");
        let stdout = File::create(&log_path).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let ready = root.join("same-group-ready");
        let baseline = process_topology_snapshot()
            .unwrap()
            .into_values()
            .collect::<Vec<_>>();
        let mut command =
            b177_fixture_command(&root, "provider-same-group-child-exits", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr))
            .process_group(0);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, Vec::new());
        let provider_pid = fixture.provider_pgid;
        let provider = inspect_stable_process(provider_pid)
            .unwrap()
            .expect("same-PGID provider lacks a stable credential");
        let promoted = std::sync::Arc::new((
            std::sync::Mutex::new(BTreeSet::<u32>::new()),
            std::sync::Condvar::new(),
        ));
        let (done_tx, done_rx) = std::sync::mpsc::channel();
        let supervised_provider = provider.clone();
        let supervisor_policy = WakeSupervisorPolicy {
            natural_exit_grace_ms: 300,
            term_grace_ms: 30,
            poll_interval_ms: 5,
        };
        let mut supervisor = Some(std::thread::spawn({
            let log_path = log_path.clone();
            let promoted = std::sync::Arc::clone(&promoted);
            let child = fixture.take_child();
            move || {
                let result = supervise_managed_child_with_baseline(
                    child,
                    "opencode",
                    &log_path,
                    supervisor_policy,
                    baseline,
                    Some(supervised_provider),
                    None,
                    false,
                    ProcessObserver {
                        owned_promotion_notify: Some(promoted),
                        ..ProcessObserver::default()
                    },
                );
                let _ = done_tx.send(result);
            }
        }));
        let mut helper_pid = None;
        let mut helper_receipt = None;
        let protocol = (|| -> Result<()> {
            wait_for_fixture_file(&ready, fixture_deadline, "same-PGID helper readiness")?;
            let exact_helper_pid = fs::read_to_string(&ready)
                .context("read same-PGID helper readiness")?
                .trim()
                .parse::<u32>()
                .context("parse same-PGID helper pid")?;
            helper_pid = Some(exact_helper_pid);
            let (lock, condition) = &*promoted;
            let promoted_pids = lock
                .lock()
                .map_err(|_| anyhow::anyhow!("same-PGID promotion mutex poisoned"))?;
            let (promoted_pids, _) = condition
                .wait_timeout_while(
                    promoted_pids,
                    remaining_test_deadline(fixture_deadline, "same-PGID promotion")?,
                    |pids| !pids.contains(&exact_helper_pid),
                )
                .map_err(|_| anyhow::anyhow!("same-PGID promotion condvar poisoned"))?;
            if !promoted_pids.contains(&exact_helper_pid) {
                bail!("exact same-PGID helper never received an owned receipt");
            }
            drop(promoted_pids);
            let receipt = inspect_stable_process(exact_helper_pid)?
                .context("promoted same-PGID helper lost its stable credential")?;
            if receipt.pid != exact_helper_pid
                || receipt.observed_ppid != provider_pid
                || receipt.pgid != provider_pid
            {
                bail!(
                    "same-PGID helper credential has wrong pid/ppid/pgid: {}/{}/{}",
                    receipt.pid,
                    receipt.observed_ppid,
                    receipt.pgid
                );
            }
            helper_receipt = Some(receipt);
            fs::write(ready.with_extension("exit-provider"), b"exit\n")?;
            Ok(())
        })();

        let mut completed = None;
        let mut failure = protocol.err().map(|error| format!("{error:#}"));
        if failure.is_none() {
            match done_rx.recv_timeout(
                remaining_test_deadline(fixture_deadline, "same-PGID supervision")
                    .unwrap_or(Duration::ZERO),
            ) {
                Ok(result) => completed = Some(result),
                Err(error) => failure = Some(format!("same-PGID supervision timed out: {error}")),
            }
        }
        if let Some(failure) = failure {
            let cleanup = b177_bounded_fixture_failure_cleanup(
                "same-PGID",
                &[ready.with_extension("exit-provider")],
                Some(&ready),
                &mut helper_receipt,
                &provider,
                supervisor_policy,
                &done_rx,
                &mut supervisor,
            );
            completed = cleanup.completed;
            panic!(
                "same-PGID bounded fixture failed: {failure}; joined={}; cleanup={:?}; before={:?}/{:?}; after={:?}/{:?}; completed={}",
                cleanup.joined,
                cleanup.diagnostics,
                cleanup.helper_before_join,
                cleanup.provider_before_join,
                cleanup.helper_after_join,
                cleanup.provider_after_join,
                completed.is_some()
            );
        }

        let mut details = completed
            .expect("same-PGID completion recorded")
            .expect("same-PGID supervision returned an error");
        supervisor
            .take()
            .unwrap()
            .join()
            .expect("supervision thread panicked");
        if details.residual_child.is_some()
            || details.error.is_some()
            || !details.ambiguity.is_empty()
            || !details.outcome.process_tree_terminated
        {
            converge_supervision_residual(&mut details);
            panic!(
                "same-PGID supervision was not clean: error={:?} ambiguity={:?} order={:?}",
                details.error, details.ambiguity, details.termination_order
            );
        }
        assert!(
            helper_pid.is_some(),
            "exact helper promotion was not recorded"
        );
        assert!(details.outcome.terminal_seen, "sample={sample}");
        assert!(!details.outcome.exited_naturally);
        assert!(details.outcome.process_tree_terminated);
        assert_eq!(details.exit_status, Some(0));
        assert!(details.error.is_none());
        assert!(details.ambiguity.is_empty());
        assert!(details.residual_child.is_none());
        assert_eq!(
            details.signal_trace,
            [
                (provider_pid, crate::tierf::TerminationSignal::Term),
                (provider_pid, crate::tierf::TerminationSignal::Kill),
            ]
        );
        assert_eq!(details.termination_order.last(), Some(&provider_pid));
        assert!(!process_group_alive_exact(provider_pid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_instant_provider_zombie_epoch_finds_unobserved_cross_pgid_helper() {
        let root = temp_root("instant-provider-zombie-epoch");
        fs::create_dir_all(&root).unwrap();
        let log_path = root.join("wake.jsonl");
        let stdout = File::create(&log_path).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let helper_ready = root.join("ready/helper");
        let baseline = process_topology_snapshot()
            .unwrap()
            .into_values()
            .collect::<Vec<_>>();
        let mut command = b177_fixture_command(
            &root,
            "provider-instant-detached-helper",
            Some(&helper_ready),
        );
        command
            .stdin(Stdio::null())
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr));
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, vec![helper_ready.clone()]);
        let provider_pid = fixture.provider_pgid;
        let deadline = Instant::now() + Duration::from_secs(5);
        let mut zombie_ready = false;
        while Instant::now() < deadline {
            if helper_ready.is_file() && matches!(inspect_opaque_zombie(provider_pid), Ok(Some(_)))
            {
                zombie_ready = true;
                break;
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(helper_ready.is_file());
        assert!(
            zombie_ready,
            "provider never reached its strong opaque zombie epoch before the deadline"
        );
        assert!(inspect_stable_process(provider_pid).unwrap().is_none());
        let epoch = capture_isolated_zombie_provider_epoch(provider_pid)
            .unwrap()
            .expect("unreaped direct provider must yield a birth-bearing zombie epoch");
        assert!(is_zombie_provider_epoch(&epoch));
        assert_eq!(
            (epoch.pid, epoch.pgid, epoch.sid),
            (provider_pid, provider_pid, provider_pid)
        );
        fixture.register_provider_receipt(epoch).unwrap();
        let helper_pgid = fs::read_to_string(&helper_ready)
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        assert_ne!(helper_pgid, provider_pid);

        let started = Instant::now();
        let mut details = supervise_managed_child_with_baseline(
            fixture.take_child(),
            "opencode",
            &log_path,
            WakeSupervisorPolicy {
                natural_exit_grace_ms: 300,
                term_grace_ms: 30,
                poll_interval_ms: 5,
            },
            baseline,
            None,
            Some("provider pre-ACK identity failed: deterministic instant exit".to_string()),
            true,
            ProcessObserver::default(),
        )
        .unwrap();
        converge_supervision_residual(&mut details);
        assert!(started.elapsed() < Duration::from_secs(10));
        assert!(details.outcome.process_tree_terminated);
        assert_eq!(
            details.outcome.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill
            ]
        );
        assert!(details.owned_helpers >= 1);
        assert_eq!(details.termination_order, [helper_pgid]);
        assert_eq!(
            details.signal_trace,
            [
                (helper_pgid, crate::tierf::TerminationSignal::Term),
                (helper_pgid, crate::tierf::TerminationSignal::Kill),
            ]
        );
        assert!(details.exit_status.is_some());
        assert!(details
            .error
            .as_deref()
            .is_some_and(|error| error.contains("pre-ACK identity failed")));
        assert!(details.ambiguity.is_empty());
        assert!(details.residual_child.is_none());
        assert!(!process_group_alive_exact(helper_pgid).unwrap());
        assert!(!process_group_alive_exact(provider_pid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_isolated_session_finds_cross_pgid_helper_reparented_before_first_observation() {
        let root = temp_root("reparent-before-observe");
        fs::create_dir_all(&root).unwrap();
        let log_path = root.join("wake.jsonl");
        let stdout = File::create(&log_path).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let ready = root.join("ready");
        let helper_ready = ready.join("helper");
        let baseline = process_topology_snapshot()
            .unwrap()
            .into_values()
            .collect::<Vec<_>>();
        let mut command = b177_fixture_command(
            &root,
            "provider-detached-helper-exits-before-observe",
            Some(&ready),
        );
        command
            .stdin(Stdio::null())
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr));
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, vec![helper_ready.clone()]);
        let provider_pid = fixture.provider_pgid;
        let deadline = Instant::now() + Duration::from_secs(5);
        while !helper_ready.is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let provider = inspect_stable_process(provider_pid).unwrap().unwrap();
        assert_eq!(provider.sid, provider_pid);
        let helper_pgid = fs::read_to_string(&helper_ready)
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        fixture.register_provider_receipt(provider.clone()).unwrap();
        let helper = inspect_stable_process(helper_pgid)
            .unwrap()
            .expect("detached helper lacks a stable pre-reparent receipt");
        fixture.register_helper_receipt(helper).unwrap();
        fs::write(ready.join("exit-now"), b"exit\n").unwrap();
        // Preserve the direct Child as an unreaped zombie epoch anchor. A
        // prior version used try_wait here, creating an impossible production
        // state: the provider was reaped before supervision while its
        // reparented helper was deliberately left alive.
        let deadline = Instant::now() + Duration::from_secs(5);
        let provider_zombie = loop {
            if let Ok(Some(zombie)) = inspect_opaque_zombie(provider_pid) {
                break zombie;
            }
            assert!(
                Instant::now() < deadline,
                "provider never reached its strong opaque zombie epoch"
            );
            std::thread::sleep(Duration::from_millis(5));
        };
        assert!(provider_zombie.birth_identity.is_some());

        let details = supervise_managed_child_with_baseline(
            fixture.take_child(),
            "opencode",
            &log_path,
            WakeSupervisorPolicy {
                natural_exit_grace_ms: 300,
                term_grace_ms: 30,
                poll_interval_ms: 5,
            },
            baseline,
            Some(provider),
            None,
            true,
            ProcessObserver::default(),
        )
        .unwrap();
        assert!(details.outcome.terminal_seen);
        assert!(!details.outcome.exited_naturally);
        assert!(details.outcome.process_tree_terminated);
        assert!(details.owned_helpers >= 1);
        assert!(details.termination_order.contains(&helper_pgid));
        assert!(!process_group_alive_exact(helper_pgid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_supervisor_reaps_parent_and_five_completed_children_without_orphans() {
        let root = temp_root("five-zombies-reaped");
        fs::create_dir_all(&root).unwrap();
        let log_path = root.join("wake.jsonl");
        let stdout = File::create(&log_path).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let ready = root.join("ready");
        let baseline = process_topology_snapshot()
            .unwrap()
            .into_values()
            .collect::<Vec<_>>();
        let mut command =
            b177_fixture_command(&root, "provider-five-zombies-then-reap", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr))
            .process_group(0);
        let child = command.spawn().unwrap();
        let provider_pid = child.id();
        let provider = inspect_stable_process(provider_pid).unwrap();
        let supervisor = std::thread::spawn({
            let log_path = log_path.clone();
            move || {
                supervise_managed_child_with_baseline(
                    child,
                    "opencode",
                    &log_path,
                    WakeSupervisorPolicy {
                        natural_exit_grace_ms: 300,
                        term_grace_ms: 30,
                        poll_interval_ms: 5,
                    },
                    baseline,
                    provider,
                    None,
                    false,
                    ProcessObserver::default(),
                )
            }
        });
        let guard = ZombieFixtureGuard {
            release_path: ready.join("reap-now"),
            supervisor: Some(supervisor),
        };
        let children_path = ready.join("children");
        let deadline = Instant::now() + Duration::from_secs(5);
        while !children_path.is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let child_pids = fs::read_to_string(&children_path)
            .unwrap()
            .lines()
            .map(|line| line.parse::<u32>().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(child_pids.len(), 5);
        let unreaped_window = ready.join("unreaped-window");
        let deadline = Instant::now() + Duration::from_secs(5);
        while !unreaped_window.is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(
            unreaped_window.is_file(),
            "fixture must enter its five-completed-child unreaped window"
        );
        let provider_alive_before_release = process_group_alive_exact(provider_pid).unwrap();
        let details = guard.finish();
        assert!(provider_alive_before_release);
        assert!(ready.join("reaped").is_file());
        assert!(details.outcome.terminal_seen);
        assert!(details.outcome.exited_naturally);
        assert!(details.outcome.signals.is_empty());
        assert!(details.outcome.process_tree_terminated);
        assert_eq!(details.exit_status, Some(0));
        assert!(!process_group_alive_exact(provider_pid).unwrap());
        assert!(child_pids
            .iter()
            .all(|pid| inspect_topology(*pid).unwrap().is_none()));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_frozen_opencode_corpus_replays_without_false_positives_when_available() {
        let Some(log_dir) = std::env::var_os("ORCH_B177_CORPUS_DIR").map(PathBuf::from) else {
            return;
        };
        let threshold = 1_785_354_338_703_538_000u64;
        let mut files = fs::read_dir(&log_dir)
            .unwrap()
            .filter_map(|entry| entry.ok())
            .map(|entry| entry.path())
            .filter(|path| {
                let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                    return false;
                };
                let Some(rest) = name.strip_prefix("wake-executor-opencode-") else {
                    return false;
                };
                rest.split('-')
                    .next()
                    .and_then(|nanos| nanos.parse::<u64>().ok())
                    .is_some_and(|nanos| nanos < threshold)
                    && name.ends_with(".jsonl")
            })
            .collect::<Vec<_>>();
        files.sort();
        assert_eq!(files.len(), 102);
        let mut terminal_files = 0usize;
        let mut nonterminal_files = 0usize;
        for path in files {
            let bytes = fs::read(&path).unwrap();
            let mut terminals = Vec::new();
            let mut last_nonempty = None;
            for (index, framed) in bytes.split_inclusive(|byte| *byte == b'\n').enumerate() {
                if !framed.ends_with(b"\n") {
                    continue;
                }
                let line = &framed[..framed.len() - 1];
                if line.iter().any(|byte| !byte.is_ascii_whitespace()) {
                    last_nonempty = Some(index);
                }
                if std::str::from_utf8(line).ok().is_some_and(|line| {
                    classify_managed_terminal("opencode", line) == ManagedTerminal::OpenCodeStop
                }) {
                    terminals.push(index);
                }
            }
            match terminals.as_slice() {
                [] => nonterminal_files += 1,
                [terminal] => {
                    terminal_files += 1;
                    assert_eq!(
                        Some(*terminal),
                        last_nonempty,
                        "terminal must be last record"
                    );
                }
                _ => panic!("corpus file has duplicate terminal records"),
            }
            let digest = Sha256::digest(&bytes);
            println!(
                "{} {}",
                path.file_name().unwrap().to_string_lossy(),
                hex::encode(digest)
            );
        }
        assert_eq!((terminal_files, nonterminal_files), (63, 39));
    }

    fn review_test_git(root: &Path, args: &[&str]) {
        let output = Command::new("git")
            .arg("-C")
            .arg(root)
            .args(args)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "git {:?} failed: {}",
            args,
            String::from_utf8_lossy(&output.stderr)
        );
    }

