    #[test]
    fn b204_concurrent_review_inbox_parent_creation_revalidates_the_winner() {
        let root = temp_root("b204-review-inbox-mkdir-race");
        fs::create_dir_all(&root).unwrap();
        let rel =
            review_inbox_relpath(B180_ROUND, "B204-A0001", "primary", "executor-claw").unwrap();
        let root = std::sync::Arc::new(root);
        let threads = (0..12)
            .map(|_| {
                let root = std::sync::Arc::clone(&root);
                let rel = rel.clone();
                std::thread::spawn(move || ensure_review_inbox_parent(&root, &rel))
            })
            .collect::<Vec<_>>();
        for thread in threads {
            thread.join().unwrap().unwrap();
        }
        let parent = root.join(rel).parent().unwrap().to_path_buf();
        let metadata = fs::symlink_metadata(parent).unwrap();
        assert!(metadata.is_dir());
        assert!(!metadata.file_type().is_symlink());
        fs::remove_dir_all(root.as_ref()).unwrap();
    }

