    #[test]
    fn agy_plain_text_contract_retries_an_incomplete_trailing_utf8_codepoint() {
        let expected = crate::verify::ReviewContractExpectation::exact(
            "B900",
            "r53",
            "B900-A0001",
            "primary",
            "executor-claw",
            "1111111111111111111111111111111111111111",
        )
        .unwrap();
        let path = "/repo/coordination/rounds/r53/reviews/B900-A0001-primary-executor-claw.md";
        let frontmatter = render_review_frontmatter_template(&expected)
            .unwrap()
            .replace("__VERDICT__", "PASS");
        let log = format!("REVIEW_OUTPUT_PATH={path}\n```yaml\n{frontmatter}```\n中");
        let partial_end = log.len() - 1;

        assert!(!plain_text_review_contract_consumed(
            log.as_bytes(),
            0,
            partial_end as u64,
            path,
            &expected,
        )
        .unwrap());
        assert!(plain_text_review_contract_consumed(
            log.as_bytes(),
            0,
            log.len() as u64,
            path,
            &expected,
        )
        .unwrap());
        assert!(!plain_text_review_contract_consumed(
            log.as_bytes(),
            0,
            log.len() as u64,
            "/repo/coordination/rounds/r53/reviews/wrong.md",
            &expected,
        )
        .unwrap());

        let invalid = [0xff];
        assert!(plain_text_review_contract_consumed(
            &invalid,
            0,
            invalid.len() as u64,
            path,
            &expected,
        )
        .is_err());
    }

    #[test]
    fn review_consumption_partial_record_needs_a_later_immutable_window() {
        let root = temp_root("review-consumption-partial-window");
        let path = root.join("attempt.jsonl");
        let challenge = "019fb34b-partial-window";
        let partial = format!(
            r#"{{"type":"tool_result","sessionId":"claw","callId":"read_1","output":"{challenge}""#
        );
        fs::write(&path, partial.as_bytes()).unwrap();

        let first = capture_probe_window(&path, 0).unwrap();
        let mut append = fs::OpenOptions::new().append(true).open(&path).unwrap();
        append.write_all(b"}\n").unwrap();
        append.flush().unwrap();
        assert_eq!(
            captured_review_consumption_proof(first, challenge).unwrap(),
            None,
            "bytes appended after capture must not complete the old immutable window"
        );

        let second = capture_probe_window(&path, 0).unwrap();
        assert_eq!(
            captured_review_consumption_proof(second, challenge).unwrap(),
            Some(ReviewConsumptionProof::StructuredProbe(
                ReviewProbeSource::ClawToolOutput
            )),
            "a later capture may consume the now-complete JSON record"
        );
        fs::remove_dir_all(root).unwrap();
    }

