    #[test]
    fn b260_real_deadline_lands_last_frame_gap_and_summary_in_the_ledger() {
        let root = temp_root("b260-real-deadline-ledger");
        let round = "r260";
        let logs = root.join("coordination/runtime/logs");
        let bin = root.join("bin");
        fs::create_dir_all(&logs).unwrap();
        fs::create_dir_all(&bin).unwrap();
        fs::create_dir_all(root.join(format!("coordination/rounds/{round}"))).unwrap();
        fs::write(
            root.join(format!("coordination/rounds/{round}/events.jsonl")),
            "",
        )
        .unwrap();
        append_schema3_round_opened(&root, round);
        let program = bin.join("opencode");
        fs::copy(std::env::current_exe().unwrap(), &program).unwrap();
        fs::set_permissions(&program, fs::Permissions::from_mode(0o755)).unwrap();
        let log_path = logs.join("wake-opencode.jsonl");
        File::create(&log_path).unwrap();
        let argv = vec![
            program.to_string_lossy().into_owned(),
            "--exact".to_string(),
            b260_deadline_test_name().as_str().to_string(),
            "--nocapture".to_string(),
            "--test-threads=1".to_string(),
        ];
        let wake_id = fresh_managed_wake_id();
        // Leave enough time for the copied libtest provider to pass through
        // dyld and libtest startup even under review-sandbox load.  The
        // contract under test is the real last-frame diagnostic, not a
        // one-second process-startup race.
        let runtime_limit = managed_wake_runtime_limit(Some(5));
        ledger::append(
            &root,
            round,
            &[ledger::event(
                "WakeIssued",
                "runtime:orch",
                Some("B260"),
                Some(round),
                serde_json::json!({
                    "wakeId": wake_id,
                    "controlWakeId": wake_id,
                    "agent": "executor-opencode",
                    "runtimeLimit": runtime_limit,
                }),
            )],
        )
        .unwrap();

        let provider_pid = spawn_managed_wake_supervisor(
            &root,
            "executor-opencode",
            &argv,
            &log_path,
            &wake_id,
            runtime_limit,
            &BTreeMap::new(),
            None,
            &root,
        )
        .unwrap();
        assert!(provider_pid > 0);
        let (dir, descriptor) = read_managed_wake_control_descriptor(&root, &wake_id).unwrap();
        let deadline = Instant::now() + Duration::from_secs(15);
        while !descriptor.status_path.exists() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(10));
        }
        let body = secure_read_lf_frame(
            &descriptor.status_path,
            &dir,
            MAX_MANAGED_WAKE_CONTROL_BYTES,
        )
        .unwrap();
        let status: WakeSupervisorStatus = serde_json::from_slice(&body).unwrap();
        assert_eq!(
            status.completion_reason,
            ManagedWakeStopReason::HardDeadline
        );
        assert!(status.hard_deadline_reached);
        assert!(!status.terminal_seen);
        assert!(status.managed_scope_terminated);

        assert!(reconcile_managed_wake_termination(&root, round, &wake_id).unwrap());
        let ledger =
            orch_core::read_ledger(&root.join(format!("coordination/rounds/{round}/events.jsonl")))
                .unwrap();
        assert!(ledger.bad_lines.is_empty());
        let terminated = ledger
            .events
            .iter()
            .find(|event| {
                event.kind == "ManagedWakeTerminated"
                    && payload_string(event, "wakeId") == Some(wake_id.as_str())
            })
            .expect("real deadline must reconcile a terminal ledger fact");
        let payload = terminated.payload.as_ref().unwrap();
        println!(
            "B260_MANAGED_WAKE_TERMINATED={}",
            serde_json::to_string(payload).unwrap()
        );
        assert_eq!(payload["outcomeClass"], "StoppedByHardDeadline");
        let last_frame_age_secs = payload["lastFrameAgeSecs"]
            .as_u64()
            .expect("deadline fixture must publish the observed last-frame age");
        assert!(
            last_frame_age_secs <= 5,
            "last-frame gap exceeds the five-second deadline: {payload}"
        );
        assert!(
            payload["lastFrameSummary"]
                .as_str()
                .is_some_and(|summary| summary.contains(B260_LAST_FRAME_MARKER)),
            "last frame summary must retain the bounded semantic marker: {payload}"
        );
        wait_for_managed_supervisor_reaped(&dir, &descriptor, deadline);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b191_cancel_during_accept_wait_never_publishes_accepted() {
        let root = temp_root("b191-handshake-cancel");
        let logs = root.join("coordination/runtime/logs");
        let bin = root.join("bin");
        fs::create_dir_all(&logs).unwrap();
        fs::create_dir_all(&bin).unwrap();
        let program = bin.join("opencode");
        fs::copy(std::env::current_exe().unwrap(), &program).unwrap();
        fs::set_permissions(&program, fs::Permissions::from_mode(0o755)).unwrap();
        let log_path = logs.join("wake-opencode.jsonl");
        File::create(&log_path).unwrap();
        let supervisor_dir = authenticated_supervisor_dir(&root, true).unwrap();
        let token = fresh_supervisor_token().unwrap();
        let wake_id = fresh_managed_wake_id();
        let ack_path = supervisor_dir.join(format!("{token}.ack.json"));
        let status_path = supervisor_dir.join(format!("{token}.status.json"));
        let spec = WakeSupervisorLaunchSpec {
            version: 1,
            protocol_revision: WAKE_SUPERVISOR_PROTOCOL_REVISION,
            token: token.clone(),
            argv: vec![
                program.to_string_lossy().into_owned(),
                "--exact".to_string(),
                b177_stubborn_test_name().as_str().to_string(),
                "--nocapture".to_string(),
                "--test-threads=1".to_string(),
            ],
            cwd: fs::canonicalize(&root).unwrap(),
            log_path: log_path.clone(),
            ack_path: ack_path.clone(),
            status_path: status_path.clone(),
            policy: WakeSupervisorPolicy::production(),
            env: BTreeMap::new(),
            channel_binding: None,
            environment_is_complete: false,
            wake_id: Some(wake_id.clone()),
            agent: Some("executor-opencode".to_string()),
            attach_action_id: None,
            continued_from_wake_id: None,
            runtime_limit: managed_wake_runtime_limit(None),
            launch_variant: WakeSupervisorLaunchVariant::ManagedRevision3,
            baseline: Vec::new(),
            baseline_topology: process_topology_snapshot().unwrap().into_values().collect(),
        };
        let orch = fresh_orch_debug_bin_for_wake_tests().unwrap();
        let mut command = Command::new(orch);
        command
            .args([
                "--root",
                root.to_string_lossy().as_ref(),
                "__wake-supervise",
            ])
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        configure_isolated_session(&mut command);
        let mut supervisor = command.spawn().unwrap();
        let mut stdin = supervisor.stdin.take().unwrap();
        let mut frame = serde_json::to_vec(&spec).unwrap();
        frame.push(b'\n');
        stdin.write_all(&frame).unwrap();
        stdin.flush().unwrap();

        let descriptor_path = supervisor_dir.join(format!("{wake_id}.control.json"));
        let deadline = Instant::now() + Duration::from_secs(5);
        while !descriptor_path.exists() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(descriptor_path.exists());
        let cancel = request_managed_wake_cancel(&root, &wake_id, "cancel before ACCEPT").unwrap();
        assert_eq!(
            cancel.completion_reason,
            Some(ManagedWakeStopReason::ManualCancel)
        );
        let status = supervisor
            .wait_timeout(Duration::from_secs(15))
            .unwrap()
            .expect("hidden supervisor did not exit after handshake cancel");
        assert!(status.success());
        drop(stdin);
        assert!(!ack_path.exists(), "ACCEPTED/OFFER must not survive winner");
        let body = secure_read_lf_frame(
            &status_path,
            &supervisor_dir,
            MAX_MANAGED_WAKE_CONTROL_BYTES,
        )
        .unwrap();
        let final_status: WakeSupervisorStatus = serde_json::from_slice(&body).unwrap();
        assert_eq!(
            final_status.completion_reason,
            ManagedWakeStopReason::ManualCancel
        );
        assert!(final_status.managed_scope_terminated);
        assert_eq!(
            final_status.cancel_reason.as_deref(),
            Some("cancel before ACCEPT")
        );
        fs::remove_dir_all(root).unwrap();
    }

